-- AP&E glossary — Machine B batch 1 — PASTE FILE 2 of 6
-- Paste this whole file into the Supabase SQL editor and Run. Order between files does not matter.
-- Idempotent: safe to re-run. Backup already exists (glossary_backup_mb_batch1_20260721).
BEGIN;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"3df7e422-b6b0-4f74-8d93-5fdd81ec7fd2": {"definition": "A dedicated pass through a vocal track in which the engineer writes automation over time, most often volume level, but also mute, pan, sends, or plugin settings. Its aim is to keep the vocal even and intelligible from start to finish of the song.", "plain_english": "It means going through a vocal track and drawing in volume moves line by line. It keeps every word at the right level so nothing gets lost or jumps out.", "purpose_function": "It evens out level and effect changes that the singer or compressor left behind so each word sits right in the mix. It gives a level of control finer than a single fader setting can.", "practical_application": "After basic balancing, a technician plays the song and rides the vocal fader or draws level moves so quiet words come up and loud peaks stay in place.", "category": "Vocal Automation", "related_terms": ["Fader riding", "Volume automation", "Vocal breath automation", "Compression", "Mix automation"], "common_mistakes": ["Relying only on heavy compression for level control instead of a fine automation pass, so words still get lost.", "Writing automation moves so extreme that the vocal level pumps and sounds unnatural.", "Automating the vocal in solo rather than against the band, so the balance is wrong in the full mix."], "scenario_contexts": ["Riding the lead vocal level word by word so every lyric is clearly heard over the band.", "Automating a reverb send up on the last word of a phrase for a throw effect.", "Drawing level dips on loud consonants that a compressor alone could not tame."]}, "1c3e1b3f-db47-4f27-a46f-01417f5cf18a": {"definition": "The removal or reduction of unwanted background sound from a recorded vocal, such as room hum, air-conditioning, hiss, chair squeaks, or headphone bleed, using noise-reduction tools, spectral editing, gating, or manual editing while preserving the voice. It restores a clean vocal recording.", "plain_english": "It means cleaning quiet junk out of a vocal recording, like fan hum or hiss. The goal is a clear voice with the background noise gone.", "purpose_function": "It keeps noise from building up or distracting once the vocal is compressed and raised in level. A clean recording sits better in the mix and sounds professional.", "practical_application": "An editor uses a noise-reduction or spectral-repair plugin to learn the steady room noise and subtract it, then listens for artifacts before moving on.", "category": "Audio Restoration", "related_terms": ["Noise gate", "Spectral editing", "Vocal ambience control", "Hum removal", "De-essing"], "common_mistakes": ["Applying too much noise reduction, which leaves a watery, robotic artifact on the voice.", "Gating out low-level noise but also chopping soft breaths and phrase tails.", "Cleaning noise late in the mix instead of fixing the recording chain and room at the source."], "scenario_contexts": ["Removing steady air-conditioner hum from a vocal tracked in an untreated room.", "Using spectral repair to erase a single chair creak between two vocal phrases.", "Reducing headphone click bleed captured on a quiet, close-miked verse."]}, "de9c6d48-882c-49b6-b971-f266ad5906a8": {"definition": "The reinforcement of a vocal's low-midrange fundamentals, roughly 100 to 300 Hz, to add weight, warmth, and fullness. It is done with EQ boosts, saturation, or parallel processing so a thin voice sounds fuller and more present.", "plain_english": "It means adding weight and warmth to a thin-sounding voice. It fills in the lower part of the sound so the singer feels fuller and closer.", "purpose_function": "It gives a thin or distant vocal more warmth and power so it feels present and supported in the mix. A voice with body holds its place instead of sounding weak.", "practical_application": "When a vocal sounds thin, a technician boosts the low-mids or adds gentle saturation, watching that it does not clash with the bass and turn muddy.", "category": "Vocal EQ", "related_terms": ["Low-mid EQ", "Saturation", "Vocal boxiness reduction", "Proximity effect", "Parallel compression"], "common_mistakes": ["Boosting low-mids so much that the vocal turns muddy and masks the bass guitar.", "Adding body to fix a poor take when a better mic distance would solve it at the source.", "Confusing warm body around 200 Hz with boxy honk higher up and boosting the wrong range."], "scenario_contexts": ["Warming up a thin vocal recorded on a bright condenser microphone.", "Adding weight to a backing vocal so it supports rather than disappears under the lead.", "Using saturation to give a distant-sounding take more presence and fullness."]}, "0bce22a0-1cb6-4260-a389-92d813690c5b": {"definition": "The cutting of low-mid frequencies, typically around 300 to 600 Hz, that make a vocal sound hollow or boxy, using a moderate to narrow EQ dip. It clears congestion in that range and improves the vocal's clarity and openness.", "plain_english": "It means cutting the tones that make a voice sound like it comes from inside a box. Taking them down makes the voice clearer and more open.", "purpose_function": "It removes the hollow, cardboard-like tone that small rooms and close miking can add, so the vocal sounds clear and natural. This frees up space in a crowded part of the mix.", "practical_application": "A technician sweeps a narrow EQ boost to find the boxy frequency, then cuts it a few decibels until the vocal opens up.", "category": "Vocal EQ", "related_terms": ["Low-mid EQ", "Vocal body enhancement", "Subtractive EQ", "Proximity effect", "Muddiness"], "common_mistakes": ["Cutting too wide or too deep, which thins the voice and strips out its natural warmth.", "Removing all low-mids and losing the body that keeps the vocal full.", "Fixing boxiness only with EQ when the real cause was a reflective room that needed treating."], "scenario_contexts": ["Clearing a hollow tone from a vocal tracked in a small untreated room.", "Dipping the low-mids so a close-miked vocal stops sounding congested.", "Sweeping to find and cut a boxy resonance before adding air and presence."]}, "598e0be2-20e9-4330-96b8-4a7274b4eae6": {"definition": "The use of volume automation, muting, or editing to reduce, but usually not fully remove, the level of a singer's breaths between phrases. It keeps breaths natural while stopping compression from pushing them up too loud.", "plain_english": "It means turning down the breaths a singer takes between lines so they do not jump out. You lower them a bit but keep some so the voice still sounds human.", "purpose_function": "It stops breaths from being made loud by heavy compression while keeping the performance natural rather than lifeless. Fully cutting breaths often sounds unnatural, so they are tamed instead.", "practical_application": "After compressing a vocal, a technician draws volume dips on each breath or uses a de-breath tool to lower them without cutting them out completely.", "category": "Vocal Automation", "related_terms": ["Vocal automation pass", "De-breath", "Compression", "Fader riding", "Vocal editing"], "common_mistakes": ["Muting breaths entirely, which makes phrases start abruptly and sound robotic.", "Ignoring breaths so a hard compressor pushes them up as loud as the words.", "Automating breath levels before compression, so the compressor changes them again afterward."], "scenario_contexts": ["Taming loud inhales that a fast compressor pulled up on an intimate vocal.", "Lowering breaths between rap lines so they do not distract from the delivery.", "Keeping soft, natural breaths in a ballad while trimming the loudest gasps."]}, "0fe6a07c-ac6e-492e-a415-41331a24146f": {"definition": "The adjustment of a vocal's upper-frequency content, roughly the 3 to 8 kHz presence range and above, with EQ or dynamic processing to make it more or less bright. It balances clarity and cut against harshness and sibilance.", "plain_english": "It means setting how sharp and clear the top of a voice sounds. You add some to help words cut through, or pull back if it gets too harsh.", "purpose_function": "It balances a vocal's clarity and edge so it stays easy to understand and present without sounding thin or piercing. This keeps the voice sitting well over a busy band.", "practical_application": "A technician boosts or cuts presence and high frequencies, sometimes with a dynamic EQ, so the vocal cuts through the band without turning harsh.", "category": "Vocal EQ", "related_terms": ["Vocal air enhancement", "Presence", "De-essing", "High-shelf EQ", "Sibilance"], "common_mistakes": ["Boosting brightness broadly and making the sibilant s and t sounds harsh.", "Adding presence to a harsh vocal instead of first cutting the frequency that is causing the problem.", "Judging brightness on headphones alone, then finding the vocal is too sharp on speakers."], "scenario_contexts": ["Lifting presence so a soft vocal is understood over loud electric guitars.", "Cutting harsh upper frequencies on a vocal recorded through a bright signal chain.", "Using dynamic EQ so brightness only rises on quieter passages where the vocal needs help."]}, "db450d4b-6b06-4cc4-a66a-f7999a941d1d": {"definition": "The mixing practice of panning the lead vocal to the phantom center of the stereo image, fed at equal level to the left and right channels so it appears directly in front of the listener.", "plain_english": "Putting the lead singer's voice in the middle, so it comes out of both speakers the same. That makes the voice sound like it is right in front of you.", "purpose_function": "It anchors the most important part of a song at the listener's focal point and keeps the vocal solid when the mix is heard in mono, matching how kick and bass are also centered.", "practical_application": "On the console or DAW the engineer sets the lead vocal channel's pan control to center, then checks the mix in mono to confirm the voice stays strong and level.", "category": "Vocal mixing", "related_terms": ["Panning", "Stereo image", "Phantom center", "Mono compatibility", "Lead vocal", "Vocal compression"], "common_mistakes": ["Panning the lead vocal off-center to make room, which weakens the song's focal point", "Forgetting to check the balance in mono, so a center vocal drifts when summed", "Assuming center placement alone makes a vocal sit forward, instead of using level and EQ"], "scenario_contexts": ["Placing the lead vocal dead-center in a pop or rock mix while backing vocals spread to the sides", "Checking a broadcast mix in mono to confirm the centered vocal does not shift or drop in level", "Keeping the lead vocal centered alongside kick, snare, and bass in a typical band arrangement"]}, "5d0e28fc-f5cd-42d7-af87-f360fef63135": {"definition": "An editing pass through a recorded vocal track that removes unwanted noises and artifacts before mixing, such as loud breaths, lip smacks, mic bumps, chair squeaks, and background noise in the gaps between phrases.", "plain_english": "A careful listen-through of the vocal track to cut out sounds you do not want. That means things like loud breaths, mouth clicks, and hiss between the words.", "purpose_function": "It gives the mix engineer a clean, distraction-free vocal and stops small noises from being made louder by the compression and EQ that come later.", "practical_application": "The engineer zooms in on the vocal waveform, fades or silences the gaps between phrases, and lowers or deletes stray noises take by take.", "category": "Vocal editing", "related_terms": ["Vocal click removal", "Vocal comp map", "Noise gate", "Fades", "Vocal de-essing", "Breath control"], "common_mistakes": ["Cutting every breath out completely, which makes the vocal sound unnatural and robotic", "Hard-cutting silence instead of using short fades, which leaves clicks at the edit points", "Deleting quiet consonant tails along with the noise, which dulls the words"], "scenario_contexts": ["Editing a comped lead vocal to remove breaths and mouth noise before handing it to the mix engineer", "Silencing headphone bleed and room noise in the gaps of a quiet verse", "Cleaning stray coughs and chair squeaks from a long ballad take"]}, "82f5f357-d272-4665-a4dd-07db9c8c0300": {"definition": "The targeted removal of short transient clicks, pops, and mouth noises from a vocal recording, including saliva clicks, digital clicks from bad edits, and pops from the microphone, usually using spectral repair or interpolation tools.", "plain_english": "Taking out the tiny clicking and popping sounds in a vocal recording. These can come from the mouth, from bad edits, or from the microphone.", "purpose_function": "Clicks and pops draw the ear and get louder after compression, so removing them keeps the vocal smooth and professional without changing the words.", "practical_application": "The engineer finds each click on the waveform or spectrogram and repairs it with a de-click tool or a short redraw, or fixes edit clicks by adding a tiny crossfade.", "category": "Vocal editing", "related_terms": ["Vocal cleanup pass", "Crossfade", "Spectral editing", "Vocal comp map", "Vocal consonant editing", "Transient"], "common_mistakes": ["Confusing a wanted consonant transient with a click and repairing it, which softens the word", "Fixing edit clicks by deleting audio instead of adding a short crossfade, leaving a gap", "Over-processing with broadband de-noise when only a few clicks need repair"], "scenario_contexts": ["Removing saliva and lip clicks from a close-miked lead vocal in a sparse arrangement", "Repairing a digital click left where two comped takes were spliced together", "Fixing a plosive pop that slipped past the pop filter on an opening line"]}, "e67373b9-75f6-49d2-978c-06d19a08a58a": {"definition": "Adjusting the gain of individual vocal clips or regions on the timeline, before the channel fader and processing, to even out level differences between words, phrases, or takes.", "plain_english": "Changing the loudness of small pieces of the vocal one at a time, before any other processing. It smooths out words that are too loud or too quiet.", "purpose_function": "It hands the compressor a more even signal, so the compressor reacts musically instead of clamping hard on just a few loud words, and it saves heavy fader riding later.", "practical_application": "In the DAW the engineer selects a loud syllable and pulls its clip-gain handle down a few dB, or lifts a buried word, evening out the take before the fader and plugins.", "category": "Vocal editing", "related_terms": ["Gain staging", "Vocal compression", "Automation", "Fader", "Vocal cleanup pass", "Dynamic range"], "common_mistakes": ["Trying to fix every level jump with the compressor alone instead of leveling clip gain first", "Making large clip-gain jumps without checking that the noise floor does not pump up", "Boosting a clip so far that it clips or reveals room noise and breaths"], "scenario_contexts": ["Evening out a singer who leaned into loud choruses and backed off in the verses", "Balancing word-to-word level before adding compression so gain reduction stays gentle", "Lifting a mumbled word at the end of a phrase so it stays intelligible in the mix"]}, "20d5c242-73a8-4d45-857a-0e1116703fc4": {"definition": "A documented plan showing which section of which recorded take is chosen to build a single composite (comp) lead vocal, mapping take or playlist numbers to each line, phrase, or word.", "plain_english": "A plan showing which piece of each recorded try is used to build the best full vocal. It is like picking the best word from take 1 and the best line from take 3.", "purpose_function": "It keeps comping organized and repeatable, so the engineer knows the source of every phrase and can rebuild or revise the composite vocal later.", "practical_application": "Using take lanes or playlists, the engineer marks the keeper phrases and notes them, then assembles the comped vocal and can revisit the map if a section needs changing.", "category": "Vocal editing", "related_terms": ["Vocal cleanup pass", "Take lanes", "Playlist", "Crossfade", "Lead vocal", "Vocal consonant editing"], "common_mistakes": ["Comping so many tiny fragments that phrasing and consonants stop matching across the edits", "Not labeling chosen takes, making the comp impossible to rebuild after a change", "Forgetting crossfades at the comp joins, which leaves clicks between spliced takes"], "scenario_contexts": ["Building one strong lead vocal from six recorded passes of the same song", "Noting keeper phrases per line so a producer's later notes can be applied quickly", "Rebuilding a chorus comp after the artist re-sings one weak line"]}, "f43e5fea-db7f-4136-84f5-ee8a679e7faf": {"definition": "Dynamic-range compression applied to a vocal track, which reduces the level of passages above a set threshold by a chosen ratio, making the overall vocal level more consistent so it sits steadily in the mix.", "plain_english": "Making the loud and quiet parts of a voice closer in volume. This keeps the singing steady so it does not jump out or get lost in the song.", "purpose_function": "The human voice has a very wide dynamic range, so compression keeps every word audible over a busy band without the engineer having to ride the fader constantly.", "practical_application": "The engineer sets a threshold, a ratio (often about 2:1 to 4:1 for control), and attack and release times so a few dB of gain reduction show on loud phrases, then adds make-up gain.", "category": "Vocal processing", "related_terms": ["Vocal de-essing", "Threshold", "Ratio", "Vocal clip-gain editing", "Make-up gain", "Attack and release"], "common_mistakes": ["Over-compressing until the vocal sounds squashed, pumps, and loses natural dynamics", "Setting the attack too fast, which dulls the consonant attacks and softens the words", "Chasing loudness with heavy compression instead of leveling clip gain first"], "scenario_contexts": ["Controlling a singer whose choruses are far louder than the verses", "Keeping a lead vocal steady and present over a loud rock arrangement", "Using gentle compression on tracking and more on the mix bus vocal chain"]}, "d929d9f4-7835-4450-bcdd-0c0d10028f55": {"definition": "Fine editing of the consonant sounds in a vocal, such as the hard onsets and endings of t, k, p, and s, to correct timing, align them across comped takes or doubled parts, and improve the clarity of the words.", "plain_english": "Lining up and cleaning the sharp sounds in singing, like the t, k, and s. This makes the words clear and keeps doubled voices tight together.", "purpose_function": "Consonants carry word clarity and timing, so editing them keeps lyrics easy to understand and makes stacked or doubled vocals lock tightly to the lead.", "practical_application": "The editor nudges a late t into place, aligns the s and t of a double to the lead, and trims or crossfades each consonant edit so it does not click.", "category": "Vocal editing", "related_terms": ["Vocal comp map", "Vocal click removal", "Crossfade", "Vocal de-essing", "Double tracking", "Timing alignment"], "common_mistakes": ["Cutting consonant tails too short, which makes words sound clipped and unclear", "Leaving doubled esses and tees out of alignment, which smears the stacked vocal", "Making consonant edits without crossfades, leaving audible clicks at the splices"], "scenario_contexts": ["Tightening the ending consonants of a doubled chorus so they hit as one", "Nudging a late plosive back into time in a rap or fast lyric line", "Aligning the sibilants of a lead and its harmony before de-essing the pair"]}, "a27bba86-5d6b-4e09-ae17-fd4196a09cdf": {"definition": "The reduction of excessive sibilance, the harsh high-frequency energy of s, sh, and t sounds (typically around 5 to 10 kHz), in a vocal, using a frequency-selective compressor called a de-esser.", "plain_english": "Turning down the harsh sss sounds in singing without dulling the rest of the voice. A special tool listens for those sounds and only lowers them.", "purpose_function": "Close-miking, bright EQ, and compression all boost sibilance, so de-essing tames it and keeps the vocal smooth and easy to listen to on bright playback systems.", "practical_application": "The engineer inserts a de-esser after compression, sets the detection band around 5 to 8 kHz, and dials in a few dB of reduction that triggers only on the sibilant sounds.", "category": "Vocal processing", "related_terms": ["Vocal compression", "Sibilance", "Vocal consonant editing", "EQ", "Vocal cleanup pass", "Frequency-dependent compression"], "common_mistakes": ["Setting too much reduction, which gives the singer a lisp by removing needed sibilance", "Placing the de-esser before heavy compression, so the compressor pushes sibilance back up", "Using broadband EQ cuts instead of a de-esser, which dulls the whole vocal"], "scenario_contexts": ["Taming harsh esses on a close-miked pop vocal after adding high-shelf EQ", "Smoothing sibilance on a doubled and compressed chorus stack", "Fixing a bright condenser microphone that exaggerated a singer's s sounds"]}, "5a034894-a45d-4051-b566-f05b19da9eba": {"definition": "An auxiliary send that routes a portion of the vocal signal to a delay (echo) effect on a return bus, so the wet delay is blended in parallel with the dry vocal rather than inserted directly in the channel.", "plain_english": "Sending a copy of the voice to an echo effect on its own channel. You can blend in as much echo as you want without changing the main dry voice.", "purpose_function": "A parallel send lets the engineer add echo and control its level on its own, keep the dry vocal untouched, and feed one delay from several sources at once.", "practical_application": "The engineer creates an aux or return with a delay, turns up the vocal channel's send to taste, and often times the delay to the song tempo, such as an eighth or quarter note.", "category": "Vocal effects", "related_terms": ["Aux send", "Return bus", "Delay", "Reverb send", "Tempo sync", "Lead vocal"], "common_mistakes": ["Inserting the delay in-line instead of on a send, which makes the wet and dry levels hard to balance", "Leaving the return fader up so the echo washes over the words and hurts clarity", "Not timing the delay to tempo, so the repeats fight the groove of the song"], "scenario_contexts": ["Adding a tempo-synced eighth-note echo to the ends of vocal phrases in a chorus", "Feeding one delay return from both the lead and a backing vocal to save channels", "Automating the send up on the last word of a line for a throw-style echo"]}, "6eccd064-15c0-4082-829c-804c688ad413": {"definition": "The use of reverb, delay, level, and equalization to place a vocal at a perceived front-to-back distance within a mix, controlling how close or far the voice sounds relative to other elements.", "plain_english": "This is making a voice sound close-up or far away in a song. You add echo or reverb and roll off some high tones to push a voice back, because far-off sounds seem softer and less clear.", "purpose_function": "It shapes the spatial layering of a mix so the lead voice sits at the right distance and does not clash with other parts, giving a flat stereo image a sense of depth.", "practical_application": "A mixing engineer uses short reverb, pre-delay, and a gentle high-frequency roll-off to move a backing vocal behind a drier, up-front lead.", "category": "Vocal Processing", "related_terms": ["Reverb", "Pre-delay", "Vocal equalization", "Vocal effects chain", "Dry/wet balance"], "common_mistakes": ["Adding so much reverb that the vocal loses clarity and drowns in the mix", "Treating depth as volume alone and ignoring reverb, pre-delay, and EQ cues", "Skipping pre-delay, which smears the vocal instead of placing it back in space"], "scenario_contexts": ["Placing stacked backing vocals behind the lead", "Creating an intimate, close-sounding lead vocal", "Matching a vocal to the roominess of a live band mix"]}, "5801300c-d25f-413a-8210-f26e25ec6b35": {"definition": "The addition of harmonic and intermodulation content to a vocal by driving a device, plug-in, or amplifier stage past its linear range; used deliberately as a creative effect or flagged as a fault when unintended.", "plain_english": "This is adding grit or fuzz to a voice on purpose, or a fault when a signal is too loud. It comes from pushing the sound past a clean level, the way a guitar amp turned up gets a rough, edgy tone.", "purpose_function": "As an effect it adds edge and harmonic richness so a vocal cuts through a dense mix; as a fault it signals that a stage is overloaded and clipping.", "practical_application": "An engineer runs a vocal through a saturation plug-in or overdriven preamp for attitude, often blending it under the clean take on a parallel channel.", "category": "Vocal Processing", "related_terms": ["Saturation", "Clipping", "Harmonic distortion", "Overdrive", "Parallel processing", "Gain staging"], "common_mistakes": ["Mistaking harsh digital clipping for pleasant analog-style saturation", "Distorting the whole take instead of blending a parallel distorted copy", "Adding so much grit that the words become hard to understand"], "scenario_contexts": ["Adding aggression to a rock or rap vocal", "Creating a lo-fi telephone or megaphone effect", "Diagnosing accidental clipping at an overloaded preamp"]}, "8698a591-1709-4796-9a0d-474e837442b9": {"definition": "Equalization of a vocal in which the gain of one or more frequency bands changes in response to the signal level in that band, so correction is applied only when a threshold is crossed rather than statically.", "plain_english": "This is EQ for a voice that only kicks in when one pitch range gets too loud. Instead of always cutting those tones, it turns them down just for the moments they jump out, then leaves them alone.", "purpose_function": "It tames problem frequencies such as harsh sibilance, boomy notes, or resonances only when they actually occur, keeping the natural tone intact the rest of the time.", "practical_application": "An engineer sets a dynamic EQ band around 3 to 6 kHz to duck only on harsh syllables, or a low band to control proximity boom, avoiding a permanent static cut.", "category": "Vocal Processing", "related_terms": ["Vocal equalization", "De-esser", "Multiband compression", "Threshold", "Resonance"], "common_mistakes": ["Confusing it with static EQ, which cuts a band all the time", "Setting the threshold so low that the band acts constantly", "Choosing attack and release times that make the band pump audibly"], "scenario_contexts": ["Taming sibilance only on the loud 's' sounds", "Controlling proximity boom that comes and goes", "Reducing a single resonant note that rings out"]}, "eddd3add-b819-4938-983f-6e64e2e37714": {"definition": "The process of hiding audible artefacts at splice points in a comped or corrected vocal by using crossfades, matched levels, and continuous breath and room tone so assembled takes play as one seamless performance.", "plain_english": "This is hiding the joins when you stitch the best bits of several vocal takes together. You blend each cut with a short fade so no clicks or jumps reveal where one take stops and the next begins.", "purpose_function": "It makes a composite vocal built from many takes sound like one continuous performance, removing clicks, level jumps, and cut-off breaths at the edit points.", "practical_application": "After comping, an engineer places short crossfades at each edit, matches breath and room tone across the splice, and cuts at zero crossings to avoid pops.", "category": "Vocal Editing", "related_terms": ["Comping", "Crossfade", "Zero crossing", "Room tone", "Punch-in"], "common_mistakes": ["Cutting in the middle of a word so the join is obvious", "Leaving hard cuts with no crossfade, which creates clicks", "Deleting all breaths so the vocal sounds robotic and unnatural"], "scenario_contexts": ["Comping a lead vocal from several takes", "Cleaning up a punch-in edit", "Removing a click left at a splice point"]}, "b4cdfc85-e853-4350-8a1a-8854a0a9ce2b": {"definition": "The ordered series of signal processors, such as EQ, compression, de-essing, saturation, delay, and reverb, through which a vocal signal passes, where each stage's placement affects the overall result.", "plain_english": "This is the line-up of effects a voice passes through, one after another, like an assembly line. The order matters, because each effect changes the sound before it reaches the next one.", "purpose_function": "It shapes a raw vocal into a finished, polished sound, and the chosen order, such as EQ before or after compression, determines how the processors interact.", "practical_application": "A typical chain runs gain, high-pass, compression, EQ, and de-esser into time-based sends; the engineer reorders stages to solve specific tonal or dynamic problems.", "category": "Vocal Processing", "related_terms": ["Signal chain", "Insert", "Vocal equalization", "Compression", "De-esser", "Send/return"], "common_mistakes": ["Placing the de-esser after a big high boost so sibilance returns", "Stacking so many processors that the vocal sounds over-processed", "Failing to match levels between stages, which changes how each one reacts"], "scenario_contexts": ["Building a tracking chain for recording", "Setting up an insert chain during the mix", "Troubleshooting a chain by changing the order of processors"]}, "ee89a1bb-ff53-487a-a687-697546f81d9b": {"definition": "A dedicated stage in the production workflow during which time-based and creative effects, such as delays, reverbs, modulation, and throws, are added to a vocal, typically after corrective editing and balancing are complete.", "plain_english": "This is a work session set aside just for adding effects to a voice, like echo and reverb. You do it after the voice is already tuned and balanced. That way you can focus only on the creative sounds.", "purpose_function": "Separating effect-adding into its own pass lets the engineer focus on creative sound design once the vocal is clean, and makes automated throws and returns easier to manage.", "practical_application": "During the mix, an engineer does an effects pass to automate delay throws on line ends, add reverb tails, and print special one-off effects to their own tracks.", "category": "Vocal Processing", "related_terms": ["Delay throw", "Reverb", "Automation", "Vocal effects chain", "Send/return"], "common_mistakes": ["Adding effects before the tuning and timing are fixed", "Over-effecting so the words get buried", "Leaving effects un-automated so they clutter quiet verses"], "scenario_contexts": ["Automating delay throws on the ends of vocal lines", "Adding reverb tails during the mix", "Printing a special one-off vocal effect to a track"]}, "2ba80812-58db-4756-bc96-36391664eacb": {"definition": "The adjustment of the relative levels of frequency bands in a vocal signal using an equalizer, to correct tonal problems, remove unwanted resonances or rumble, and shape the voice to sit within a mix.", "plain_english": "This is turning different pitch ranges of a voice up or down to fix its tone. Like the bass and treble knobs on a stereo, it can cut a boomy low end or add air on top so the voice sounds clear.", "purpose_function": "It removes rumble, boxiness, and harshness and can add clarity or air, so the vocal is balanced on its own and carves out its own space in the mix.", "practical_application": "An engineer high-passes below about 80 to 100 Hz to cut rumble, dips boxy mids around 300 to 500 Hz, and adds a gentle high shelf for air.", "category": "Vocal Processing", "related_terms": ["Equalization", "High-pass filter", "Proximity effect", "De-esser", "Presence"], "common_mistakes": ["Reaching for a boost when a cut would solve the problem more cleanly", "Judging EQ with the vocal soloed instead of in the full mix", "Making cuts so deep that the voice sounds thin and lifeless"], "scenario_contexts": ["Cleaning low-frequency rumble from a vocal track", "Fixing a boxy or muddy tone", "Adding presence so the vocal sits over a busy mix"]}, "17d0f75b-efdb-428e-8031-ebffb1d3a13f": {"definition": "The addition of synthesised high-frequency harmonics to a vocal using an exciter or harmonic enhancer, generating content derived from the source signal to increase perceived brightness, presence, and detail without a simple level boost.", "plain_english": "This is brightening a voice by adding brand-new high harmonics, not just turning the treble up. A tool called an exciter makes fresh sparkle from the voice itself, so it sounds crisper and more present.", "purpose_function": "It restores or adds air and articulation to a dull vocal, making it feel closer and more detailed while using less energy than a large equalizer boost would.", "practical_application": "An engineer applies a harmonic exciter lightly to a dark or lifeless vocal to add sheen and intelligibility, watching that it does not sharpen sibilance.", "category": "Vocal Processing", "related_terms": ["Harmonic enhancement", "Aural exciter", "Vocal equalization", "Saturation", "Presence"], "common_mistakes": ["Overusing the exciter until the vocal sounds harsh and tiring", "Exciting the sibilant range so 's' sounds become piercing", "Using it to rescue a poorly recorded source instead of fixing the recording"], "scenario_contexts": ["Brightening a dull or muffled vocal", "Adding air to a vocal cut on a dark microphone", "Improving intelligibility in a dense mix"]}, "13dc4890-f9ab-4080-8b08-df088db923ab": {"definition": "The application of dynamic-range expansion to a vocal, in which the level of signal below a set threshold is reduced, widening the gap between loud and soft passages to lower noise, bleed, and low-level artefacts between phrases.", "plain_english": "This is a tool that makes the quiet parts of a voice track even quieter. It turns down soft background noise and spill between words, so the gaps sound clean while the sung words stay full.", "purpose_function": "Expansion, and its extreme form the noise gate, cleans up spill, breaths, headphone bleed, and room noise in the gaps of a vocal without the abrupt on-off of a hard gate.", "practical_application": "An engineer sets a gentle downward expander with a threshold just under the softest sung notes to pull down bleed between phrases while keeping breaths sounding natural.", "category": "Vocal Processing", "related_terms": ["Expander", "Noise gate", "Compression", "Threshold", "Dynamic range"], "common_mistakes": ["Setting the threshold too high, which chops off soft note tails and word endings", "Using too fast a release (with no hold time or hysteresis), so the expander or gate chatters on and off when the signal hovers near the threshold", "Confusing expansion with compression, which reduces dynamic range instead"], "scenario_contexts": ["Cleaning bleed between vocal phrases", "Reducing steady room noise on a recorded take", "Tightening a vocal without a hard, obvious gate"]}, "5d44a54a-e578-4a81-bc00-5d56a6b0d9c9": {"definition": "A mixing approach in which the lead vocal is balanced to sit prominently at the front of the perceived depth field, achieved through relative level, presence-range EQ, and restrained ambience so the voice reads as closer and more immediate than the surrounding arrangement.", "plain_english": "This means setting the singer's voice so it sits right up front in the mix. Like a lead actor standing at the front of the stage, the voice stays clear and easy to hear above the band.", "purpose_function": "It keeps the most important element, the vocal, clearly audible and emotionally central so the listener follows the lyric and melody without effort. It exists because dense band arrangements can easily bury a voice.", "practical_application": "An engineer creates it by lifting the vocal fader relative to the backing, adding a touch of presence-range EQ, and keeping reverb short and lower in level so the voice stays close rather than pushed back into the room.", "category": "Mix Balance", "related_terms": ["Vocal level ride", "Vocal intelligibility enhancement", "Vocal leveling compression", "Vocal gain automation", "Vocal low-cut filtering"], "common_mistakes": ["Pushing the vocal fader up so far that the rest of the band feels weak and disconnected instead of using EQ and dynamics to help the voice cut", "Adding long, loud reverb while trying to sound forward, which actually pushes the voice back and away", "Assuming forward placement means simply louder, ignoring that presence EQ and controlled dynamics do most of the work"], "scenario_contexts": ["Mixing a pop or rock song where the lead vocal must ride clearly on top of guitars, drums, and synths", "Preparing a rough mix for a client who wants to hear the singer front and center", "Balancing a dense full-band arrangement so the lyric stays intelligible on small speakers and earbuds"]}, "afc0547b-745d-4c51-9942-383c193c30f0": {"definition": "The use of a DAW's automation system to write and play back level changes on a vocal track over time, so that individual words, phrases, or sections are raised or lowered to a consistent, intended balance without manual real-time adjustment.", "plain_english": "This is writing volume moves for the vocal track so they play back on their own. The software remembers each change, so quiet words come up and loud words come down every time.", "purpose_function": "It evens out a vocal's changing loudness and keeps every word audible against the arrangement, complementing compression by fixing bigger, section-level balance shifts. It exists so the balance is repeatable and precise.", "practical_application": "An engineer draws or records fader moves on the vocal automation lane, nudging soft syllables up and loud belts down phrase by phrase, then fine-tunes the drawn points while listening in context.", "category": "Level Automation", "related_terms": ["Vocal level ride", "Vocal leveling compression", "Vocal forward placement", "Vocal limiting", "Vocal intelligibility enhancement"], "common_mistakes": ["Relying only on automation to fix dynamics that a compressor should handle first, leading to hundreds of tiny moves", "Writing volume moves so aggressive that the vocal loses its natural feel and sounds flat", "Forgetting that automation happens after the plug-in chain, so heavy moves can change how downstream processors react"], "scenario_contexts": ["Bringing up a mumbled word at the end of a line so the lyric stays clear", "Automating a chorus vocal a bit louder than the verse to lift the energy", "Cleaning up an uneven performance where the singer moved off and on the microphone"]}, "f5f08e32-c334-4969-889d-d402d486bb45": {"definition": "The application of a noise gate to a vocal track so that the signal is attenuated or muted whenever it falls below a set threshold, removing low-level bleed, hum, breaths, and room noise in the gaps between sung or spoken phrases.", "plain_english": "A gate is a switch that mutes a track when the sound drops below a set level. On vocals it cuts the hiss, hum, and breath sounds during the gaps when the singer is not singing.", "purpose_function": "It cleans up the silent spaces in a vocal so noise and bleed do not build up when many tracks play together. It exists to keep a vocal track quiet and controlled between phrases.", "practical_application": "An engineer sets the threshold just above the background noise and adjusts attack, hold, and release so the gate opens instantly on words but does not chop off soft word endings or clamp shut during held notes.", "category": "Dynamics Processing", "related_terms": ["Vocal low-cut filtering", "Vocal leveling compression", "Vocal gain automation", "Vocal limiting", "Vocal level ride"], "common_mistakes": ["Setting the threshold too high so quiet words and breath tails get cut off, making the vocal sound choppy", "Using too fast a release so the gate 'chatters' open and shut on sustained or fading notes", "Gating instead of editing, when muting or fading the gaps by hand would sound cleaner and more natural"], "scenario_contexts": ["Silencing headphone bleed and mic hiss between lines on a tracked studio vocal", "Cleaning up a spoken-word or podcast take with audible room noise in the pauses", "Tightening a live vocal channel so an open mic does not pass stage noise between phrases"]}, "bf8bdeae-86f6-4fe2-a1b3-200dc9c5ab59": {"definition": "Tonal treatment that tames aggressive, edgy energy in a vocal, typically in the upper midrange and lower presence region around 2 to 5 kHz, using subtractive EQ, dynamic EQ, or multiband compression to soften strident peaks while preserving clarity.", "plain_english": "Some singing has a sharp, edgy tone that can hurt the ears. This means turning down those harsh notes so the voice sounds smooth but still clear.", "purpose_function": "It makes a bright or strident vocal comfortable to listen to over time without dulling the voice or hiding the words. It exists because forceful singing and some microphones push extra energy in the range the ear is most sensitive to.", "practical_application": "An engineer sweeps a narrow EQ boost through the upper mids to find the harsh spot, then cuts it, or uses a dynamic EQ so the reduction only kicks in on the loud, harsh moments and leaves softer passages untouched.", "category": "EQ / Tone", "related_terms": ["Vocal intelligibility enhancement", "Vocal low-cut filtering", "Vocal leveling compression", "Vocal forward placement", "Vocal limiting"], "common_mistakes": ["Cutting too wide or too deep, which removes the presence that helps the vocal cut and makes it sound dull and distant", "Confusing harshness (upper mids) with sibilance (higher 'ess' frequencies) and reaching for the wrong tool", "Fixing with static EQ what really needs a dynamic EQ, so quiet parts lose brightness they never had a problem with"], "scenario_contexts": ["Softening a belted rock chorus that turns brittle and edgy on loud notes", "Taming a bright condenser microphone that exaggerates a singer's upper midrange", "Smoothing a vocal that sounds fine alone but grates once played loud in the full mix"]}, "05896a93-f7ea-4b8b-939f-f22e29f597ff": {"definition": "Processing aimed at making the words of a vocal clearly understandable in a mix, primarily by supporting the consonant and presence range (roughly 2 to 6 kHz), controlling dynamics, and clearing competing energy from other instruments so speech cues are not masked.", "plain_english": "This means making the words easy to understand. You lift the sounds that carry speech and clear away anything that covers them, so every word comes through.", "purpose_function": "It ensures the listener can follow the lyric even in a busy arrangement or on small speakers. It exists because consonants, which carry most of the meaning, are low in energy and easily buried by other instruments.", "practical_application": "An engineer adds gentle presence-range EQ, keeps vocal dynamics under control so quiet words stay audible, and carves a little competing energy out of guitars or keys so the voice has its own space.", "category": "EQ / Tone", "related_terms": ["Vocal harshness reduction", "Vocal forward placement", "Vocal leveling compression", "Vocal low-cut filtering", "Vocal gain automation"], "common_mistakes": ["Only boosting presence and ignoring that consistent level (dynamics) matters just as much for hearing every word", "Adding so much high-mid boost that the voice becomes harsh while chasing clarity", "Failing to make room in competing instruments, so the vocal fights guitars and keys for the same frequencies"], "scenario_contexts": ["Making sure the lyric is clear in a dense rock or pop mix on phone speakers", "Improving word clarity on a dialogue or voice-over track for broadcast", "Helping a soft or breathy singer's consonants read against a full band"]}, "b33fc077-e197-4341-a494-bc0c3f419dd4": {"definition": "The practice of manually adjusting a vocal's fader in real time during playback, pushing quiet phrases up and pulling loud phrases down, to keep the voice at a consistent balance against the arrangement.", "plain_english": "This is moving the fader by hand to keep the voice at a steady level. You pull it down on loud parts and push it up on soft parts, like steering to stay in your lane.", "purpose_function": "It smooths out a vocal's natural loudness changes so every phrase sits right in the mix, often serving as the foundation before or alongside compression. It exists because the ear notices even small balance shifts on a lead vocal.", "practical_application": "An engineer plays the song and rides the vocal fader in passes, recording the moves as automation, focusing on catching phrases that duck under the band or jump out too far.", "category": "Level Control", "related_terms": ["Vocal gain automation", "Vocal leveling compression", "Vocal forward placement", "Vocal limiting", "Vocal intelligibility enhancement"], "common_mistakes": ["Trying to fix every syllable by hand instead of letting a compressor handle fast changes and riding only the bigger moves", "Riding after heavy compression, which can leave little useful range and cause noticeable pumping", "Making moves so large the vocal balance feels unnatural and jumps around"], "scenario_contexts": ["Evening out a dynamic singer whose verses whisper and choruses belt", "Setting up automation passes before committing a final vocal balance", "Rescuing a lively performance where compression alone cannot keep every phrase in place"]}, "5222cde1-3903-4d34-8311-07d1b32455c2": {"definition": "The use of a compressor to reduce the dynamic range of a vocal, attenuating louder passages so that soft and loud portions sit closer in level, giving the voice a steadier, more even presence in the mix.", "plain_english": "A compressor turns down the loudest parts of a track. On vocals it brings soft and loud words closer in level, so the voice stays even and sits well in the mix.", "purpose_function": "It controls the wide loudness swings of a natural voice so the vocal stays audible and consistent without constant manual riding. It exists because untreated vocals vary too much to hold a steady place in a busy mix.", "practical_application": "An engineer sets a moderate ratio and a threshold that catches the louder phrases for a few decibels of gain reduction, adjusting attack and release so the compression evens the level without dulling the delivery, sometimes splitting the work across two compressors.", "category": "Dynamics Processing", "related_terms": ["Vocal limiting", "Vocal level ride", "Vocal gain automation", "Vocal forward placement", "Vocal gating"], "common_mistakes": ["Using too high a ratio with too much gain reduction, squashing the life and breath out of the vocal", "Setting the attack too fast and killing the consonant transients that give the voice clarity", "Leaning entirely on the compressor and skipping level rides for the big section-level balance moves"], "scenario_contexts": ["Evening out a pop lead vocal so it holds a steady spot through verse and chorus", "Controlling a singer who drifts on and off the microphone during a take", "Preparing a vocal to sit consistently in a loud, dense band arrangement"]}, "9065782f-35a7-4fdc-8597-8b7c0d444522": {"definition": "The application of a limiter, a compressor with a very high ratio and fast response, to a vocal so that peaks are prevented from exceeding a set ceiling, catching sudden transients while leaving the bulk of the signal largely unchanged.", "plain_english": "A limiter is a strong compressor that stops a signal from going past a set ceiling. On vocals it catches sudden loud peaks so nothing clips or distorts.", "purpose_function": "It safeguards against occasional overshoots that would clip or spike above the rest of the vocal, and can add a final touch of loudness. It exists to hold a hard peak ceiling that gentler compression is not designed to enforce.", "practical_application": "An engineer places a limiter after leveling compression, sets the ceiling just below clipping, and lets it grab only the rare loudest peaks, watching that it engages sparingly rather than working constantly.", "category": "Dynamics Processing", "related_terms": ["Vocal leveling compression", "Vocal level ride", "Vocal gain automation", "Vocal gating", "Vocal intelligibility enhancement"], "common_mistakes": ["Driving the limiter hard as a loudness tool, which flattens the vocal and adds distortion", "Using a limiter to do the everyday dynamic control that a normal compressor should handle first", "Setting the ceiling too high so real peaks still slip through and clip downstream"], "scenario_contexts": ["Catching the odd loud consonant or belt that spikes above an already compressed vocal", "Protecting a live vocal channel from sudden peaks that could overload the system", "Placing a peak ceiling on a vocal bus before it hits the mix bus"]}, "1b248a01-99df-4905-9f98-31749ef888fd": {"definition": "The use of a high-pass (low-cut) filter on a vocal to attenuate energy below a chosen corner frequency, typically in the roughly 60 to 120 Hz region, removing subsonic rumble, handling and stand noise, and excess proximity-effect buildup that the voice does not need.", "plain_english": "A low-cut filter removes the deep low sounds a voice does not need. It clears out rumble, wind, and pops so the vocal sounds clean and tight.", "purpose_function": "It cleans up unwanted low-frequency content so the vocal does not muddy the mix or waste headroom, and it eases the low-end clutter that many tracks add together. It exists because vocals carry little useful information in the deep bass.", "practical_application": "An engineer engages the console or plug-in high-pass filter and sets the corner frequency just below the singer's lowest useful notes, raising it until rumble and boom disappear while the natural body of the voice stays intact.", "category": "EQ / Tone", "related_terms": ["Vocal harshness reduction", "Vocal intelligibility enhancement", "Vocal gating", "Vocal leveling compression", "Vocal forward placement"], "common_mistakes": ["Setting the corner frequency too high and thinning out the natural warmth and chest of the voice", "Skipping the low cut, letting rumble and proximity boom pile up and muddy the whole mix", "Assuming one fixed cut frequency fits every singer instead of tuning it to each voice's low range"], "scenario_contexts": ["Removing subsonic rumble and mic-stand thumps from a close-miked studio vocal", "Cutting proximity-effect boom when a singer works the microphone tightly", "Cleaning low-end buildup from a live vocal channel to control stage rumble and feedback risk"]}, "8a8ef51b-12d9-4c2e-a6b9-c753f096d6f9": {"definition": "The process of detecting and removing unwanted non-musical mouth sounds—lip smacks, clicks, saliva crackles, and tongue noises—from a recorded vocal track using specialized de-click/de-crackle tools or manual waveform editing.", "plain_english": "This means cleaning small mouth sounds out of a singer's recording. Lip smacks, clicks, and spit noises get removed, so only the words are left. It is like wiping smudges off a photo to make the picture look clean.", "purpose_function": "It removes distracting mouth sounds that become obvious once a vocal is compressed and pushed to the front of a mix, keeping the listener's focus on the words and tone.", "practical_application": "An engineer zooms into the waveform between words and uses a mouth de-click module or short fades to silence tiny clicks, usually before compression exaggerates them.", "category": "Vocal editing", "related_terms": ["Vocal phrase editing", "De-essing", "Noise reduction", "Comping", "Vocal mud reduction"], "common_mistakes": ["Removing so many mouth sounds that the vocal sounds unnatural and lifeless", "Confusing sibilance (ess sounds) with mouth clicks and treating them the same way", "Cutting whole sections instead of just the click, leaving audible gaps in room tone"], "scenario_contexts": ["Cleaning a close-mic'd lead vocal before heavy compression in a pop mix", "Preparing an intimate acoustic ballad where every mouth noise is audible", "Editing a voiceover or podcast where clicks distract from the message"]}, "7dc5f3ee-b1c6-4999-baa5-f76fe39037a4": {"definition": "The reduction of excessive low-midrange energy in a vocal, typically in the range of roughly 150–500 Hz, usually with EQ cuts, to remove a boomy, cluttered \"muddy\" quality and improve clarity.", "plain_english": "This means turning down the thick, boomy lower part of a voice. Too much energy around 200 to 400 Hz makes a voice sound muffled. Cutting it a little makes the words clearer, like opening a window in a stuffy room.", "purpose_function": "It clears low-mid buildup so the vocal sits clearly in the mix and does not clash with bass, guitars, and other instruments crowding the same range.", "practical_application": "The engineer sweeps a narrow EQ boost to find the boomy frequency, then cuts a few dB there, often around 200–400 Hz, while listening to the vocal in the full mix.", "category": "Vocal processing", "related_terms": ["Equalization", "Vocal nasality reduction", "High-pass filter", "Frequency masking", "Vocal multiband compression"], "common_mistakes": ["Cutting too much low-mid so the vocal becomes thin and weak", "Judging mud on the soloed vocal instead of in the full mix where it matters", "Setting a high-pass filter too high and losing the natural body of the voice"], "scenario_contexts": ["Cleaning up a male lead vocal that sounds boomy on a dense rock track", "Fixing a proximity-effect buildup from a singer working close to the mic", "Making room for bass and rhythm guitar in a crowded arrangement"]}, "20cf3d3b-2b51-46a0-8d9b-179561a22bd9": {"definition": "A dynamics process that splits a vocal signal into separate frequency bands and compresses each independently, allowing problem ranges such as boomy lows or harsh highs to be controlled without affecting the whole signal.", "plain_english": "This tool splits the voice into low, middle, and high parts, then controls the loudness of each part on its own. So you can calm just the boomy or harsh part without changing the rest. It is like each part having its own automatic volume that turns down only when that part gets too loud.", "purpose_function": "It tames only the frequency ranges that jump out—like a boom on low notes or a harsh edge on loud words—so the vocal stays even without dulling the whole track.", "practical_application": "An engineer sets a band around the harsh or boomy range and applies gentle compression there, tightening trouble spots while leaving the rest of the vocal untouched.", "category": "Vocal processing", "related_terms": ["Compression", "Vocal peak compression", "De-essing", "Dynamic EQ", "Vocal mud reduction"], "common_mistakes": ["Over-compressing every band until the vocal sounds squashed and lifeless", "Using it to fix problems that a simple EQ cut would solve more cleanly", "Setting crossover points carelessly and creating an uneven, phasey tone"], "scenario_contexts": ["Controlling a singer whose low notes boom while high notes stay fine", "Smoothing an uneven vocal recorded with inconsistent mic distance", "Taming harsh loud words on a bright vocal during vocal processing"]}, "daae5eae-05e8-49e8-a29b-a5812623252a": {"definition": "The reduction of an excessively nasal, honky quality in a vocal, typically by cutting a narrow band in the roughly 1–2 kHz region with EQ or dynamic EQ, where nasal resonance tends to concentrate.", "plain_english": "This means fixing a voice that sounds too honky, like someone talking through their nose. The problem sits around 1000 to 2000 Hz. Cutting a little there makes the voice sound more open and natural.", "purpose_function": "It removes a pinched, nasal tone that can make a vocal sound unpleasant, helping the voice sound fuller and more natural in the mix.", "practical_application": "The engineer sweeps a narrow EQ cut through the low treble to find the honky spot, then reduces it a few dB, sometimes with a dynamic EQ so it acts only on the nasal notes.", "category": "Vocal processing", "related_terms": ["Equalization", "Vocal mud reduction", "Dynamic EQ", "Formant", "Resonance"], "common_mistakes": ["Cutting too wide a band and making the vocal sound dull and distant", "Confusing natural vocal formants with a nasal problem and over-correcting", "Removing so much that the vocal loses presence and intelligibility"], "scenario_contexts": ["Fixing a singer with a naturally nasal tone on a lead vocal", "Reducing honk caused by a mic or room emphasizing the low treble", "Cleaning up backing vocals that sound pinched when stacked"]}, "ff070394-363b-4e59-b453-f390ad89e948": {"definition": "The timing adjustment of the start (onset) of vocal notes or phrases—especially across doubled or stacked takes—so their attacks begin together, tightening the ensemble and cleaning up the stereo image.", "plain_english": "This means lining up the exact moment each vocal take starts. When you stack two takes, their first sounds should hit at the same time. If they do not, you nudge them so they start together, like two hands clapping as one.", "purpose_function": "It makes doubled and layered vocals sound tight and unified instead of loose or flammed, which is vital when several takes share the same words.", "practical_application": "The engineer zooms into the waveform starts and slides syllables earlier or later so a double lines up with the lead, or uses timing-alignment software to match them.", "category": "Vocal editing", "related_terms": ["Vocal phrase editing", "Comping", "Double tracking", "Time alignment", "Vocal phrase replacement"], "common_mistakes": ["Aligning so perfectly that stacked vocals lose their natural width and thickness", "Lining up only the note starts while ignoring where the words end", "Creating clicks or gaps when moving syllables without crossfading the edits"], "scenario_contexts": ["Tightening a doubled chorus vocal against the lead take", "Lining up a group of stacked backing vocals singing the same line", "Fixing a late entrance where a singer came in slightly behind the beat"]}, "24e6933f-aa33-49e4-86fe-052a441d1aef": {"definition": "A technique in which a heavily compressed copy of a vocal is blended underneath the original, largely uncompressed track, adding density and sustain while preserving natural dynamics and transients; also called New York or parallel compression.", "plain_english": "This means mixing a squashed copy of the voice under the normal one. The squashed copy fills in the quiet parts, while the main track keeps its punch. It is like putting a soft cushion under the voice so nothing gets lost.", "purpose_function": "It raises the quieter details and adds body and consistency to a vocal without crushing the loud peaks, keeping the performance lively yet steady.", "practical_application": "The engineer sends the vocal to a bus with strong compression, then blends that bus quietly beneath the main vocal, adjusting the balance to taste.", "category": "Vocal processing", "related_terms": ["Compression", "Vocal peak compression", "Vocal multiband compression", "Bus routing", "Aux send"], "common_mistakes": ["Blending in too much compressed signal so the vocal sounds pumping and unnatural", "Forgetting to match latency and causing phase problems between the two tracks", "Using it as a substitute for fixing a poorly recorded or badly performed take"], "scenario_contexts": ["Adding sustain and body to a lead vocal in a pop or R&B mix", "Bringing up quiet breaths and word tails on an intimate vocal", "Giving a thin backing vocal more weight without obvious compression"]}, "2a052599-cf0e-4bc5-bebe-3073ec52699f": {"definition": "Fast-acting compression applied to a vocal to catch and reduce short, loud transient peaks, evening out the level so the vocal stays controlled and can be brought forward in the mix safely.", "plain_english": "This means catching the loudest quick spikes in a voice and turning them down. Singers often jump loud on certain words, and this smooths those jumps. It is like a quick hand on the volume knob for every loud burst.", "purpose_function": "It controls sudden loud peaks so the vocal has a steadier level, stopping spikes from clipping or jumping out and letting the overall vocal sit louder in the mix.", "practical_application": "The engineer uses a fast attack and moderate ratio to clamp peaks, watching the gain-reduction meter so only the loudest moments are tamed.", "category": "Vocal processing", "related_terms": ["Compression", "Limiting", "Vocal parallel compression", "Vocal multiband compression", "Transient"], "common_mistakes": ["Setting the attack too fast and dulling the natural consonants and life of the vocal", "Using a high ratio that squashes the whole vocal instead of just the peaks", "Chasing meters instead of listening for when the compression sounds natural"], "scenario_contexts": ["Taming loud belted notes in a dynamic pop lead vocal", "Controlling peaks before a vocal reaches a limiter or further processing", "Evening out a singer who moves a lot on and off the mic"]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"8e6d302c-ffb2-4936-a455-78958f188907": {"definition": "Editing a vocal at the level of whole phrases or lines—cutting, moving, timing, cleaning, and crossfading them—to assemble and polish a performance, as opposed to editing single syllables or the whole track at once.", "plain_english": "This means working on a voice one line or phrase at a time. You cut, move, fix timing, and clean up each phrase, then smooth the joins. It is like editing a story sentence by sentence instead of all at once.", "purpose_function": "It lets an engineer shape and repair a vocal performance in manageable chunks, fixing timing and cleaning gaps while keeping the natural flow of each line.", "practical_application": "The engineer splits the vocal into phrases, nudges or replaces weak lines, trims noise between them, and crossfades the edits so the joins are inaudible.", "category": "Vocal editing", "related_terms": ["Comping", "Vocal phrase replacement", "Vocal onset alignment", "Crossfade", "Vocal mouth-noise repair"], "common_mistakes": ["Leaving hard edits with no crossfade, causing clicks at the joins", "Cutting room tone or breaths unevenly so phrases sound disconnected", "Over-editing until the performance loses its natural feel"], "scenario_contexts": ["Assembling a final lead vocal from several takes phrase by phrase", "Fixing the timing of a single weak line in an otherwise good take", "Cleaning noise and breaths between sung phrases before mixing"]}, "58717f67-a10e-4871-a44e-1851a4a65d86": {"definition": "Replacing a specific phrase, word, or line in a vocal track with the same phrase from another take or a re-recorded punch-in, matching level, timing, and tone so the swap is seamless.", "plain_english": "This means swapping one bad line in a vocal for a better version of the same line. You take the good phrase from another take and drop it in. It is like fixing one wrong word in a sentence without rewriting the whole page.", "purpose_function": "It fixes a single flawed phrase—wrong pitch, poor timing, or a slip—without redoing the whole vocal, saving the good parts of a performance.", "practical_application": "The engineer finds a better take of the problem line, drops it onto the timeline, matches its timing and level, and crossfades the edges so the replacement blends in.", "category": "Vocal editing", "related_terms": ["Comping", "Punch-in", "Vocal phrase editing", "Vocal onset alignment", "Crossfade"], "common_mistakes": ["Using a replacement phrase whose tone or mic distance does not match the rest", "Forgetting to align the timing so the swapped line feels off", "Leaving an audible level or room-tone jump at the edit points"], "scenario_contexts": ["Swapping a flat-pitched word for a better take in a lead vocal", "Punching in a corrected line the singer re-recorded later", "Replacing a mistimed phrase during vocal comping"]}, "9fe01ca6-652f-46dd-a47c-8e437ff87983": {"definition": "A note-by-note reference of a vocal part's intended melody and target pitches, used to guide pitch-correction tools and manual editing so each sung note is tuned toward its correct scale degree in the song's key.", "plain_english": "A chart of the exact notes a singer is meant to hit. It guides tuning software so each note is nudged to the right place instead of by guesswork.", "purpose_function": "It gives pitch correction a clear target, so off-key notes are moved toward the intended melody and key rather than to the nearest arbitrary pitch.", "practical_application": "Before tuning a lead vocal in a tool like Melodyne, the engineer checks or sets the target notes so corrected pitches follow the written melody, not random snapping.", "category": "Vocal Editing", "related_terms": ["Pitch correction", "Vocal production", "Vocal playlist comp", "Melody", "Scale degree"], "common_mistakes": ["Letting auto-tune snap every note to the nearest semitone without a mapped target, which forces notes to the wrong scale degree", "Mapping to equal temperament and ignoring the song's actual key or mode", "Over-correcting so the vocal loses natural expression and slides"], "scenario_contexts": ["Tuning a lead vocal where the singer drifts flat on sustained notes", "Setting reference pitches before comping a doubled harmony line", "Correcting a modulating chorus so notes track the new key"]}, "c36f72a0-39c9-498a-b988-c3b8e6f4bcfe": {"definition": "A composite lead vocal assembled by selecting the best phrases or words from several recorded takes held on separate playlists (alternate take lanes) of one track, then joining them into a single continuous performance.", "plain_english": "A best-of vocal built from many takes. You pick the strongest bits from each try and join them into one smooth performance.", "purpose_function": "It lets the engineer keep the best moments from many passes and deliver one strong vocal without demanding a single flawless take from the singer.", "practical_application": "In Pro Tools the engineer records several passes into playlists, auditions them lane by lane, and copies the best lines up into the main comp track.", "category": "Vocal Editing", "related_terms": ["Comping", "Take", "Punch-in", "Vocal production", "Crossfade"], "common_mistakes": ["Cutting between takes without crossfades, leaving clicks or breath jumps at the edits", "Choosing takes only for pitch and ignoring timing and tone, so the comp sounds stitched together", "Deleting alternate playlists too early, losing options needed later"], "scenario_contexts": ["Building a final lead vocal from ten recorded passes", "Comping a chorus where each take nailed a different phrase", "Assembling a tight double from several stacked takes"]}, "1262f4ec-0793-4e1d-b563-e4e9a246621a": {"definition": "The correction of low-frequency pops caused by plosive consonants (p, b, t) forcing air into the microphone, typically by high-pass filtering just the affected word, drawing volume automation over the burst, or attenuating the low-frequency transient in an editor.", "plain_english": "Fixing the loud pop a mic catches on P and B sounds. You cut the low thump with a filter or turn that split-second down.", "purpose_function": "It removes the distracting low-end thumps plosives create so the vocal sits cleanly in the mix without bursts of boom.", "practical_application": "When a p pops on an otherwise perfect take, the engineer draws a quick volume dip or high-passes just that syllable instead of re-recording the line.", "category": "Vocal Editing", "related_terms": ["Pop filter", "High-pass filter", "Proximity effect", "Vocal production", "Volume automation"], "common_mistakes": ["Applying a broad high-pass across the whole track, thinning the vocal's body instead of just killing the pop", "Assuming a pop filter always prevents plosives so no cleanup is ever needed", "Cutting the entire word rather than just the low-frequency burst beneath it"], "scenario_contexts": ["Cleaning a plosive on a keeper vocal take", "Repairing pops on a close-miced rap vocal", "Fixing wind bursts on a live vocal recording"]}, "6677839c-f9da-4fe6-99ba-10ca196c10f1": {"definition": "Boosting the upper-midrange presence band of a vocal, roughly 2-8 kHz and often centered around 3-5 kHz, with equalization to increase clarity, articulation, and intelligibility so the voice cuts through a dense mix.", "plain_english": "Adding a small boost in the high-mid range so words sound clear and up front. It helps the voice stand out over the band.", "purpose_function": "It lifts the frequencies where consonants and vocal detail live, improving intelligibility and making the vocal feel closer and more present.", "practical_application": "When a vocal sounds buried, the engineer adds a broad EQ boost around 3-5 kHz, listening in the full mix so it does not turn harsh.", "category": "Vocal Processing", "related_terms": ["Equalization", "Presence", "De-essing", "Vocal production", "Intelligibility"], "common_mistakes": ["Boosting presence too hard, which adds harshness and exaggerates sibilance", "Trying to fix a dull vocal with EQ alone when the take or mic choice is the real problem", "Judging the boost solo instead of in the full mix"], "scenario_contexts": ["Helping a lead vocal cut through a loud guitar mix", "Adding clarity to a dark-sounding vocal take", "Matching the presence of a comped vocal to a bright reference track"]}, "89f4c200-14b9-40d7-ba9f-1c725badcd31": {"definition": "The overall craft of capturing and shaping a sung vocal, spanning performance direction, take selection and comping, tuning, timing correction, editing, and mix processing, to deliver a finished vocal track.", "plain_english": "The whole job of turning a singer's takes into a polished vocal. It covers recording, picking the best bits, tuning, and mixing.", "purpose_function": "It exists to turn raw performances into a controlled, expressive, mix-ready vocal that serves the song and holds the listener's attention.", "practical_application": "A vocal producer coaches the singer during tracking, then comps, tunes, times, and processes the result into the final lead and backing vocals.", "category": "Vocal Production", "related_terms": ["Vocal playlist comp", "Vocal pitch map", "Comping", "Mixing", "Tracking"], "common_mistakes": ["Relying on editing and tuning to rescue a weak performance instead of getting a better take", "Over-processing until the vocal sounds artificial and lifeless", "Neglecting arrangement and levels of backing vocals around the lead"], "scenario_contexts": ["Producing lead and backing vocals for a pop song", "Directing a singer during a tracking session", "Preparing a comped, tuned vocal for the mix engineer"]}, "2f29e2f7-4d40-43fe-bc06-c760708bb3c9": {"definition": "Techniques that counter the low-frequency boost a directional (cardioid) microphone produces as a singer works close to it, using a high-pass filter, a low-shelf cut, greater mic distance, or an omnidirectional pattern to restore a balanced tone.", "plain_english": "Cutting the extra boom you get when a singer sings very close to a directional mic. You use a filter, more distance, or a different mic pattern.", "purpose_function": "It keeps the vocal from turning bass-heavy and muddy when the singer is close, preserving clarity and a consistent tone as they move.", "practical_application": "On a close-miced vocal that sounds boomy, the engineer rolls off the lows with a high-pass filter or asks the singer to back off the mic slightly.", "category": "Vocal Processing", "related_terms": ["Proximity effect", "High-pass filter", "Cardioid", "Microphone technique", "Vocal plosive repair"], "common_mistakes": ["Using a very high high-pass corner that thins the vocal instead of just taming the buildup", "Blaming the mic or preamp when the real cause is working distance and pattern", "Ignoring that omnidirectional patterns show little proximity effect and could solve it at the source"], "scenario_contexts": ["Taming boom on a crooner singing into a large-diaphragm cardioid", "Controlling low buildup on a handheld vocal mic held tight to the lips", "Setting a high-pass on a close-miced backing vocal"]}, "5c63b2b4-81ca-4ae1-b8b0-6dc4b891dc33": {"definition": "Editing the timing of note and word endings (releases) in a vocal so that doubled, stacked, or comped parts stop together, keeping layered vocals tight and consonants such as final t and s synchronized.", "plain_english": "Making sure doubled vocals end their words at the same moment. If one track holds a note longer, you trim it so both release together.", "purpose_function": "It tightens layered vocals by matching where phrases end, so overlapping consonants and note tails line up instead of smearing or flamming.", "practical_application": "When a double vocal ends words slightly late, the engineer nudges or trims each release so the final consonants of both tracks hit as one.", "category": "Vocal Editing", "related_terms": ["Vocal playlist comp", "Double tracking", "Time alignment", "Sibilance", "Vocal production"], "common_mistakes": ["Aligning note starts but ignoring the releases, so word endings still flam", "Trimming so aggressively that natural breaths and tails are lost", "Editing releases without crossfades, leaving clicks at the cuts"], "scenario_contexts": ["Tightening a doubled lead vocal", "Syncing the final consonants of stacked backing vocals", "Cleaning phrase endings across a comped chorus"]}, "d33f411d-936d-4342-ae52-4ab776d5b062": {"definition": "The reduction of narrow resonant frequency peaks in a vocal, such as harsh or ringing tones from the voice or recording room, usually with narrow or dynamic EQ cuts applied only when those frequencies become excessive.", "plain_english": "Taming the few harsh, ringing notes that jump out of a vocal. You use a narrow EQ cut, often one that only reacts when that tone gets too loud.", "purpose_function": "It smooths out isolated peaks that make a vocal sound harsh or nasal, without dulling the whole tone the way a broad cut would.", "practical_application": "The engineer sweeps a narrow EQ band to find a ringing frequency, then dips it, often using dynamic EQ so the cut only engages on loud peaks.", "category": "Vocal Processing", "related_terms": ["Dynamic EQ", "Equalization", "De-essing", "Resonance", "Vocal presence enhancement"], "common_mistakes": ["Making static cuts so deep the vocal turns hollow on notes that were not actually harsh", "Confusing sibilance, which is best handled by de-essing, with midrange resonance", "Chasing every small peak until the vocal loses its natural character"], "scenario_contexts": ["Taming a nasal honk around 1 kHz on a lead vocal", "Controlling room ring captured on a home-studio take", "Smoothing a harsh peak that only appears on loud belted notes"]}, "5d96a438-633f-42af-8f83-8e9884ff700e": {"definition": "An auxiliary send that routes a portion of the vocal signal to a reverb processor on a separate bus, letting the engineer blend ambience with the dry vocal and feed one shared reverb from multiple sources.", "plain_english": "A control that sends some of the vocal to a reverb effect on its own channel. It adds space and lets you dial in the ambience without changing the dry voice.", "purpose_function": "Using a send instead of an insert keeps the dry vocal intact, gives independent control of the wet-to-dry blend, and lets several tracks share the same reverb for a unified space.", "practical_application": "The engineer raises the vocal's reverb-send level to taste and sets the return level, often automating extra send on phrase ends for depth.", "category": "Vocal Mixing", "related_terms": ["Auxiliary send", "Reverb", "Effects bus", "Return", "Wet/dry"], "common_mistakes": ["Placing the reverb on an insert with a wet-heavy mix, losing independent control of the blend", "Feeding a bright vocal full-range into reverb, causing a washy, sibilant tail", "Forgetting to bring up the reverb return so the send appears to do nothing"], "scenario_contexts": ["Adding hall reverb to a ballad lead vocal", "Sharing one plate reverb across lead and backing vocals", "Automating more reverb send on the last word of each phrase"]}, "a835410c-4a12-4bde-8e69-26dbe100062c": {"definition": "The practice of manually adjusting a lead or backing vocal's level in real time, either by moving a fader during a pass or by drawing volume automation, so every word sits at a consistent, intelligible level within the mix.", "plain_english": "Moving the volume up and down on a vocal by hand so no word gets lost or too loud. It is like turning up the TV for a quiet whisper and back down for a shout, so you always hear the words clearly.", "purpose_function": "It keeps the vocal steady and clear over a changing backing track, catching soft words a compressor would miss and taming loud ones without the pumping a heavy compressor can add. It exists because musical phrasing varies too much for level alone to be handled by dynamics processing.", "practical_application": "An engineer records fader moves or draws clip-gain and volume automation phrase by phrase, often riding before the compressor so the compressor sees a more even signal and works less hard.", "category": "Vocal Processing", "related_terms": ["Vocal serial compression", "Vocal sidechain compression", "Automation", "Fader", "Gain staging", "Compression"], "common_mistakes": ["Relying only on a compressor for level control instead of riding, which leaves quiet consonants buried and forces heavy gain reduction", "Riding after the compressor when the goal was to feed it a steadier signal, undoing the benefit", "Making moves too coarse or too fast so the ride sounds unnatural or audibly steps"], "scenario_contexts": ["Bringing up dropped word endings in a soft verse before a loud chorus", "Evening out a singer who leans in and out of the mic during a dynamic take", "Feeding a smoother signal into a compressor so it reacts gently instead of clamping down"]}, "76de6815-a866-44d4-a6ae-e66036a289ae": {"definition": "The editing practice of making the quiet background ambience under a vocal consistent across edits, comps and punch-ins by inserting or level-matching room tone, so joins between takes do not reveal an audible change in the noise floor.", "plain_english": "Making the quiet background hiss under a vocal sound the same all the way through, so edits do not click or jump. It is like patching a wall so the paint matches and you cannot see where the repair is.", "purpose_function": "It hides edit points and silences by keeping the natural room sound continuous, which stops the listener from hearing sudden gaps or shifts in background noise. It exists because splicing takes recorded at different moments or in gated silence otherwise creates jarring holes in the ambience.", "practical_application": "An editor captures a few seconds of the room's tone during the session, then pastes or crossfades it under muted gaps and across take boundaries, matching its level so the noise floor stays even.", "category": "Vocal Editing", "related_terms": ["Vocal syllable editing", "Room tone", "Comping", "Crossfade", "Noise floor", "Punch-in"], "common_mistakes": ["Using a hard gate or absolute silence between phrases, which makes the background drop out and edits stand out", "Pasting room tone from a different session or room whose tone does not match", "Forgetting to crossfade the room-tone joins, leaving clicks at the splice points"], "scenario_contexts": ["Filling gaps between lines in a comped lead vocal so the background stays continuous", "Smoothing a punch-in where the fixed word was recorded on a different day", "Cleaning up breath and mouth noise so the edited spots do not sound like dead holes"]}, "2480e595-3e30-4a47-a475-1fd5b29e4964": {"definition": "The deliberate addition of harmonic distortion to a vocal, using tube, tape or analog-modeling processors, to add harmonics and gentle dynamic compression that make the voice sound warmer, denser and more present without a large level increase.", "plain_english": "Adding a touch of warm, controlled distortion to a vocal to make it sound fuller and richer. It is like toasting bread: the same slice, but browned so it has more flavor and character.", "purpose_function": "It generates extra harmonics that add richness and help a vocal cut through a dense mix, while its soft compression rounds off peaks. It exists because a clean, dynamically flat vocal can sound thin or dull against a loud band.", "practical_application": "An engineer inserts a saturation, tube or tape plug-in on the vocal and drives it lightly, often in parallel, listening for added warmth and presence while avoiding obvious grit or harshness.", "category": "Vocal Processing", "related_terms": ["Vocal serial compression", "Harmonic distortion", "Parallel processing", "Tape emulation", "Compression", "Overdrive"], "common_mistakes": ["Driving the saturation so hard the vocal sounds gritty or fizzy instead of warm", "Adding saturation on every stage until harshness and sibilance build up", "Judging saturation soloed instead of in the mix, where a little goes a long way"], "scenario_contexts": ["Warming up a clean digital vocal so it sits better with an analog-style track", "Helping a soft vocal cut through a loud rock mix without just raising its level", "Adding density to a lead vocal in parallel so the dry take stays intact"]}, "e2c42e05-5a9d-45ec-8978-4af658b1fcf1": {"definition": "A vocal dynamics technique that chains two or more compressors in series, each applying only a small amount of gain reduction, so the overall control is heavier yet more transparent than forcing a single compressor to do all the work.", "plain_english": "Using two or more compressors on a vocal, one after another, each doing just a little. This works better than one compressor doing all the work. It is like two people sharing a heavy box, so neither one strains.", "purpose_function": "Spreading the gain reduction across several stages tames a wide dynamic range without the obvious pumping or squashing a single hard-working compressor produces. It exists because vocals often need a lot of control, and one compressor pushed that far sounds unnatural.", "practical_application": "An engineer places a slower compressor to catch broad level swings and a faster one to catch quick peaks, setting each for only a few decibels of gain reduction so their effects add up gently.", "category": "Vocal Processing", "related_terms": ["Vocal ride", "Vocal saturation", "Compression", "Gain reduction", "Limiter", "Attack and release"], "common_mistakes": ["Setting each compressor for heavy gain reduction, which stacks up and over-squashes the vocal", "Using two compressors with identical settings instead of giving each a distinct job", "Chaining more stages to fix a level problem that a fader ride would solve more cleanly"], "scenario_contexts": ["Controlling a singer with a very wide loud-to-soft range for a dense pop mix", "Getting a consistent, upfront lead vocal without obvious pumping", "Combining a leveling compressor with a fast peak compressor on a rap or spoken vocal"]}, "598cb6a0-eced-4511-a31f-a23871a6e164": {"definition": "The practice of controlling harsh 's', 'sh' and 't' sounds on a vocal by drawing targeted volume or gain automation on just those consonants, as an alternative or complement to a de-esser, so each sibilant is tamed by exactly the amount it needs.", "plain_english": "Turning down only the sharp 'ess' and 'shh' sounds in a vocal by hand, spot by spot. It is like dabbing down just the shiny spots on a photo instead of dimming the whole picture.", "purpose_function": "It removes piercing sibilant peaks precisely where they occur while leaving the rest of the vocal untouched, avoiding the lisping or dulling a heavy de-esser can cause. It exists because sibilance varies word to word and a single automatic setting rarely fits every one.", "practical_application": "An engineer zooms in on each harsh consonant and draws a short dip in clip gain or volume automation, or automates a de-esser's threshold, listening so the 's' softens without turning into an 'f' or 'th'.", "category": "Vocal Editing", "related_terms": ["Vocal syllable editing", "Vocal ride", "De-esser", "Sibilance", "Automation", "Clip gain"], "common_mistakes": ["Cutting sibilants so far they turn into a lisp, making 's' sound like 'th'", "Automating whole-word dips instead of targeting only the sibilant, dulling the consonant", "Relying on one de-esser setting for a whole track when sibilance level changes line to line"], "scenario_contexts": ["Taming a few piercing 's' sounds a de-esser missed on a bright pop vocal", "Smoothing sibilance on a close-miked whispery vocal that trips a de-esser too easily", "Fixing harsh consonants on a doubled or layered vocal where sibilance stacks up"]}, "5306902e-20a5-4f18-ac1b-d6d97b893781": {"definition": "A technique in which a compressor's gain reduction is triggered by the vocal signal fed to its sidechain input, so that another element such as a synth, pad or reverb return automatically ducks in level whenever the vocal is present and recovers when it stops.", "plain_english": "The vocal itself makes another sound get quieter whenever the singer sings. It is like a car radio that turns down the moment someone talks, then back up when they stop.", "purpose_function": "It carves space for the vocal by dipping competing parts only while the singer is active, keeping words clear without permanently lowering those parts. It exists because busy backing elements can mask a vocal, and manual level juggling every phrase is tedious.", "practical_application": "An engineer routes the vocal to the sidechain (key) input of a compressor placed on the part to be ducked, then sets threshold and release so that element drops a couple of decibels under the vocal and returns smoothly in the gaps.", "category": "Vocal Processing", "related_terms": ["Vocal ride", "Vocal serial compression", "Sidechain", "Ducking", "Compression", "Bus routing"], "common_mistakes": ["Confusing sidechain ducking with putting a compressor directly on the vocal", "Setting release too fast so the ducked part audibly pumps between words", "Ducking so deeply the backing part disappears instead of just making room"], "scenario_contexts": ["Dipping a wide synth pad or reverb wash under the lead vocal so lyrics stay clear", "Ducking a music bed under a voiceover in broadcast or podcast work", "Keeping a busy guitar or keyboard layer from masking the vocal in a dense chorus"]}, "9fae88c3-4efd-4c0b-bc89-78d4b5d18485": {"definition": "A single short, discrete echo applied to a vocal, typically delayed roughly 80 to 150 milliseconds with little or no feedback, producing one distinct repeat rather than a decaying reverb tail; it is the classic rockabilly and early rock-and-roll vocal effect.", "plain_english": "One quick echo added just after a vocal, like a fast bounce back. Think of shouting toward a nearby wall and hearing a single clear repeat, not a long fading echo.", "purpose_function": "It thickens and energizes a vocal and adds a sense of space and vintage character while staying rhythmic and out of the way, because it is one repeat rather than a wash of reverb. It exists as a period-accurate way to make a dry vocal feel bigger without muddying the mix.", "practical_application": "An engineer sets a delay to a single repeat around 80 to 150 milliseconds with feedback near zero, then blends it under the dry vocal, sometimes tuning the time to the song's tempo for a musical bounce.", "category": "Vocal Effects", "related_terms": ["Vocal spread", "Delay", "Reverb", "Feedback", "Doubling", "Pre-delay"], "common_mistakes": ["Adding feedback so the delay repeats several times instead of the single slap", "Setting the delay so short it flams or so long it sounds like a separate word", "Mixing the slap so loud it competes with the dry vocal instead of supporting it"], "scenario_contexts": ["Getting a rockabilly or early rock-and-roll vocal sound on a lead take", "Adding vintage energy and space to a dry vocal without long reverb", "Timing a single delay to tempo so the repeat locks with the groove"]}, "41a4dee8-c47c-43a9-ba16-fa4ce01ecf8d": {"definition": "The widening of a vocal's stereo image so it occupies more of the left-right field, achieved through techniques such as hard-panned doubles, short stereo delays, pitch-based stereo wideners or micro-timing offsets, most often applied to backing vocals.", "plain_english": "Making a vocal sound wide across the left and right speakers instead of coming from one spot in the middle. It is like a choir spread across a stage rather than one person standing dead center.", "purpose_function": "It creates a bigger, more enveloping vocal and frees the center for the lead by pushing supporting voices out to the sides. It exists because backing vocals and effects sound fuller and less cluttered when they surround the lead rather than stacking on top of it.", "practical_application": "An engineer hard-pans doubled takes left and right, or applies a stereo widener or short offset delay to backing vocals, checking mono compatibility so the widening does not collapse or thin out.", "category": "Vocal Effects", "related_terms": ["Vocal slapback", "Doubling", "Stereo width", "Panning", "Mono compatibility", "Haas effect"], "common_mistakes": ["Widening with out-of-phase tricks that cancel and vanish when the mix is summed to mono", "Spreading the lead vocal so wide it loses its solid center focus", "Over-widening backing vocals until they sound hollow or disconnected from the track"], "scenario_contexts": ["Panning doubled backing vocals wide to build a lush chorus around a centered lead", "Adding width to a harmony stack so it wraps around the lead vocal", "Checking a widened vocal in mono to confirm it still holds up for club or broadcast playback"]}, "06b22a27-bedb-4f0a-a97b-05cbbed80d74": {"definition": "Detailed editing of a recorded vocal at the level of individual syllables, cutting, nudging, crossfading, retiming or replacing them to fix timing, comp the best pieces of multiple takes, or tighten phrasing without re-recording.", "plain_english": "Editing a vocal one syllable at a time to fix timing or swap in the best bits from different takes. It is like cutting and rearranging words in a document to make a sentence read just right.", "purpose_function": "It lets an engineer perfect timing and assemble a flawless performance from several takes when a whole-phrase edit is too coarse. It exists because a single syllable can be late, weak or flat while the rest of the line is perfect.", "practical_application": "An editor zooms in, splits the vocal at syllable boundaries, then slides, stretches or crossfades those pieces, matching room tone and level so the joins are inaudible.", "category": "Vocal Editing", "related_terms": ["Vocal room-tone matching", "Vocal sibilance automation", "Comping", "Crossfade", "Time stretching", "Pitch correction"], "common_mistakes": ["Cutting across a syllable's breath or tail so the edit clicks or sounds chopped", "Skipping crossfades at splice points, leaving audible pops", "Over-editing until the vocal loses its natural flow and feel"], "scenario_contexts": ["Nudging a late syllable back into time on an otherwise great take", "Comping the best syllables from several passes into one clean lead vocal", "Tightening a doubled or stacked vocal so the layers line up word for word"]}, "b3ee3be6-2ded-4b4f-8d31-73c525ffa993": {"definition": "A vocal comping and editing technique in which a single syllable or short phonetic segment from an alternate take is spliced into the chosen lead vocal to repair a flawed word, pitch, or consonant without re-recording the entire line.", "plain_english": "Swapping just one bad syllable in a sung line for the same syllable from another take. It is like fixing one wrong letter in a sentence instead of rewriting the whole thing.", "purpose_function": "It lets an engineer repair a small vocal flaw while keeping the rest of a strong, emotional performance intact, saving time and avoiding a full re-record.", "practical_application": "In a DAW the engineer finds a matching syllable on another take lane, trims it at zero crossings, crossfades it into the comp, and matches its level, tone, and timing.", "category": "Vocal editing", "related_terms": ["Vocal comping", "Crossfade", "Vocal timing pass", "Vocal tuning pass", "Punch-in"], "common_mistakes": ["Cutting away from a zero crossing so the edit clicks or pops", "Not crossfading the join, leaving an audible seam", "Using a syllable whose tone, level, or room sound does not match the surrounding words", "Fixing the pitch but ignoring that the replacement lands slightly off the beat"], "scenario_contexts": ["A lead vocal is perfect except for one mispronounced word that is patched from an earlier take", "A single flat note on one syllable is replaced rather than tuned", "A popped or distorted consonant is swapped for a clean version from another pass"]}, "1e7ddcf5-d4af-48a1-8ad9-e914d6e76766": {"definition": "An organizational grid that maps multiple recorded vocal takes against the song's sections or phrases, used to track, rate, and select the strongest segments when building a composite (comp) vocal.", "plain_english": "A chart that lines up every vocal take against each part of the song. It helps you spot the best-sung version of each line, a bit like a scorecard.", "purpose_function": "It gives the engineer and artist a clear overview so the best moments from many takes can be found and combined without losing track of what was recorded.", "practical_application": "Engineers keep ratings and notes for each take against each section, often using DAW take lanes or playlists, then use that map to guide their comp choices.", "category": "Vocal comping", "related_terms": ["Vocal comping", "Take lane", "Playlist", "Vocal syllable replacement", "Comp track"], "common_mistakes": ["Recording many takes but never labeling or rating them, making the matrix useless", "Choosing takes only by pitch and ignoring timing or emotion", "Deleting alternate takes too early before the comp is finished", "Comping across so many takes that phrasing no longer feels natural"], "scenario_contexts": ["A producer compares six chorus takes line by line before comping", "An assistant labels and rates takes so the mixer can find keepers fast", "A remote artist and engineer use shared notes to agree on the best segments"]}, "63a14ec3-5a4d-432c-8443-c633f8af54a3": {"definition": "A reference outline of the intended rhythmic placement of vocal words or syllables against the song's grid, tempo, or a guide track, used as a target when aligning edited or corrected vocal timing.", "plain_english": "A plan that shows where each word should land in the beat. You use it as a target when nudging vocal timing into place.", "purpose_function": "It defines a consistent timing reference so multiple vocal layers or edited phrases line up tightly with each other and with the music.", "practical_application": "An engineer marks the target positions for key words or downbeats, then moves or stretches vocal segments to match those points during editing.", "category": "Vocal editing", "related_terms": ["Vocal timing pass", "Time stretching", "Quantize", "Guide track", "Vocal comping"], "common_mistakes": ["Forcing every syllable dead onto the grid so the vocal sounds robotic", "Ignoring that lead and backing vocals may need slightly different placement", "Mapping timing to a click when the band plays with natural push and pull", "Confusing a timing reference with pitch correction"], "scenario_contexts": ["Doubled vocals are aligned to one reference take before mixing", "Stacked harmonies are tightened so consonants hit together", "Edited phrases are checked against the beat before a tuning pass"]}, "8adf87f0-b33e-4917-8e5f-6e6c65236e66": {"definition": "A dedicated editing pass in which the engineer moves, stretches, or nudges vocal words and syllables so their rhythmic placement aligns with the beat, a guide track, or other vocal layers.", "plain_english": "A round of edits focused only on when each word lands. It is like sliding words a little earlier or later so they sit right on the beat.", "purpose_function": "It tightens the rhythmic feel of a vocal and locks stacked or doubled parts together, which helps the vocal sit cleanly in the mix.", "practical_application": "Using DAW editing and time-stretching tools, the engineer works phrase by phrase to fix late or early entries while keeping the performance sounding natural.", "category": "Vocal editing", "related_terms": ["Vocal timing map", "Time stretching", "Quantize", "Vocal comping", "Crossfade"], "common_mistakes": ["Over-tightening until the vocal loses its groove and feel", "Time-stretching so far that artifacts and warble appear", "Cutting off breaths or consonants when sliding segments", "Doing timing edits after tuning, which can undo careful pitch work"], "scenario_contexts": ["Loose double-tracked vocals are aligned to the lead", "A rushed verse entry is pulled back onto the beat", "Backing harmonies are tightened before the tuning pass"]}, "b1915d7d-cc5b-4ce3-b604-aba5ffe313b2": {"definition": "Processing a vocal with a transient shaper to increase or reduce the attack, and sometimes sustain, of word onsets and consonants, controlling clarity and punch independently of the overall level or threshold.", "plain_english": "Using a tool to make the start of each word softer or sharper. It is like turning the bite of the singer's words up or down.", "purpose_function": "It shapes how the front edge of vocal sounds cuts through a mix, adding articulation when a vocal is dull or softening harsh, spiky consonants.", "practical_application": "An engineer inserts a transient designer on the vocal and adjusts attack to bring out or tame consonant onsets, often alongside EQ and de-essing.", "category": "Vocal processing", "related_terms": ["Transient designer", "De-essing", "Compression", "Equalization", "Vocal upward compression"], "common_mistakes": ["Pushing attack so hard that consonants become harsh or clicky", "Reducing attack until the vocal sounds mushy and unclear", "Using it to replace EQ or de-essing rather than working with them", "Applying heavy shaping before checking the raw recording quality"], "scenario_contexts": ["A soft-sung vocal needs more articulation to be heard in a dense mix", "Overly sharp consonants are softened for a smoother lead", "Rap or spoken vocals are sharpened for extra punch"]}, "241fa144-2edc-47f4-99e5-1c02a2b41035": {"definition": "An editing pass using pitch-correction software such as Melodyne or Auto-Tune to move off-pitch vocal notes toward their intended pitches, correcting intonation while preserving the singer's phrasing.", "plain_english": "A round of fixing notes that are slightly out of tune. Software nudges each note to the right pitch, like snapping it to the correct key.", "purpose_function": "It corrects intonation problems so a strong performance can be kept, and it can also create a deliberate tuned effect when applied hard.", "practical_application": "The engineer loads the vocal into a pitch editor, sets the key and scale, then corrects notes by hand or with retune speed, checking that vibrato and character stay natural.", "category": "Vocal editing", "related_terms": ["Pitch correction", "Formant", "Vocal vowel editing", "Vocal timing pass", "Vocal comping"], "common_mistakes": ["Setting retune speed so fast that natural vibrato is flattened", "Correcting to the wrong key or scale and making notes sound worse", "Over-tuning until the vocal sounds artificial when a natural sound was wanted", "Tuning before timing edits, which can shift the corrected notes"], "scenario_contexts": ["A few flat notes in an otherwise great take are pulled into tune", "Stacked harmonies are tuned to lock the chord together", "A hard, obvious tuned effect is applied as a creative choice"]}, "d0df2ce3-5bee-456c-9ea8-306e10fc89f2": {"definition": "Dynamic processing that raises the level of the quietest parts of a vocal rather than lowering the loudest, reducing dynamic range from the bottom up to bring out low-level detail such as breaths and word tails.", "plain_english": "A way to make the quiet parts of a vocal louder without squashing the loud parts. It lifts the soft bits up so every word can be heard.", "purpose_function": "It evens out a vocal's dynamics and increases perceived intimacy and consistency without the pumping that heavy downward compression can cause.", "practical_application": "Engineers use upward-compression modes or parallel setups to boost quiet passages, helping a whispered or uneven vocal stay present in the mix.", "category": "Vocal processing", "related_terms": ["Compression", "Parallel compression", "Downward compression", "Dynamic range", "Vocal transient shaping"], "common_mistakes": ["Raising the noise floor and hiss along with the quiet vocal", "Pushing it so far the vocal sounds squashed and lifeless", "Confusing it with normal downward compression and setting the wrong threshold direction", "Using it to rescue a poorly recorded track instead of fixing the source"], "scenario_contexts": ["A soft, breathy verse is lifted so quiet words stay audible", "An uneven performance is smoothed without obvious pumping", "A vocal is prepared to sit at a consistent level for broadcast"]}, "9be7cd38-a85e-4880-a003-e83f70eb99ca": {"definition": "Editing the sustained vowel portions of vocal notes, adjusting their pitch, formant, length, or level in a pitch editor, to refine tone and intonation while leaving the consonants largely untouched.", "plain_english": "Changing the held vowel sounds inside words, like the ah or ee. You can shift their pitch or length to smooth a note without touching the sharp consonants.", "purpose_function": "It gives fine control over the most tonally important part of a sung note, letting an engineer correct pitch drift or reshape vowels without disturbing word attacks.", "practical_application": "In a pitch editor the engineer separates the vowel body of a note and adjusts its center pitch, formant, or transition to smooth intonation and blend stacked vocals.", "category": "Vocal editing", "related_terms": ["Formant", "Vocal tuning pass", "Pitch correction", "Vocal comping", "Time stretching"], "common_mistakes": ["Shifting formants so far the singer sounds unnatural or chipmunk-like", "Editing the vowel but leaving an audible pitch jump at the consonant", "Flattening natural vowel movement so the note sounds static", "Over-editing many notes until the whole vocal loses its human feel"], "scenario_contexts": ["A vowel that drifts flat in a held note is centered on pitch", "Stacked harmonies are matched so their vowels blend", "A vowel formant is nudged to make a doubled vocal sound less identical"]}, "896a6604-a72d-4f81-aa5b-627eae0a5386": {"definition": "Tonal processing that increases the body and low-mid harmonic content of a vocal, using EQ, harmonic saturation, or tube and tape emulation, to make it sound fuller and less thin or harsh.", "plain_english": "Making a voice sound fuller and rounder instead of thin or harsh. Engineers add a little low-mid boost or gentle saturation, like adding a cozy glow.", "purpose_function": "It adds perceived richness and pleasing harmonics so a vocal feels close and full-bodied, helping a thin or clinical recording sit better in the mix.", "practical_application": "The engineer applies gentle low-mid EQ boosts and light harmonic saturation or a tube emulation, listening in the full mix to avoid muddiness.", "category": "Vocal processing", "related_terms": ["Equalization", "Harmonic saturation", "Compression", "Proximity effect", "Vocal transient shaping"], "common_mistakes": ["Boosting low-mids until the vocal sounds boxy or muddy", "Adding heavy saturation that turns into audible distortion", "Judging warmth on the solo vocal instead of in the full mix", "Using processing to fix a dull recording that a better mic or source would solve"], "scenario_contexts": ["A thin, bright vocal is given more body to sit with a warm track", "A digital-sounding recording gets gentle tube emulation for character", "A distant vocal is warmed to feel closer and more intimate"]}, "e0823ff4-282b-49d8-8eb6-f3ad59ea6ebc": {"definition": "The practice of setting how wide a vocal part sits across the stereo field, using panning of doubles and layers, stereo effects, or mid/side processing to control the perceived spread between the left and right speakers.", "plain_english": "It means setting how far a voice spreads out between the left and right speakers. A lead vocal is usually kept in the middle, while copies and harmonies are spread out wide to sound big.", "purpose_function": "It lets an engineer keep the lead vocal firmly in the center while spreading supporting layers outward, shaping focus, size, and how the vocal fits around the other instruments.", "practical_application": "An engineer pans doubles and harmony stacks left and right, or uses a stereo widener, then checks the result in mono to make sure the vocal still holds together.", "category": "Vocal production", "related_terms": ["Wide doubling", "Vocal-stack arrangement", "Vocal-stack blend", "Panning", "Stereo image"], "common_mistakes": ["Panning the lead vocal wide, which pulls it off center and weakens its focus.", "Widening so much that the vocal loses power or thins out when the mix is summed to mono.", "Confusing stereo width with reverb depth; width is left-to-right, not front-to-back."], "scenario_contexts": ["Spreading doubled backing vocals hard left and right to make a chorus feel big.", "Keeping a lead vocal centered while widening its harmony stack in a pop mix.", "Checking a widened vocal in mono to confirm it still translates on a phone speaker."]}, "c2c20b3a-ca73-4838-8698-aaeda016802b": {"definition": "A vocal editing technique in which a single word, syllable, or short phrase in a chosen take is swapped for the same word taken from another take, to fix a flubbed lyric, poor tuning, or weak delivery without re-recording the whole part.", "plain_english": "It is fixing one bad word in a vocal take by dropping in the same word from another take. It saves the singer from redoing a whole line just to fix one slip.", "purpose_function": "It lets an engineer repair small problems in an otherwise great performance, keeping the best overall take while patching only the weak moment.", "practical_application": "During comping, the engineer finds a matching word from an alternate take, places it at a zero-crossing or quiet gap, and crossfades the joins so the swap is inaudible.", "category": "Vocal editing", "related_terms": ["Comping", "Crossfade", "Punch-in", "Zero-crossing", "Vocal-stack arrangement"], "common_mistakes": ["Splicing in a word with a different pitch or tone, so the edit sticks out.", "Cutting on a loud part of the waveform instead of a zero-crossing, which causes a click.", "Forgetting to match the room sound or breath, so the replaced word feels pasted in."], "scenario_contexts": ["Replacing a mispronounced word in the second verse using the same word from another take.", "Swapping a flat-sounding syllable for a better one before tuning the vocal.", "Patching a single word after the singer has already left the session."]}, "4497d5a1-2cd2-4654-a381-7680eb2b23c2": {"definition": "The way multiple recorded vocal layers, such as leads, doubles, octaves, and harmonies, are chosen, assigned, and organized within each song section to build a fuller, more produced vocal part.", "plain_english": "It is the plan for how many vocal layers you record and where each one sits in a song. Think of it like stacking voices in a choir so the chorus sounds big while the verse stays simple.", "purpose_function": "It shapes the size and energy of each section, letting quieter verses stay intimate while choruses open up with added doubles and harmonies.", "practical_application": "A producer maps out which parts get single leads versus stacked doubles and harmonies, then tracks each layer cleanly so they can be balanced later.", "category": "Vocal arrangement", "related_terms": ["Vocal-stack blend", "Vocal-stack density", "Wide doubling", "Harmony", "Double tracking"], "common_mistakes": ["Stacking every section the same way, so the chorus no longer feels like a lift.", "Recording harmonies out of tune with each other, which muddies the whole stack.", "Adding so many layers that the lead vocal gets buried."], "scenario_contexts": ["Planning a big stacked chorus and a bare single-vocal verse for a pop song.", "Adding octave-up harmonies only in the final chorus for extra lift.", "Deciding which backing lines to double for a fuller sound."]}, "ba9f8479-b1d9-408b-b85a-885fe44ebdd4": {"definition": "The balance and tonal matching of the individual layers within a stacked vocal so they fuse into one cohesive part rather than a set of separate voices, achieved through relative levels, EQ, panning, timing, and dynamics.", "plain_english": "It is getting all the stacked voices to melt together into one smooth sound. Like a choir where no single singer sticks out, the layers should feel like one big voice.", "purpose_function": "A good blend makes many recorded layers read as a single, rich vocal, so the stack supports the song instead of sounding cluttered.", "practical_application": "The engineer sets relative fader levels, matches EQ and timing across layers, and often buses them together with light compression so they move as one.", "category": "Vocal production", "related_terms": ["Vocal-stack arrangement", "Vocal-stack density", "Vocal width control", "Bus compression", "EQ"], "common_mistakes": ["Leaving one layer much louder than the rest, which breaks the single-voice illusion.", "Skipping timing edits, so loose layers smear the words.", "Over-compressing the stack until it sounds flat and lifeless."], "scenario_contexts": ["Balancing a lead, two doubles, and harmonies into one smooth chorus vocal.", "Bussing a harmony stack and gluing it with gentle compression.", "Matching EQ across layers recorded on different days."]}, "f1d2d389-b7c3-457a-b3cf-39eb14333765": {"definition": "The number and thickness of vocal layers sounding at a given point in a stack, describing how many doubles, octaves, and harmonies play together to create a thin or thick vocal texture.", "plain_english": "It is how many voices are stacked up at once, making the sound thin or thick. A few layers feel light, while many layers feel huge and wall-like.", "purpose_function": "Varying density across a song controls contrast and energy, letting sections grow or shrink in size to serve the arrangement.", "practical_application": "An engineer adds or mutes layers section by section, building density into choruses and thinning it in verses to keep the song dynamic.", "category": "Vocal arrangement", "related_terms": ["Vocal-stack arrangement", "Vocal-stack blend", "Vocal-stack depth", "Wide doubling", "Double tracking"], "common_mistakes": ["Keeping density high the whole way through, so the chorus stops feeling bigger.", "Piling on layers that fight for the same frequencies and turn muddy.", "Confusing more layers with more volume; density is about texture, not just level."], "scenario_contexts": ["Thinning vocal layers in a verse to leave room for the lead.", "Stacking many harmonies in a final chorus for maximum size.", "Building density gradually across a pre-chorus into the drop."]}, "09988a8f-9b24-418d-b8a7-b8440a3f35ca": {"definition": "The sense of front-to-back space among vocal layers in a stack, created with reverb, delay, level, and EQ so some layers sit forward and close while others sit farther back behind the lead.", "plain_english": "It is how near or far each stacked voice sounds. The lead sits up close, while backing layers are pushed back with echo and reverb so they feel behind it.", "purpose_function": "Depth keeps the lead vocal up front and clear while placing supporting layers behind it, giving the stack a three-dimensional feel instead of a flat wall.", "practical_application": "The engineer uses reverb and delay sends, small level cuts, and gentle high-frequency rolloff on backing layers to set them back behind a dry, present lead.", "category": "Vocal production", "related_terms": ["Vocal-stack blend", "Vocal-stack density", "Reverb", "Delay", "Vocal width control"], "common_mistakes": ["Drowning the lead in reverb, which pushes it back with the backing layers.", "Using the same reverb on every layer, so nothing sits in front.", "Confusing depth, which is front-to-back, with width, which is left-to-right."], "scenario_contexts": ["Pushing harmony layers back with reverb while keeping the lead dry and close.", "Using a longer reverb on distant backing vocals in a ballad.", "Layering a soft, far-back vocal behind a present lead for atmosphere."]}, "0d8fdeae-a644-4ab9-ad22-29f5acfbcfb3": {"definition": "The use of automatic gain reduction so a backing vocal stack drops in level whenever the lead vocal is present, keyed from the lead, so the layers make room for the lead and rise back up in the gaps between phrases.", "plain_english": "It means the backing voices automatically dip down whenever the lead sings, then come back up in the gaps. Like backup singers stepping back so you always hear the main voice.", "purpose_function": "It keeps the lead vocal clear and out front even under a thick stack, without the engineer having to ride the backing levels by hand through the whole song.", "practical_application": "The engineer puts a sidechain compressor or volume automation on the backing bus, keyed from the lead vocal, and sets threshold and release so the stack dips only while the lead sings.", "category": "Vocal production", "related_terms": ["Sidechain compression", "Vocal-stack blend", "Ducking", "Automation", "Bus compression"], "common_mistakes": ["Setting too much gain reduction, so the backing vocals pump noticeably.", "Using too fast a release, which causes an audible surge between words.", "Ducking the whole mix instead of just the backing bus."], "scenario_contexts": ["Dipping a harmony stack under the lead in a dense chorus.", "Sidechaining backing vocals so they lift in the gaps between lead lines.", "Keeping a rap ad-lib stack from covering the main vocal."]}, "35207e1c-2df0-41c8-95cb-569ef4b00a61": {"definition": "A production technique in which a vocal or instrument part is performed twice and the two takes are panned toward opposite sides of the stereo field, so the small differences between them create a wider, thicker sound.", "plain_english": "It means recording the same part twice and sending one take to the left and one to the right. The small differences between the two takes make the sound feel wide and full.", "purpose_function": "It broadens and thickens a part across the stereo image, adding size to choruses and backing vocals without simply raising the level of a single centered track.", "practical_application": "The singer performs the line a second time, and the engineer pans the two takes hard left and right at matched levels, then checks the result in mono.", "category": "Vocal production", "related_terms": ["Double tracking", "Vocal width control", "Vocal-stack arrangement", "Panning", "Stereo image"], "common_mistakes": ["Copying one take instead of performing a real second take, which gives no true width.", "Setting the two sides at different levels, which pulls the image to one side.", "Not checking mono, where hard-panned doubles can partly cancel or change tone."], "scenario_contexts": ["Panning two chorus vocal takes hard left and right for a big, wide sound.", "Widening a doubled rhythm guitar in a rock mix.", "Spreading backing vocals across the stereo field behind a centered lead."]}, "e7d40156-960e-41ba-8d7a-1f6bce5335a0": {"definition": "The designation of a particular song or mix as the A-side, the featured and promoted primary track of a single release, as opposed to the secondary B-side. The term originates from the two sides of a vinyl single, the A-side being the side intended for airplay and promotion.", "plain_english": "Picking which song is the main track of a single release, the one meant for radio and promotion. It comes from old records, where the A-side was the hit side.", "purpose_function": "Assigning the A-side sets which track gets priority in mastering, marketing, and delivery, guiding how time and polish are spent.", "practical_application": "When delivering a single, the team confirms the A-side assignment so the lead track is mastered, labeled, and submitted to platforms as the primary release.", "category": "Release workflow", "related_terms": ["Approval master", "Action List", "Anchor the mix", "Active take"], "common_mistakes": ["Thinking the A-side must be the first song recorded rather than the chosen lead track", "Assuming only the A-side needs careful mastering, when the B-side should also meet spec", "Confusing A-side/B-side (release role) with the A/B of monitor or mix comparison"], "scenario_contexts": ["Deciding which single from a session is promoted as the lead A-side", "Labeling and delivering master files with the correct A-side and B-side", "Planning a vinyl single's sides for a release"]}, "6f4f82ad-c2da-49f5-8d14-76974f9a2a77": {"definition": "In Ableton Live, a Live Set is the document that holds a single piece of music: all of its tracks, clips, MIDI and audio, devices, mixer settings and arrangement. It is saved as an .als file inside a Project folder, which also stores the samples and presets the Set references.", "plain_english": "A Live Set is Ableton Live's name for one song file. It keeps all of your tracks, loops, and effect settings together in one place, like a document that saves your whole project so you can open it again later.", "purpose_function": "It gathers every part of a song, such as audio, MIDI, instruments, effects and mix settings, into one saved document so the work can be reopened, edited and shared as a single unit.", "practical_application": "An engineer names and saves the .als Live Set at the start of a session and uses Save As to keep versioned copies inside the Project folder as the mix develops.", "category": "Project File", "related_terms": ["Project folder", "Clip", "Arrangement View", "Session View", "Track", "Template"], "common_mistakes": ["Moving or renaming the .als file out of its Project folder, which can break links to samples so files show as missing when the Set is reopened.", "Assuming that saving the Set also copies in external samples; samples stay referenced in place unless the Set is saved or collected into the Project.", "Confusing a Live Set (a song document) with the Live Library or a Live Pack (collections of content, not a song)."], "scenario_contexts": ["Starting a new song by saving a fresh Live Set into a dated Project folder.", "Reopening a Live Set on another computer after using 'Collect All and Save' so all samples travel with it.", "Exporting the final stereo mix from the finished Live Set."]}, "3de5168e-c3d4-4f24-8461-63dc660b4aef": {"definition": "An automation write behaviour in which fader or control moves are recorded as absolute values that replace any existing automation for that parameter over the duration of the pass, as opposed to Trim (relative) mode, which offsets existing automation by a delta amount.", "plain_english": "With absolute automation, the moves you record become the new values. They wipe out whatever was there before. It works like typing over old text, not nudging each word up or down a bit.", "purpose_function": "It lets an engineer set precise, fixed level or parameter values over time so that playback repeats those exact moves on every pass.", "practical_application": "In Write mode the engineer rides a fader and the DAW stores those exact positions across the whole pass, overwriting any existing moves; Touch and Latch also write absolute values but only while the control is actively moved, so they leave untouched sections intact. To lift an already automated section without erasing its moves, they switch to Trim instead.", "category": "Automation", "related_terms": ["Trim automation", "Write mode", "Touch mode", "Latch mode", "Automation pass", "Fader ride"], "common_mistakes": ["Leaving a track in Write mode and erasing good automation on the next playback pass.", "Confusing Absolute with Trim, then overwriting existing moves instead of offsetting them.", "Forgetting to switch out of Write into Touch or Read after the first pass."], "scenario_contexts": ["Writing a fixed vocal level ride across a chorus.", "Automating a plugin bypass or send level to exact points in a song.", "Redoing a botched move by punching a new absolute pass over it."]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"deb5f716-0039-4891-88b4-71f8408a33e2": {"definition": "The practice of assigning emphasis (an accent) to selected steps or notes in a sequenced pattern, typically as a boost in velocity or level and sometimes in filter or envelope depth, to create dynamic stress and groove; many drum machines and step sequencers provide a dedicated accent function for this.", "plain_english": "Accent programming means telling certain drum hits or notes in a pattern to play stronger than the rest. It is how a stiff, robotic beat gets its groove, a bit like stressing certain syllables when you speak.", "purpose_function": "It adds rhythmic emphasis and dynamic variation to programmed parts so they feel musical and human rather than flat and mechanical.", "practical_application": "A producer sets accent flags, or higher velocity values, on backbeats or key notes in a step sequencer or drum machine so those hits punch through the pattern.", "category": "Sequencing", "related_terms": ["Velocity", "Step sequencer", "Quantization", "Swing", "Drum programming", "Dynamics"], "common_mistakes": ["Accenting too many steps, which flattens the contrast so nothing stands out.", "Confusing an accent (emphasis on chosen hits) with simply raising the whole pattern's level.", "Using a single fixed velocity for every note, which produces a lifeless, machine-like feel."], "scenario_contexts": ["Programming a drum-machine pattern and flagging the snare backbeats as accented.", "Adding accents to a bassline on a step sequencer to shape its groove.", "Humanising a programmed hi-hat part by accenting the off-beats."]}, "dc0302f9-2edc-4c1b-853f-69c1bd3cbf22": {"definition": "The share of a recorded or monitored sound that arises from real acoustic (airborne) sound, the natural tone of an instrument and its room, as distinct from a direct or electronic signal such as a DI feed. It describes how much of the result comes from air-moving sound versus a captured electrical signal.", "plain_english": "The part of a sound that comes from real air moving in a room, like a mic on an instrument, rather than a direct plugged-in signal. It is the natural, in-the-room part of the sound.", "purpose_function": "Separating the acoustic contribution from direct signal lets an engineer blend natural room tone and direct clarity, and control how live or dry a track feels.", "practical_application": "When recording an electric bass or an acoustic-electric guitar, an engineer blends the DI with a mic to dial in the right amount of acoustic contribution.", "category": "Signal sources", "related_terms": ["Direct guitar track", "Re-amping", "Anchor the mix", "Off-axis pickup"], "common_mistakes": ["Ignoring the room's acoustic contribution and wondering why a DI-only track sounds lifeless", "Blending mic and DI without checking polarity, so the acoustic contribution partly cancels", "Assuming a close mic captures no room, when it always adds some acoustic contribution"], "scenario_contexts": ["Blending a bass DI with a mic'd cabinet to add acoustic contribution", "Deciding how much room mic to fold into a drum mix", "Recording an acoustic-electric guitar and balancing pickup with a mic"]}, "a79b2894-d564-4918-9bf4-8c2e77ef626b": {"definition": "In REAPER, the Action List is the searchable window that lists every available command (action) in the program; from it, actions can be run directly, bound to keyboard, MIDI or OSC shortcuts, or combined into custom actions and macros.", "plain_english": "The Action List is REAPER's master menu of every command the program can run. You open it to find a command, run it, or give it a shortcut key. Think of a giant index of every button in the app.", "purpose_function": "It gives one place to find, trigger and assign shortcuts to any function, and to build custom actions or macros, so users can tailor and speed up their workflow.", "practical_application": "An engineer opens the Action List from the Actions menu, searches for a command, assigns it a key or controller button, or chains several actions into one macro for a repetitive editing task.", "category": "Workflow", "related_terms": ["Custom action", "Macro", "Keyboard shortcut", "ReaScript", "Key binding", "Command"], "common_mistakes": ["Assigning a shortcut that collides with an existing binding without noticing the conflict.", "Confusing the Action List with the track or media context menus.", "Building a long macro without saving it as a named custom action, then being unable to reuse it."], "scenario_contexts": ["Binding a rarely used command to a key during a fast editing session.", "Creating a macro that splits, trims and fades a clip in one keystroke.", "Searching the Action List to find a feature whose menu location is unknown."]}, "37fca017-9851-4b64-aefa-0ffb2a21ed3b": {"definition": "In DAW comping, the active take is the single recorded pass currently selected to play back from a take folder (or playlist) that holds several passes; only the active take sounds, and comping assembles a composite performance by choosing which take is active across different sections.", "plain_english": "When you record something several times, all the tries are stored together. The active take is the one you have picked to actually play right now, while the others stay muted underneath.", "purpose_function": "It lets an engineer audition and switch between multiple recorded passes and assemble the best parts into one composite performance without deleting any takes.", "practical_application": "While comping vocals, the engineer clicks to make a chosen take active for each phrase, and the selected segments join into the final comp.", "category": "Comping", "related_terms": ["Take folder", "Comp", "Playlist", "Punch-in", "Quick Swipe Comping", "Take"], "common_mistakes": ["Flattening or deleting the take folder too early and losing the alternate takes.", "Assuming muted takes are gone; they are still there, just inactive.", "Editing the composite before confirming the right take is active for each section."], "scenario_contexts": ["Comping a lead vocal from ten recorded passes.", "Switching the active guitar-solo take to compare two performances.", "Choosing the active take for each line before flattening a comp."]}, "ec26cce4-25c0-4860-b128-8bbee241ed87": {"definition": "A Logic Pro Smart Tempo project-tempo mode (Adapt) in which the project tempo follows the performance: Logic analyses recorded or imported audio or MIDI, leaves the timing of the material intact, and generates a tempo map that matches the material's actual tempo.", "plain_english": "Adapt Project Tempo tells Logic to follow your playing instead of forcing you onto a fixed click. It listens to your recording and bends the song's tempo grid to match how you actually played.", "purpose_function": "It preserves the natural feel and tempo changes of a free performance while still giving the project a matching tempo map, so grids, loops and quantised parts can line up with the real timing.", "practical_application": "A producer records a freely played piano take with Smart Tempo set to Adapt so Logic builds a tempo map from the performance, then adds quantised drums that follow that map.", "category": "Tempo & Sync", "related_terms": ["Smart Tempo", "Tempo map", "Keep mode", "Flex Time", "Beat mapping", "Quantization"], "common_mistakes": ["Leaving Adapt on when you actually want the take conformed to a fixed tempo, which is Keep mode instead.", "Recording against a poor reference and getting a jumpy, wrong tempo map.", "Confusing Adapt (the project follows the performance) with Keep (the performance follows the project)."], "scenario_contexts": ["Capturing a freely played piano intro and building a tempo map from it.", "Importing a live recording made without a click and having the project tempo follow it.", "Preserving natural tempo drift in a singer-songwriter demo."]}, "19ea5180-a0d2-4bb1-9c82-8e695a443782": {"definition": "Digital signal processing whose algorithm parameters adjust themselves in real time from the incoming signal or environment, typically using adaptive filters (for example LMS or RLS) that continuously update their coefficients to minimise an error signal; in audio it underlies tasks such as adaptive feedback suppression, echo and noise cancellation, and room correction.", "plain_english": "Adaptive DSP is processing that changes its own settings to match the sound coming in. It does not use fixed settings; it keeps adjusting itself. Think of cruise control that keeps tweaking the gas to hold one speed.", "purpose_function": "It automatically tracks changing signals or acoustics so the processor stays effective without manual retuning, for example hunting and notching feedback as a room's response shifts.", "practical_application": "A technician relies on a processor's adaptive feedback suppression to detect and notch ringing frequencies during a live event as mic positions and room conditions change.", "category": "Signal Processing", "related_terms": ["Adaptive filter", "Feedback suppression", "Echo cancellation", "Noise gate", "DSP", "Room correction"], "common_mistakes": ["Trusting adaptive feedback suppression to rescue a badly gain-staged or poorly positioned system instead of setting it up properly first.", "Assuming 'adaptive' means no setup is needed; it still needs sensible input levels and limits.", "Letting aggressive adaptive filtering audibly dull or thin the program material."], "scenario_contexts": ["Adaptive feedback suppression on a lectern mic in a reverberant room.", "Acoustic echo cancellation in a conferencing DSP matrix.", "An adaptive room-tuning process tracking changing audience absorption during a show."]}, "51f79031-3841-41f0-8854-06a06279838d": {"definition": "An equalizer that automatically and continuously adjusts its filter response in reaction to the incoming audio, applying gain changes to specific frequency bands only when the signal's spectral content triggers them, rather than holding fixed static settings. It is often called a dynamic EQ.", "plain_english": "A smart tone control that listens to the sound and changes the level of certain pitches by itself, only when needed. It works like a thermostat that heats a room only when it gets too cold, instead of staying on all the time.", "purpose_function": "It lets an engineer tame problem frequencies that come and go, such as a harsh vocal peak, without permanently cutting those frequencies when they are not causing trouble. This keeps the source sounding natural while controlling only the moments that need it.", "practical_application": "A mixer might place an adaptive EQ on a lead vocal so it dips harshness near 3 kHz only on loud, bright words, leaving quieter phrases untouched.", "category": "Equalization", "related_terms": ["Dynamic EQ", "Multiband compression", "Parametric EQ", "De-esser", "Spectral processing", "Sidechain"], "common_mistakes": ["Confusing adaptive EQ with a static EQ and expecting the displayed curve to stay fixed", "Setting thresholds so aggressively that the EQ pumps or dulls the source", "Using it to fix a mic or arrangement problem that should be solved at the source", "Stacking several adaptive processors so their movements fight each other"], "scenario_contexts": ["Controlling sibilance and harshness on a vocal only when it spikes", "Evening out resonant notes on a bass that jump out on certain pitches", "Automatically dipping mud from an acoustic guitar during loud strums"]}, "6a4222dc-f3bd-4118-a071-638814603bd8": {"definition": "Gain that an algorithm adjusts automatically and continuously in response to the measured level or characteristics of the incoming signal, so the amount applied changes over time to reach a target instead of remaining at one fixed setting.", "plain_english": "A volume control that turns itself up or down to keep the sound at a steady level. It works like cruise control in a car, easing off or pressing the gas to hold one speed.", "purpose_function": "It keeps a signal at a usable, consistent level despite changing input, reducing the need to ride the fader by hand and helping quiet parts stay audible while loud parts stay in check.", "practical_application": "On dialogue or a podcast, an engineer may use an adaptive-gain stage to hold speech near a target level as the talker moves closer to or further from the mic.", "category": "Gain & Dynamics", "related_terms": ["Automatic gain control", "Gain staging", "Leveler", "Compressor", "Makeup gain", "Normalization"], "common_mistakes": ["Assuming adaptive gain replaces good gain staging at the input", "Letting it pump up the noise floor and room tone during quiet pauses", "Confusing it with compression, which reshapes dynamics faster and by a set ratio", "Trusting it blindly and not watching meters, so levels drift or feed a system too hot"], "scenario_contexts": ["Holding podcast or broadcast speech at a consistent level", "Smoothing an uneven vocal take before compression", "Managing level on a lavalier mic as a presenter moves around"]}, "0c1adb4c-9ae0-4b36-b28e-734ffff5d708": {"definition": "A musical score, most common in games and interactive media, that changes in real time in response to events or user actions by switching, layering, or reshaping its musical parts on the fly, rather than playing back as one fixed linear recording.", "plain_english": "Background music that changes as you play a video game. It is like a movie soundtrack that speeds up or grows tense on its own when the action does.", "purpose_function": "It keeps the music matched to what is happening moment to moment, so the mood and energy follow the story or gameplay instead of feeling disconnected from it.", "practical_application": "A game audio engineer builds an adaptive score in middleware so calm exploration music adds drums and rises in intensity the instant combat begins, then eases back when the fight ends.", "category": "Interactive Audio", "related_terms": ["Interactive music", "Vertical layering", "Horizontal re-sequencing", "Game audio middleware", "Stem", "Cue"], "common_mistakes": ["Thinking an adaptive score is just a normal linear track set to loop", "Writing music that does not transition smoothly between states", "Forgetting to align musical changes to tempo or bar boundaries, causing jarring jumps", "Overlooking memory and voice limits on the target platform"], "scenario_contexts": ["Video game music that intensifies during combat", "Interactive museum or VR installations that respond to visitors", "Apps or ads whose music reacts to user choices"]}, "73f879dd-b833-4fe6-a714-7c2517f7999f": {"definition": "The use of AI or machine-learning tools to analyze a mix and automatically adjust its loudness to hit a target, usually an integrated loudness in LUFS defined by standards such as ITU-R BS.1770 and EBU R128, often as part of automated mastering or loudness-matching services.", "plain_english": "Software that uses AI to measure how loud a song is and set it to the right level on its own. It aims for the loudness targets that streaming services expect.", "purpose_function": "It speeds up loudness matching and normalization so tracks meet platform targets consistently, without an engineer setting every level by hand.", "practical_application": "An engineer runs a mix through an AI loudness or mastering tool to reach a streaming target, then checks the result against a compliant metering standard.", "category": "Loudness & metering", "related_terms": ["AI mastering", "Adaptive gain", "Adaptive DSP", "Anchor the mix"], "common_mistakes": ["Trusting an AI loudness result without checking it on a compliant LUFS meter", "Pushing loudness so high the AI tool adds audible distortion or pumping", "Assuming one loudness target fits every platform, when specs differ"], "scenario_contexts": ["Normalizing a batch of tracks to a streaming LUFS target with an AI tool", "Using an AI mastering service to loudness-match songs across an album", "Checking an AI-set level against ITU-R BS.1770 metering before delivery"]}, "c3120361-52f1-474c-8deb-7d05d86fdbcd": {"definition": "An automated approach to audio mastering in which software driven by machine-learning models analyzes a mix and applies mastering-style processing such as equalization, dynamics, stereo adjustment, and loudness targeting, producing a finished master with little or no manual input from an engineer.", "plain_english": "Software that masters a song for you by studying the sound and making its own tweaks. It is like a photo app that auto-fixes a picture's brightness and color with one tap.", "purpose_function": "It offers a fast, low-cost way to bring a mix up to a competitive loudness and tonal balance, which is useful for demos, drafts, or creators without access to a mastering engineer.", "practical_application": "A producer might run a mix through an AI mastering tool to get a quick reference master, then compare it against a human master or use it as a starting point.", "category": "Mastering", "related_terms": ["Mastering", "Loudness normalization", "LUFS", "Reference track", "Limiter", "Master bus"], "common_mistakes": ["Treating an AI master as final without critical listening on good monitors", "Feeding it a poor mix and expecting mastering to fix mix problems", "Ignoring platform loudness targets and letting the tool over-limit", "Assuming one algorithm suits every genre and every song"], "scenario_contexts": ["Quickly mastering a demo before release", "Getting a loud reference version to compare with a manual master", "Batch-finishing tracks for an independent release on a budget"]}, "d9ecf2ce-d6fd-46c9-a560-ed9efb691afb": {"definition": "An alternative version of a film or program's soundtrack prepared for in-flight entertainment, typically edited to remove or replace objectionable content and mixed for intelligibility on headphones in a noisy cabin, often delivered as a dialogue-forward, level-controlled, downmix-compatible version.", "plain_english": "A special edit of a movie's sound made for watching on a plane. Bad language is taken out and the talking is made clearer so you can follow it over the engine noise through earbuds.", "purpose_function": "It lets airlines show content that meets their audience and censorship rules and stays easy to understand in a loud cabin on small headphones, without altering the original theatrical mix.", "practical_application": "A re-recording mixer delivers an airline mix alongside the theatrical and home versions, muting or replacing profanity and keeping dialogue clear and consistent in level.", "category": "Deliverables", "related_terms": ["Deliverables", "Re-recording mix", "Dialogue stem", "Fold-down", "Censored version", "Loudness normalization"], "common_mistakes": ["Assuming the airline mix is identical to the theatrical mix", "Forgetting to check that the edited version stays in sync with picture", "Leaving dialogue too low to hear over cabin noise", "Missing an item on the airline's content or loudness spec sheet"], "scenario_contexts": ["Preparing a feature film for in-flight entertainment", "Delivering a clean, edited version to meet airline content rules", "Creating a dialogue-forward mix for noisy headphone listening"]}, "70498e47-0859-4100-822a-55e588845576": {"definition": "In Apple Logic Pro, a browser pane that lets you navigate the computer's file system to locate, preview, and import supported files, such as Logic Pro and GarageBand projects, audio files, and QuickTime movies, directly into the current project.", "plain_english": "A file finder built into Logic Pro. It works like a Finder window on a Mac, letting you dig through folders to grab sounds, movies, or old projects and drop them into your song.", "purpose_function": "It gives quick in-app access to any importable file on the computer, so you can browse, preview, and bring media into a session without leaving Logic Pro.", "practical_application": "An engineer opens the All Files Browser to preview and drag an audio file into the timeline, or to import track settings from another Logic Pro project.", "category": "DAW Interface", "related_terms": ["Browser", "Project Audio Browser", "Media Browser", "Import", "Workspace", "Region"], "common_mistakes": ["Confusing the All Files Browser with the Project Audio Browser, which shows only files already in the project", "Importing a file from an external drive and then disconnecting it, breaking the link", "Overlooking the search filters and scrolling manually through large folders", "Assuming importing a project's data copies its audio when it may only reference it"], "scenario_contexts": ["Importing audio or movie files into a Logic Pro session", "Copying track settings or channel strips from another project", "Previewing sound files on disk before adding them to a mix"]}, "ffcc847f-6788-49c4-91ef-241a8408e39b": {"definition": "The practice of establishing one central element, commonly the lead vocal, kick, or snare, as a fixed reference point and building the balance, levels, and effects of the other tracks in relation to it, rather than adjusting each element in isolation.", "plain_english": "Picking one main sound, like the lead singer, as your reference and setting everything else around it. It is like arranging furniture around the biggest piece in the room so the whole layout makes sense.", "purpose_function": "It gives the mix a stable foundation, so decisions about level and space stay consistent and the balance does not drift as more tracks are added.", "practical_application": "A mixer sets the lead vocal or kick to a target level first, then brings up every other track to sit around that anchor, rechecking against it as the mix grows.", "category": "Mix Technique", "related_terms": ["Static mix", "Balance", "Gain staging", "Reference track", "Lead vocal", "Fader"], "common_mistakes": ["Constantly re-adjusting the anchor so nothing has a stable reference", "Choosing an anchor that is not central to the song", "Pushing every other track up to compete with the anchor until nothing has room", "Forgetting to recheck the balance against the anchor as the mix changes"], "scenario_contexts": ["Starting a mix by setting the lead vocal level first", "Building a drum balance around the kick or snare", "Keeping levels consistent when returning to a mix on another day"]}, "fe3679a5-496d-4ec2-88f2-bc80cab80409": {"definition": "A version of a finished master sent to the client or artist for review and sign-off before final delivery, typically watermarked, quality- or level-limited, or otherwise marked so it is clearly not the final release file.", "plain_english": "A near-final version of a song sent to the artist to okay before it goes out. It is like showing someone a proof to approve before you print the whole batch.", "purpose_function": "It lets the client confirm the master meets their expectations and catch changes early, protecting both sides before the real, unrestricted files are released.", "practical_application": "A mastering engineer sends an approval master, often a watermarked or lower-resolution file, and waits for written sign-off before delivering the final high-resolution masters.", "category": "Deliverables", "related_terms": ["Master", "Reference master", "Revision", "Deliverables", "Watermark", "Bounce"], "common_mistakes": ["Sending the full-resolution final master before payment or sign-off", "Treating an approval master as the release file", "Not labeling versions clearly, so an old approval file gets released by mistake", "Skipping written approval and relying on a verbal okay"], "scenario_contexts": ["Getting artist sign-off before releasing masters", "Sending a watermarked draft for label approval", "Confirming revisions are correct before final delivery"]}, "b4683e9d-5c94-4aa1-b44f-cf8b6f326618": {"definition": "The highest-quality, long-term preservation copy of a finished recording, stored in a stable format with minimal processing so it serves as the authoritative source for all future copies. It is kept unchanged and separate from the access or production copies used in day-to-day work.", "plain_english": "The archival master is the best, safest copy of a finished recording. You keep it in top quality and never change it. All future copies are made from it. It is like keeping the original of an important photo locked in a safe.", "purpose_function": "It protects the definitive version of a recording against loss, format decay, or accidental change, giving a trusted source for later remasters, reissues, and derivative files.", "practical_application": "An engineer exports a full-resolution, unprocessed master and files it with checksums and metadata in a preservation store, then makes working copies for streaming or CD from it rather than editing the original.", "category": "Masters & Archiving", "related_terms": ["Production master", "Flat master", "Access copy", "Bit depth", "Sample rate", "Metadata"], "common_mistakes": ["Saving only a lossy MP3 or a loudness-limited streaming file as the archival master instead of a full-resolution copy", "Overwriting or editing the archival master rather than working from a duplicate", "Storing the master with no checksums, metadata, or backups so it cannot be verified later", "Confusing the archival master with the final access or distribution copy"], "scenario_contexts": ["A label requests the archival master years later to prepare a remaster or vinyl reissue", "A studio ingests finished mixes into a preservation archive with fixity checks", "Migrating older masters to a new file format before the original media degrades"]}, "bbee86a9-06e1-488d-9b6d-57025e38de8f": {"definition": "A formal quality-control step in which delivered audio materials are checked against archive requirements, such as format, resolution, metadata, file integrity, and completeness, to decide whether they are accepted into the archive or returned for correction.", "plain_english": "Before a recording goes into the archive, someone checks it carefully. They make sure the files, format, and labels all follow the rules. If something is wrong or missing, it gets sent back to be fixed. It is like a librarian checking a book is complete before shelving it.", "purpose_function": "It keeps an archive trustworthy by ensuring only complete, correctly formatted, and verifiable material is accepted, preventing corrupt or non-standard files from entering long-term storage.", "practical_application": "An archivist or QC engineer opens each delivered file, confirms it plays, matches the agreed spec and checksums, and carries the required metadata before signing it off for ingest.", "category": "Masters & Archiving", "related_terms": ["Archival master", "Ingest", "Quality control", "Checksum", "Metadata", "Deliverables"], "common_mistakes": ["Accepting files without verifying checksums or that every promised deliverable is present", "Skipping a listen-through, so dropouts or wrong files reach the archive", "Ignoring required metadata and file-naming conventions", "Treating the review as a formality rather than a gate that can reject material"], "scenario_contexts": ["A broadcast archive reviews a season of program masters before adding them to its store", "A studio checks a client's delivered stems and masters meet the archive spec", "A digitization project verifies transferred tapes before ingest"]}, "bb46e763-d598-4b94-b4b8-9c236223da35": {"definition": "A defined section of a song's overall arrangement—such as an intro, verse, chorus, or bridge—treated as a single selectable block on a DAW timeline, commonly delimited by arrangement markers so it can be named, moved, copied, or deleted as a unit.", "plain_english": "It is a labeled chunk of a song, like the chorus or verse. You can grab that whole chunk and move it or copy it in one go.", "purpose_function": "It lets an engineer organize and restructure a song at the section level rather than editing individual regions or notes, speeding up arrangement changes and navigation.", "practical_application": "An engineer marks the intro, verse, and chorus as arrangement regions, then drags a chorus block to a new spot to try a different song order without cutting each track by hand.", "category": "Arrangement", "related_terms": ["Arrangement track (Logic)", "Arranger track", "Marker", "Region", "Cycle area"], "common_mistakes": ["Confusing an arrangement region (a whole song section) with an individual audio or MIDI region on a single track", "Moving an arrangement region without checking that markers and automation stay aligned to the new position", "Assuming section boundaries snap to bars automatically when they may sit off the grid"], "scenario_contexts": ["Reordering a song's structure by dragging the chorus section earlier during a mix revision", "Duplicating a verse arrangement region to extend a song for an alternate edit", "Navigating quickly to the bridge by selecting its arrangement region"]}, "bfb3adeb-8353-437c-abe3-aba0b0983dd4": {"definition": "A global track in Logic Pro that holds arrangement markers, which divide a project into named sections such as intro, verse, and chorus. Moving a marker moves all regions, track markers, and automation within that section, so whole sections can be reordered, copied, or swapped.", "plain_english": "The Arrangement track is a special row at the top of Logic Pro. You drop markers on it to label parts of your song, like verse and chorus. When you drag a marker, everything in that part moves with it. So you can rearrange a song by sliding whole sections around, like moving blocks of a story.", "purpose_function": "It gives a high-level view of song structure and lets you restructure a whole arrangement quickly, without manually selecting and moving every region and automation point.", "practical_application": "A producer marks out song sections, then drags an arrangement marker to move a chorus earlier or Option-drags to duplicate a verse, and every region and automation point in that section follows.", "category": "DAW Arrangement", "related_terms": ["Arranger track", "Arrangement marker", "Global tracks", "Region", "Marker", "Song structure"], "common_mistakes": ["Confusing arrangement markers with ordinary timeline or locator markers", "Forgetting that moving a marker also moves that section's automation and every track's regions", "Expecting it to play sections in a custom order like Cubase's Arranger track, when it actually edits the linear timeline", "Resizing one marker without realizing the adjacent marker resizes too"], "scenario_contexts": ["Restructuring a demo by moving the chorus before the second verse", "Duplicating a verse section to extend a song", "Labeling sections so collaborators can navigate the project quickly"]}, "215f13c5-edfd-4918-9a74-f8f29c7fabab": {"definition": "A track type in Cubase and Nuendo on which you define arranger events (sections) and then build an arranger chain that sets the order and number of repeats in which those sections play back. This allows non-linear rearrangement and live restructuring without permanently moving the underlying events.", "plain_english": "The Arranger track lets you mark parts of your project, like verse and chorus. Then you make a playlist that says what order to play them and how many times. You can change the order without cutting and pasting anything. It is like making a set list from parts you already recorded.", "purpose_function": "It lets you try different song structures and perform arrangements live by controlling the playback order of predefined sections, instead of permanently editing the timeline.", "practical_application": "A composer defines sections on the Arranger track, builds a chain that repeats the chorus twice and skips a verse, auditions it, and can later flatten the chain into a normal linear project.", "category": "DAW Arrangement", "related_terms": ["Arrangement track (Logic)", "Arranger chain", "Arranger Editor", "Cycle markers", "Region", "Song structure"], "common_mistakes": ["Confusing the Arranger track's non-linear playback with simply moving events on the timeline", "Forgetting to flatten (make permanent) the arranger chain before exporting, so the export follows the wrong order", "Expecting Logic's Arrangement track to behave the same way", "Leaving Arranger mode inactive, so the chain is ignored during playback"], "scenario_contexts": ["Auditioning several song structures before committing to one", "Performing a track live and repeating a chorus on cue", "Building a long arrangement from a few recorded sections"]}, "7acc3a2d-2708-43a3-8678-2e61aec0a65c": {"definition": "Audio technology designed to help people with hearing or other disabilities access sound, most notably assistive listening systems such as induction (hearing) loops, FM, and infrared systems that deliver clearer sound directly to a listener's hearing aid or receiver.", "plain_english": "Assistive audio technology is gear that helps people who have trouble hearing. It sends sound straight to a hearing aid or a small receiver, cutting out room noise and distance. Hearing loops in theaters and airports are a common example. It makes speech and music much easier to follow.", "purpose_function": "It improves access and speech clarity for people with hearing loss, and is required in many public venues so everyone can hear announcements, performances, and presentations.", "practical_application": "An AV technician installs and tests a hearing loop or infrared system fed from the venue's sound mix, sets its output level, and confirms coverage and compatibility with hearing aids' telecoil.", "category": "Accessibility", "related_terms": ["Assistive listening system", "Hearing loop", "Telecoil", "Infrared system", "Signal-to-noise ratio", "Public address"], "common_mistakes": ["Assuming a normal PA or loudspeaker system meets accessibility rules without a dedicated assistive listening system", "Not testing the system with a receiver or telecoil, so faults go unnoticed", "Ignoring the required coverage area and number of receivers for the venue size", "Confusing assistive listening systems with simply turning up the volume"], "scenario_contexts": ["Fitting a hearing loop in a theater so patrons with hearing aids can hear dialogue", "Providing infrared receivers at a conference for delegates with hearing loss", "Checking a house of worship's assistive listening coverage during commissioning"]}, "31c14e8e-ba03-46de-9110-7cb6caf77075": {"definition": "Mastering carried out with the help of an intelligent assistant tool that analyzes a mix and automatically generates a starting master chain, setting EQ, dynamics, and loudness toward a genre target or a loaded reference track, which the engineer then reviews and refines.", "plain_english": "Assistive mastering uses smart software to give you a head start on a master. The tool listens to your song and sets up EQ, compression, and loudness for you. You can also point it at a reference track you like. Then you tweak its suggestions instead of starting from nothing.", "purpose_function": "It speeds up mastering and gives less-experienced users a competent starting point, offering a data-driven baseline that the engineer can accept, adjust, or override.", "practical_application": "An engineer runs a tool like Ozone's Master Assistant on the loudest part of a mix, picks a streaming or reference target, then fine-tunes the generated EQ, limiter ceiling, and loudness before exporting.", "category": "Mastering", "related_terms": ["Archival master", "Reference track", "LUFS", "Maximizer", "Loudness normalization", "Mastering chain"], "common_mistakes": ["Accepting the assistant's output without critical listening or metering", "Treating the AI-generated target as a finished master rather than a starting point", "Chasing a reference track's loudness and crushing the dynamics", "Assuming one genre preset fits every song"], "scenario_contexts": ["Getting a quick master reference for a client demo", "Giving a beginner a solid starting chain to learn from", "Matching a new mix's tone and loudness to a released reference"]}, "1a4e076c-2f3b-4cba-872b-af5be19217c7": {"definition": "A separate sound or sample layered under a source specifically to reinforce its initial transient (attack), adding click, snap, or punch without changing the body or sustain of the main sound.", "plain_english": "An attack layer is an extra sound stacked on top to sharpen the very start of a hit. It adds click or snap so a drum or note cuts through. Think of it like adding a crisp tap to the front of a soft thud. The main sound stays the same; only the beginning gets punchier.", "purpose_function": "It makes a sound's onset more defined and audible in a busy mix, improving punch and clarity, especially on drums and layered instruments.", "practical_application": "A producer layers a short click or transient sample under a soft kick so it translates on small speakers, time-aligns it to the main hit, and blends its level so it adds snap without sounding separate.", "category": "Sound Layering", "related_terms": ["Transient", "Layering", "Attack (envelope)", "Phase alignment", "Sample layering", "Punch"], "common_mistakes": ["Adding an attack layer that is out of phase with the main sound, thinning the low end", "Setting the attack layer too loud so it sounds like a separate click", "Not time-aligning the layers, which smears the transient", "Layering to patch a part that really needs to be re-recorded or re-sampled"], "scenario_contexts": ["Adding click to a dull kick so it punches on phones and laptop speakers", "Reinforcing the pick attack on a soft bass sample", "Stacking a transient sample under a snare for more snap"]}, "3d82ac37-0ee3-4d32-b413-a989276ef5b3": {"definition": "A configuration window in Cubase and Nuendo (formerly VST Connections) where you set up input and output busses and map them to the physical ports of your ASIO audio interface, defining their channel format (mono, stereo, or surround) and saving them as presets.", "plain_english": "The Audio Connections window is where Cubase learns how your audio interface is wired. You create input and output paths and connect them to the real sockets on your gear. Without this setup, you cannot record or hear playback. Think of it as a patchbay that tells the software which jack is which.", "purpose_function": "It links the software's audio busses to the hardware interface's ports, which is required before you can record inputs or play sound out of Cubase.", "practical_application": "A technician opens Audio Connections, creates a stereo output bus mapped to the interface's main outs and input busses mapped to the mic preamps, then saves the layout as a preset for future sessions.", "category": "DAW Routing", "related_terms": ["Bus", "Audio interface", "ASIO driver", "Input monitoring", "Signal routing", "Control room"], "common_mistakes": ["Not setting up any output bus, so playback is silent", "Mapping busses to the wrong interface ports, sending audio to the wrong outputs", "Assuming settings transfer automatically after changing the audio device, when busses must be remapped", "Confusing input busses with the tracks that record from them"], "scenario_contexts": ["Setting up a new studio interface in Cubase for the first time", "Reconfiguring routing after moving a project to a different rig", "Adding a dedicated headphone or cue output bus for a performer"]}, "217073b1-f7be-40a5-8948-9b73b19aaf26": {"definition": "In Ableton Live, an Audio Effect Rack is a container device that holds one or more parallel signal chains of audio effects behind a single interface, with up to 16 Macro controls (eight shown by default) that can be mapped to parameters of the enclosed devices. Because it processes audio, it hosts only audio effects, and the whole assembly appears, is saved, and is loaded as one device.", "plain_english": "It is a single box in Ableton Live that holds a group of audio effects together. You can control the whole group with a few big knobs, and save it to use again later. Think of it like a folder that keeps several effects in one tidy place.", "purpose_function": "It groups several effects into one manageable device and exposes their key controls as Macros, so complex processing can be recalled, tweaked, and performed from a simple interface. Parallel chains also let one input be processed several ways at once and then mixed back together.", "practical_application": "A technician builds an Audio Effect Rack to store a go-to vocal or drum-bus chain, maps the most-used settings to Macros, and drops it onto tracks in later sessions for a consistent starting point.", "category": "Effects Processing", "related_terms": ["Macro control", "Device chain", "Parallel processing", "Audio effect", "Instrument Rack"], "common_mistakes": ["Trying to load an instrument or MIDI effect into an Audio Effect Rack, which only accepts audio effects.", "Forgetting that parallel chains sum together, so stacking similar chains can build up level or cause phase issues.", "Not mapping key parameters to Macros, losing the main benefit of quick, consolidated control.", "Assuming the Rack itself changes the sound; an empty Rack passes audio through unaffected."], "scenario_contexts": ["Saving a reusable vocal chain of EQ, compression, and reverb as one recallable device.", "Building a parallel drum setup with a clean chain and a heavily compressed chain mixed together.", "Creating a performance-ready effect with Macros mapped for live tweaking."]}, "af7d0007-86dc-4b2a-aad8-df0000b0343f": {"definition": "An Audio File Editor is a tool or window for viewing and editing the waveform of an audio file at the sample level, performing operations such as trimming, normalizing, fading, reversing, and removing DC offset. These edits typically alter the underlying audio file itself (destructive editing), so hosts such as Logic Pro usually create a backup first.", "plain_english": "This is a tool that lets you open one sound file and change the sound wave inside it directly. You can cut, boost, or fade the actual file, not just how it plays back. It is like editing a photo itself instead of only cropping how it shows on screen.", "purpose_function": "It provides precise, sample-accurate editing of the audio file itself, which is needed for cleanup and repair tasks that region-level editing cannot do. Because it can change the source file, it is used when a permanent fix to the recording is wanted.", "practical_application": "An engineer opens a noisy take in the Audio File Editor to trim silence, remove a DC offset, and normalize the clip before using it in the arrangement.", "category": "Audio Editing", "related_terms": ["Audio Track Editor", "Destructive editing", "Waveform", "Normalize", "DC offset"], "common_mistakes": ["Confusing it with the Audio Track Editor, which edits regions non-destructively in the timeline.", "Forgetting edits change the source file, so every other region using that file is affected too.", "Not keeping a backup before destructive edits, making mistakes hard to undo later.", "Normalizing every file out of habit, which can raise noise and upset gain staging downstream."], "scenario_contexts": ["Removing a DC offset from a recorded take.", "Trimming leading silence and clicks from a sample.", "Reversing a cymbal hit to create a swell effect."]}, "79330ad1-0fd8-4511-8b19-b7e4ba4ae3cb": {"definition": "In Ableton Live, \"Audio From\" is the input-routing chooser in a track's In/Out section that selects the source of audio feeding the track — an external hardware input, resampling of the master, or the output of another track or device. A second chooser below it selects the specific input channel or tap point.", "plain_english": "In Ableton Live, this setting picks where a track gets its sound from. You can choose a microphone input, the computer's own output, or another track. It is like choosing which cable is plugged into that track's input.", "purpose_function": "It lets a track take audio from a chosen source rather than only its own clips, which is essential for recording external signals, resampling, and internal routing between tracks. This flexible input selection underpins Live's signal flow and bussing.", "practical_application": "To record a guitar, a technician sets a track's Audio From to the interface input; to capture a processed synth, they set it to that synth track's output and arm the track.", "category": "Signal Routing", "related_terms": ["Audio To routing", "Input monitoring", "Resampling", "Bus", "Track arming"], "common_mistakes": ["Confusing Audio From (input source) with Audio To (output destination).", "Setting monitoring incorrectly, so the incoming source is not heard or a feedback loop forms.", "Selecting the wrong input channel in the lower chooser and recording silence.", "Forgetting to arm the track, so nothing records even with the source set."], "scenario_contexts": ["Setting a track to record from a specific interface input.", "Resampling the master output into a new audio track.", "Routing one track's output into another for internal processing."]}, "32855191-8ad4-44da-ad77-81b4ff1f6e97": {"definition": "In Steinberg Cubase and Nuendo, an audio part is a container that groups one or more audio events so they can be moved, copied, and edited as a single object on an audio track. Parts are created by drawing on the track or by combining selected events, and can be broken back into events with Dissolve Part.", "plain_english": "In Cubase, an audio part is a box that holds several audio clips together as one block. You can move or copy the whole block at once instead of each clip on its own. It is like putting several photos in one envelope so you can carry them together.", "purpose_function": "It lets an editor organize many small audio events into one manageable block, which simplifies arranging, repeating, and moving grouped material. Grouping into parts keeps complex edits, such as comped or sliced takes, tidy on the track.", "practical_application": "An engineer selects a set of sliced drum hits, combines them into one audio part, then copies that part across the timeline to repeat the pattern.", "category": "Arrangement", "related_terms": ["Audio event", "Audio Part Editor", "Region", "Comping", "Dissolve Part"], "common_mistakes": ["Confusing an audio part (a container of events) with a single audio event.", "Editing inside a part and not realizing shared copies of the part change too.", "Forgetting to use Dissolve Part when individual events need separate handling.", "Assuming a part is a separate audio file; it only references events and the underlying clips."], "scenario_contexts": ["Grouping sliced drum hits into one block to repeat across a song.", "Combining several vocal takes into a part for tidy arrangement.", "Dissolving a part back into events to edit one hit individually."]}, "2ffc18a2-c263-4bdb-9234-9234d636993f": {"definition": "Audio pitch automation is the use of automation to change the pitch or transposition applied to an audio signal over time, by recording moves on a clip's pitch/transpose control or on a pitch-shifting device's parameter. The stored automation then replays those pitch changes automatically during playback.", "plain_english": "This means telling the software to change the pitch of a sound by itself as the song plays. You draw or record the pitch moves once, and they happen the same way every time. It is like programming a slider to move on its own to raise or lower the note.", "purpose_function": "It lets pitch changes be planned, repeated exactly, and recalled, instead of being adjusted by hand on each pass, which suits both creative effects and corrective moves. Because it is stored as automation, the changes stay locked in time with the arrangement.", "practical_application": "A producer automates the pitch of a vocal clip to dip down on one word, or ramps a sample's pitch upward to build tension into a drop.", "category": "Automation", "related_terms": ["Automation", "Pitch shifting", "Transpose", "Warping", "Automation envelope"], "common_mistakes": ["Confusing pitch automation (changing pitch over time) with pitch correction (fixing tuning).", "Automating large pitch shifts that expose artifacts from the pitch-shifting algorithm.", "Forgetting that time-stretch or warp settings can interact with pitch changes and alter timing.", "Leaving stray automation points that cause unwanted pitch jumps on playback."], "scenario_contexts": ["Dropping a vocal word down an octave for effect.", "Ramping a riser sample's pitch up into a chorus.", "Automating a subtle pitch fall on a synth tail."]}, "032ea02e-15ff-4de5-b0b5-6d8d4f4591a4": {"definition": "In Ableton Live, \"Audio To\" is the output-routing chooser in a track's In/Out section that selects where the track's audio is sent — the Master, an external hardware output, \"Sends Only,\" or the input of another track. A second chooser sets the exact destination point, such as a track's input or a device.", "plain_english": "In Ableton Live, this setting picks where a track's sound goes next. You can send it to the main output, out to your speakers or interface, or into another track. It is like choosing which output socket that track's cable plugs into.", "purpose_function": "It routes a track's signal to a chosen destination instead of only the Master, which enables submixing, grouped processing, and internal sends between tracks. Output routing is the counterpart to Audio From and shapes the whole mix's signal flow.", "practical_application": "A technician routes several drum tracks' Audio To a single audio track to create a drum bus, then processes them together with one compressor.", "category": "Signal Routing", "related_terms": ["Audio From routing", "Bus", "Submix", "Send", "Return track"], "common_mistakes": ["Mixing up Audio To (destination) with Audio From (source).", "Routing a track into another and forgetting the receiving track must be monitored to hear it.", "Creating a routing loop by sending a track back into its own signal path.", "Leaving a track set to 'Sends Only' and wondering why it is missing from the main mix."], "scenario_contexts": ["Building a drum bus by routing several tracks to one audio track.", "Sending a track to an external hardware output for outboard processing.", "Setting a track to Sends Only so it feeds effects but not the Master."]}, "bfa932e6-d5a7-4e54-b216-fd87063fb158": {"definition": "An Audio Track device is a processing device loaded into the device chain of an audio track in a device-based DAW such as Ableton Live or Bitwig Studio. On an audio track these devices are audio effects, and the track's signal passes through them in series from left to right.", "plain_english": "This is an effect that you place on an audio track to change its sound. The track's sound flows through each device in order, one after another. It is like adding pedals to a guitar chain, where each one shapes the tone before the next.", "purpose_function": "It lets a technician shape or process a track's audio right on that track, building a chain of effects such as EQ, compression, and reverb in a chosen order. The device chain is the core way per-track processing is applied in device-based DAWs.", "practical_application": "On a vocal audio track, an engineer adds devices in order — a gate, an EQ, then a compressor — so each stage processes the signal before the next.", "category": "DAW Devices", "related_terms": ["Device chain", "Audio effect", "Audio Effect Rack", "Insert effect", "Signal chain"], "common_mistakes": ["Placing devices in an order that hurts the sound, such as heavy reverb before a gate.", "Expecting an instrument to work on an audio track, which hosts audio effects only.", "Leaving a CPU-heavy device active on many tracks and overloading the system.", "Forgetting a device is bypassed, then troubleshooting a sound that never changes."], "scenario_contexts": ["Adding an EQ then a compressor on a vocal track.", "Inserting a gate first in a drum track's chain to control bleed.", "Reordering devices to hear how the processing order changes the tone."]}, "5cbbe1c1-b54d-4fb6-b6ed-7e7590ee0114": {"definition": "In Logic Pro, the Audio Track Editor is a workspace for editing the audio regions of a single track non-destructively within the timeline, including trimming, splitting, and applying Flex Time and Flex Pitch. It changes how regions play back and are arranged without altering the underlying audio files.", "plain_english": "In Logic Pro, this is a window for editing the audio on one track without changing the original file. You can trim clips, fix timing, and nudge pitch, and the source file stays safe. It is like using sticky notes on a recording instead of writing on the tape itself.", "purpose_function": "It gives close-up, non-destructive control over one track's regions and their timing and pitch, which supports tightening performances and arranging without risk to the source audio. It complements the Audio File Editor, which changes the file itself.", "practical_application": "A technician opens the Audio Track Editor to Flex-Time a slightly late snare hit onto the grid and nudge a flat vocal note up with Flex Pitch.", "category": "Audio Editing", "related_terms": ["Audio File Editor", "Flex Time", "Flex Pitch", "Region", "Non-destructive editing"], "common_mistakes": ["Confusing it with the Audio File Editor, which edits the actual file destructively.", "Applying heavy Flex Time and expecting no audible artifacts.", "Thinking edits change the source file, when only playback instructions change.", "Choosing the wrong Flex mode for the material, which degrades the sound."], "scenario_contexts": ["Nudging a late drum hit onto the beat with Flex Time.", "Correcting a flat sung note with Flex Pitch.", "Trimming and splitting a region tightly within one track."]}, "7a951040-ff48-48ce-845e-b793822fb718": {"definition": "Auto-ducking is a mixing technique in which the level of one audio signal, such as background music, is automatically reduced whenever another signal, such as dialogue or a voiceover, is present, then restored when that signal stops. It is driven by a detector that senses the triggering audio, applied either as real-time sidechain gain reduction or as automatically written volume automation.", "plain_english": "Auto-ducking turns the music down by itself whenever someone is talking, then brings it back up when they stop. The software listens for the voice and lowers the music for you. It is like a radio DJ who dips the song under their voice, done automatically.", "purpose_function": "It keeps a foreground element such as speech clear over a background bed without constant manual fader moves, saving time and giving consistent, repeatable results. It is central to podcast, broadcast, and video mixing where dialogue must stay intelligible.", "practical_application": "A podcast editor uses auto-ducking so the intro music drops several dB under the host's voice and rises again in the gaps, with the software writing the volume changes automatically.", "category": "Mixing Technique", "related_terms": ["Sidechain compression", "Ducking", "Compression", "Volume automation", "Gain reduction"], "common_mistakes": ["Confusing auto-ducking with plain sidechain compression, though the two overlap in method.", "Setting too much reduction, making the background pump or drop out awkwardly.", "Using fades that are too fast, causing an unnatural jump as the level snaps down and up.", "Triggering from a noisy source, so background noise falsely ducks the music."], "scenario_contexts": ["Dipping music under a podcast host's voice.", "Lowering a music bed under voiceover in a video edit.", "Ducking ambience beneath radio DJ announcements."]}, "28a1e2d1-b283-4fd4-ae7e-be271a5164cd": {"definition": "A technique in which a mixer automatically manages the gains of multiple open microphones in real time, favoring the mic being spoken or sung into and attenuating the others to control feedback and background noise without a person riding faders. Gain-sharing automixers (such as the Dugan system) hold the summed gain of all active mics roughly constant.", "plain_english": "Auto-mixing lets a mixer turn microphones up and down by itself. It leaves the mic someone is talking into open and quietly pulls the others down, so the sound stays clean without an engineer moving every fader. It works like a spotlight that follows whoever is speaking.", "purpose_function": "It exists to keep multi-microphone events like panels, theatre, and worship services clear and feedback-free by cutting the number of open mics adding noise at any moment, a job that is hard to do by hand with many talkers.", "practical_application": "A technician assigns panel or lavalier mics to an automixer group on a digital console, or a Dugan card or plug-in, then lets it manage the relative mic gains during the event while still setting the overall level.", "category": "Automatic Mixing", "related_terms": ["Gain-sharing automixer", "Number of open mics (NOM)", "Acoustic feedback", "Noise gate", "Digital mixing console", "Gain staging"], "common_mistakes": ["Confusing auto-mixing with mix automation: auto-mixing manages live mic gains in real time, while mix automation records and replays a mixer's moves", "Assigning a music or instrument channel that must stay open to the automixer, so it ducks unexpectedly", "Assuming an automixer removes the need to set gain structure and ring out feedback first"], "scenario_contexts": ["A panel discussion with eight table mics where only one or two people talk at a time", "A house of worship with several lavalier and pulpit mics", "A broadcast talk show or courtroom needing clean multi-mic pickup without a dedicated operator"]}, "12576d21-e10f-45c6-b535-808054fc7500": {"definition": "In Logic Pro's Flex Time, the Automatic setting is a Flex algorithm that analyzes an audio region and picks the most suitable time-stretching algorithm for it, choosing Monophonic for single-note material, Slicing for percussive non-tonal material, or Polyphonic for chordal or complex material.", "plain_english": "This is a Logic Pro setting that fixes the timing of audio for you. It listens to the track and picks the best stretching method by itself, one way for drums, another for a bass line, another for chords. It is like a camera's auto mode choosing the right settings for the shot.", "purpose_function": "It exists so users can time-stretch audio without knowing which specialized algorithm fits the material, giving good results by matching the processing to the detected content.", "practical_application": "An engineer turns on Flex for a track, leaves the algorithm set to Automatic, and drags flex markers to nudge notes or beats into time while Logic applies the fitting algorithm behind the scenes.", "category": "Time Editing", "related_terms": ["Flex Time", "Flex Pitch", "Time-stretching", "Smart Tempo", "Transient detection", "Quantization"], "common_mistakes": ["Expecting Automatic to be flawless on very complex material, where manually choosing Polyphonic or another algorithm can sound better", "Confusing Flex Time (timing) with Flex Pitch (pitch correction)", "Leaving Flex enabled on regions that do not need it, adding processing artifacts"], "scenario_contexts": ["Tightening a slightly rushed vocal phrase to the grid", "Aligning a double-tracked guitar part to the main take", "Fixing the timing of an imported loop that drifts from the project tempo"]}, "34a29874-f27f-442f-a437-5d7029a73fb4": {"definition": "In Logic Pro's Smart Tempo, Automatic is a Project Tempo mode in which Logic decides, from the musical context, whether to keep the project tempo (conforming new material to it) or adapt the project tempo to follow the timing of a new recording or import.", "plain_english": "This Logic Pro setting handles tempo for you. When you record or import audio, it decides whether to bend your take to the song's tempo or bend the tempo to your take. It is like a smart thermostat that picks whether to heat or cool without being told.", "purpose_function": "It exists to take manual tempo decisions out of the workflow, letting Logic build or apply a tempo map on its own so recordings and the project stay in sync.", "practical_application": "A producer sets the Project Tempo mode to Automatic before tracking freely played parts, so Logic either maps the performance's tempo or locks it to the grid depending on what it detects.", "category": "Tempo Management", "related_terms": ["Smart Tempo", "Tempo map", "Flex Time", "Click track", "Beat mapping", "Quantization"], "common_mistakes": ["Assuming Automatic always guesses right: on loose or rubato takes it may adapt when you wanted it to keep, or the reverse", "Not checking the resulting tempo map, which can leave unwanted tempo changes", "Confusing Smart Tempo's Automatic mode with the Flex Time Automatic algorithm"], "scenario_contexts": ["Recording a band that speeds up naturally and wanting a matching tempo map", "Importing a loop that should snap to the project tempo", "Building a project around a freely performed piano take"]}, "f8bc4c99-f1af-4ca1-b2f5-4628991e689a": {"definition": "The process of shaping mix automation by creating, moving, and deleting breakpoints, the individual editable points (nodes) on an automation line that set a parameter's value at specific moments, with the DAW interpolating between them.", "plain_english": "Automation is how a mixer remembers moves like volume changes over time. Breakpoint editing means grabbing the little dots on the automation line and dragging them to set exactly when and how a control changes. It is like bending a wire by pinning it down at chosen points.", "purpose_function": "It gives precise, repeatable control over how parameters change over time, letting an engineer draw exact fades, mutes, and effect sweeps instead of performing them by hand.", "practical_application": "An engineer shows a track's volume automation lane, then uses the pencil or grabber tool to add breakpoints and drag them into a fade or to ride a vocal level word by word.", "category": "Mix Automation", "related_terms": ["Breakpoint", "Automation glide", "Automation lane", "Write mode", "Read mode", "Volume ride"], "common_mistakes": ["Creating too many breakpoints, giving jittery, stair-stepped moves instead of smooth ramps", "Editing on the wrong automation lane, such as pan instead of volume", "Forgetting the track must be in Read, not Write, so hand-drawn breakpoints are not overwritten"], "scenario_contexts": ["Drawing a smooth fade-out at the end of a song", "Dipping a music bed under a voiceover at exact points", "Automating a filter sweep across a build-up"]}, "d33bbf9f-d4b9-403e-83fa-ecba03817e0e": {"definition": "The behavior by which an automation system updates a channel's controls to their correct automated positions for the current transport location, so motorized faders and parameters follow (chase) the recorded automation, typically synchronized to timecode, whenever you locate, scrub, or play to a new point.", "plain_english": "Chase means the mixer's controls jump to the right settings for wherever the song is playing. If you skip to the chorus, the faders move themselves to match the moves you recorded there. It is like subtitles keeping pace with the scene you jump to.", "purpose_function": "It keeps the audible mix in step with stored automation no matter where playback starts, so a recalled or synced mix always reflects the recorded moves at that exact time position.", "practical_application": "When an engineer stops and relocates the playhead, motorized faders on a console or control surface snap to their automated values so the mix picks up correctly from the new spot.", "category": "Mix Automation", "related_terms": ["Mix automation", "SMPTE timecode", "Motorized faders", "Read mode", "Control surface", "Total recall"], "common_mistakes": ["Expecting non-motorized faders to physically chase: only their stored values update, not a manual control's position", "Confusing automation chase (following stored moves) with writing new automation", "Losing sync when timecode is missing or the automation is switched offline"], "scenario_contexts": ["Jumping to a later section and having the faders update to that section's levels", "Locking console automation to SMPTE timecode from a video edit", "Recalling a mix and having controls follow the saved automation on playback"]}, "2c78ef1d-5506-4857-a9a9-24fa47036a03": {"definition": "The act of making dynamic automation permanent by rendering or printing the automated result to fixed audio (often a new track), so the recorded parameter moves are baked in rather than reproduced live on every playback.", "plain_english": "Committing automation turns your moving controls into a fixed recording. The volume rides and effect sweeps get printed into the audio for good. They then play back the same every time. It is like saving a recipe as a cooked meal you can reheat.", "purpose_function": "It locks in a decided automation performance, frees up CPU and routing, and simplifies a session by turning live, editable moves into a stable rendered track.", "practical_application": "Once an engineer is happy with a track's automation and plug-in moves, they commit (render) it to a new audio file, keeping the original for safety while working with the lighter committed version.", "category": "Mix Automation", "related_terms": ["Track commit", "Bounce/render", "Freeze", "Printing effects", "Mix automation", "Read mode"], "common_mistakes": ["Committing before the automation is final, forcing a redo because the moves are now baked in", "Not keeping the original un-committed track, losing the ability to tweak later", "Assuming a commit captures moves on the master or other routing outside the committed track"], "scenario_contexts": ["Rendering a heavily automated synth to save CPU", "Locking in a final vocal ride before handing the session to another engineer", "Printing an automated filter sweep so it transfers to another system"]}, "5845a3a4-d0b4-4042-98ac-0e4356604338": {"definition": "A function that lets an engineer switch between newly written or edited automation and the previously stored automation for the same parameter, so the two versions can be auditioned against each other before deciding which to keep.", "plain_english": "Compare lets you flip between your new automation moves and the old ones to hear which is better. Nothing is thrown away until you choose. It is like an A/B test that plays version one, then version two, so you can pick the winner.", "purpose_function": "It supports decision-making during a mix by preserving the prior automation while a new pass is tried, so good moves are not lost before the engineer confirms an improvement.", "practical_application": "After riding a new fader pass, an engineer uses compare to toggle back to the original automation, confirms the new version is better, and then keeps it.", "category": "Mix Automation", "related_terms": ["Mix automation", "Automation history", "A/B comparison", "Undo history", "Write mode", "Read mode"], "common_mistakes": ["Thinking compare permanently saves both versions: once you commit to one, the other may be discarded", "Comparing at different playback levels, which biases the choice toward the louder pass", "Forgetting which state is currently active and keeping the wrong one"], "scenario_contexts": ["Auditioning a re-ridden chorus vocal against the earlier pass", "Checking a redrawn fade against the original before keeping it", "Deciding between two automation takes of an effect send"]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"306af33c-d98f-49ef-9c60-e79ae190515a": {"definition": "The editing operation of copying automation data from a selected time range or parameter and pasting it elsewhere, to another spot on the same track, another parameter, or another track, so identical moves can be reused without redrawing them.", "plain_english": "Automation copy means grabbing a set of recorded control moves and pasting them somewhere else. If the second chorus should move like the first, you just copy the moves over. It is like copy-and-paste for text, but for volume and effect changes.", "purpose_function": "It saves time and keeps sections consistent by letting an engineer reuse existing automation instead of performing or drawing the same moves again.", "practical_application": "An engineer selects the volume automation across the first chorus, copies it, and pastes it onto the later choruses so each one has the same rides.", "category": "Mix Automation", "related_terms": ["Automation breakpoint editing", "Automation lane", "Special paste", "Automation glide", "Mix automation", "Write mode"], "common_mistakes": ["Pasting automation onto the wrong parameter lane, such as copying volume onto pan", "Not aligning the paste to the correct bar or time, shifting the moves off the music", "Copying only visible automation and missing hidden parameter lanes"], "scenario_contexts": ["Reusing a first-verse vocal ride on later verses", "Duplicating a filter-sweep automation across repeated sections", "Copying pan moves from one tom to matching drum hits"]}, "52bac839-c6b4-4022-bb75-ddd21895bdc4": {"definition": "An automation operation that writes a smooth ramp between two values over a selected time range, so a parameter transitions gradually from its start value to a target value rather than jumping abruptly; in Pro Tools this is the Glide Automation command.", "plain_english": "Glide creates a smooth slide from one setting to another over time. Instead of the volume snapping up, it eases up gently across the part you chose. It is like slowly turning a dimmer instead of flipping a light switch.", "purpose_function": "It provides controlled, gradual parameter changes, such as fades, gentle pan moves, and effect swells, by ramping between breakpoints instead of stepping, giving natural-sounding transitions.", "practical_application": "An engineer selects a range, sets the target value, and applies glide so a reverb send or fader ramps smoothly from its current level to the new one across that selection.", "category": "Mix Automation", "related_terms": ["Automation breakpoint editing", "Trim automation", "Automation ramp", "Fade", "Mix automation", "Write mode"], "common_mistakes": ["Selecting too short a range, so the glide sounds like a sudden jump", "Confusing glide (a gradual ramp) with a snap or step change", "Applying glide across a section that already has breakpoints you meant to keep"], "scenario_contexts": ["Smoothly bringing up a reverb send into a chorus", "Gradually panning a sound from left to right over four bars", "Easing a synth filter open across a build"]}, "af41f37e-23ee-4dec-8d33-4db11f55da66": {"definition": "The stored record of automation edits and moves applied to a track's parameters during a mix, letting an engineer review, compare, or revert changes to levels, panning, mutes, and plug-in settings over time.", "plain_english": "It is a list of the volume, pan, and effect moves you made on a track. You can look back at these moves and undo the ones you do not like, much like the edit history in a word processor.", "purpose_function": "It preserves a trail of automation changes so an engineer can undo mistakes and recover earlier moves rather than losing work. This makes automated mixing safe to experiment with.", "practical_application": "When a written fader move sounds wrong, the engineer steps back through the automation history to restore the previous version instead of redrawing it by hand.", "category": "Mix Automation", "related_terms": ["Automation pass review", "Automation paste", "Write mode", "Read mode", "Breakpoint", "Undo history"], "common_mistakes": ["Assuming automation moves are permanent and cannot be undone once written", "Confusing the automation history with the arrangement's clip edit history", "Relying on history recovery instead of saving named versions of the session"], "scenario_contexts": ["Reverting a bad vocal ride after a fresh automation pass overwrote a good one", "Comparing two automation approaches on the same chorus before committing", "Recovering earlier plug-in automation after an accidental clear"]}, "07f11e55-b5bb-4711-85f5-b5baedf4c5bc": {"definition": "The method a DAW uses to calculate a parameter's values between two automation breakpoints, such as linear, stepped/hold, or curved (bezier) transitions, which determines how the parameter moves from one point to the next.", "plain_english": "This is how the software fills in the values between two automation points. It can jump straight, hold flat, or curve smoothly, like choosing to draw a straight line or a bend between two dots.", "purpose_function": "It defines the shape of the change between points so a move can be smooth, sudden, or curved to fit the music. Without it a fader could only sit at fixed points.", "practical_application": "An engineer switches a segment from linear to a curved interpolation so a level rise eases in gently instead of climbing at a constant rate.", "category": "Mix Automation", "related_terms": ["Breakpoint", "Automation ramp", "Automation curve", "Write mode", "Fader", "Snapshot automation"], "common_mistakes": ["Thinking all automation between points is always a straight line", "Using stepped interpolation where a smooth ramp was intended, causing audible jumps", "Adding many extra breakpoints instead of changing the curve type to shape a move"], "scenario_contexts": ["Smoothing a volume swell on a synth pad with a curved transition", "Creating an instant mute change using stepped/hold interpolation", "Shaping a filter sweep so it accelerates toward the end"]}, "180a4c29-db34-40a4-a347-1e90f8b74a80": {"definition": "An automation behavior that combines newly written or edited moves with the existing automation on the same parameter instead of replacing it, so successive passes and edits accumulate into one set of data.", "plain_english": "This blends your new automation moves with the ones already there. Nothing gets erased, so both sets of moves are kept together.", "purpose_function": "It lets an engineer build up complex automation over several passes without wiping earlier work each time. This supports layering moves for different sections.", "practical_application": "After riding the verse levels, the engineer merges a second pass that adds chorus moves so both stay on the same track.", "category": "Mix Automation", "related_terms": ["Write mode", "Latch mode", "Touch mode", "Automation pass review", "Automation paste", "Breakpoint"], "common_mistakes": ["Expecting a merge when the mode is actually set to overwrite existing data", "Merging conflicting moves that fight each other on the same parameter", "Forgetting which passes were merged and losing track of the final result"], "scenario_contexts": ["Adding new fills to existing drum-bus automation across several passes", "Combining separately drawn moves for verse and chorus on one fader", "Layering a manual ride onto previously written level automation"]}, "7d774c80-127d-47f9-9fe2-496871eab850": {"definition": "A fixed shift applied to existing automation data, either in value (raising or lowering all points together) or in time (moving events earlier or later), used to adjust overall balance or correct timing without redrawing each point.", "plain_english": "This shifts all your automation moves at once, either up or down in level, or earlier or later in time. It is like sliding a whole drawing up or sideways without changing its shape.", "purpose_function": "It lets an engineer nudge an entire set of moves as a group, so the balance or timing of a part can change while its relative shape stays intact. This saves editing every point by hand.", "practical_application": "When a whole automated vocal sits a little quiet, the engineer applies a small value offset (often via trim mode) to lift every move together.", "category": "Mix Automation", "related_terms": ["Trim mode", "Automation ramp", "Breakpoint", "Write mode", "Fader", "Gain staging"], "common_mistakes": ["Confusing a value offset with a time offset and shifting the wrong axis", "Offsetting into clipping by pushing all levels up too far", "Forgetting an offset is still applied and layering another on top"], "scenario_contexts": ["Trimming a full vocal automation lane up a couple of dB in one move", "Sliding automation earlier to compensate for plug-in latency", "Nudging a whole panning ride to sit slightly wider"]}, "96698e4b-e65e-4d97-b437-01cad549253c": {"definition": "The step of playing back a recorded automation pass to audition and evaluate the written moves before accepting, keeping, adjusting, or re-recording them.", "plain_english": "After you record a set of automation moves, you play them back to check them. You listen to make sure the moves sound right before you keep them.", "purpose_function": "It gives the engineer a chance to confirm that live-written moves actually work in context before committing. This catches overshoots and timing errors early.", "practical_application": "After latching a fader ride on the lead vocal, the engineer plays the section back in read mode to review the pass and fix any spots that jumped too far.", "category": "Mix Automation", "related_terms": ["Read mode", "Write mode", "Latch mode", "Touch mode", "Automation history", "Automation merge"], "common_mistakes": ["Skipping the review and moving on before hearing the written moves in context", "Reviewing while still in write mode and accidentally overwriting the pass", "Judging a pass in solo instead of within the full mix"], "scenario_contexts": ["Checking a vocal fader ride against the full band before the next section", "Auditioning a written mute pattern to confirm the timing is clean", "Reviewing an automated reverb send change during a chorus lift"]}, "8de20a87-8819-4e50-b8ca-8bf65bf150cb": {"definition": "An edit operation that inserts previously copied automation data at a new timeline location, or onto another track or parameter, reproducing the copied breakpoints and their values there.", "plain_english": "This copies automation moves from one spot and drops them somewhere else. It works like copy and paste in a document, but for fader and knob moves.", "purpose_function": "It lets an engineer reuse a set of moves instead of redrawing them, keeping repeated sections consistent. This speeds up automating songs with recurring parts.", "practical_application": "The engineer copies a polished chorus fader ride and pastes it onto the following choruses so every one matches.", "category": "Mix Automation", "related_terms": ["Automation history", "Breakpoint", "Write mode", "Automation merge", "Snapshot automation", "Automation offset"], "common_mistakes": ["Pasting to the wrong parameter so values land on an unintended control", "Pasting at the wrong timeline position and shifting the moves off the beat", "Overwriting existing automation when a merge was intended"], "scenario_contexts": ["Copying verse mute automation to every verse in the arrangement", "Reusing a filter sweep across repeated drops", "Duplicating a pan move onto a doubled guitar track"]}, "45d0e4cc-3ef6-490b-a57e-4cc19581a5d5": {"definition": "In Pro Tools, the data lane that holds the breakpoint automation for a single automatable parameter, such as volume, pan, mute, or a plug-in control; each parameter on a track has its own automation playlist.", "plain_english": "Each thing you automate, like volume or pan, gets its own lane of moves. That lane is called an automation playlist, and it holds all the points for that one control.", "purpose_function": "It keeps each parameter's moves separate so they can be edited, viewed, and cleared on their own. This organizes a track's automation into manageable lanes.", "practical_application": "The engineer opens the volume automation playlist on a vocal track to see and edit only the level breakpoints, leaving pan and send lanes untouched.", "category": "Mix Automation", "related_terms": ["Breakpoint", "Read mode", "Write mode", "Automation paste", "Automation history", "Track lane"], "common_mistakes": ["Editing points in the wrong parameter's playlist", "Assuming clearing one lane removes automation from all parameters", "Confusing the automation playlist with an audio takes playlist"], "scenario_contexts": ["Displaying the pan automation lane to fine-tune a stereo move", "Clearing only the mute automation playlist on a track", "Viewing a plug-in parameter's lane to edit a filter automation"]}, "a204cb82-6925-450e-96ed-af2339fcebb4": {"definition": "In Pro Tools Preview automation, the temporary hold of proposed parameter values that lets an engineer audition changes to a control before punching or writing them to the track's automation.", "plain_english": "This lets you try out new automation values before you save them. You can hear the change first, then decide whether to write it in or throw it away.", "purpose_function": "It separates trying a value from committing it, so an engineer can find the right setting by ear before it becomes part of the mix. This reduces guesswork and wasted passes.", "practical_application": "In Preview mode the engineer holds a new reverb-send level to hear it in context, then punches it in only once it sounds right.", "category": "Mix Automation", "related_terms": ["Write mode", "Latch mode", "Automation pass review", "Snapshot automation", "Breakpoint", "Automation merge"], "common_mistakes": ["Forgetting a previewed value is not saved until it is written", "Leaving preview active and being surprised the change did not stick", "Punching in a previewed value at the wrong point on the timeline"], "scenario_contexts": ["Auditioning a new fader level before committing it in Preview mode", "Testing a send amount for a chorus before writing it", "Trying different pan positions on a part before punching one in"]}, "56dedb55-ac13-4901-aadb-d8e6b8ac3752": {"definition": "A gradual, continuous transition of an automated parameter from one value to another over a span of time, defined by the slope between two breakpoints.", "plain_english": "A ramp is a smooth slide from one value to another over time. An example is a fader slowly moving up so a part gradually gets louder.", "purpose_function": "It creates a controlled change over time rather than a sudden jump, so levels, panning, or effects can build or fade naturally. This shapes the flow of a mix.", "practical_application": "The engineer draws a ramp on the master or a bus to fade a section out smoothly over several bars instead of cutting it abruptly.", "category": "Mix Automation", "related_terms": ["Breakpoint", "Automation interpolation", "Automation curve", "Fader", "Write mode", "Fade out"], "common_mistakes": ["Placing breakpoints too far apart so a ramp changes faster than intended", "Confusing a linear ramp with a curved transition", "Making a ramp so steep it causes an audible zipper or jump"], "scenario_contexts": ["Ramping a synth pad up into a chorus", "Drawing a slow fade-out at the end of a song", "Sweeping an automated filter open across a build-up"]}, "c7f9a8fd-0c4c-4519-b6b1-009d54fa6644": {"definition": "A stored set of static mixer parameter values, such as fader levels, pans, sends, mutes, and plug-in settings, captured at one instant and recalled as an immediate step change rather than as time-varying moves.", "plain_english": "A saved photo of all your mixer settings at one moment. You can load it later to snap every fader and knob back to those exact positions.", "purpose_function": "It lets an engineer store and recall a whole console or mixer state so different scenes, sections, or songs can be reset instantly and repeatably.", "practical_application": "A live engineer stores a snapshot for each song so the desk reconfigures at the touch of a button, and a studio engineer snapshots a starting balance before trying changes.", "category": "Automation", "related_terms": ["Automation trim mode", "Automation undo", "Scene recall", "Fader automation", "Total recall"], "common_mistakes": ["Confusing a snapshot, which is an instant static jump, with dynamic automation that records moves over time", "Forgetting that firing a snapshot overwrites current settings, causing an abrupt jump if triggered at the wrong moment", "Not re-saving a snapshot after tweaking settings, so the recall restores old values"], "scenario_contexts": ["Recalling a full desk setup for each song in a live show", "Storing a baseline mix balance before experimenting during a session", "Resetting a console to a known state at the start of a rehearsal"]}, "7975ef63-ee92-442a-9e65-b96fc9154bf9": {"definition": "An automation mode that records relative offsets to existing automation rather than absolute values; nudging a control adds or subtracts that amount from the underlying automation curve while preserving its shape.", "plain_english": "An automation mode that saves changes as a little louder or a little quieter instead of exact levels. It keeps the shape of your old moves and just shifts them up or down.", "purpose_function": "It lets an engineer adjust an overall level or balance across a passage without erasing the detailed automation moves already written underneath.", "practical_application": "After writing detailed vocal rides, an engineer switches to trim to raise the whole vocal by a decibel through the chorus while keeping every existing move intact.", "category": "Automation", "related_terms": ["Automation snapshot", "Automation undo", "Write mode", "Touch mode", "Fader automation"], "common_mistakes": ["Thinking trim writes absolute levels when it only adds an offset to what is already there", "Forgetting to coalesce or commit trim moves, leaving a separate trim layer that confuses later edits", "Leaving a channel in trim when a fresh absolute pass was intended"], "scenario_contexts": ["Raising a whole vocal line a decibel while keeping existing rides", "Balancing a submix level without redoing detailed automation", "Making a global correction after a client asks for more guitar throughout"]}, "218573e4-1d9f-4593-8832-bb78c6779bd3": {"definition": "The function that reverses the most recent automation edit or recorded pass, restoring the automation data to its previous state within the project's edit history.", "plain_english": "A button that takes back your last automation change. If a move sounds wrong, undo puts the settings back the way they were.", "purpose_function": "It gives the engineer a safety net to experiment with automation freely, since any unwanted move can be reversed step by step.", "practical_application": "After a fader pass goes wrong, the engineer hits undo to drop the bad automation and try the ride again from the previous version.", "category": "Automation", "related_terms": ["Automation snapshot", "Automation trim mode", "Write mode", "Edit history", "Fader automation"], "common_mistakes": ["Assuming undo can recover automation from before the project was closed, when the history usually clears on close", "Undoing past an intended point and losing good edits along with the bad one", "Confusing undo of an automation pass with disabling automation playback"], "scenario_contexts": ["Reversing a botched fader ride during mixing", "Stepping back through several automation edits to find a better take", "Recovering the previous curve after an accidental overwrite"]}, "81a6129e-0f9e-4f5e-bed8-7d54fe38534e": {"definition": "How well a finished mix keeps its intended tonal balance, clarity, and level relationships when played over a car audio system, which is one of the most common real-world environments used to check whether a mix holds up.", "plain_english": "How good your mix sounds when you play it in a car. Cars have odd speakers and road noise, so a mix that holds up there usually works almost anywhere.", "purpose_function": "Checking a mix in a car reveals balance and low-end problems that a treated studio can hide, helping ensure the mix works on the systems most listeners actually use.", "practical_application": "After finishing a rough mix, an engineer bounces it to a phone and listens in the car to judge whether the vocal, bass, and kick still sit right.", "category": "Mix translation", "related_terms": ["Mix translation", "Reference monitoring", "Mono compatibility", "A/B referencing", "Nearfield monitor"], "common_mistakes": ["Judging a car listen at very high volume, which flatters the low end and misleads decisions", "Trusting only one car and treating its coloured sound as the truth", "Making big EQ moves by ear in the car without confirming them back on studio monitors"], "scenario_contexts": ["Checking a near-final mix on the drive home from the studio", "Comparing a mix to a commercial reference track in the same car", "Spotting excess or weak bass that the studio room masked"]}, "1a4ec082-ccb2-487c-87bc-d6f6b2134dd7": {"definition": "The release-planning decision to designate a completed recording as the B-side—the secondary track paired with the promoted A-side (lead single)—of a single release.", "plain_english": "It means picking which finished song rides along as the extra track on a single, behind the main hit. The A-side is the star; the B-side is the bonus track.", "purpose_function": "It determines which mix or master is delivered and promoted as the lead track versus the supporting track, shaping the release package and its metadata.", "practical_application": "When prepping a single for release, an engineer or label labels and delivers one master as the A-side and assigns another finished mix as the B-side.", "category": "Release & Delivery", "related_terms": ["Delivery master", "Broadcast master", "Archival master", "Mastering", "Metadata"], "common_mistakes": ["Assuming the B-side is a lower-quality or unfinished mix rather than a fully mastered release track", "Confusing the physical A/B sides of vinyl with streaming-era 'single plus bonus track' assignments", "Mislabeling deliverable files so the A-side and B-side masters are swapped"], "scenario_contexts": ["Choosing which of two finished songs becomes the B-side of a 7-inch vinyl single", "Assigning a remix or alternate version as the B-side of a digital single", "Preparing delivery files and metadata that identify the A-side and B-side"]}, "efd8c411-2f62-4883-a1ea-16d8cd1b5149": {"definition": "In audio post-production, a consolidated intermediate mix of all the background (ambience/atmosphere) sound effects, balanced and processed as a group before the final re-recording mix so the many background tracks can be handled as one manageable element.", "plain_english": "A rough mix that blends all the background sounds, like room tone, traffic, or wind, into one tidy group. It gets the atmospheres balanced early so the final mix has fewer things to juggle.", "purpose_function": "It reduces a huge number of background tracks to a controllable sub-mix, letting the re-recording mixer set the overall ambience level quickly during the final mix.", "practical_application": "A sound editor premixes dozens of city-ambience tracks into a backgrounds premix so the dub-stage mixer can ride one background level against dialogue and effects.", "category": "Post-production", "related_terms": ["Backgrounds-only stem", "Premix", "Re-recording mix", "Stem", "Dialogue premix"], "common_mistakes": ["Baking in too much level or EQ so the final mixer loses room to adjust the backgrounds", "Confusing a backgrounds premix, which is a working sub-mix, with a delivered stem", "Printing backgrounds too loud against dialogue, forcing rework at the dub stage"], "scenario_contexts": ["Consolidating many ambience tracks before a film's final dub", "Preparing TV episode atmospheres so the mix stage runs efficiently", "Balancing crowd and room tones as one element ahead of the final mix"]}, "2dc6aaa9-f80f-47ad-9f48-76f7e0454724": {"definition": "A delivered stem containing only the background (ambience/atmosphere) elements of a mix, isolated from dialogue, music, and foreground effects, so the backgrounds can be recalled, replaced, or re-balanced independently.", "plain_english": "A separate audio file that holds just the background sounds of a scene, with no dialogue or music. It lets someone later change or reuse the atmospheres on their own.", "purpose_function": "It exists so backgrounds can be adjusted, muted, or swapped later, for example during foreign-language versions or re-edits, without touching the other elements.", "practical_application": "A studio delivers a backgrounds-only stem so a foreign-language dub can keep the original ambiences while replacing the dialogue.", "category": "Post-production", "related_terms": ["Backgrounds premix", "Stem", "M&E stem", "Dialogue stem", "Re-recording mix"], "common_mistakes": ["Leaving foreground spot effects or dialogue bleed in what should be a clean backgrounds stem", "Confusing a backgrounds-only stem with a full effects stem that also holds hard effects", "Not matching the stem's level and processing to the final mix, so it will not sum back correctly"], "scenario_contexts": ["Delivering separated stems for a film's international versions", "Rebalancing ambience level during a client revision without a full remix", "Reusing scene atmospheres in a trailer or re-edit"]}, "c9544dcb-9f86-4011-9ae1-2cee6b1b5a89": {"definition": "Unwanted sound from the stage backline, such as guitar and bass amps or the drum kit, that leaks into microphones intended for other sources, colouring those channels and reducing separation.", "plain_english": "When loud gear on stage, like guitar amps or drums, bleeds into microphones meant for other things. The extra sound leaks in and makes each channel harder to control.", "purpose_function": "It names a common cause of poor separation on stage, and recognizing it guides microphone choice, placement, and stage layout so channels stay cleaner.", "practical_application": "Hearing a guitar amp in the vocal mic, an engineer angles or moves the amp, chooses a tighter cardioid mic, or gates the channel to cut backline spill.", "category": "Live sound", "related_terms": ["Spill", "Microphone bleed", "Noise gate", "Stage volume", "Isolation"], "common_mistakes": ["Trying to EQ out spill instead of fixing stage volume or mic placement, which rarely works", "UNSAFE: Raising stage monitor and amp levels to mask spill, driving stage SPL to levels that risk hearing damage over a show", "Gating too hard so wanted parts of the source get chopped along with the spill"], "scenario_contexts": ["A loud guitar amp bleeding into the lead vocal mic at a club gig", "Drum spill into vocal mics blurring a live recording of the band", "Bass amp energy leaking into every open channel on a small stage"]}, "79c0e933-362a-4d00-8fb9-54fb49ed183c": {"definition": "A transition, edit, or arrangement change placed exactly on a bar (measure) boundary so it lands in time with the musical grid, keeping the groove intact across the change.", "plain_english": "A change in the music, like a new section or a cut, that lands right at the start of a bar. Because it hits on the beat grid, the switch feels smooth and in time.", "purpose_function": "Aligning transitions to bars keeps edits musical and rhythmically seamless, which is essential for looping, arranging, and joining sections without breaking the pulse.", "practical_application": "When rearranging a song in a DAW, an engineer snaps the cut between verse and chorus to the downbeat of a bar so the join sounds natural.", "category": "Editing", "related_terms": ["Snap to grid", "Crossfade", "Arrangement", "Downbeat", "Quantize"], "common_mistakes": ["Cutting on the visual waveform instead of the bar line, so the edit drifts off the beat", "Ignoring pickup notes that start before the bar, which get chopped off by a strict bar cut", "Assuming a bar-aligned cut is beat-perfect when the project tempo map is wrong"], "scenario_contexts": ["Snapping a verse-to-chorus cut to the downbeat while arranging in a DAW", "Building a seamless loop that repeats cleanly every bar", "Editing a live recording so section joins stay in time"]}, "ffa8021c-bdf2-4141-8e57-6ccb355cd965": {"definition": "The component of an audio program that analyzes a recording to find where beats and transients occur, generating timing points the software can use for tempo mapping, quantizing, warping, or slicing. It works by detecting sudden rises in level or energy that mark rhythmic hits.", "plain_english": "The part of music software that listens to a track and works out where each beat lands. It is like tapping your foot to a song, except the computer marks every hit so it can line things up.", "purpose_function": "It removes the need to find beats by hand, so the software can sync audio to a tempo grid, match loops, or fix timing quickly and consistently.", "practical_application": "An engineer drops a drum loop into a session, lets the beat detection engine mark each hit, then uses those points to lock the loop to the project tempo.", "category": "Tempo & Timing", "related_terms": ["Transient", "Tempo map", "Warp marker", "Quantize", "Grid", "BPM"], "common_mistakes": ["Assuming detection is perfect and not checking for missed or false beats", "Running detection on a busy, reverb-heavy mix where transients are unclear", "Confusing beat detection with pitch detection", "Leaving stray markers in place before warping, which smears the audio"], "scenario_contexts": ["Matching an imported drum loop to the session tempo", "Building a tempo map from a freely played recording", "Slicing a drum break into hits for a sampler"]}, "2ad575d4-bf30-43b5-bd0a-016e268adaf7": {"definition": "In a DAW, the track or lane used for beat mapping: matching the software's bar and beat grid to audio that was recorded without a click, by marking where each beat or bar falls so the tempo map follows the performance rather than forcing it onto a fixed grid.", "plain_english": "A special track where you show the software where the beats of a song are. It is used when a song was played without a click, so the computer follows the real timing instead of a steady grid.", "purpose_function": "It makes the DAW's grid follow a human performance, so you can add loops, edits, or MIDI parts that stay in time even when the tempo drifts.", "practical_application": "A producer imports a live band recording, then uses the beat mapping track to mark where each bar lands so added samples snap to the real groove.", "category": "Tempo & Timing", "related_terms": ["Tempo map", "Beat marker", "Grid", "Warp marker", "Metronome", "BPM"], "common_mistakes": ["Confusing beat mapping, where the grid follows the audio, with warping, where the audio follows the grid", "Placing bar lines on the wrong beat and shifting the whole map", "Skipping tempo changes, so the grid slips against a drifting performance", "Mapping to a weak or missed transient"], "scenario_contexts": ["Adding programmed parts to a live, click-free recording", "Making a loose, rubato performance editable on the grid", "Building a tempo map before quantizing overdubs"]}, "e9d55eae-9263-4b91-8fa8-9160d79934a6": {"definition": "A marker placed at a beat or transient point on an audio clip, showing the software where a rhythmic hit occurs so the audio can be warped, quantized, sliced, or tempo-mapped to that point.", "plain_english": "A small tag placed on a sound to show exactly where a beat hits. It works like a sticky note on a drum hit, so the software knows where to line things up.", "purpose_function": "It gives the DAW fixed reference points on the audio, so timing edits, stretching, and grid alignment all happen at the right spots.", "practical_application": "An engineer nudges a beat marker onto a snare that landed early, then quantizes so the marker snaps to the grid and tightens the groove.", "category": "Tempo & Timing", "related_terms": ["Transient", "Warp marker", "Quantize", "Beat Mapping track", "Grid", "Tempo map"], "common_mistakes": ["Leaving false markers on non-beat sounds like bleed or reverb tails", "Moving a marker so far that it stretches the audio into artifacts", "Confusing beat markers with arrangement or cue markers", "Deleting needed markers and losing the timing reference"], "scenario_contexts": ["Tightening a loose drum take to the grid", "Slicing a loop at each hit for re-triggering", "Setting reference points before tempo mapping"]}, "8a915222-84ce-470c-b19b-707aa4ed4b44": {"definition": "The practice of creating a rhythm or drum part by entering notes or steps into a sequencer or drum machine rather than recording a live performance, building the pattern hit by hit on a grid with control over timing, velocity, and sound choice.", "plain_english": "Making a drum beat by placing each hit into the software by hand, instead of playing drums live. It is like building a rhythm out of blocks on a grid, one hit at a time.", "purpose_function": "It lets a producer craft precise, repeatable rhythms with full control, even without drumming skills or a live kit.", "practical_application": "A producer opens a step sequencer and clicks in a kick, snare, and hi-hat pattern, then adjusts swing and velocity to make it groove.", "category": "Rhythm & Sequencing", "related_terms": ["Step sequencer", "Drum machine", "Quantize", "Groove", "MIDI", "Velocity"], "common_mistakes": ["Leaving every hit at the same velocity, so the beat sounds robotic", "Over-quantizing until the groove feels stiff and lifeless", "Ignoring how a real kit cannot play two conflicting hits at once", "Programming parts that feel unnatural for the chosen sounds"], "scenario_contexts": ["Building a drum track for an electronic song", "Sketching a rhythm before tracking a live drummer", "Creating a guide groove for a session"]}, "9f546013-02c8-4498-b7a1-3e3c1ff5e8cd": {"definition": "The process of reordering or restructuring the rhythmic events or sections of a track by cutting, copying, and moving beats or bars, changing the arrangement or groove while keeping the underlying recorded material.", "plain_english": "Changing the order of the beats or sections in a track by cutting and moving pieces around. It is like rearranging blocks you already built into a new pattern.", "purpose_function": "It lets an editor reshape a groove or song structure, fix timing, or create fills and variations without recording anything new.", "practical_application": "An editor chops a drum loop into single hits, then reorders them to build a fill or a fresh variation for the chorus.", "category": "Editing", "related_terms": ["Beat marker", "Quantize", "Groove", "Arrangement", "Crossfade", "Slice"], "common_mistakes": ["Cutting on the wrong point so edits click or lose the groove", "Forgetting crossfades, leaving audible pops at each join", "Rearranging so heavily that the part loses its natural feel", "Not matching levels between moved pieces"], "scenario_contexts": ["Turning a plain loop into a varied drum track", "Building fills from existing hits", "Reshaping a performance during editing"]}, "69ac4bf0-8576-4e39-94d8-2df2721bfe62": {"definition": "A change from one section, clip, or song to another that is timed to land on a beat of the music, so the switch feels rhythmically smooth rather than abrupt or off-time.", "plain_english": "A change between two parts of the music that happens right on a beat. It is like switching songs at the exact moment the drum hits, so it feels smooth instead of clumsy.", "purpose_function": "It keeps energy and flow intact across a transition, which matters in DJ sets, edits, and arrangements where an off-beat change would feel jarring.", "practical_application": "A DJ lines up the grids of two tracks and starts the crossfade on the downbeat, so the switch stays locked to the groove.", "category": "Editing", "related_terms": ["Crossfade", "Grid", "Beat marker", "Quantize", "BPM", "Arrangement"], "common_mistakes": ["Starting the transition off the beat, causing a stumble in the groove", "Ignoring that the two parts run at different tempos", "Cutting mid-phrase so the change feels unfinished", "Forgetting to match keys or levels across the change"], "scenario_contexts": ["Mixing two songs together in a DJ set", "Cutting between sections in an arrangement", "Editing a live recording into a seamless montage"]}, "11c29756-19b6-4974-9723-0d5780732f0c": {"definition": "The practice of muting a channel, group, or the main output during the gap between songs in a live performance, silencing handling noise, tuning, chatter, and potential feedback until the next song begins.", "plain_english": "Turning off the sound between songs at a show, so the crowd does not hear tuning, bumps, or hum. It is like hitting mute during a break so only the music comes through.", "purpose_function": "It keeps the pauses between songs clean and controlled, preventing unwanted noise and reducing the risk of feedback while the band resets.", "practical_application": "A live engineer mutes the vocal and instrument channels between songs, then unmutes on cue as the next song starts.", "category": "Live Sound", "related_terms": ["Mute", "Mute group", "Feedback", "Fader", "Channel strip", "Gain staging"], "common_mistakes": ["Forgetting to unmute before the next song starts", "UNSAFE: leaving an open mic hot between songs so handling or a feedback squeal blasts the PA and risks hearing", "Muting the wrong channel or mute group", "Muting so late that the noise still reaches the audience"], "scenario_contexts": ["Silencing tuning and chatter between songs at a concert", "Preventing feedback while performers move or swap instruments", "Keeping a live recording or broadcast clean during song gaps"]}, "ac448793-5737-4c05-a499-ebc3e7945ab7": {"definition": "In Reason Studios' Reason, a sequencer view where an engineer records and edits reusable multi-track sections called Blocks, which can then be placed and repeated along the timeline in Song view to build an arrangement.", "plain_english": "A way of working in Reason where you build short, reusable song sections called blocks. It is like making a few pieces once, then snapping copies together to build the whole song.", "purpose_function": "It speeds up arranging by letting you create a verse, chorus, or drum section once and reuse it, instead of copying clips over and over.", "practical_application": "A producer builds an 8-bar chorus Block in Block mode, then drops it wherever the chorus repeats in Song view and tweaks a few clips for variation.", "category": "Arrangement", "related_terms": ["Arrangement", "Clip", "Sequencer", "Loop", "Pattern", "Song view"], "common_mistakes": ["Confusing Block view edits with Song view, since each keeps its own clips", "Expecting a Block change to update copies that were separately altered", "Overusing repeated Blocks so the song feels static", "Forgetting to switch back to Song view to arrange the Blocks"], "scenario_contexts": ["Building reusable verse and chorus sections in Reason", "Sketching a song structure quickly from repeated parts", "Combining Blocks with linear clips for variation"]}, "8146d1a2-0a30-4396-87ed-ec0bf371befb": {"definition": "In sound layering, the body layer is the component of a stacked or composite sound that supplies its fullness and weight, carrying the low-mid fundamental energy (roughly the 150 Hz to 800 Hz region). It sits between the sub layer, which provides the deepest lows, and the top or attack layer, which provides high-frequency click and definition.", "plain_english": "When you stack sounds to build one big sound, the body layer is the part that gives it fullness and warmth. Think of it like the trunk of a tree: the sub layer is the roots and the top layer is the leaves, but the body is the solid middle that holds it together.", "purpose_function": "It gives a layered sound its core tone and perceived size, filling the low-mid range so the sound feels full instead of thin or hollow.", "practical_application": "When layering a kick, bass, or synth, a producer chooses or shapes a body layer to add warmth and mass, often using EQ to carve its low-mids so it does not clash with other parts.", "category": "Sound Layering", "related_terms": ["Sub layer", "Attack layer", "Layering", "Equalization", "Frequency masking", "Sound design"], "common_mistakes": ["Choosing a body layer that sits in the same frequencies as the bass, causing a muddy, masked low-mid buildup.", "Leaving every layer full-range instead of filtering each one so the body layer owns its band.", "Confusing the body layer (low-mid fullness) with the sub layer (deep lows) and boosting the wrong one."], "scenario_contexts": ["Stacking two or three kick samples where one gives the click, one the body, and one the sub.", "Designing a lead synth by combining a bright top layer with a warmer body layer for weight.", "Reinforcing a thin recorded bass by adding a synth body layer underneath it."]}, "9027107a-9075-4770-9ca6-bf07d5d0d5c0": {"definition": "In video game audio, a distinct musical cue that plays during a boss encounter—typically a heightened, more intense or dramatic piece that signals a major challenge and often differs sharply from the surrounding level music.", "plain_english": "It is the special, intense music that kicks in when you fight a big enemy in a game. It tells you this fight is a huge deal.", "purpose_function": "It heightens tension and signals the stakes of a major fight, giving players an emotional and gameplay cue that the encounter matters more than normal combat.", "practical_application": "A game composer writes a dedicated boss theme, and an audio implementer triggers it—often with a transition from the level music—when the boss fight begins.", "category": "Game Audio", "related_terms": ["Combat music", "Defeat music", "Adaptive music", "Delayed transition"], "common_mistakes": ["Assuming boss music must be loud or fast when its role is to signal significance, which some games do with quieter, ominous themes", "Forgetting to score a smooth transition into and out of the boss cue, causing an abrupt musical jump", "Treating boss music as a fixed loop when many games layer or adapt it to the fight's phases"], "scenario_contexts": ["Triggering a unique theme when the player enters a boss arena", "Transitioning from exploration music into boss music as a fight begins", "Layering an extra intensity section of the boss theme when the boss reaches a second phase"]}, "f8ac5abc-1e7d-4360-8428-55e226dc2097": {"definition": "Bouncing mixer channels is the process of rendering the output of one or more mixer channels to new audio files, either as a single combined mixdown or as separate stems. The bounce prints all channel processing (level, pan, EQ, dynamics, and effects) into fixed audio, performed offline (faster than real time) or in real time.", "plain_english": "To bounce mixer channels means to turn what you hear on those channels into new audio files. It is like taking a photo of the finished sound so you can save it, send it, or free up the computer.", "purpose_function": "It commits a mix or a group of channels to audio for delivery, archiving, or to lighten the processing load on the computer during a session.", "practical_application": "A technician bounces the master bus to create the final mix file, or bounces groups of channels into stems that a mastering engineer or another studio can reopen.", "category": "Mixdown & Export", "related_terms": ["Stems", "Mixdown", "Rendering", "Freeze track", "Master bus", "Offline bounce"], "common_mistakes": ["Bouncing with a channel or plug-in accidentally muted or soloed, so the exported file is missing parts.", "Choosing real-time bounce when offline would be fine, wasting time, or using offline when a hardware insert needs real time.", "Forgetting to match the bounce sample rate and bit depth to the delivery specification."], "scenario_contexts": ["Exporting the final stereo mix to send for mastering.", "Printing stems for a live-show playback rig.", "Committing a heavy virtual instrument to audio to save CPU."]}, "2bddb806-624f-494c-bde2-7c97061d712e": {"definition": "Breakbeat slicing is the technique of cutting a sampled drum break into individual segments, usually at the transient of each hit, so the pieces can be rearranged, retriggered, and matched to a new tempo. The slices are mapped to a sampler, drum pads, or MIDI notes for creative resequencing.", "plain_english": "A breakbeat is a drum loop taken from a record. Slicing means chopping it into single drum hits so you can play them back in any order and at any speed, like cutting a sentence into words and making a new sentence.", "purpose_function": "It frees a drum loop from its original tempo and order, letting a producer reshape the groove and lock it to the project tempo.", "practical_application": "A producer loads a break such as the Amen into a slicer, detects the transients, and remaps the hits to build new jungle, drum-and-bass, or hip-hop patterns.", "category": "Sampling & Editing", "related_terms": ["Transient detection", "Sampler", "Quantization", "Time-stretching", "Warping", "Breakbeat"], "common_mistakes": ["Placing slice points off the transient, so hits start late or with an audible click.", "Relying only on auto-slicing without checking and nudging the markers by hand.", "Time-stretching carelessly after slicing, so the break loses its natural swing."], "scenario_contexts": ["Chopping the Amen break to program a jungle drum pattern.", "Rearranging a funk drum loop to fit a new song at a different tempo.", "Extracting single hits from a break to build a custom drum kit."]}, "a0927cd8-386e-435c-8d54-365ae19c1ad3": {"definition": "Broadcast compliance is the state of a programme meeting a broadcaster's technical delivery specifications, most importantly integrated loudness and true-peak limits. In practice this means normalising the programme to a loudness target such as -23 LUFS under EBU R128 or -24 LKFS under ATSC A/85, measured with an ITU-R BS.1770 meter, with true peaks kept at or below -1 dBTP.", "plain_english": "Broadcast compliance means your mix follows the loudness and level rules a TV or radio station sets. It is like the weight limit for airline bags. If the audio is too loud, or peaks too high, the station will turn it down.", "purpose_function": "It keeps loudness consistent between programmes and adverts so viewers are not blasted or forced to ride the volume, which is also a legal requirement in some regions.", "practical_application": "Before delivery, an engineer sets the mix to the required loudness target and true-peak ceiling for the destination and checks it on a compliant loudness meter.", "category": "Broadcast Delivery", "related_terms": ["LUFS", "True peak", "EBU R128", "ITU-R BS.1770", "Loudness normalization", "Dialnorm"], "common_mistakes": ["Mixing by peak meters alone and ignoring integrated loudness, so the mix fails the specification.", "Confusing loudness units (LUFS) with sample peak and letting true peaks exceed -1 dBTP.", "Assuming one target fits every outlet instead of checking each broadcaster's specification."], "scenario_contexts": ["Delivering a TV commercial that must meet the CALM Act / ATSC A/85 target.", "Preparing a programme for a European broadcaster to EBU R128.", "Re-checking loudness after a last-minute re-edit before hand-off."]}, "f79fbc90-541c-41f8-8134-fade2f8af274": {"definition": "Broadcast compliance verification is the quality-control step of measuring a finished programme against the broadcaster's technical specification and confirming it passes before delivery. It typically means running an ITU-R BS.1770 loudness meter to check integrated loudness, loudness range, and maximum true peak against the required limits, for example -23 LUFS and -1 dBTP under EBU R128.", "plain_english": "This is the final check that proves your mix obeys the station's loudness and level rules. It is like weighing your suitcase on the airport scale before you fly, so you know it will pass.", "purpose_function": "It catches loudness or peak problems before hand-off, preventing costly rejects, re-deliveries, or on-air penalties.", "practical_application": "An engineer runs the completed file through a loudness meter or automated QC tool, reads the integrated loudness and true-peak values, and logs that they meet the delivery specification.", "category": "Broadcast Delivery", "related_terms": ["Integrated loudness", "True peak", "EBU R128", "ITU-R BS.1770", "Loudness meter", "Quality control"], "common_mistakes": ["Measuring only a short section instead of the whole programme for integrated loudness.", "Trusting a plug-in meter that is not ITU-R BS.1770 compliant.", "Verifying loudness but forgetting the separate true-peak limit."], "scenario_contexts": ["Running final QC on a documentary before uploading to a broadcaster portal.", "Checking a batch of adverts for CALM Act loudness before air.", "Confirming a re-versioned mix still passes after edits."]}, "3e6fadc7-b998-412f-b30c-73c20c77c9c0": {"definition": "A broadcast master is the final approved master version of a mix conformed to a broadcaster's delivery requirements and ready for air or hand-off. It carries the correct integrated loudness, true-peak ceiling, channel layout, and file format for the target outlet.", "plain_english": "The broadcast master is the finished, approved audio made to fit a TV or radio station's rules. It is the ready-to-play copy the station actually airs, not a rough draft.", "purpose_function": "It provides a single, spec-correct deliverable so the programme airs at the right loudness and levels without further adjustment.", "practical_application": "After the mix is signed off, the engineer renders a broadcast master at the required loudness and format, checks it, and delivers it to the broadcaster.", "category": "Broadcast Delivery", "related_terms": ["Broadcast compliance", "Broadcast printmaster", "Master bus", "LUFS", "Deliverables", "Stems"], "common_mistakes": ["Delivering the streaming or CD master instead of one conformed to the broadcaster's loudness specification.", "Wrong channel order or missing M&E, making the broadcast master unusable.", "Skipping a final loudness check on the rendered master."], "scenario_contexts": ["Rendering the on-air master of a TV episode to EBU R128.", "Creating the broadcast master of a commercial for network delivery.", "Archiving the approved broadcast master alongside the stems."]}, "e961511d-3849-4bef-ad93-3a83f25f9c5c": {"definition": "A broadcast mix version is an alternate version of a programme's mix prepared specifically for broadcast delivery, conformed to the outlet's loudness and true-peak specifications and, where required, edited for content (such as removing explicit language) or for timing. It sits alongside other versions such as the theatrical, streaming, or clean mixes.", "plain_english": "This is a copy of the mix made just for TV or radio. It follows the station's loudness rules and may swap out swear words or fit a set run time, so it can differ from the version you stream at home.", "purpose_function": "It lets one project meet different outlets' technical and content rules by supplying a mix tailored to broadcast, without changing the original mix.", "practical_application": "An engineer creates a broadcast mix version by conforming loudness to spec and muting or replacing flagged words, then delivers it as a separate file.", "category": "Broadcast Delivery", "related_terms": ["Broadcast master", "Clean version", "M&E", "Loudness normalization", "Deliverables", "Broadcast compliance"], "common_mistakes": ["Overwriting the original mix instead of saving broadcast as a separate version.", "Editing language but forgetting to re-check loudness afterwards.", "Assuming the broadcast version and streaming version share the same loudness target."], "scenario_contexts": ["Making a radio-clean version of a song with explicit lyrics.", "Delivering a TV-timed cut of a programme to a network's loudness spec.", "Supplying a broadcast version plus a streaming version from the same session."]}, "a39250b5-d7c4-4313-9c94-2ea7c2952a57": {"definition": "A broadcast printmaster is the final combined mixed master of a programme, with dialogue, music, and effects summed together, conformed to broadcast delivery specifications and used to produce the on-air deliverable. It is the broadcast-spec form of the printmaster, distinct from the separate dialogue, music, and effects stems delivered for versioning and foreign-language dubbing.", "plain_english": "A printmaster is the finished soundtrack. Dialogue, music, and effects are all mixed into one. A broadcast printmaster is that soundtrack set to a TV station's rules. It is ready to go on air.", "purpose_function": "It supplies the single, fully mixed, spec-correct soundtrack a broadcaster plays, while the matching stems allow later re-versioning or foreign-language dubs.", "practical_application": "In post-production, the re-recording mixer prints the final mix to a broadcast printmaster at the required loudness and format, and also prints the dialogue, music, and effects stems for delivery.", "category": "Broadcast Delivery", "related_terms": ["Broadcast master", "Stems", "M&E", "Final mix", "Broadcast compliance", "Deliverables"], "common_mistakes": ["Confusing the printmaster (the combined full mix) with stems (the separated dialogue, music, and effects groups).", "Delivering a printmaster that misses the broadcaster's loudness or channel specification.", "Failing to keep the printmaster and its stems in sync after a late change."], "scenario_contexts": ["Printing the final broadcast soundtrack of a TV drama once the mix is locked.", "Delivering a broadcast printmaster plus dialogue, music, and effects stems to a network.", "Re-conforming an existing printmaster to a broadcaster's loudness target."]}, "8459064d-e117-47fe-9357-c97c93a4b4c9": {"definition": "The degree to which a finished mix keeps its intended tonal balance, clarity, and impact after passing through broadcast processing and playback on broadcast systems, including loudness normalization, mono fold-down, peak and loudness limiting, and small consumer speakers such as those in televisions and radios.", "plain_english": "How well a song still sounds right after it goes out over TV or radio. Broadcast gear squashes the loud parts and can shrink the sound, so a mix that ignores this may come out weak or muddy on a small TV speaker.", "purpose_function": "It names a quality goal in mixing: making sure the balance and detail a listener hears survives the extra processing and limited speakers used in broadcast, not just sounding good in the studio.", "practical_application": "Engineers check broadcast translation by referencing on small and mono speakers and by metering to broadcast loudness targets, so the mix holds up when aired on TV, radio, or streaming that applies loudness normalization.", "category": "Mixing Concept", "related_terms": ["Mix translation", "Loudness normalization", "Mono compatibility", "Reference monitoring", "LUFS"], "common_mistakes": ["Mixing only on large studio monitors and never checking small or mono speakers, so problems only appear once the mix is aired.", "Ignoring broadcast loudness targets and delivering an over-limited mix that gets turned down and sounds flat on air.", "Assuming heavy low end that sounds good in the studio will survive on tiny broadcast speakers."], "scenario_contexts": ["Preparing a song mix that will air on FM radio and needs to stay punchy on car and kitchen radios.", "Mixing a TV commercial bed so dialogue and music stay clear through television speakers and loudness limiting.", "Delivering a mix to a streaming service that applies loudness normalization on playback."]}, "0194f4e5-f530-4310-a7b2-496c65d0f6d3": {"definition": "The workflow stage of combining recorded tracks into a balanced whole by adding elements in a deliberate order and setting their relative level, panning, tone, and dynamics, typically starting from a foundational element such as the rhythm section or the lead vocal.", "plain_english": "The step where you take all the separate recorded tracks and blend them into one good-sounding song. You usually start with one key part, like the drums or the main singer, then add the rest one at a time until everything fits.", "purpose_function": "It turns a set of isolated recordings into a cohesive, balanced piece, giving the mix a clear structure and priority order rather than adjusting everything at random.", "practical_application": "A mixer builds the mix by bringing up faders in a chosen order, setting levels and panning first, then refining EQ, dynamics, and effects as each part is added.", "category": "Mixing Workflow", "related_terms": ["Static mix", "Gain staging", "Balance", "Rough mix", "Panning", "Bus"], "common_mistakes": ["Adding effects and processing to each track before a solid level balance exists.", "Building the whole mix while soloing tracks, so parts do not fit together when heard as a group.", "Pushing every element louder instead of lowering competing parts, which leaves no headroom."], "scenario_contexts": ["Starting a mix session by setting a rough level balance before any detailed processing.", "Working a song up from a multitrack recording toward a first full-band balance.", "Rebuilding a balance from scratch after a rough mix reveals level problems."]}, "f802202e-849a-4505-b46e-b7c0a3e70ae2": {"definition": "The quality-control step of confirming that a mix's bus (subgroup/aux) routing, assignments, and levels are correct—verifying each source feeds the intended bus, that bus outputs reach the proper destinations, and that no unintended sums, gain errors, or missing feeds exist before printing or delivery.", "plain_english": "It means double-checking that every group of channels is wired to the right place before you finish the mix. It is like making sure each pipe empties into the correct tank.", "purpose_function": "It catches routing mistakes—wrong assignments, doubled signals, or dead buses—so the printed mix and stems match what the engineer intended.", "practical_application": "Before bouncing stems, an engineer checks the routing matrix and solos each bus to confirm drums, vocals, and effects land on their assigned subgroups at the right levels.", "category": "Signal Routing", "related_terms": ["Bus", "Subgroup", "Aux send", "Signal flow", "Clipping validation"], "common_mistakes": ["Assuming a channel is routed correctly because it makes sound, without confirming which bus it feeds", "Accidentally summing a signal to both a subgroup and the main bus, so it is counted twice", "Overlooking a bus whose output is unassigned, so its audio never reaches the mix or print"], "scenario_contexts": ["Verifying subgroup routing before printing stems for a film re-recording mix", "Checking that all input channels feed the correct buses after loading a session template", "Troubleshooting a missing instrument by confirming its bus assignment"]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"a8878869-6751-44c4-a050-1ab197dbf5c0": {"definition": "A view mode, found in DAWs such as Logic Pro, in which an editor or window automatically scrolls to keep the moving playhead visible during playback or recording, so the display always shows the section currently being played.", "plain_english": "A setting that makes the screen follow along with the moving play line as a song plays. Instead of the music scrolling off the edge, the view keeps jumping to show the part you are hearing right now.", "purpose_function": "It keeps the current playback position on screen without manual scrolling, so an engineer can watch and edit the audio that is playing in real time.", "practical_application": "A user turns Catch on when they want windows to track the playhead during playback, and off when they want the view to stay put on a fixed region while the song plays past it.", "category": "DAW Feature", "related_terms": ["Playhead", "Scroll in Play", "Edit window", "Transport", "Timeline"], "common_mistakes": ["Thinking Catch changes the audio, when it only affects how the display follows the playhead.", "Leaving Catch off and then wondering why the view will not follow playback.", "Confusing Catch, which follows the playhead, with continuous-scroll modes that keep the playhead centered."], "scenario_contexts": ["Following a long arrangement on screen during playback without manual scrolling.", "Punching in a recording and wanting the editor to stay on the current bar.", "Turning Catch off to keep a zoomed-in edit region in view while the song plays through it."]}, "1e8f151a-b0d6-4d8a-90ad-9796a0e89fef": {"definition": "In an Ableton Live Instrument, Drum, or Effect Rack, a draggable indicator on the Chain Select Ruler (a 0 to 127 scale) that determines which chains are active; only chains whose chain select zones overlap the selector's current value can pass signal and produce output.", "plain_english": "A slider inside an Ableton Live Rack that picks which of the stacked sound or effect paths is switched on. Each path responds to a range of positions, so moving the slider swaps between them, like turning a dial to choose a channel.", "purpose_function": "It lets one Rack hold several chains and switch or blend between them from a single control that can be mapped and automated, instead of needing separate tracks.", "practical_application": "A producer assigns each chain a chain select zone, then maps the chain selector to a knob or an automation lane to switch presets or morph between sounds live.", "category": "DAW Feature", "related_terms": ["Chain zone", "Instrument Rack", "Macro control", "Chain", "MIDI mapping"], "common_mistakes": ["Moving the chain selector but leaving chains with overlapping zones, so more than one chain sounds at once unexpectedly.", "Forgetting that the Chain Select Ruler stays hidden until the Chain Select Editor view is shown.", "Confusing the chain selector with key or velocity zones, which filter by note and by playing strength instead."], "scenario_contexts": ["Building a single Rack that switches between several synth presets from one knob during a performance.", "Setting up an effect Rack that morphs between different processing chains.", "Mapping the chain selector to automation so a track changes sound over the course of a song."]}, "9efed616-e279-4382-8576-c2d05621e529": {"definition": "In an Ableton Live Rack, the range on the Chain Select Ruler (0 to 127) assigned to a given chain; the chain is active only when the chain selector's value falls within or overlaps that zone, so the zone acts as a data filter at the Rack's input.", "plain_english": "The stretch of positions on a Rack's selector that turns one sound path on. If the selector lands inside that stretch, the path plays; if not, it stays silent. It works like setting which channel numbers switch on a given speaker.", "purpose_function": "It defines when each chain responds, letting a single Rack route the selector to different chains for switching or crossfading between sounds.", "practical_application": "A user drags the edges of each chain's zone in the Chain Select Editor so the chains switch cleanly, or overlaps them with fades to blend between chains as the selector moves.", "category": "DAW Feature", "related_terms": ["Chain selector", "Instrument Rack", "Chain", "Key zone", "Velocity zone"], "common_mistakes": ["Setting zones with unintended overlap, so two chains sound together when only one was wanted.", "Leaving a chain's zone outside the selector's range, so the chain never plays.", "Mixing up chain zones with key or velocity zones, which filter by note pitch or by playing strength."], "scenario_contexts": ["Assigning each preset in a Rack its own zone so a knob steps through them.", "Creating overlapping zones with fades to morph between two textures.", "Troubleshooting a chain that never sounds because its zone does not meet the selector value."]}, "a1ca4a48-1981-49f8-9da8-aaaeb30ef7a9": {"definition": "Recorded music played over a venue's PA system during the changeover between acts, while one performer's equipment is struck and the next is set up and line-checked, used to cover the silence and hold the audience's attention.", "plain_english": "The recorded songs played through the speakers between live acts while the crew swaps gear on stage. It fills the quiet gap so the crowd stays relaxed and the room does not feel dead.", "purpose_function": "It keeps energy up and masks stage noise during the gap between performances, buying the crew time to reset the stage without leaving the audience in silence.", "practical_application": "The front-of-house engineer starts a changeover playlist from a media player or DAW at a comfortable background level, then fades or ducks it out as the next act is ready to begin.", "category": "Live Sound", "related_terms": ["Changeover", "Walk-in music", "Front of house", "Line check", "PA system"], "common_mistakes": ["Playing changeover music so loud that the stage crew cannot communicate during the reset.", "Forgetting to fade the music out before the act begins, so it clashes with the opening number.", "Leaving the media player routed so a line check or feedback burst blasts through it at full level."], "scenario_contexts": ["Covering the gap between bands at a club show while the stage is reset.", "Filling time during a festival changeover as the next act's backline is placed and line-checked.", "Providing background music before doors and between sets at a corporate event."]}, "56ad7097-ef73-4aba-949d-1c2e5b5f3beb": {"definition": "In Steinberg Cubase and Nuendo, a window that opens a single MixConsole channel on its own, showing that channel's full signal path, including inserts, EQ, sends, routing, and fader, in one focused view for detailed editing.", "plain_english": "A window in Cubase that shows everything for just one mixer channel at a time, like its effects, EQ, and volume. It lets you fine-tune one track without the clutter of the whole mixer on screen.", "purpose_function": "It gives a clear, single-channel overview so an engineer can edit one channel's processing and routing in detail without hunting through the full mixer.", "practical_application": "A user opens the Channel Settings window for a track to adjust its insert effects, EQ curve, and sends, and can open several windows to compare channels side by side.", "category": "DAW Feature", "related_terms": ["MixConsole", "Insert effect", "Channel EQ", "Send", "Routing"], "common_mistakes": ["Editing in the Channel Settings window without noticing which channel is selected, so changes land on the wrong track.", "Assuming it is a separate mixer, when it only shows the one channel already in the MixConsole.", "Overlooking that the EQ and inserts shown here are the same ones as in the main MixConsole."], "scenario_contexts": ["Dialing in EQ and compression on a lead vocal channel in detail.", "Comparing two channels by opening a Channel Settings window for each.", "Checking a channel's routing and send levels while troubleshooting a signal path."]}, "fc90be23-f616-4c6d-adc4-b8221d9d474c": {"definition": "The process of confirming that each mixer input channel is correctly patched, labeled, and passing clean signal at the expected level and polarity before a session or show. It verifies the whole path from source through preamp, gain staging and routing so faults are caught before they reach the mix.", "plain_english": "A quick check that every input on the mixing desk is plugged in right and passing sound. You go channel by channel to make sure each mic or instrument shows up where it should before the show starts.", "purpose_function": "It catches wiring, patching, phantom-power and labeling errors early, so no input ends up dead, mislabeled, or out of phase once the performance or mix begins.", "practical_application": "During line check a technician listens to each channel in turn, confirming the right source lands on the right fader with clean gain before soundcheck or tracking begins.", "category": "Signal Flow", "related_terms": ["Line check", "Gain staging", "Signal flow", "Phantom power", "Patch list", "Soundcheck"], "common_mistakes": ["Assuming a channel is fine because the meter moves, without confirming it is the correct source", "Skipping validation of spare or backup channels that are only needed later in the show", "UNSAFE: Hot-patching condenser mics with phantom power on and monitors up, which can send a loud, damaging pop through speakers and headphones", "Not checking polarity between paired mics, leaving phase cancellation baked into the mix"], "scenario_contexts": ["Line-checking a 32-input band before doors open at a club", "Confirming studio inputs are patched correctly before a multitrack tracking session", "Troubleshooting a dead or swapped channel found during soundcheck"]}, "2f36acc4-5c7b-43db-84d2-150b6e5e2fc7": {"definition": "A sequencer/DAW playback function that scans MIDI and related events occurring before the current start point and re-sends the relevant ones (such as program changes, controllers, pitch bend, sustain and sometimes held notes) so instruments are in the correct state when playback begins mid-project.", "plain_english": "A setting that lets your music software 'catch up' on MIDI note and control messages it skipped when you press play partway through a song. It resends things like the chosen sound, the sustain pedal, and pitch settings, so the part plays right.", "purpose_function": "It prevents wrong sounds, missing or stuck sustain, and incorrect pitch bend when you start playback partway through a track, by reconstructing the MIDI state that earlier events had set.", "practical_application": "When a producer starts from bar 30 and a synth still plays the correct patch and holds the sustain set at bar 1, chase events is doing that work; engineers choose which event types get chased in the project settings.", "category": "Sequencing", "related_terms": ["MIDI", "Program change", "Control change", "Pitch bend", "Sustain pedal", "Sequencer"], "common_mistakes": ["Thinking chase resends audio; it only reconstructs MIDI-style event states", "Chasing note events into samplers or drum loops, which can retrigger samples out of time", "Assuming every controller is chased by default when the option must often be enabled per event type", "Blaming a synth for wrong patches when program-change chasing is simply turned off"], "scenario_contexts": ["Starting playback mid-song and hearing the correct synth patch instead of the default", "Sustain-pedal state carried over when auditioning a section from the middle", "Fixing a part whose controller jumps to the wrong value on mid-song starts"]}, "341108e9-47d5-475a-beac-141190d90c9b": {"definition": "A live-sound practice of walking to the rear of the audience area, farthest from the stage and PA, to judge level, tonal balance, intelligibility and coverage there, since the back row hears the system very differently from the mix position. It confirms distant seats receive adequate, clear sound.", "plain_english": "Walking to the seats at the very back of the room to hear how the show sounds there. The back is far from the speakers, so you check it is still loud enough and clear, not muddy or too quiet.", "purpose_function": "It confirms the PA covers the whole audience, not just the mix position, so distant listeners get enough level and clarity despite the added distance and room reflections.", "practical_application": "During soundcheck an engineer walks to the back wall to confirm vocals stay intelligible and the low end has not built up, then returns to fine-tune EQ and system level.", "category": "Coverage Check", "related_terms": ["Coverage", "Mix position", "Soundcheck", "SPL", "Intelligibility", "System tuning"], "common_mistakes": ["Mixing only from the console position and never verifying the back rows", "UNSAFE: Pushing overall level to reach the back until front seats exceed safe SPL exposure limits", "Ignoring low-frequency buildup that collects near a rear wall", "Assuming coverage is even without actually walking the space"], "scenario_contexts": ["Soundcheck in a deep club where the back wall is far from the PA", "Checking speech intelligibility for a spoken-word event", "Diagnosing why patrons at the back report a muddy mix"]}, "df176023-1715-4416-9846-0cef385915b5": {"definition": "A live-sound practice of listening in the room's corners and edges, outside the main coverage pattern, to judge how much level and tone reaches off-axis seats and where bass buildup or coverage gaps occur. It reveals problems the on-axis mix position hides.", "plain_english": "Stepping into the corners of the room to hear the seats that sit off to the side. Corners often trap bass and can be too quiet or boomy, so you check the crowd there still gets good sound.", "purpose_function": "It exposes off-axis coverage loss and low-frequency buildup in corners, helping the engineer decide on speaker aim, fill speakers, or EQ so edge seats are not neglected.", "practical_application": "An engineer walks the room's corners during soundcheck to spot boomy bass or dropouts, then adjusts speaker angles, adds fills, or trims low EQ.", "category": "Coverage Check", "related_terms": ["Coverage", "Off-axis", "Fill speaker", "Room modes", "Low-frequency buildup", "System tuning"], "common_mistakes": ["Judging coverage only on-axis at the mix position", "Mistaking corner bass buildup for too much bass everywhere and cutting it globally", "Forgetting that corners can sit outside the speakers' coverage pattern", "Overlooking corner seats when planning fill speakers"], "scenario_contexts": ["Setting up in a rectangular hall with seating pushed into corners", "Chasing a boomy low end reported only at the room's edges", "Deciding whether fill speakers are needed for wide seating"]}, "1a051e41-d6ed-4cd7-8877-7186ed7a3e5b": {"definition": "A live-sound practice of listening at the frontmost seats, closest to the stage and PA, where level is highest and tonal balance is often harsh or bass-heavy, to ensure near-field listeners are not overwhelmed. It balances the needs of close seats against the rest of the room.", "plain_english": "Listening from the front seats, right up near the speakers and stage. It is the loudest, sometimes harshest spot, so you check the sound there is not painfully loud or too bright for the people sitting closest.", "purpose_function": "It checks the near-field extreme of the audience so front listeners get safe, comfortable level and tone, and it shows how uneven the system is from front to back.", "practical_application": "An engineer steps to the front row to gauge harshness and SPL, then may adjust speaker aim, high-frequency EQ, or level to protect close listeners while still covering the back.", "category": "Coverage Check", "related_terms": ["SPL", "Coverage", "Near field", "Speaker aim", "System tuning", "Hearing exposure"], "common_mistakes": ["UNSAFE: Ignoring dangerously high SPL at the front row while pushing level for the back", "Assuming the front sounds like the mix position", "Over-brightening the system for the back and leaving the front harsh", "Forgetting the front row hears far more direct stage sound"], "scenario_contexts": ["Checking SPL and harshness for patrons seated against the stage", "Balancing a system that is far too loud up front and weak at the back", "Aiming line-array boxes so the top covers distance without blasting the front"]}, "f6422af7-a524-4849-b1b8-face43fb8115": {"definition": "A live-sound practice of listening in the seats beneath a balcony overhang, an acoustically shadowed zone where the main PA's high frequencies and direct sound are blocked, to judge coverage, clarity and the need for delay or fill speakers. It targets one of a venue's hardest areas to cover.", "plain_english": "Going to the seats tucked under a balcony to hear how they sound. The balcony blocks sound from the main speakers, so these seats can be dull or unclear, and you check whether extra small speakers are needed.", "purpose_function": "It reveals the high-frequency loss and reduced clarity under a balcony overhang, guiding the use of under-balcony fill or delay speakers so those seats match the rest of the room.", "practical_application": "An engineer walks under the balcony to check intelligibility, then tunes under-balcony delay fills timed to the main system so speech and music stay clear.", "category": "Coverage Check", "related_terms": ["Delay speaker", "Fill speaker", "Coverage", "Shadow zone", "Intelligibility", "System tuning"], "common_mistakes": ["Assuming the mains cover under-balcony seats when the overhang blocks them", "Adding fill speakers without time-aligning them to the mains, smearing clarity", "Checking only open seating and ignoring the shadowed area", "Judging under-balcony coverage from the open floor nearby"], "scenario_contexts": ["Tuning delay fills for deep under-balcony seating in a theater", "Fixing muffled vocals reported by patrons beneath a balcony", "Designing coverage for a two-tier venue during system setup"]}, "c82b6019-b10b-47b7-badf-ab932ecfb7f3": {"definition": "A dedicated track in a DAW that holds a timeline of chord symbols defining a song's harmony, which the software can display, follow, and use to influence or conform the pitches of MIDI and sometimes audio tracks. It acts as a harmonic reference for the whole project.", "plain_english": "A special track in music software where you lay out the song's chords in order. Other tracks can follow it, so parts you play or record can be nudged to fit the chords you set.", "purpose_function": "It gives a project a single harmonic map, helping with composing, arranging, and keeping MIDI or audio parts in key without editing every note by hand.", "practical_application": "A producer enters a chord progression on the chord track, then has a piano MIDI part or arpeggiator follow it, quickly auditioning reharmonizations across the arrangement.", "category": "DAW Tools", "related_terms": ["MIDI", "Key", "Transpose", "Arpeggiator", "Chord pads", "Harmony"], "common_mistakes": ["Expecting the chord track to conform audio pitch as reliably as it conforms MIDI", "Forgetting to set tracks to follow the chord track, so nothing actually changes", "Confusing the chord track's guide role with an instrument that makes sound", "Entering chords in the wrong key or voicing and trusting the result blindly"], "scenario_contexts": ["Sketching a chord progression before recording melodies", "Reharmonizing a song and hearing MIDI parts update to the new chords", "Sharing a session's harmony map with a collaborator"]}, "85842147-9072-4000-961d-672304056652": {"definition": "A time-varying representation of audio that maps spectral energy into the twelve pitch classes (chroma) of the equal-tempered scale, collapsing all octaves so each column shows how much of each note name is present at that moment. It is widely used for chord, key, and harmonic analysis.", "plain_english": "A chart that shows which of the twelve note names, like C, C sharp, and D, are sounding at each moment, ignoring which octave they are in. It is a handy way for software to 'see' the harmony in a piece of music.", "purpose_function": "It reduces complex audio down to its pitch-class content, making it useful for automatic chord detection, key finding, and matching or comparing musical passages.", "practical_application": "Music-analysis and DAW tools compute a chromagram to label chords or find a track's key, and engineers may view it when using harmony-aware editing or tagging software.", "category": "Audio Analysis", "related_terms": ["Spectrogram", "Pitch class", "Chord detection", "Key detection", "FFT", "Harmony"], "common_mistakes": ["Confusing a chromagram with a spectrogram, which keeps full frequency detail and octaves", "Expecting perfect chord labels despite overtones and percussion blurring the chroma", "Assuming it shows octave or melody information, which it deliberately discards", "Trusting key detection from a chromagram on very noisy or atonal material"], "scenario_contexts": ["Automatic chord recognition in a music-analysis app", "Detecting a song's key before applying pitch effects", "Aligning a cover to an original using harmonic similarity"]}, "89c42e96-e620-463a-be06-51b9846c017c": {"definition": "In MOTU Digital Performer, the window that lists and manages a project's Chunks (independent sequences, songs, and V-racks), letting you create, rename, reorder, duplicate, and switch between them. It is the hub for handling multiple songs or cues inside one project file.", "plain_english": "In Digital Performer, a window that holds all the separate pieces of a project, called chunks. Each chunk can be its own song or section, and this window lets you name, sort, and jump between them.", "purpose_function": "It lets one project file contain many independent songs, sections, or film cues and switch among them quickly, instead of opening a separate file for each.", "practical_application": "A composer scoring to picture keeps each cue as a chunk and uses the Chunks window to jump between cues, duplicate a starting point, or arrange sections into a song.", "category": "DAW Tools", "related_terms": ["Sequence", "V-rack", "Song mode", "Digital Performer", "Project file", "Playlist"], "common_mistakes": ["Thinking a chunk is just a track rather than a whole self-contained sequence", "Losing track of which chunk is playing, since only one is active at a time", "Not using V-racks, so instruments are duplicated across chunks and waste resources", "Confusing Song chunks with Sequence chunks when arranging"], "scenario_contexts": ["Managing multiple film cues in one Digital Performer project", "Storing song variations as separate chunks for a client to compare", "Building a live set as chunks and switching between songs"]}, "f9ff1bbd-e847-41fa-8d04-bc8215b1180b": {"definition": "The production technique of stacking two or more handclap sounds (recorded claps, sampled claps, and often added room ambience or reverb) into one combined layer, usually placed on the backbeat, to create a fuller, wider, and more powerful clap than any single sample provides.", "plain_english": "Layering claps means stacking a few clap sounds so they play as one. This makes a bigger, fuller clap than a single one. It is like a crowd clapping instead of just one person.", "purpose_function": "It exists to give a clap or snare backbeat more size, width, and impact than a lone sample, letting the producer shape the tone by blending different claps and adding space.", "practical_application": "A producer stacks a tight electronic clap, a live-sounding acoustic clap, and a short reverb tail on beats 2 and 4, then adjusts each layer's level and timing so they hit as one solid sound.", "category": "Drum Programming", "related_terms": ["Clap sample", "Layering", "Backbeat", "Sample", "Reverb", "Transient"], "common_mistakes": ["Stacking claps that are not time-aligned, so the layers smear and the combined clap loses its sharp attack.", "Layering several full-range claps without EQ, causing a muddy buildup and phase cancellation between similar samples.", "Adding so much reverb to the layer that the clap loses punch and pushes the backbeat back in the mix."], "scenario_contexts": ["Building a pop or hip-hop backbeat by layering a clap on top of the snare on beats 2 and 4.", "Widening a thin single clap sample so it sits better in a dense electronic dance mix.", "Creating a custom clap by blending a dry sampled clap with a live recorded clap and a short room."]}, "fceaa069-f077-40a9-bdce-dad39b27f7fa": {"definition": "A short recorded or synthesized audio file of one or more hand claps, stored in a sampler or DAW library, that is triggered as a percussion sound within a beat or arrangement.", "plain_english": "A clap sample is a recording of a hand clap saved as a sound file. You trigger it in your music software to add a clap to the beat. That way you do not have to clap live every time.", "purpose_function": "It provides a ready-made clap sound a producer can drop onto the backbeat or accents, adding rhythmic emphasis and energy without recording live clapping.", "practical_application": "A beatmaker loads a clap sample onto a drum pad or sampler track and triggers it on beats 2 and 4, then tunes, trims, and EQs it to fit the groove.", "category": "Drum Programming", "related_terms": ["Clap layering", "Sample", "One-shot", "Sampler", "Backbeat", "Snare"], "common_mistakes": ["Using a clap sample tuned or recorded in a way that clashes with the track, making it sound out of place.", "Leaving a long clap sample's tail uncut, so it overlaps the next hit and muddies the groove.", "Relying on one stock clap sample everywhere, which makes different songs sound identical."], "scenario_contexts": ["Adding a clap on the backbeat of a pop or hip-hop beat.", "Reinforcing a snare with a clap sample for extra top-end snap.", "Building a handclap rhythm in an electronic track from a single one-shot sample."]}, "6945e685-18fc-451c-a7fa-f4793228a077": {"definition": "The workflow stage in which the client reviews a delivered mix or master against the agreed brief and either formally approves (accepts) it or returns specific revision notes before the project is considered complete.", "plain_english": "This is the step where the client listens to your finished mix and says yes or asks for changes. Nothing is final until they approve it. It is like a customer checking an order before they accept the delivery.", "purpose_function": "It exists to confirm the work meets the client's expectations and contract terms, protecting both sides by getting sign-off before final delivery and payment.", "practical_application": "The engineer sends a reference version of the final mix for review, logs the client's feedback, makes the agreed revisions, and secures written approval before releasing the final files.", "category": "Project Delivery", "related_terms": ["Client delivery package", "Revision", "Reference mix", "Recall", "Mastering", "Stems"], "common_mistakes": ["Treating a verbal 'sounds good' as final sign-off instead of getting written approval, leading to disputes later.", "Sending full-resolution masters before approval, so the client uses them without paying or finishing review.", "Not defining how many revision rounds are included, causing endless unpaid changes."], "scenario_contexts": ["A mix engineer sending a rough of the final mix for the artist and label to approve.", "A mastering engineer confirming loudness and track order with the client before cutting final files.", "A studio getting written sign-off before invoicing for a completed project."]}, "77cb8620-f1a0-417b-b0f8-5f8bd55da9e6": {"definition": "The complete set of finished files and documentation handed to a client at project completion, typically including the approved main mix and required alternate versions (such as instrumental, a cappella, and TV/PA mixes), any requested stems, and metadata or delivery notes.", "plain_english": "This is the bundle of final files you hand over when the job is done. It usually holds the main mix plus extra versions and notes. Think of it like a delivery box packed with everything the client ordered.", "purpose_function": "It exists to give the client every version and file they need for release, licensing, and future use in one organized handoff, reducing back-and-forth after the project ends.", "practical_application": "After approval, the engineer exports the main mix, instrumental, and stems at the agreed format and sample rate, labels them clearly, and delivers them with a track list and technical notes.", "category": "Project Delivery", "related_terms": ["Client acceptance review", "Stems", "Alternate mix", "Instrumental mix", "Bounce", "File naming"], "common_mistakes": ["Delivering files at the wrong sample rate or bit depth, forcing re-exports and delaying release.", "Forgetting required alternate versions like the instrumental or clean edit, so the client comes back for more.", "Using unclear file names, making it hard for the client to tell versions apart."], "scenario_contexts": ["Packaging final masters, instrumentals, and stems for a label after a song is approved.", "Preparing deliverables to a broadcaster's spec for a TV placement.", "Handing off stems so a remixer or sync team can rework the track later."]}, "3308f994-285a-45a4-aebc-95b3c7a97154": {"definition": "Audio effects (such as EQ, compression, or reverb) inserted directly on an individual clip or region rather than on the whole track, so the processing applies only to that clip and moves, copies, or splits along with it.", "plain_english": "Clip effects are effects placed on just one clip instead of the whole track. Only that piece of audio gets processed. It is like putting a filter on one photo in an album, not every photo.", "purpose_function": "They let a technician process a single section differently from the rest of the track, useful for fixing or shaping one part without adding track-wide automation or extra tracks.", "practical_application": "In a DAW that supports them, an editor drops an EQ or de-esser onto a single problem clip so the fix travels with that clip and does not affect the rest of the track.", "category": "DAW Editing", "related_terms": ["Clip Gain Line", "Clip lane", "Insert effect", "Track effects", "Region", "Automation"], "common_mistakes": ["Assuming a clip effect applies to the whole track, then wondering why the other clips are unprocessed.", "Forgetting that effect tails can be cut off when a clip ends, losing reverb or delay decay.", "Loading heavy clip effects on many clips, spiking CPU compared with one track-wide plugin."], "scenario_contexts": ["Adding a notch EQ to one clip that has a resonance the rest of the track does not.", "Putting a short reverb on a single vocal ad-lib clip for a one-off effect.", "Cleaning up one noisy region without touching the clean takes around it."]}, "3ec0867f-0f8a-4c4e-9cf2-fa865dd1d2a6": {"definition": "A horizontal gain control drawn across an audio clip's waveform that raises or lowers that clip's level non-destructively before it reaches the track inserts and fader; in Pro Tools it can be a single static value or a breakpoint line for gain changes within the clip.", "plain_english": "The clip gain line is a level line drawn right on the audio clip. Drag it up or down to make just that clip louder or quieter, before the mixer fader. It is a handy way to even out loud and soft parts early.", "purpose_function": "It exists to set and balance levels at the clip stage, taming loud words or hits before compression and fader moves, which keeps the signal clean and makes later mixing easier.", "practical_application": "An editor drags the clip gain line down on a loud vocal breath or up on a quiet phrase, or adds breakpoints to ride level inside a single clip, all before touching track automation.", "category": "DAW Editing", "related_terms": ["Clipping prevention", "Clip Effects", "Gain staging", "Volume automation", "Fader", "Waveform"], "common_mistakes": ["Confusing clip gain with track volume automation; clip gain sits before the inserts, automation after them.", "Boosting clip gain so high the clip overloads the plugins, instead of fixing the source level.", "Editing clip gain but forgetting it copies with the clip, so pasted copies carry unexpected levels."], "scenario_contexts": ["Evening out a vocal take's loud and soft phrases before compressing it.", "Pulling down a single loud drum hit that pokes out of the performance.", "Setting consistent clip levels across edited dialogue before the mix."]}, "56b11441-3d85-4899-ac32-d02b1fec6227": {"definition": "A horizontal sub-row within a track's timeline that holds audio or MIDI clips separately from the main track lane, used to stack alternate takes, overlapping material, or comping sources inside a single track.", "plain_english": "A clip lane is an extra row inside one track that holds clips. It lets you stack takes or spare parts on the same track without making new tracks. Think of it like extra shelves inside one drawer.", "purpose_function": "It exists to organize multiple takes or overlapping clips within one track, keeping related material together for comping and editing instead of spreading it across many tracks.", "practical_application": "A technician records several vocal passes into separate clip lanes on one track, then comps the best moments up to the main lane.", "category": "DAW Editing", "related_terms": ["Clip View", "Comping", "Take", "Clip Effects", "Playlist", "Crossfade"], "common_mistakes": ["Leaving clips in lower lanes and forgetting they can still play once promoted, causing doubled audio.", "Confusing clip lanes with separate tracks, so routing and effects get applied in the wrong place.", "Comping across lanes without crossfades, leaving clicks at the edit points."], "scenario_contexts": ["Recording multiple vocal takes into lanes on one track for later comping.", "Stacking alternate guitar passes to pick the best phrases.", "Keeping overlapping loop variations organized within a single track."]}, "1c9b243f-4b65-496b-ad6f-e8b2399510ae": {"definition": "In Ableton Live, the dedicated editing panel that opens when a clip is selected or double-clicked, showing and letting the user edit that clip's properties and content, including the audio waveform or MIDI notes, warp and loop settings, envelopes, and launch behavior.", "plain_english": "Clip View is the panel that shows the inside of one selected clip. There you can see its waveform or notes and change its settings, like looping and warping. It is like opening one item to edit its details.", "purpose_function": "It exists to give detailed, per-clip control in one place, so a user can shape a single clip's timing, pitch, loop, and automation without affecting the rest of the arrangement.", "practical_application": "A Live user double-clicks a clip to open Clip View, sets loop points and warp markers, edits MIDI notes, and draws clip envelopes for that clip.", "category": "DAW Editing", "related_terms": ["Clip lane", "Session View", "Warping", "Clip Effects", "MIDI editor", "Envelope"], "common_mistakes": ["Editing a clip in Clip View expecting it to change every copy, when unlinked copies stay unchanged.", "Confusing clip-level envelopes in Clip View with track automation, which behave differently.", "Changing warp settings without checking transient markers, causing timing artifacts."], "scenario_contexts": ["Setting loop points and warp markers on a sampled loop in Ableton Live.", "Editing MIDI notes for a single clip before duplicating it.", "Drawing a clip envelope to modulate a filter only within that clip."]}, "dda94bb1-26a8-4051-8a39-bc344d7e5529": {"definition": "The practice of keeping audio levels below the point where they exceed the maximum a converter, channel, or plugin can represent, so peaks are not flattened (clipped) into distortion; achieved through proper gain staging, headroom, and metering, sometimes with a limiter or clipper as a safeguard.", "plain_english": "Clipping prevention means keeping the sound from getting too loud for the gear to handle. If a peak goes over the limit, the top gets chopped off and it distorts. Leaving headroom and watching your meters stops that.", "purpose_function": "It exists to protect audio quality by avoiding harsh digital distortion and overdriven stages, keeping signals clean from input through to the final mix and master.", "practical_application": "A technician sets input gain so peaks stay below 0 dBFS with headroom, watches peak meters, and lowers clip gain or adds a limiter when levels approach the ceiling.", "category": "Gain Staging", "related_terms": ["Clip Gain Line", "Gain staging", "Headroom", "Limiter", "0 dBFS", "Peak meter"], "common_mistakes": ["UNSAFE: Driving a power amplifier into hard clipping for more level; clipped waveforms carry excess high-frequency energy that can overheat and destroy loudspeaker drivers, especially tweeters.", "Chasing loudness by pushing past 0 dBFS and relying on a limiter to hide clipping instead of fixing gain staging.", "Watching only average or RMS meters and missing short peaks that clip between readings.", "Assuming a little clipping is inaudible, when repeated inter-sample peaks can distort on playback converters."], "scenario_contexts": ["Setting mic preamp gain during tracking so the loudest hits stay below digital full scale.", "Gain staging a mix bus so the summed peaks leave headroom before the master.", "Checking a master's true-peak level before export to avoid clipping on streaming playback."]}, "f49b47df-31fc-4e29-a9fc-705d73039ae6": {"definition": "The quality-control step of checking a mix or master for clipping—confirming that no samples reach or exceed the digital ceiling (0 dBFS) and that inter-sample (true) peaks stay within the intended limit—typically using a peak or true-peak (dBTP) meter as defined by ITU-R BS.1770.", "plain_english": "It means checking that the loudest parts of a track do not go over the top and distort. Going past the ceiling is like pouring water past the rim of a full glass.", "purpose_function": "It ensures the delivered audio contains no hard digital distortion or inter-sample overs that can distort on playback devices and converters.", "practical_application": "Before delivery, an engineer runs a true-peak meter and keeps the master at or below the target ceiling (commonly -1 dBTP) to pass clipping checks for streaming and broadcast.", "category": "Quality Control", "related_terms": ["Clipping", "True peak", "Inter-sample peak", "Bus validation", "Broadcast compliance"], "common_mistakes": ["Trusting a sample-peak meter alone when inter-sample (true) peaks can still clip after digital-to-analog conversion", "Assuming a limiter set to 0 dBFS prevents clipping, ignoring true-peak overshoot on lossy codecs", "Confusing loudness (LUFS) with peak level and checking only one"], "scenario_contexts": ["Checking a master against a -1 dBTP ceiling before uploading to a streaming platform", "Verifying no clipping after loudness normalization for broadcast delivery", "Spotting inter-sample overs revealed by a true-peak meter that a standard peak meter missed"]}, "e44dec5d-4896-4327-aae0-f7c0c71bbe28": {"definition": "In MOTU Digital Performer, the Clippings window is a storage palette that holds reusable pieces of project data, called clippings, such as MIDI phrases, audio soundbites, track and channel settings, automation, whole sequences, or even external files. You drag material into the window to store it and drag it back out to reuse it in any project.", "plain_english": "It is a place in Digital Performer where you keep bits you want to reuse, like a favourite drum loop or a saved channel setup. You drag a piece in to store it, then drag it back out whenever you need it. Think of it as a scrapbook of parts.", "purpose_function": "It lets you save and instantly recall commonly used musical parts and settings, so you do not have to rebuild them from scratch in every session.", "practical_application": "A producer stores a go-to hi-hat pattern, a vocal effects chain, and a full mix channel setup as clippings, then drags them into new songs to start faster.", "category": "DAW feature", "related_terms": ["MIDI clip", "Soundbite", "Preset", "Session template", "Automation", "Drag and drop"], "common_mistakes": ["Confusing clippings with the system clipboard; clippings persist and can be reused across sessions, while the clipboard only holds the last copied item.", "Assuming a clipping stores the actual audio file inside the window, when the data really lives in a folder the clipping points to.", "Forgetting that project clippings stay with one project while global clippings are shared across all projects."], "scenario_contexts": ["Saving a favourite drum groove as a clipping to reuse in future beats.", "Storing a fully configured vocal channel with EQ, compression and sends for quick recall on new songs.", "Keeping lyric text files and reference audio in the Clippings window alongside musical parts."]}, "df8e7374-109c-4f44-a8c6-81cc3e7f6c3b": {"definition": "A closed-hi-hat sample is a recorded sound of a hi-hat cymbal struck while its two cymbals are pressed shut, giving a short, tight tick. In drum programming it is usually placed in the same mute (choke) group as the open-hi-hat sample, so a closed hit cuts off a ringing open hit, imitating a real hi-hat closed with the foot pedal.", "plain_english": "This is a recorded tick sound of a hi-hat with its cymbals clamped shut. Producers link it to the open hi-hat sound so that hitting the closed one stops the ringing open one. That copies what a real drummer does when they close the pedal.", "purpose_function": "It supplies the crisp, short hi-hat sound used to mark the small beats in a groove, and pairing it with the open sample in one choke group makes programmed hi-hats behave like a real player's.", "practical_application": "When building a beat, a producer loads open and closed hi-hat samples into one exclusive or mute group in a sampler or drum machine so the closed hit chokes the open hit for a natural feel.", "category": "Drum sampling", "related_terms": ["Open hi-hat sample", "Choke group", "Mute group", "Drum machine", "Sampler", "One-shot"], "common_mistakes": ["Not placing the open and closed hi-hats in the same choke or mute group, so open hi-hats ring through closed hits and sound unnatural.", "Layering many overlapping hi-hat hits without cutting the previous one, causing a cluttered, washy sound.", "Using one fixed velocity for every hit, which makes programmed hi-hats sound robotic instead of lively."], "scenario_contexts": ["Programming a trap or hip-hop hi-hat pattern from one-shot samples.", "Setting up a sampler kit so closed hats choke open hats like an acoustic kit.", "Replacing a weak recorded hi-hat with a sample during drum editing."]}, "a6b2a47a-6c26-4bb5-b20b-fa96bfc800dc": {"definition": "CloudBounce is a commercial online, automated (algorithmic/AI-driven) audio mastering service that analyzes an uploaded mix and returns a processed, mastered version; it is offered both as a web service and as a desktop application.", "plain_english": "It is a website and app that masters your song for you automatically. You upload a mix and it sends back a louder, polished version without a human engineer.", "purpose_function": "It gives musicians a fast, low-cost way to obtain a mastered-sounding track without booking a mastering engineer, by applying automated processing based on analysis of the audio.", "practical_application": "A producer uploads a stereo mix to CloudBounce, chooses a style or reference, and downloads the automatically mastered file for a demo or release.", "category": "Mastering", "related_terms": ["Assistive mastering", "Mastering", "Delivery master", "Loudness normalization"], "common_mistakes": ["Treating automated mastering as a full replacement for a skilled mastering engineer on critical releases", "Uploading an already-loud or clipped mix and expecting the service to fix underlying mix problems", "Assuming one automated result fits every playback target without checking loudness and true-peak levels"], "scenario_contexts": ["Mastering a demo quickly for a client to review before a full session", "Producing a streaming-ready master on a tight budget", "Comparing an automated master against a manual one to evaluate results"]}, "97a27e20-d75f-443a-bed6-e4e1a5158133": {"definition": "Club translation is how well a finished mix holds up when played on a large club or dance-venue sound system, which is typically loud with powerful subwoofers and strong low end, compared with how it sounded in the studio. A mix with good club translation keeps its intended balance, punch and clarity on that system instead of turning boomy, harsh or thin.", "plain_english": "This is how good your mix sounds when it is played loud on a club's big speakers, not just in the studio. Clubs have huge bass, so a mix that felt fine on small speakers can turn into a muddy mess. Checking club translation means making sure it still sounds right there.", "purpose_function": "It exists because playback systems differ hugely; mixing and checking for club translation makes sure a track keeps its impact and balance on the powerful, bass-heavy rigs it will be played on.", "practical_application": "A dance-music engineer checks a mix on large monitors or an actual club rig, taming excess sub-bass and harsh highs so the track stays clear and punchy when it is played out.", "category": "Mix translation", "related_terms": ["Mix translation", "Reference monitors", "Subwoofer", "Low-end management", "Reference track", "Loudness"], "common_mistakes": ["Mixing only on small speakers or headphones and assuming it will sound the same on a big club system.", "Adding too much sub-bass in the studio, which becomes overwhelming and muddy on a club rig.", "Judging club translation at low volume, since loud playback changes how bass and treble are heard."], "scenario_contexts": ["Preparing a house or techno track intended mainly for club and festival play.", "Test-playing a mix on a large PA before finalising the low end.", "Comparing a mix against a released club reference track to match its balance."]}, "1f62dd53-f7e4-4560-89f8-d096345ea07d": {"definition": "Collect All and Save is an Ableton Live command that copies all external media a Live Set depends on, such as audio samples, video files and Max for Live devices, into the project's own folder so the whole project is self-contained. It does not copy third-party plug-ins, which must still be installed on each computer.", "plain_english": "This is an Ableton command that gathers all the sounds and files your song uses and copies them into one project folder. That way, if you move the project or send it to someone, nothing goes missing. It cannot pack up plug-ins, though, so those must be installed separately.", "purpose_function": "It prevents missing-file problems by pulling every referenced sample and media file into the project folder, which makes the Set easy to back up, archive or move between machines.", "practical_application": "Before handing a project to a collaborator or copying it to an external drive, an engineer runs Collect All and Save so all samples travel with the Set instead of breaking their links.", "category": "Session management", "related_terms": ["Live Set", "Project folder", "Sample", "Missing files", "Max for Live", "Consolidate"], "common_mistakes": ["Assuming Collect All and Save also copies plug-ins; it does not, so missing plug-ins still break the project on another computer.", "Not collecting before moving a project, which leaves samples behind and causes media-files-missing warnings.", "Collecting huge sample libraries into every project, which can waste a lot of disk space."], "scenario_contexts": ["Sending a session to another producer for collaboration.", "Archiving a finished project so it still opens correctly years later.", "Moving work between a studio desktop and a laptop."]}, "f0741c05-2d6c-4d39-8ae0-efbe2c104a6d": {"definition": "In video game audio, the music that plays during combat or battle sequences—usually a more energetic, driving cue that contrasts with exploration or ambient music and is triggered when the player enters a fight.", "plain_english": "It is the fast, exciting music that plays while you are fighting enemies in a game. When the fight ends, the game usually switches back to calmer music.", "purpose_function": "It raises energy and tension during fights, cueing the player that they are in danger and reinforcing the pace of the action.", "practical_application": "An audio implementer sets combat music to trigger when enemies engage and to transition back to exploration music—often at a musical boundary—when the threat clears.", "category": "Game Audio", "related_terms": ["Boss music", "Defeat music", "Adaptive music", "Delayed transition"], "common_mistakes": ["Cutting abruptly between exploration and combat music instead of using a musical transition", "Assuming combat music must always be fast and loud rather than fitting the game's tone", "Looping a single combat cue with no variation, causing listener fatigue in long fights"], "scenario_contexts": ["Switching from ambient exploration music to combat music when a fight starts", "Layering additional instruments as more enemies appear", "Returning to background music at the next bar after combat ends"]}, "fc75b7c7-eab0-4f4b-af8c-5796d187225d": {"definition": "The Combinator is a device in Reason (Reason Studios) that holds any combination of instruments, effects and other devices, together with their internal connections, inside a single container called a Combi. The whole Combi can be saved and recalled as one patch, and it has a custom front panel whose controls map to parameters of the devices inside.", "plain_english": "The Combinator is like a box in Reason that holds several instruments and effects wired together as one unit. You can save the whole setup as a single sound and load it again instantly. It even has its own control panel, so a few knobs can steer everything inside.", "purpose_function": "It lets you build, save and reuse complex layered instruments and effect chains as one portable patch, and control many devices at once through a simplified custom panel.", "practical_application": "A producer stacks a piano and a pad into a Combinator to play them as one layered sound, then saves it as a Combi patch to reuse in other songs.", "category": "DAW device", "related_terms": ["Patch", "Layering", "Keyboard split", "Rack", "Effect chain", "Preset"], "common_mistakes": ["Thinking a Combinator makes its own sound; it only hosts other devices and their connections.", "Overloading a single Combi with many heavy devices, which can strain the computer's CPU.", "Forgetting to map the Combinator's front-panel controls, so its knobs and buttons do nothing."], "scenario_contexts": ["Building a layered synth-and-pad patch to play from one MIDI keyboard.", "Saving a favourite chain of effects as a reusable Combi.", "Creating a keyboard split with a bass on the low keys and a lead on the high keys."]}, "45febc3d-d3d7-4122-9657-f7ae33ac0239": {"definition": "In Pro Tools, Comments View is a display option that shows each track's editable Comments field, a small text area for notes about that track, in the Edit or Mix window. It is switched on from the View menu and lets engineers store per-track reminders directly in the session.", "plain_english": "This is a Pro Tools setting that shows a little notes box on each track. You can type reminders there, like which mic was used or that a vocal still needs tuning. It keeps your notes right next to the track instead of on paper.", "purpose_function": "It gives each track a place for written notes inside the session, helping engineers remember settings, mic choices or to-do items and pass them on to collaborators.", "practical_application": "During a session an engineer switches on Comments View and types the mic and preamp used on each track, so those details are saved with the project for later recall.", "category": "DAW feature", "related_terms": ["Track", "Markers", "Edit window", "Mix window", "Session", "Memory locations"], "common_mistakes": ["Confusing track comments with timeline markers; comments describe a track, while markers flag points in time.", "Leaving Comments View hidden and then forgetting the notes exist.", "Typing so much text that it is cut off, since the visible comment area is small."], "scenario_contexts": ["Noting the microphone and preamp used on each recorded track.", "Leaving instructions for another engineer taking over the mix.", "Tracking which takes still need editing or tuning."]}, "fc74f6e8-6f05-4172-8a80-321ef73c309d": {"definition": "A DAW operation that renders a track's real-time processing — virtual instruments, plug-in inserts, and clip gain — into a new plain audio track, so the processed sound is baked into audio and the original live processing can be disabled to free CPU.", "plain_english": "Commit turns a track that uses live effects or an instrument into a plain audio recording of its sound. It is like taking a photo of the finished sound so the computer no longer has to build it each time.", "purpose_function": "It frees up computer processing power and locks in a sound, and it lets you open or share a session on a system that lacks the original plug-ins.", "practical_application": "A technician commits heavy virtual-instrument or plug-in tracks when a session starts straining the CPU, or before sending tracks to another studio.", "category": "Track Commit", "related_terms": ["Freeze", "Bounce in Place", "Rendering", "Stem", "Virtual Instrument", "Insert"], "common_mistakes": ["Committing a track before the part is finished, then having to rebuild the processing from scratch", "Deleting the source track after committing instead of hiding it, losing the ability to tweak later", "Forgetting to copy sends, so the committed track loses its reverb or effect routing"], "scenario_contexts": ["A large orchestral template running out of CPU, so soft-synth tracks are committed to audio", "Sharing a session with a collaborator who does not own the same plug-ins", "Archiving a finished project as plain audio so it still opens years later"]}, "cdd14021-a52a-433b-a1d4-7da479fe03bc": {"definition": "A commit option that renders a track's signal chain only as far as a chosen insert slot, leaving the plug-ins after that point still active and editable on the resulting audio track.", "plain_english": "This bakes in only the first part of a track's effects and keeps the rest live to change later. It is like baking a cake but leaving the icing off so you can still decorate it.", "purpose_function": "It lets you lock in and offload the settled early part of a processing chain while keeping later effects flexible.", "practical_application": "A technician commits up to a CPU-heavy amp simulator or instrument insert but leaves the EQ and compression after it live for mix tweaks.", "category": "Track Commit", "related_terms": ["Commit Track", "Insert", "Signal Chain", "Freeze", "Plug-in", "Bounce in Place"], "common_mistakes": ["Choosing the wrong insert point and baking in an effect you still wanted to adjust", "Assuming the whole chain is rendered when only inserts up to the chosen slot are", "Not noting which insert was the commit point, causing confusion later"], "scenario_contexts": ["Committing a heavy amp simulator while keeping the post-EQ live", "Rendering a virtual instrument but leaving its channel effects editable", "Offloading a settled part of a long insert chain to save CPU"]}, "c817cc5a-6514-4553-ac86-c57fabd5a53d": {"definition": "A commit option that renders a track's full insert processing chain up to the point where its sends tap the signal, so the committed audio carries all insert processing and its send feeds to shared effects are preserved.", "plain_english": "This bakes in all of a track's effects up to the point where its extra outputs, called sends, branch off to things like reverb. So the copy still feeds the same reverb or delay the same way.", "purpose_function": "It captures the full processed sound while keeping the track's send routing to effects such as reverb and delay intact.", "practical_application": "A technician uses this when committing tracks that feed a shared reverb or parallel effect bus, so the rendered track still drives those effects correctly.", "category": "Track Commit", "related_terms": ["Commit Track", "Send", "Aux Bus", "Insert", "Signal Chain", "Return"], "common_mistakes": ["Forgetting that the send effects, such as reverb, live on other tracks and are not part of this render", "Confusing commit up to sends with a full bounce of the wet effect", "Not enabling copy sends, so the committed track loses its effect routing"], "scenario_contexts": ["Committing dry tracks that feed a shared reverb bus", "Offloading CPU while keeping parallel compression sends working", "Preparing tracks for a collaborator while preserving send routing"]}, "ae011b1f-9fbe-4996-b857-424f742d5b30": {"definition": "In take-based comping, the row or lane that holds the composite performance assembled by selecting the best sections from multiple recorded takes stored in the take lanes beneath it.", "plain_english": "When you record a part several times, the comp row is where you build one best version by picking the best bits of each take. It is like making one clean sentence from several rough drafts.", "purpose_function": "It gives a single, editable best-of performance without deleting any of the original takes.", "practical_application": "A technician swipes across the comp row to choose which take plays at each moment while comping a lead vocal.", "category": "Comping", "related_terms": ["Comping", "Take Lane", "Playlist", "Take Folder", "Crossfade", "Punch In"], "common_mistakes": ["Editing the original take lanes instead of the comp row and losing a good take", "Not crossfading the joins between takes, causing clicks or pops", "Flattening the comp too early, before checking every phrase"], "scenario_contexts": ["Building a lead vocal from ten recorded passes", "Comping a guitar solo from several takes", "Assembling a tight drum performance from multiple takes"]}, "af982305-22e2-433b-a45e-b86d372984b5": {"definition": "The quality-control step of measuring a finished mix or master against required technical delivery specifications — such as integrated loudness and true-peak limits (for example EBU R128, ITU-R BS.1770, ATSC A/85), file format, and channel layout — and confirming it meets them before delivery.", "plain_english": "This is the final check that a mix meets the loudness and format rules a broadcaster or platform demands. It is like checking a package fits the size and weight limits before you mail it.", "purpose_function": "It ensures a deliverable will be accepted and will play back at the correct, agreed loudness instead of being rejected or automatically adjusted.", "practical_application": "A technician runs a loudness meter over the final mix to confirm it hits the target LUFS and stays under the true-peak limit before exporting.", "category": "Delivery & QC", "related_terms": ["Loudness", "LUFS", "True Peak", "Metering", "Mastering", "Delivery Spec"], "common_mistakes": ["Checking only peak level and ignoring integrated loudness in LUFS", "Measuring loudness on a short section instead of the whole program", "Confusing sample peak with true peak and exceeding the limit after conversion"], "scenario_contexts": ["Verifying a TV mix meets EBU R128 before delivery", "Checking a podcast hits a streaming platform's LUFS target", "Confirming true-peak level before encoding to a lossy format"]}, "794bbe54-5edd-4a8a-9b1a-c2a38d4339e8": {"definition": "A sequencer trigger set to fire only when a defined condition is met — such as a probability percentage, a specific loop pass (first, last, or every Nth), or a fill state — rather than on every pass of the sequence.", "plain_english": "This is a note or hit in a pattern that only plays when a rule you set is true, such as one time in four. It is like a rule that says knock on the door only every third visit.", "purpose_function": "It adds variation and movement to a repeating pattern without you having to program every change by hand.", "practical_application": "A producer sets drum hits to conditional triggers so a looping beat evolves, with ghost notes or fills appearing only on certain passes.", "category": "Sequencing", "related_terms": ["Step Sequencer", "Probability", "Trig", "Pattern", "Fill", "Parameter Lock"], "common_mistakes": ["Expecting a conditional trigger to sound on every pass and thinking it is broken", "Stacking conditions so tightly that the trig almost never fires", "Confusing a probability condition with a fixed every-Nth condition"], "scenario_contexts": ["Adding occasional ghost notes to a looping drum pattern", "Triggering a fill only on the last bar of a loop", "Creating evolving sequences on a hardware groovebox"]}, "f5af3caf-6b3a-432e-a947-9cfd9b79d1e0": {"definition": "A DAW window that presents the project as a mixing console — vertical channel strips for tracks, buses or groups, and outputs, each with a fader, pan, sends, inserts, and metering — as an alternative to the timeline or arrange view.", "plain_english": "This is the view that makes your software look like a mixing desk, with a channel strip and fader for each track. It is like switching from a list of songs to a row of volume sliders.", "purpose_function": "It gives a familiar console-style layout for setting levels, panning, routing, and processing during mixdown.", "practical_application": "A technician switches to the console view to balance faders, set sends to effects, and watch meters while mixing.", "category": "Mixer Views", "related_terms": ["Channel Strip", "Fader", "Bus", "Send", "Insert", "Arrange View"], "common_mistakes": ["Thinking the console view is a separate mixer from the tracks, when it shows the same channels", "Overlooking hidden channel strips that are filtered out of the view", "Adjusting a group or bus fader thinking it is a single track"], "scenario_contexts": ["Setting a rough balance at the start of a mix", "Routing several tracks to a drum bus", "Watching input meters while setting gain staging"]}, "b041884e-cc1f-4684-93bb-7c5933a12e29": {"definition": "A single, unified DAW workspace window that combines multiple views — such as the tracks list, editing timeline, mixing board, and transport — into one set of panes, rather than spreading them across separate floating windows. It is most associated with MOTU Digital Performer.", "plain_english": "This is one big window that holds all your main tools together instead of lots of separate pop-up windows. It is like a dashboard where everything you need sits on one screen.", "purpose_function": "It keeps a session tidy and fast to navigate by putting editing, mixing, and transport controls in one place.", "practical_application": "A technician works from the consolidated window to move between arranging, editing, and mixing without hunting for floating windows.", "category": "DAW Interface", "related_terms": ["Arrange View", "Console view", "Mixing Board", "Transport", "Workspace", "Sequence Editor"], "common_mistakes": ["Accidentally closing panes and thinking features are gone", "Not resizing panes, so key views stay cramped", "Confusing it with opening a separate window for each editor"], "scenario_contexts": ["Editing and mixing on a single laptop screen", "Keeping a session organized during a long project", "Quickly switching views without managing floating windows"]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"687084d1-ade7-4492-9fb6-61a186844ad3": {"definition": "The practice of mixing and checking a track so it translates well on everyday consumer playback systems — phone speakers, earbuds, laptops, and car stereos — by managing low-end, midrange balance, mono compatibility, and overall loudness for those limited devices.", "plain_english": "This means making sure a song still sounds good on cheap earbuds, phones, and car speakers, not just on studio monitors. It is like testing a recipe in a normal home oven, not only a fancy restaurant one.", "purpose_function": "It ensures a mix holds up where most people actually listen — on small, limited devices — rather than only sounding good in the studio.", "practical_application": "A technician checks the mix on phone speakers, earbuds, and in mono, and controls sub-bass and harsh mids so it survives cheap playback.", "category": "Mix Translation", "related_terms": ["Mix Translation", "Reference Monitoring", "Mono Compatibility", "Low-End Management", "Loudness", "Frequency Balance"], "common_mistakes": ["Mixing loud on big monitors and adding bass the small speakers cannot reproduce", "Never checking the mix in mono, which hides phase problems", "Judging a mix only on expensive headphones or monitors"], "scenario_contexts": ["Checking a pop mix on phone speakers before release", "Testing a mix in a car to judge the low end", "Confirming a mix holds together in mono on a single speaker"]}, "3549d563-6dac-4473-bf64-dd44a523bce2": {"definition": "In Reason Studios' Reason software, control-voltage (CV) routing is the practice of connecting the CV and Gate mini-jacks on the back of virtual rack devices so one device can modulate or trigger a parameter on another. CV cables carry a changing control value rather than audio, Gate signals switch on and off to trigger notes and envelopes, and a trim knob at each CV input scales how strongly the incoming signal affects its target.", "plain_english": "In the music app Reason, you can flip the gear rack around and run thin cables between devices. These cables do not carry sound. Instead they send a control signal, so one device can move a knob or trigger a note on another. It works like the patch cables on an old modular synth.", "purpose_function": "It lets devices modulate and trigger each other, so a technician can build custom modulation and sequencing chains that go beyond fixed presets, much as hardware modular synths are patched.", "practical_application": "A producer patches an LFO or Matrix sequencer's CV output to a synth's filter cutoff or pitch input, then uses the trim knob to set how much modulation is applied.", "category": "Signal Routing", "related_terms": ["Gate signal", "Modulation", "LFO", "Envelope", "Step sequencer"], "common_mistakes": ["Confusing CV and Gate cables with audio cables and expecting to hear sound through them.", "Leaving the CV trim knob fully down, so the routed modulation has no audible effect.", "Forgetting that CV routing is separate from MIDI note data, so notes and modulation must be patched independently."], "scenario_contexts": ["Patching a Matrix pattern sequencer's Gate and Note CV to a synth to drive a melodic line.", "Routing an LFO's CV output to a filter cutoff for slow, evolving movement.", "Using an envelope follower's CV so one instrument's dynamics control a parameter on another device."]}, "76aff3e6-7b5b-4225-af18-d22783168198": {"definition": "A coverage shadow is an area within a listening space that receives little or no direct sound from a loudspeaker because it falls outside the loudspeaker's coverage pattern or is blocked by an obstruction, leaving that area dependent on lower-level, often lower-frequency, diffracted or reflected sound.", "plain_english": "A coverage shadow is a spot where a speaker's sound does not really reach. It happens when the spot sits outside the speaker's aiming pattern, or when something big blocks the path. It is like standing where a spotlight cannot land, so you only get weak, indirect sound.", "purpose_function": "Spotting coverage shadows matters because they mark seats or zones where the audience hears reduced level and clarity, so a designer can re-aim or add loudspeakers to fill them.", "practical_application": "During system design or tuning, a technician predicts and measures coverage shadows behind balconies, pillars, or under-balcony seating, then adds fill loudspeakers or re-aims boxes to cover them.", "category": "System Design", "related_terms": ["Coverage angle", "Dispersion pattern", "Fill loudspeaker", "Acoustic shadow", "SPL"], "common_mistakes": ["Assuming a single main loudspeaker covers the whole room and ignoring shadowed under-balcony seats.", "Confusing a coverage shadow with a dead spot caused only by comb filtering.", "Aiming the loudspeakers at the front rows and leaving the back or far sides in shadow."], "scenario_contexts": ["Under-balcony seats hearing muffled sound because the mains do not reach them.", "A structural pillar casting a shadow across a block of seats.", "Wide rooms where far-side seats fall outside the mains' horizontal coverage."]}, "d91ce5f4-8292-4fcd-b2a0-f06ff8b48bc4": {"definition": "A crash sample is a digital audio recording of a crash cymbal strike, stored as a one-shot sample for playback from a sampler, drum machine, or virtual instrument. It is triggered as a single hit and typically captures the full decay of the cymbal.", "plain_english": "A crash sample is a recorded hit of a crash cymbal saved as a sound file. You load it into a drum program and press a pad or key to play it back. It is like taking a photo of one cymbal crash so you can reuse that exact sound.", "purpose_function": "It gives a producer a consistent, ready-made cymbal sound to place in programmed drum parts without recording a live kit, so cymbal hits can be triggered on demand in electronic and hybrid productions.", "practical_application": "A producer drops a crash sample on a downbeat or section change, then tunes, trims, or fades its long decay to fit the arrangement.", "category": "Sampling", "related_terms": ["One-shot", "Sampler", "Drum machine", "Velocity layer", "Decay"], "common_mistakes": ["Letting the long crash decay clash with the next section instead of trimming or fading it.", "Layering many crash samples so their combined level overpowers the mix.", "Using a single fixed hit with no velocity variation, so repeated crashes sound machine-like."], "scenario_contexts": ["Adding a crash on the first beat of a new chorus in a programmed beat.", "Reinforcing a live-recorded cymbal with a crash sample for extra weight.", "Building an electronic drum kit in a sampler from individual cymbal samples."]}, "7bec3ce6-53e3-4b65-b5ec-f49e8c8f269f": {"definition": "A review step in which a deliverable is evaluated against the agreed creative brief or artistic intent—rather than only its technical specifications—to decide whether the client or creative lead accepts it as meeting the intended sound and feel.", "plain_english": "It is a check to see if a mix actually sounds the way the client asked for, not just whether it meets the tech rules. It is the 'does this feel right?' sign-off.", "purpose_function": "It confirms that subjective, artistic requirements are satisfied before final acceptance, catching mismatches between what was delivered and the creative vision.", "practical_application": "A mixer plays the near-final mix for the artist or director against the brief, and only moves to delivery once the creative stakeholders sign off.", "category": "Quality Control", "related_terms": ["Creative checklist", "Delivery certification", "Broadcast compliance verification", "Delivery master"], "common_mistakes": ["Confusing creative acceptance (artistic approval) with technical compliance checks like loudness or clipping", "Skipping written sign-off, so later disputes arise over whether the mix met the brief", "Judging against the engineer's taste instead of the client's stated creative goals"], "scenario_contexts": ["Playing a mix for a director to confirm it matches the emotional intent of a scene", "Getting artist approval on a mix's vibe before mastering", "Reviewing a jingle against the ad agency's creative brief before final delivery"]}, "fbf0dee9-1559-4fd2-aa70-2bbea73fb89b": {"definition": "A predefined list of creative or artistic tasks and decisions to review before a mix is considered complete—covering elements such as arrangement balance, effects, and automation, and adherence to the creative brief—used to ensure nothing is overlooked.", "plain_english": "It is a to-do list of artistic things to check before you call a mix finished, like 'are the vocals loud enough?' It helps make sure you did not forget anything.", "purpose_function": "It standardizes the final creative review so recurring artistic details are checked consistently, reducing missed elements from project to project.", "practical_application": "Before printing a mix, an engineer runs through a creative checklist confirming vocal level, effect returns, automation moves, and brief requirements are handled.", "category": "Quality Control", "related_terms": ["Creative acceptance test", "Delivery certification", "Bus validation", "Clipping validation"], "common_mistakes": ["Treating the checklist as a substitute for critical listening rather than a support for it", "Mixing technical delivery items (formats, loudness) with creative items and losing focus on either", "Reusing a generic checklist without adapting it to the project's specific brief"], "scenario_contexts": ["Running a final creative pass before bouncing a song", "Onboarding an assistant with the studio's standard creative checklist", "Ensuring each track on an album meets the same set of creative goals"]}, "f90739ad-ab09-440d-acc9-59afe78fe8f5": {"definition": "Crest-factor preservation is the practice of maintaining a signal's crest factor — the ratio between its peak level and its RMS (average) level, expressed in dB — while processing, so that transient peaks are not excessively flattened relative to the average level. It is a goal when applying compression, limiting, or loudness normalization to keep natural dynamics and transient impact intact.", "plain_english": "Crest factor is the gap between a sound's loudest peaks and its average level. Preserving it means you keep that gap instead of squashing the peaks flat. It is like keeping the tall spikes in a graph instead of flattening them, so drums still hit hard.", "purpose_function": "Preserving crest factor keeps transients punchy and the audio sounding dynamic and natural, so engineers weigh it against the loudness they gain when compressing or limiting.", "practical_application": "When mastering, an engineer watches a crest-factor or dynamics meter and eases off limiting when peaks are being crushed too far, trading a little loudness to protect transient impact.", "category": "Dynamics & Mastering", "related_terms": ["Crest factor", "RMS", "Peak level", "Limiting", "Dynamic range"], "common_mistakes": ["Pushing a limiter for maximum loudness until transients are flattened and the mix sounds lifeless.", "Reading only peak meters and ignoring how far the RMS level has been raised.", "Assuming louder always sounds better, when a healthy crest factor often sounds punchier."], "scenario_contexts": ["Mastering a drum-heavy track where keeping transient snap matters.", "Meeting a streaming loudness target without over-limiting the dynamics.", "Comparing two masters to hear how much punch was lost to heavy limiting."]}, "91609764-dd59-4b6a-b4c9-fcee6ca228a8": {"definition": "Crossfader assignment is the routing setting on a DJ mixer that selects which side of the crossfader — typically labeled A or B, or 'thru'/off — controls a given channel. Assigning a channel to a crossfader side lets that channel be faded in or out with the crossfader, while 'thru' removes the channel from crossfader control so its level follows only its own channel fader.", "plain_english": "On a DJ mixer, the crossfader is the slider that blends between two sides. Crossfader assignment picks which side each channel belongs to: A, B, or none. If you set a channel to none, the crossfader stops controlling it and only its own volume fader does.", "purpose_function": "It lets a DJ choose which decks the crossfader blends between and which channels stay independent, so scratching, cutting, and blending affect only the intended sources.", "practical_application": "A scratch DJ assigns one turntable to side A and the other deck to side B, and sets a microphone or effects channel to 'thru' so the crossfader cannot mute it.", "category": "DJ Mixing", "related_terms": ["Crossfader", "Crossfader curve", "Channel fader", "Cut-in point", "Deck"], "common_mistakes": ["Leaving a channel assigned to one crossfader side and wondering why it is silent when the fader sits on the opposite side.", "Assigning a microphone or effects return to the crossfader so it cuts out during blends.", "Forgetting to set a channel to 'thru' when it should always stay audible."], "scenario_contexts": ["Setting up a battle mixer so both turntables sit on opposite crossfader sides for scratching.", "Routing a microphone channel to 'thru' so announcements are not cut by the crossfader.", "Assigning decks so a smooth club blend happens across the crossfader."]}, "dcab0751-8e6e-4e38-82ee-0a570de998d2": {"definition": "The crossfader curve (also called the crossfader contour or taper) is the setting that defines how a DJ mixer's channel levels change across the travel of the crossfader. A gentle, constant-power curve fades sources gradually for smooth blends, while a sharp curve makes each side reach full level almost immediately near the edge of travel for fast cuts and scratching.", "plain_english": "The crossfader curve sets how quickly the sound comes in as you move the slider. A smooth curve fades slowly for gentle blends. A sharp curve turns the sound full-on almost as soon as you nudge the slider, which is what scratch DJs use to cut fast.", "purpose_function": "It lets a DJ match the crossfader's response to the task, giving slow, even fades for mixing and instant on/off action for cutting and scratching.", "practical_application": "A DJ sets a smooth curve to beatmatch and blend two tracks, then switches to a sharp curve to perform cuts and scratches where the sound must snap on at the edge of travel.", "category": "DJ Mixing", "related_terms": ["Crossfader", "Crossfader assignment", "Constant-power fade", "Scratching", "Fader curve"], "common_mistakes": ["Trying to scratch with a smooth curve, so cuts sound slow and mushy.", "Using a very sharp curve for blends, causing abrupt jumps in level.", "Confusing the crossfader curve with the separate channel fader curve."], "scenario_contexts": ["Setting a sharp curve for a scratch routine.", "Choosing a constant-power curve for long, smooth club blends.", "Adjusting the contour knob to fine-tune how quickly a track cuts in near the edge."]}, "b32b373e-124d-46db-b90d-e0d11116cd9d": {"definition": "The crowd noise floor is the background sound-pressure level produced by an audience — talking, movement, and applause between numbers — that sets the minimum ambient level a sound system must overcome for program material to be clearly heard. It effectively raises the room's noise floor during a show and rises with crowd size and energy.", "plain_english": "The crowd noise floor is the steady background noise a crowd makes: talking, clapping, and moving around. The music has to be louder than this for people to hear it clearly. It is like trying to talk to a friend in a busy cafe. The bigger and louder the crowd, the louder you must be.", "purpose_function": "Knowing the crowd noise floor helps an engineer set a level and headroom that keep vocals and detail intelligible above the audience instead of being masked by it.", "practical_application": "An engineer notices that a full, loud room raises the ambient level and nudges up overall level or vocal presence so lyrics stay intelligible above the crowd.", "category": "Live Sound", "related_terms": ["Noise floor", "Signal-to-noise ratio", "Headroom", "Intelligibility", "SPL"], "common_mistakes": ["Setting levels at soundcheck in an empty room and being caught out when the full crowd raises the ambient level.", "Confusing the crowd noise floor with the electronic noise floor of the system itself.", "UNSAFE: chasing intelligibility over a loud crowd by pushing SPL to hearing-damaging levels instead of improving mix clarity."], "scenario_contexts": ["A packed club where between-song chatter masks quiet intros.", "A sports venue where crowd roar sets how loud announcements must be.", "Nudging vocal level up once a venue fills and the ambient noise rises."]}, "79c8ba71-a97a-4bbb-8076-f318ede35504": {"definition": "The central document in Steinberg Cubase that holds all the settings and references for a piece of work, saved as a .cpr file. It stores the track arrangement, mixer and routing settings, edits, and automation, while pointing to the media files kept in the project folder.", "plain_english": "A Cubase project is the file that holds your whole song in Cubase. It remembers your tracks, edits, and mixer settings. It also links to the audio files saved in the project folder. Think of it as a map that keeps every part of your work together.", "purpose_function": "It ties every track, edit, mix setting, and media reference into one saved, reopenable state, so a whole production can be stored, recalled, and continued exactly where it was left off.", "practical_application": "A technician opens, saves, and backs up the .cpr file together with its Audio and other project subfolders, and uses Save As or Back up Project to move or archive a session without losing linked media.", "category": "Session Management", "related_terms": ["Project folder", "Track", "MixConsole", "Mixdown", "Audio Pool", "Autosave"], "common_mistakes": ["Moving or renaming the .cpr file but leaving its audio files behind, which breaks the links to the media.", "Assuming the project file contains the audio itself, when it mainly references external files in the project folder.", "Not saving incremental versions, so one corrupted project file loses all recent work."], "scenario_contexts": ["Starting a new song and choosing a project folder location before recording.", "Archiving a finished mix by using Back up Project to gather all referenced media.", "Reopening a client session weeks later and having every track, edit, and mix setting recalled."]}, "6ec18ae0-593e-490f-bc6a-42035d98c1c8": {"definition": "In REAPER, a user-created macro that combines two or more actions from the Action List so they run in sequence when triggered by a single command, shortcut, or menu item.", "plain_english": "A custom action in REAPER lets you bundle several commands into one. You pick the steps you want, put them in order, and give them a single shortcut. Pressing that shortcut then runs all the steps for you, like a one-tap recipe.", "purpose_function": "It speeds up repetitive work by letting one keystroke perform a whole chain of steps, cutting manual clicks and keeping multi-step tasks consistent every time.", "practical_application": "An engineer builds a custom action to, for example, select tracks, toggle their visibility, and zoom, then assigns it a keyboard shortcut or toolbar button for instant reuse.", "category": "Workflow Automation", "related_terms": ["Action List", "Key command", "Macro", "Cycle action", "Toolbar", "Script"], "common_mistakes": ["Ordering the steps wrong, so the actions run in a sequence that gives an unexpected result.", "Forgetting that some actions apply to whatever is focused or selected, so the macro behaves differently depending on context.", "Confusing a custom action, which is a fixed sequence, with a cycle action, which steps through actions on repeated presses."], "scenario_contexts": ["Automating a repetitive editing routine that normally takes several menu clicks.", "Creating a single shortcut that sets up a preferred track layout and zoom level.", "Sharing a reusable macro with collaborators to standardize a studio workflow."]}, "b0fb497a-1d60-45fb-9244-8ac9b79e8aa1": {"definition": "In REAPER (via the SWS/S&M extension), a user-programmable command that performs a different action or step each time its shortcut is triggered, cycling through a defined sequence of actions or states, so one key command can step through multiple behaviors in turn.", "plain_english": "It is a shortcut in Reaper that does a different thing each time you press it, moving through a list you set up. One button, several jobs in a set order.", "purpose_function": "It lets a user pack several related commands onto one shortcut and step through them, streamlining repetitive multi-step workflows and toggles.", "practical_application": "An editor builds a cycle action so one key repeatedly steps through a set of zoom levels or track views during editing.", "category": "Workflow", "related_terms": ["Custom action", "Macro", "Key command", "Action list"], "common_mistakes": ["Confusing a cycle action (steps through actions on repeated presses) with a custom action/macro (runs all its steps at once)", "Forgetting that cycle actions require the SWS/S&M extension to be installed in REAPER", "Losing track of the cycle's current state, so the shortcut appears to do the 'wrong' thing"], "scenario_contexts": ["Assigning one shortcut to step through several zoom presets in REAPER", "Toggling between mixer and arrange views with repeated presses", "Rotating through take lanes while comping"]}, "ff52ca10-c540-45f6-90a9-a3ad9733402d": {"definition": "In Logic Pro, the strip in the upper part of the ruler used to define a section of the project that plays back or records repeatedly. With Cycle mode on, playback loops between the left and right edges of this highlighted region.", "plain_english": "The cycle area in Logic Pro is a marked strip along the top ruler. It sets a part of your song to play over and over on a loop. You drag its edges to choose where the loop starts and stops, so you can practice or record a section again and again.", "purpose_function": "It lets you repeat a chosen section hands-free for focused practice, take recording, or fine-tuning edits and mix moves without constantly restarting playback.", "practical_application": "A technician drags across the ruler to set the cycle area over a chorus, enables Cycle mode, and loops that part to record several takes or audition edits.", "category": "Playback & Transport", "related_terms": ["Cycle mode", "Locators", "Loop", "Ruler", "Playhead", "Comping"], "common_mistakes": ["Leaving Cycle mode on by accident, so playback keeps looping when you expect it to continue past the section.", "Setting the cycle edges slightly off the bar lines, causing loops that feel out of time.", "Confusing the cycle area, a playback loop range, with looping an individual region."], "scenario_contexts": ["Looping a verse to record several vocal takes for comping.", "Repeating a short section to dial in an EQ or effect setting.", "Practicing a difficult passage by playing it back on a continuous loop."]}, "e1a64248-9646-4ff2-aeaf-18ff4a394388": {"definition": "A consolidated screen or window that presents key status information and controls at a glance; in Pro Tools specifically, the Dashboard is the window shown when creating or opening a session, where the user sets sample rate, bit depth, file type, and I/O settings and locates recent or existing sessions.", "plain_english": "It is a single screen that shows the important info and controls in one place. In Pro Tools, it is the window that pops up to set up or open a session.", "purpose_function": "It centralizes the settings and choices needed to start work, so the user configures a session or reviews status from one place instead of hunting through menus.", "practical_application": "When launching Pro Tools, an engineer uses the Dashboard to create a new session at 48 kHz / 24-bit or to reopen a recent project.", "category": "Interface", "related_terms": ["Session", "Sample rate", "Bit depth", "Audio Connections window"], "common_mistakes": ["Rushing past the Dashboard and creating a session at the wrong sample rate or bit depth", "Assuming the Dashboard is only for new sessions when it also opens recent and existing ones", "Confusing a software 'dashboard' overview with a hardware metering panel"], "scenario_contexts": ["Setting sample rate and bit depth when starting a new Pro Tools session", "Reopening a recent project from the Dashboard at launch", "Choosing file type and I/O settings before recording begins"]}, "8def116f-2cbd-467c-b584-6cd98cd3459a": {"definition": "In video game audio, a musical cue that plays when the player loses—such as a game-over, death, or failure state—typically a short, downbeat or resolving piece that signals the negative outcome.", "plain_english": "It is the sad or 'you lost' music that plays when you fail or die in a game. It tells you the round is over and you did not win.", "purpose_function": "It gives clear emotional feedback that the player has failed, marking the end of an attempt and setting the tone before a retry.", "practical_application": "A composer writes a brief defeat cue, and an implementer triggers it on the game-over or death event, usually stopping the gameplay music first.", "category": "Game Audio", "related_terms": ["Boss music", "Combat music", "Adaptive music", "Delayed transition"], "common_mistakes": ["Confusing defeat music (a loss cue) with victory or level-complete music", "Letting gameplay music keep playing under the defeat cue instead of stopping or ducking it", "Making the defeat cue so long it delays the player's retry"], "scenario_contexts": ["Playing a game-over theme when the player's health reaches zero", "Triggering a short failure sting when a timed mission is lost", "Transitioning from combat music to a defeat cue on player death"]}, "a7cfdb4b-261f-4230-b160-ef6729a17031": {"definition": "A change from one section, cue, or mix state to another that is intentionally deferred—executing only after a set time delay or at the next musical boundary (such as the next bar or an exit marker)—rather than taking effect the instant it is triggered.", "plain_english": "It is a switch between two parts that waits for the right moment instead of happening right away. Like waiting for the end of a musical phrase before changing the song.", "purpose_function": "It keeps changes musical and smooth by aligning them to a natural point, avoiding abrupt jumps when a cue or state change is triggered off-beat.", "practical_application": "In interactive game music, an implementer sets a combat-to-explore transition to wait until the next bar, so the music switches cleanly after the trigger.", "category": "Transitions", "related_terms": ["Bar-aligned transition", "Beat-aligned transition", "Combat music", "Adaptive music"], "common_mistakes": ["Confusing a delayed transition (deferred to a sync point) with a slow crossfade, which is about fade length, not timing", "Setting the delay so long the change feels disconnected from its trigger", "Forgetting to define an exit point, so the transition waits far longer than intended"], "scenario_contexts": ["Waiting for the next bar before switching from exploration to combat music", "Delaying a mix scene change until a song section ends", "Scheduling a stinger to land on the next downbeat"]}, "62095a0b-5c06-4513-81d4-bf7b1e8de528": {"definition": "A formal confirmation that a finished deliverable has passed quality control and conforms to the recipient's technical delivery specification, covering items such as file format, channel layout, and loudness. It is the sign-off, often documented as a QC report, that clears content for acceptance and distribution.", "plain_english": "Delivery certification is a formal check that says a finished file meets all the rules the client set. It confirms the format, channels, and loudness are right and that quality control found no faults. Think of it like a pass stamp that lets the file be accepted and released.", "purpose_function": "It protects both sides by proving, before acceptance, that the master meets the agreed spec, so faulty or non-compliant files are caught before they reach air or release.", "practical_application": "Before hand-off, an engineer or QC operator checks the deliverable against the spec sheet and provides certification or a QC report confirming it passes.", "category": "Delivery & QC", "related_terms": ["Deliverables", "Quality control", "Delivery master", "Loudness normalization", "Spec sheet", "LUFS"], "common_mistakes": ["Treating certification as a formality and skipping an actual check against the spec sheet.", "Judging loudness by ear instead of measuring it to the required target.", "Missing required elements, such as channel layout or metadata, that the specification demands."], "scenario_contexts": ["Confirming a broadcast master meets the network's loudness and format spec before hand-off.", "Providing a QC pass report with files delivered to a streaming platform.", "Rejecting and returning a deliverable that fails the technical specification."]}, "70b98a9f-8992-493c-ab63-96c8fc304c4c": {"definition": "The final approved version of a mix or master prepared to meet the exact technical specifications of its destination, such as a streaming service, broadcaster, or replication plant. It is the file or file set formally handed over for distribution, made to the required format, sample rate, bit depth, and loudness targets.", "plain_english": "A delivery master is the final, approved version of a track made to fit exactly what the client or platform asks for. It uses the right file type, quality, and loudness for that destination. Think of it as the finished copy you hand over for release, cut to spec.", "purpose_function": "It exists to give each destination a correctly formatted, compliant file so the release plays back and measures as intended without any further changes.", "practical_application": "A mastering engineer renders separate delivery masters for streaming, CD, and video, each matching that platform's format and loudness requirements before sending them off.", "category": "Mastering & Delivery", "related_terms": ["Master", "Mixdown", "Loudness normalization", "LUFS", "Deliverables", "DDP"], "common_mistakes": ["Sending one generic file to every platform instead of meeting each one's format and loudness spec.", "Over-limiting to a very loud level that gets turned down and can distort under loudness normalization.", "Mislabeling sample rate, bit depth, or channel layout so the file is rejected in QC."], "scenario_contexts": ["Preparing separate masters for a streaming service, an online store, and a CD run.", "Delivering a broadcast mix that must meet a specified loudness target.", "Sending an approved final file set to a distributor or replication plant."]}, "66964129-22d9-41a8-b624-7e4eb3aa9e1a": {"definition": "In Ableton Live, the Device Activator is the toggle switch in a device's title bar that turns that instrument or effect on or off within the track. When a device is switched off, its signal passes through unprocessed and it stops consuming CPU, without being removed from the set.", "plain_english": "It is the on/off switch at the top of each effect in Ableton Live. Turn it off and that effect stops working. It is like clicking off one pedal in a guitar chain while the others stay on.", "purpose_function": "It lets you bypass a device to compare processed and unprocessed sound and to free up CPU, all without losing the device's settings or its place in the chain.", "practical_application": "A technician clicks the activator to A/B a compressor or EQ against the raw signal, or to switch off a heavy device that is straining the computer during playback.", "category": "DAW Interface", "related_terms": ["Device chain", "Device View", "Device preset", "Device hot-swap"], "common_mistakes": ["Confusing the Device Activator, which affects one device, with the Track Activator, which mutes the whole track", "Thinking a switched-off device still colors the sound, when its processing is fully bypassed", "Deleting a device instead of just deactivating it, and losing its dialed-in settings"], "scenario_contexts": ["A/B-ing an EQ against the raw track to judge whether the boost helps", "Disabling a CPU-heavy reverb during tracking to keep latency low", "Bypassing a saturation device to check how much color it is adding"]}, "8c23b53a-2c18-45e8-8aa3-9ba6b0a5bd77": {"definition": "In Ableton Live, a device chain is the left-to-right series of instruments and effects on a single track, through which the signal always travels in order. On MIDI tracks, devices placed before the instrument process MIDI, while devices after it process the resulting audio.", "plain_english": "It is the row of effects and instruments on one track, lined up in the order the sound flows through them. Think of guitar pedals in a row: the signal hits the first, then the next, then the next.", "purpose_function": "It sets the processing order, which matters because each device shapes the signal in sequence and changing the order changes the final sound.", "practical_application": "A technician arranges devices along the chain, for example placing EQ before or after compression, and drags device title bars to reorder them for the sound they want.", "category": "Signal Flow", "related_terms": ["Device activator", "Device View", "Device preset", "Device hot-swap"], "common_mistakes": ["Ignoring device order, not realizing EQ-then-compressor sounds different from compressor-then-EQ", "On a MIDI track, placing an audio effect before the instrument, where it has no audio to process", "Confusing a track's device chain with the internal chains inside a Rack"], "scenario_contexts": ["Deciding whether to place a de-esser before or after the vocal compressor", "Reordering EQ and reverb to change how a track sits in the mix", "Building a MIDI effect, instrument, and audio effect together on one track"]}, "9f1b6dd2-cf2c-4e05-90e5-c71955a04891": {"definition": "In Ableton Live, Hot-Swap Mode temporarily links a selected device to the browser so presets, samples, or other content can be auditioned and exchanged in place, without adding a new device. It is entered with the Q key or the Hot-Swap button and exited with Q, Esc, or the close button.", "plain_english": "It is a quick way to try different presets or samples on an effect without removing it. You browse options and each one loads into the device. You hear it right away, like flipping through TV channels to find one you like.", "purpose_function": "It speeds up sound selection by letting you compare many presets or samples in the same slot, keeping the workflow fast during sound design.", "practical_application": "A technician hot-swaps through drum samples in a Simpler or presets in an effect, arrow-keying down the list until the right sound is found, then exits to keep it.", "category": "DAW Workflow", "related_terms": ["Device preset", "Device chain", "Device activator", "Device View"], "common_mistakes": ["Forgetting to exit Hot-Swap Mode, so later browser clicks keep replacing content", "Expecting hot-swap to add a device, when it replaces content in the existing one", "Losing custom tweaks by swapping in a preset that overwrites the current settings"], "scenario_contexts": ["Auditioning kick samples to find one that fits the track", "Cycling through reverb presets to pick a room sound quickly", "Swapping a synth preset during sound design without breaking the chain"]}, "5ac84a2b-4243-4675-9cab-def4d8e994b9": {"definition": "A device preset is a saved set of parameter values for an instrument or effect that can be recalled to instantly restore that configuration. In Ableton Live, presets are stored in and loaded from the browser, and users can save their own to the User Library.", "plain_english": "It is a saved snapshot of all the knob and slider settings on an effect or instrument. Load it and every control jumps back to those saved spots, like a recipe that makes the same dish every time.", "purpose_function": "It saves time and keeps results consistent by letting you recall a known-good sound instead of dialing every parameter from scratch.", "practical_application": "A technician loads a factory preset as a starting point, tweaks it for the track, and saves the result to the User Library to reuse in future sessions.", "category": "DAW Workflow", "related_terms": ["Device hot-swap", "Device chain", "Device activator", "Device View"], "common_mistakes": ["Treating a preset as a finished sound rather than a starting point to adjust for the track", "Saving over a factory preset instead of saving a new user copy", "Assuming a preset sounds the same on every source, ignoring level and context"], "scenario_contexts": ["Recalling a vocal chain preset at the start of a session", "Saving a custom synth patch to reuse across projects", "Loading a factory EQ preset as a starting point before fine-tuning"]}, "7d356379-cad5-4adf-8015-d823a117ab0f": {"definition": "Device translation is how consistently a finished mix holds up when played back on different devices — studio monitors, headphones, phone speakers, car systems, and earbuds — each with its own frequency response and limitations. A mix with good device translation keeps its balance and clarity across all of them.", "plain_english": "It is how well a mix still sounds right when you play it on different gear, from big speakers to phone speakers to earbuds. A mix that translates well sounds balanced everywhere, not just on the system you mixed it on.", "purpose_function": "It matters because listeners use many different playback devices, so a mix must survive small speakers and cheap earbuds, not only sound great in the studio.", "practical_application": "A technician checks a mix on monitors, headphones, a phone, and a car to catch problems like weak bass or harsh highs before finalizing.", "category": "Mix Translation", "related_terms": ["Reference track", "Monitoring", "Frequency balance", "Dial in the mix"], "common_mistakes": ["Mixing only on one flattering system and being surprised when the mix falls apart elsewhere", "Judging bass on speakers that cannot reproduce it, so the low end is wrong on other devices", "Mixing too loud, which hides balance problems that appear on quiet playback"], "scenario_contexts": ["Bouncing a mix to a phone to check it on a small speaker", "Comparing the mix to a reference track on the same devices", "Auditioning a master in a car to test real-world playback"]}, "bc0788a1-50f7-4202-bc7d-06224afba0bb": {"definition": "In Ableton Live, the Device View is the panel at the bottom of the window that displays and lets you edit the devices on the selected track. It is opened by double-clicking a track's title bar and can share the lower area with the Clip View.", "plain_english": "It is the strip at the bottom of Ableton Live. It shows all the effects and instruments on the track you picked. It is where you turn the knobs and change their settings.", "purpose_function": "It gives one place to insert, view, and adjust a track's devices, keeping instrument and effect controls together for editing.", "practical_application": "A technician opens the Device View to tweak an EQ curve or compressor on the selected track, and switches tracks to see each one's devices.", "category": "DAW Interface", "related_terms": ["Device chain", "Device activator", "Device preset", "Device hot-swap"], "common_mistakes": ["Not realizing the Device View follows track selection, so it shows a different track's devices than expected", "Confusing the Device View with the Clip View, which edits clip content, not devices", "Looking for devices in the Device View when they are nested inside a Rack"], "scenario_contexts": ["Adjusting a compressor's threshold while watching its display", "Inserting and ordering effects on a vocal track", "Opening a synth's controls to edit a patch"]}, "b9ba74f9-4ee7-4829-a27a-9da94b16857c": {"definition": "\"Dial in the mix\" is studio shorthand for the process of carefully adjusting levels, panning, EQ, dynamics, and effects until the balance of all elements sounds right. It describes fine-tuning many small settings by ear to reach a polished, intentional result.", "plain_english": "It means to carefully tweak all the settings until the mix sounds just right. It is like slowly adjusting the taps on a shower until the water is the perfect temperature.", "purpose_function": "The phrase names the hands-on tuning stage of mixing, where small repeated adjustments turn a rough balance into a finished sound.", "practical_application": "A technician dials in the mix by nudging fader levels, tweaking EQ, and setting reverb amounts, checking each change against the whole balance.", "category": "Mixing Workflow", "related_terms": ["Balance", "Panning", "Reference track", "Device translation"], "common_mistakes": ["Endlessly tweaking without a reference, chasing a target that keeps moving", "Making big moves when small ones are needed, and undoing a good balance", "Dialing in at very high volume, which tires the ears and skews decisions"], "scenario_contexts": ["Fine-tuning vocal level against the instrumental until it sits right", "Adjusting drum and bass balance to lock in the low end", "Tweaking reverb and delay amounts to set the sense of space"]}, "398abddd-eb60-4c00-9d71-471bf78b7dcd": {"definition": "A dialogue mixer is the audio engineer in film or television post-production responsible for balancing, cleaning, and blending the spoken-word elements — production dialogue, ADR, and voice-over — into the final mix. On larger mixes this person handles the dialogue stem while other re-recording mixers cover music and effects.", "plain_english": "It is the sound engineer in film and TV who makes sure all the talking is clear, even, and easy to follow. They balance the voices and smooth them out so lines recorded at different times fit together.", "purpose_function": "The role exists because clear, intelligible dialogue is the most important part of most film and TV soundtracks, and it needs focused, expert handling.", "practical_application": "A dialogue mixer evens out level differences between lines, removes noise, and blends ADR with production sound so the audience never notices the joins.", "category": "Post Production", "related_terms": ["Dialogue-only stem", "Re-recording mixer", "ADR", "Production sound"], "common_mistakes": ["Confusing the dialogue mixer, who works in post, with the production sound mixer, who records on set", "Prioritizing effects and music loudness over dialogue clarity", "Assuming one mixer handles everything, when large films split dialogue, music, and effects across mixers"], "scenario_contexts": ["Smoothing level jumps between two actors in a scene", "Blending ADR lines with the original production dialogue", "Balancing dialogue against music and effects on the dub stage"]}, "d3ffcdfe-d4de-4736-9481-47eed9d5680e": {"definition": "A dialogue-only stem is a submix containing just the dialogue elements of a program — production dialogue, ADR, and voice-over — with music and effects removed. It is delivered alongside the music and effects stems so the mix can be re-balanced, and it supports foreign-language versions when paired with an M&E stem.", "plain_english": "It is a version of the soundtrack that has only the talking in it, with the music and sound effects taken out. Keeping the voices on their own track makes it easy to fix them later or swap in a different language.", "purpose_function": "It exists so the dialogue can be adjusted, replaced, or removed on its own without touching music and effects, which is essential for edits, dubbing, and delivery specs.", "practical_application": "A technician delivers the dialogue stem with the music and effects stems so a broadcaster can re-balance dialogue level or drop it for a foreign-language dub.", "category": "Post Production", "related_terms": ["Dialogue mixer", "Stem", "Re-recording mixer", "ADR"], "common_mistakes": ["Confusing the dialogue-only stem with the full mix, when it has no music or effects", "Leaving music or effects bleed in the dialogue stem, which breaks foreign-language dubbing", "Forgetting to deliver matching stems, so the mix cannot be re-balanced later"], "scenario_contexts": ["Delivering separated stems to a streaming platform per spec", "Re-balancing dialogue level for a TV broadcast without a full remix", "Replacing dialogue with a dubbed language while keeping music and effects"]}, "5ec7c16b-716e-4e74-948a-928bce7470d3": {"definition": "The saved document used by MOTU Digital Performer, a digital audio workstation. A project stores the session's audio and MIDI tracks, edits, mixer settings, automation, and the links to its recorded audio files.", "plain_english": "It is the file that holds all your work in the Digital Performer recording program. Think of it like a folder that keeps your tracks, edits, and settings together, so you can open the song again later.", "purpose_function": "It keeps every part of a recording session in one organized document, so the whole mix can be reopened and edited exactly as it was left.", "practical_application": "A technician opens, saves, and backs up the project file to continue a mix across sessions or to move it to another Digital Performer rig.", "category": "Project Files", "related_terms": ["Digital audio workstation", "Session file", "MIDI track", "Automation", "Bounce"], "common_mistakes": ["Confusing the project file with the audio files it links to, then moving or deleting the audio so the project opens with missing media.", "Assuming the project opens in other DAWs; Digital Performer projects are not natively compatible with other programs.", "Never saving incremental versions, so one corrupted file loses the whole session."], "scenario_contexts": ["Reopening a multitrack recording to keep mixing the next day.", "Transferring a session between two studios that both run Digital Performer.", "Backing up a finished project before archiving a client's album."]}, "530465c7-32be-4836-87d0-4a93a6287d39": {"definition": "In Avid Pro Tools, Disk Allocation is the setting that assigns which storage drive each track records its audio to. It lets an engineer spread recording across several drives to balance the data load during large sessions.", "plain_english": "It is a Pro Tools setting that picks which hard drive saves the sound from each track. Spreading recordings across drives keeps any one disk from getting overloaded during big sessions.", "purpose_function": "It exists to direct each track's recording to a chosen drive, so a system can handle high track counts without one disk becoming a bottleneck.", "practical_application": "Before a large tracking session, an engineer opens the Disk Allocation window and points groups of tracks at different fast drives to keep recording stable.", "category": "Session Management", "related_terms": ["Digital audio workstation", "Session file", "Buffer size", "Track", "Hard disk recording"], "common_mistakes": ["Recording all tracks to the system drive, which can cause dropouts on large sessions.", "Allocating tracks to a slow or nearly full drive and then getting disk-performance errors.", "Forgetting that moving a session to a new machine can break the drive assignments."], "scenario_contexts": ["Setting up a 48-track live album recording spread across several drives.", "Troubleshooting record errors caused by a full or slow disk.", "Preparing a session so overflow audio lands on a second drive."]}, "6958ea30-5f4f-4328-a401-b91469711f29": {"definition": "The practice of keeping every stage of a signal path below its clipping point so no unwanted, non-linear distortion is added to the audio. It relies on proper gain staging and adequate headroom from input to output.", "plain_english": "It means setting levels so the sound never gets pushed too loud and starts to crackle or break up. Like not overfilling a glass, you leave room so the signal stays clean.", "purpose_function": "It protects audio quality and equipment by making sure signals stay within the clean operating range of each device in the chain.", "practical_application": "A technician sets gain at the source, checks meters at each stage, and leaves headroom so peaks do not clip the preamp, converter, or mix bus.", "category": "Gain Staging", "related_terms": ["Gain staging", "Headroom", "Clipping", "Signal-to-noise ratio", "Metering"], "common_mistakes": ["Confusing digital clipping with analog warmth; digital clipping is always harsh and should be avoided.", "Turning down the final fader to hide distortion that was already recorded into the track.", "Watching only the master meter and missing an earlier stage that is already clipping."], "scenario_contexts": ["Setting preamp gain during tracking to avoid recording a clipped take.", "Gain staging a mix so plugins receive signals at their intended level.", "Checking a live console's channel and bus meters to keep the PA clean."]}, "cbcaa623-3aa8-4e25-98b0-fcac50facade": {"definition": "The quality-control step of confirming that a finished mix or master contains no unwanted distortion, checking for digital clipping, inter-sample (true-peak) overs, and excess total harmonic distortion against accepted limits before the audio is delivered.", "plain_english": "It means checking the final track to make sure the sound is clean and not crackling or breaking up. You look at the meters and listen closely to catch any harsh, clipped spots before you send it out.", "purpose_function": "It exists to catch level and processing errors that add harshness or crackle, ensuring the delivered audio plays back cleanly and meets accepted peak and distortion limits on every system.", "practical_application": "An engineer runs a true-peak meter and does a focused listen on headphones and monitors at the end of a session, flagging any clip indicators or audible breakup before bouncing the final file.", "category": "Metering & QC", "related_terms": ["Distortion prevention", "Dynamic-range validation", "Noise-floor validation", "Headroom preservation", "True-peak metering"], "common_mistakes": ["Assuming a mix is clean because it sounds fine on one system, without checking meters or a second set of monitors", "Confusing intentional, musical distortion such as a driven guitar with unwanted digital clipping", "UNSAFE: Cranking monitor level to hunt for faint distortion, risking hearing damage from prolonged loud exposure"], "scenario_contexts": ["Final QC pass on a master before uploading to a streaming distributor", "Checking a location dialogue recording for mic-preamp overload before the mix", "Verifying a bounced stem has no inter-sample peaks after limiting"]}, "e3dc969a-fe19-455d-b24d-56d81fd1f727": {"definition": "In Apple Logic Pro, a downbeat marker indicates where the first beat of a bar falls on the timeline. It is used when aligning recorded audio or MIDI to the project's bar-and-beat grid, such as during beat mapping or Smart Tempo editing.", "plain_english": "It is a mark in Logic that shows where beat one of a measure starts. It helps the program line up your recording with the right bars, so the grid matches the music.", "purpose_function": "It tells Logic where each measure begins, so tempo, quantizing, and looping stay in step with the actual performance.", "practical_application": "When importing a freely played recording, an engineer sets the downbeat so Logic's bars line up with the music before quantizing or adding loops.", "category": "Tempo & Timing", "related_terms": ["Beat mapping", "Smart Tempo", "Quantization", "Grid", "Tempo map"], "common_mistakes": ["Placing the downbeat on the wrong transient, which shifts the whole bar grid out of alignment.", "Confusing the downbeat (beat one) with any other strong beat in the bar.", "Not setting the downbeat before beat mapping, so quantizing pulls notes to the wrong positions."], "scenario_contexts": ["Beat mapping a rubato piano take so the click follows the performance.", "Aligning an imported drum loop to bar one before building a session.", "Fixing a project where the bar lines drifted off the recorded groove."]}, "a47dd78e-b268-4799-9e26-5ee977fa5bed": {"definition": "In live sound, to drive the system means to feed the sound reinforcement system enough signal level to produce the required output from its amplifiers and loudspeakers. It describes how hard the signal is pushed through the chain toward the speakers.", "plain_english": "It means pushing enough signal into the PA to make it loud enough for the room. Like pressing a gas pedal, more drive gives more output, but too much causes strain and distortion.", "purpose_function": "The idea helps an engineer reach the loudness a room needs while staying within the safe, clean limits of the amplifiers and speakers.", "practical_application": "An engineer sets console and processor levels to drive the system to concert level while watching amp limiters so nothing clips or overheats.", "category": "Signal Level", "related_terms": ["Gain staging", "Headroom", "Amplifier", "Limiter", "Clipping"], "common_mistakes": ["UNSAFE: Driving amplifiers into hard clipping, which sends distorted signal that can overheat and destroy high-frequency drivers.", "Assuming louder input always means cleaner output, when overdriving simply adds distortion.", "UNSAFE: Driving the system hard without hearing protection or without watching safe sound-exposure limits."], "scenario_contexts": ["Bringing a festival PA up to full level during a line check.", "Setting drive levels so a small system fills a room without straining.", "Managing input level to a powered speaker to avoid triggering its protection limiter."]}, "c395b107-1223-4101-b9c1-ef056490d694": {"definition": "The amplitude envelope of a drum sound is the curve describing how its loudness changes over time, from the initial attack transient through its decay to silence. In synthesis and sampling it is often shaped with an ADSR (attack, decay, sustain, release) envelope generator.", "plain_english": "It is the shape of how a drum hit gets loud and then fades away. A drum usually starts with a sharp punch and dies down quickly, and this curve describes that rise and fall.", "purpose_function": "It defines the punch and length of a drum sound, letting a producer control how sharp the hit is and how fast it fades.", "practical_application": "When programming drums, a technician shortens the decay to tighten a snare or lengthens it to let a cymbal ring out.", "category": "Sound Design", "related_terms": ["ADSR envelope", "Transient", "Attack", "Decay", "Amplitude"], "common_mistakes": ["Confusing the amplitude envelope with the filter envelope; one shapes loudness, the other shapes tone.", "Setting too long a release so drum hits blur into each other.", "Removing the attack transient and losing the punch of the drum."], "scenario_contexts": ["Tightening a sampled kick by shortening its decay.", "Shaping an electronic snare's tail in a drum synth.", "Using a transient shaper to adjust a drum's attack and sustain."]}, "ce69601f-dd37-427e-a3f4-7e583bc99db4": {"definition": "A filter envelope on a drum sound is an envelope generator that changes a filter's cutoff frequency over time as the drum plays. It creates movement in tone, such as a bright attack that quickly darkens.", "plain_english": "It is a control that sweeps a drum's brightness up or down right after it is hit. For example, it can make a drum start bright and then get darker as it fades.", "purpose_function": "It adds tonal motion to a drum, letting a producer sculpt how the sound's brightness evolves from the hit to the tail.", "practical_application": "In a drum synth, a technician sets a fast filter envelope so a kick punches bright and then settles into a rounder low end.", "category": "Sound Design", "related_terms": ["ADSR envelope", "Filter cutoff", "Low-pass filter", "Amplitude envelope", "Resonance"], "common_mistakes": ["Confusing the filter envelope with the amplitude envelope; this one shapes tone, not loudness.", "Setting too much envelope amount so the filter sweep sounds unnatural.", "Forgetting that the chosen filter type changes how the envelope is heard."], "scenario_contexts": ["Adding a bright click to the start of a synth kick.", "Making a percussive tone open and close in brightness over its length.", "Designing an electronic tom that darkens as it decays."]}, "5d9dfc28-c46b-4f27-aee0-3073bb7ecd0f": {"definition": "A drum multisample is a sampled instrument built from many individual recordings of a drum, typically captured at several velocities and often with multiple takes (round robins) per hit. A playback engine selects the appropriate sample based on how hard the pad or key is struck.", "plain_english": "It is a drum sound made from many separate recordings of the same drum played at different strengths. The software picks the right recording based on how hard you play, so soft and loud hits both sound real.", "purpose_function": "It exists to make sampled drums sound natural and expressive by matching the recorded tone to how hard the drum is played.", "practical_application": "A producer loads a multisampled snare so light ghost notes and hard backbeats each trigger different, realistic samples.", "category": "Sampling", "related_terms": ["Velocity layer", "Round robin", "Sampler", "Velocity", "Sample library"], "common_mistakes": ["Programming every hit at the same velocity, which triggers one layer and sounds robotic.", "Confusing a multisample with a single one-shot sample stretched across the keyboard.", "Ignoring round robins, so repeated hits reveal the 'machine gun' effect."], "scenario_contexts": ["Loading a multisampled acoustic kit for a realistic programmed performance.", "Adding velocity variation so a snare pattern feels human.", "Building a sampler instrument from multi-velocity drum recordings."]}, "78795921-4158-4b91-8776-348463fc4f8f": {"definition": "A drum one-shot is a single audio sample containing one isolated drum hit, such as a kick, snare, or hi-hat, that plays through once each time it is triggered rather than looping.", "plain_english": "A drum one-shot is a short sound file of a single drum hit. You press a pad and it plays once, like tapping a drum one time.", "purpose_function": "One-shots let a producer trigger individual drum sounds on demand and arrange them freely, which makes them the basic building block of programmed drum kits.", "practical_application": "A technician loads one-shots onto sampler pads or a drum rack and sequences them into beats, or swaps one snare one-shot for another to change a kit's sound.", "category": "Drum Sampling", "related_terms": ["Drum sample layering", "Drum Rack", "Drum programming", "Drum pattern", "Drum sample blending"], "common_mistakes": ["Confusing a one-shot with a loop; a one-shot is a single hit, not a repeating bar of rhythm.", "Leaving a long tail or silence on the sample, which wastes memory and can cause overlap or timing issues.", "Forgetting to set the sample to one-shot (non-looping) mode, so held notes retrigger or sustain oddly."], "scenario_contexts": ["Building a custom kit by loading individual kick, snare, and hat one-shots onto a sampler.", "Replacing a weak recorded snare with a one-shot sample during mixing.", "Programming a hip-hop beat by sequencing one-shots on a step sequencer."]}, "30dab431-e34c-4496-a871-5154e8f513c7": {"definition": "A drum pattern is a defined rhythmic sequence of drum hits, such as kick, snare, and hats, arranged over a set number of beats or bars and usually repeated as the rhythmic foundation of a section.", "plain_english": "A drum pattern is a set rhythm made from drum hits, played over a bar or two and then repeated. It is the beat you tap your foot to.", "purpose_function": "It provides the steady groove and timing framework that the rest of a track locks to.", "practical_application": "A producer builds a drum pattern on a step sequencer or in a piano roll, then loops and varies it across a song's sections.", "category": "Drum Programming", "related_terms": ["Drum programming", "Drum one-shot", "Drum Rack", "Drum sample layering", "Drum pitch envelope"], "common_mistakes": ["Programming every hit at the same velocity, which makes the pattern sound stiff and robotic.", "Over-quantizing until the groove loses its natural feel.", "Cluttering the pattern with too many hits instead of leaving space."], "scenario_contexts": ["Laying down a basic four-on-the-floor kick pattern for a dance track.", "Copying a drum pattern to a new section and adding fills for variation.", "Auditioning preset patterns in a drum machine to find a starting groove."]}, "4016c250-88f1-461b-aa0e-6bfcfb4f6f7f": {"definition": "A drum pitch envelope is a time-based modulation of a drum sound's pitch, typically a brief sweep from a higher to a lower pitch at the onset, used to shape the attack and body of the hit.", "plain_english": "A pitch envelope makes a drum's pitch slide over time, usually dropping fast right after the hit. That quick drop is what gives an 808 kick its deep boom.", "purpose_function": "It adds punch, weight, and character to synthesized or sampled drums by controlling how their pitch changes during a hit.", "practical_application": "A producer dials in a short pitch drop on a kick or tom to make it hit harder, adjusting the envelope's amount and time to suit the track.", "category": "Sound Design", "related_terms": ["Drum programming", "Drum one-shot", "Drum sample layering", "Drum Rack", "Drum pattern"], "common_mistakes": ["Setting the pitch drop too slow, which makes the kick sound like it is bending out of tune.", "Using so much pitch modulation that the drum loses a clear fundamental pitch.", "Confusing the pitch envelope with the volume (amplitude) envelope."], "scenario_contexts": ["Designing an 808-style kick with a fast downward pitch sweep.", "Adding a short pitch drop to a tom sample for extra punch.", "Tuning a kick's pitch envelope so its low note fits the song's key."]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"fcac2cb0-7765-42e2-8e1c-fcb16c3cbed7": {"definition": "Drum programming is the practice of creating drum parts by sequencing samples or MIDI notes in software or hardware, rather than recording a live drummer performing an acoustic kit.", "plain_english": "Drum programming means building a drum part by placing hits into a sequencer instead of recording a real drummer. It is like typing out a beat step by step.", "purpose_function": "It lets one person create precise, editable, and repeatable drum parts without a drummer, room, or microphones.", "practical_application": "A producer programs drums by drawing notes in a piano roll or tapping pads, then edits velocity and timing so the part feels natural.", "category": "Drum Programming", "related_terms": ["Drum pattern", "Drum one-shot", "Drum Rack", "Drum pitch envelope", "Drum sample layering"], "common_mistakes": ["Leaving every note at identical velocity and timing, which sounds mechanical.", "Programming parts a real drummer could never physically play when realism is the goal.", "Relying only on quantization and never adding humanizing timing or velocity changes."], "scenario_contexts": ["Programming a full drum kit part for a demo when no drummer is available.", "Building electronic beats entirely from samples in a DAW.", "Programming a scratch drum track to record other instruments against."]}, "07b883e4-1abe-419f-8bb8-85ebb37bf267": {"definition": "In Ableton Live, a Drum Rack is an instrument device hosting a grid of pads, where each pad maps an incoming MIDI note to its own sample or instrument chain with independent volume, panning, and effects, letting a user assemble a complete drum kit in one device.", "plain_english": "A Drum Rack is a tool in Ableton Live that lays out drum sounds on a grid of pads. Each pad holds one sound, so you can build a whole kit in one place.", "purpose_function": "It organizes many individual drum sounds into a single playable, mixable instrument, so a producer can trigger and process a full kit from one device.", "practical_application": "A producer drags samples onto Drum Rack pads, plays them from a MIDI controller, and adds per-pad effects or routes pads to separate mixer channels.", "category": "Sampling Instrument", "related_terms": ["Drum one-shot", "Drum sample layering", "Drum programming", "Drum pattern", "Drum sample blending"], "common_mistakes": ["Assuming Drum Rack is a generic term when it is a specific Ableton Live device.", "Not knowing pads can be routed to separate return or mixer channels for individual processing.", "Overloading one pad instead of using clean layered chains."], "scenario_contexts": ["Assembling a custom kit by dropping one-shots onto Drum Rack pads.", "Routing the kick pad to its own audio channel for separate mixing.", "Layering two samples on a single pad to fatten a snare."]}, "7929f22e-af3b-4b47-b945-c3fe388679af": {"definition": "Drum sample blending is the mixing together of two or more drum samples of the same type, such as two kick samples, in balanced proportion to create a single composite sound with the desired tonal character.", "plain_english": "Drum sample blending means mixing two or more drum sounds of the same kind into one. You might blend one kick's deep low end with another kick's sharp click.", "purpose_function": "It lets a producer combine the best qualities of several samples, such as the body of one and the attack of another, into one stronger drum sound.", "practical_application": "A technician stacks two or three kick samples, then balances their levels and EQ so they fuse into a single punchy kick.", "category": "Drum Sampling", "related_terms": ["Drum sample layering", "Drum sample phase alignment", "Drum sample polarity", "Drum one-shot", "Drum Rack"], "common_mistakes": ["Blending samples without checking phase, so the combined sound is thinner than either sample alone.", "Choosing samples that occupy the same frequency range, so nothing new is gained.", "Not matching the samples' tuning, which causes a dissonant blend."], "scenario_contexts": ["Blending a sub-heavy kick with a clicky kick to get both weight and attack.", "Combining two snare samples to add body and crack.", "Blending an acoustic and an electronic clap for a hybrid sound."]}, "ab20e105-d832-4ef6-b878-a2e0d22a576c": {"definition": "Drum sample layering is the technique of stacking two or more drum samples so they play simultaneously, combining their sounds to build a fuller or more characterful composite hit.", "plain_english": "Drum sample layering is stacking drum sounds so they play at the same time. Like layering clothes, each sample adds something: one gives punch, another gives body.", "purpose_function": "It creates a richer, more powerful drum sound than a single sample by combining complementary layers such as attack, body, and sub.", "practical_application": "A producer stacks a click layer, a body layer, and a sub layer on one trigger, then balances and phase-aligns them into a single hit.", "category": "Drum Sampling", "related_terms": ["Drum sample blending", "Drum sample phase alignment", "Drum sample polarity", "Drum one-shot", "Drum Rack"], "common_mistakes": ["Stacking layers without aligning their phase, causing frequency cancellation and a weaker sound.", "Adding too many layers, which muddies the hit instead of strengthening it.", "Layering samples in clashing keys so the tuned parts sound dissonant."], "scenario_contexts": ["Building a big snare from a crack layer plus a body layer.", "Adding a sub layer under a kick to extend its low end.", "Layering a noise sample over a hi-hat for extra sizzle."]}, "8d7f2f88-bb8b-45df-8053-85b5d9ee59ec": {"definition": "Drum sample phase alignment is the process of time-shifting or polarity-adjusting layered drum samples so their waveforms line up, preventing frequency cancellation and ensuring the layers reinforce rather than weaken each other.", "plain_english": "Phase alignment means lining up stacked drum sounds so their waves match. If they do not match, they cancel out and the drum sounds thin and weak.", "purpose_function": "It ensures that layered samples add together constructively, keeping the combined low end and punch full instead of hollow.", "practical_application": "A technician nudges one layer earlier or later, or flips its polarity, until the stacked kick sounds fullest and its waveform peaks align.", "category": "Drum Sampling", "related_terms": ["Drum sample layering", "Drum sample polarity", "Drum sample blending", "Drum one-shot", "Drum Rack"], "common_mistakes": ["Confusing phase (a timing relationship) with polarity (a simple positive or negative flip).", "Layering samples and never checking phase, then wondering why the low end disappears.", "Aligning by eye only and ignoring how the combined sound actually changes by ear."], "scenario_contexts": ["Aligning a sub-kick layer with the main kick so their low ends add up.", "Zooming into two snare waveforms to line up their transients.", "Flipping one layer's polarity to fix cancellation in a stacked kick."]}, "fd6b756b-6d44-4574-a9c8-0fa0462f2229": {"definition": "Drum sample polarity refers to whether a sample's waveform is in its original orientation or inverted, with the positive and negative halves swapped; flipping polarity 180 degrees can strengthen or weaken the result when the sample is combined with another signal.", "plain_english": "Polarity is whether a drum sample's waveform is normal or flipped upside down. Flipping it can make two stacked samples add up better or cancel out.", "purpose_function": "Controlling polarity lets a producer stop layered samples from cancelling each other, keeping the combined drum sound full.", "practical_application": "When a stacked kick sounds thin, a technician flips one sample's polarity and keeps whichever version sounds fuller.", "category": "Drum Sampling", "related_terms": ["Drum sample phase alignment", "Drum sample layering", "Drum sample blending", "Drum one-shot", "Drum Rack"], "common_mistakes": ["Calling a polarity flip a phase change; polarity is a fixed 180-degree inversion, not a time shift.", "Flipping polarity by habit without listening to whether it actually helps.", "Assuming polarity matters for a single sample; it only matters relative to other combined signals."], "scenario_contexts": ["Flipping a layered kick's polarity to fix a hollow low end.", "Checking polarity when blending two snare samples that partly cancel.", "Matching the polarity of a replacement sample to the original during drum replacement."]}, "1fa4a956-174c-4c8a-8459-c0a69dba0959": {"definition": "An editing and mixing process in which recorded drum hits are detected, usually by transient triggering, and then either replaced with, or reinforced by, pre-recorded drum samples so the drum track gains a consistent, controllable tone and level.", "plain_english": "It swaps or backs up recorded drum hits with clean sampled sounds. The software spots each hit and fires a matching sample. That way a weak or messy drum track can be made to sound solid.", "purpose_function": "It exists to fix drums that were recorded poorly, weakly, or inconsistently, giving the engineer control over tone and consistency without re-recording the kit.", "practical_application": "An engineer feeds a dull, uneven snare track into a trigger or replacer plugin, aligns the samples to the original hits, and blends or replaces them to tighten the snare in a rock mix.", "category": "Drum Editing", "related_terms": ["Transient", "Trigger", "Drum sample", "Quantization", "Gate", "Layering"], "common_mistakes": ["Setting the trigger threshold poorly so soft ghost notes are missed or bleed causes false triggers.", "Leaving replacement samples out of time with the original hits, which smears the groove.", "Making every hit identical, removing the natural dynamics and feel of the live performance."], "scenario_contexts": ["Reinforcing a weak or dull recorded kick with a sampled kick for more low-end punch.", "Replacing a badly bleeding or out-of-tune snare on a live-tracked drum recording.", "Blending a sample under acoustic drums to add consistency across an album."]}, "9a55d3bf-5013-498c-af76-fca67530f141": {"definition": "A programmed, usually looping sequence of drum and percussion events stored in a drum machine or step sequencer, defining which drum sound plays on each step or beat along with its timing and accent. Patterns are the building blocks that get chained together into a full song.", "plain_english": "It is a short drum beat you program step by step on a grid. Each step turns a drum sound on or off. You loop it, then join patterns together to build a whole song.", "purpose_function": "It provides a repeatable, editable rhythmic part that can be looped, layered, and chained into full arrangements without playing drums live.", "practical_application": "A producer programs a kick, snare, and hi-hat pattern on a step grid, adjusts accents and swing, then chains variations for the verse and chorus.", "category": "Drum Programming", "related_terms": ["Step sequencer", "Quantization", "Swing", "Drum-pattern variation", "Groove", "Drum sample"], "common_mistakes": ["Leaving everything perfectly quantized with no swing or accents, so the beat feels stiff and robotic.", "Building one static loop and never varying it across the song.", "Ignoring velocity and accent so every hit plays at the same loudness."], "scenario_contexts": ["Programming a beat on a step sequencer for a demo or backing track.", "Loading factory patterns on a drum machine as a starting groove.", "Chaining several patterns into a full song arrangement."]}, "dcb81aaa-27a6-486b-8e8e-cb3c482c05a3": {"definition": "A modified version of a base drum pattern, created through fills, added or removed hits, accent or velocity changes, or altered timing, used to keep a programmed rhythm from sounding static and to mark different song sections.", "plain_english": "It is a small change to a repeating drum beat so it does not sound the same over and over. You might add a fill, drop a hit, or change the accents. This helps signal a new section of the song.", "purpose_function": "It adds movement and structure to programmed drums, preventing listener fatigue and signalling transitions between song sections.", "practical_application": "A producer copies the main groove, adds a fill on the last bar, and drops the kick for a breakdown, then chains these variations across the arrangement.", "category": "Drum Programming", "related_terms": ["Drum-machine pattern", "Fill", "Groove", "Quantization", "Arrangement", "Accent"], "common_mistakes": ["Repeating one identical loop for the entire track so it feels lifeless.", "Cramming every bar with fills so the groove never feels stable.", "Changing the pattern so drastically that the groove loses its continuity."], "scenario_contexts": ["Writing a drum fill to lead into a chorus.", "Creating a stripped-down variation for a breakdown section.", "Varying accents bar to bar to make a loop feel more human."]}, "91890661-cd1e-46c7-951f-a064e7941f97": {"definition": "An automation envelope that varies a level or dynamics-related parameter, such as fader gain, clip gain, or a compressor threshold, over time. It is drawn or recorded as a curve on the timeline so the parameter changes smoothly as the mix plays.", "plain_english": "It is a line you draw over time that tells the mix how loud something should be at each moment. The fader follows the line by itself, moving up and down as the song plays.", "purpose_function": "It lets the engineer shape level and dynamics changes precisely over time, so the moves repeat exactly on every playback instead of relying on live hands on the fader.", "practical_application": "An engineer draws a volume automation curve to lift a vocal in quiet verses and ease it down in loud choruses, using curved rather than stepped points for smooth transitions.", "category": "Automation", "related_terms": ["Fader automation", "Clip gain", "Volume riding", "Breakpoint", "Compression", "Envelope"], "common_mistakes": ["Using sharp stepped nodes where a smooth curve is needed, causing audible level jumps.", "Automating the channel fader when clip gain before the compressor would be more consistent.", "Overwriting good automation by leaving a track in latch or write mode by accident."], "scenario_contexts": ["Riding a lead vocal level line by line through a song.", "Automating a filter or send to build up into a drop.", "Smoothing an instrument that jumps in level between sections."]}, "024b010c-9761-4ce3-b60d-08826f09dbe7": {"definition": "The perceived power, punch, or sense of force a sound or mix delivers, arising from its dynamic contrast, its strong transients and the difference between loud and quiet passages, rather than from steady loudness alone.", "plain_english": "It is how much punch or force a sound seems to hit you with. It comes from the gap between loud and soft moments, not just from being turned up. Squash that gap too much and the punch fades away.", "purpose_function": "It describes a quality engineers try to protect when balancing loudness against feel, because preserving transients and contrast keeps music exciting and powerful.", "practical_application": "When an engineer hears that a heavily compressed drum bus sounds flat, they back off the compression to restore the transient punch and dynamic impact.", "category": "Dynamics", "related_terms": ["Transient", "Dynamic range", "Compression", "Punch", "Loudness", "Limiting"], "common_mistakes": ["Over-compressing or over-limiting until the transients and impact are gone.", "Assuming louder always means more impactful, ignoring dynamic contrast.", "Using slow attack with fast release settings that flatten the transient detail."], "scenario_contexts": ["Deciding how hard to compress a drum bus without killing the punch.", "Preserving impact while raising a master toward a competitive loudness.", "Comparing an over-limited master against a more dynamic reference track."]}, "2806e872-664c-490d-9c05-52dc61956ed8": {"definition": "A musical score that changes in real time in response to user actions or program state, rather than playing back as a fixed linear cue; also called adaptive or interactive music, its layers, sections, or parameters are altered on the fly to match on-screen events.", "plain_english": "It is game or app music that changes as you play, instead of staying the same. When the action heats up, the music can grow more intense to match it.", "purpose_function": "It keeps music matched to unpredictable, user-driven events, sustaining mood and tension without relying on a fixed timeline.", "practical_application": "A game composer builds the score as stems and sections, then uses audio middleware to add or remove layers and trigger transitions as the player moves between calm and combat.", "category": "Game Audio", "related_terms": ["Music switch", "Music transition rule", "Exploration music", "Music synchronization point", "Music-only stem"], "common_mistakes": ["Composing one long linear track and expecting it to feel interactive without stems or middleware logic", "Not matching musical keys and tempos across sections, so transitions clash", "Layering too many parts at once, muddying the mix when several states trigger together"], "scenario_contexts": ["Combat music intensifying as more enemies appear in a video game", "Menu music smoothly shifting into gameplay music when a level loads", "An interactive exhibit whose music responds to visitor movement"]}, "fa286826-018c-43f0-bf35-a75fe969ec95": {"definition": "A voice-management scheme in electronic instruments where the available polyphony, the pool of voices, is assigned to notes on demand as they are played rather than being fixed per part. When all voices are in use, a note-stealing rule frees the least important voice for the newest note.", "plain_english": "A synth can only play so many notes at once. This system hands those note slots out only when they are needed, so none are wasted. If it runs out, it drops the oldest or quietest note to make room.", "purpose_function": "It lets a synth or sampler with limited polyphony cover more parts and notes than a fixed allocation would, sharing the voice pool wherever it is needed moment to moment.", "practical_application": "On a multitimbral workstation, a technician relies on dynamic voice allocation so a busy MIDI arrangement shares voices; when polyphony runs out they hear notes cut off and reduce layers or free up voices.", "category": "Synthesis", "related_terms": ["Polyphony", "Voice stealing", "Multitimbral operation", "MIDI", "Sampler", "Note-on"], "common_mistakes": ["Confusing polyphony, the total number of voices, with the allocation method that shares them out.", "Assuming a patch is faulty when notes cut off, instead of recognising voice stealing from used-up polyphony.", "Stacking many voices per key without accounting for the reduced note count that leaves available."], "scenario_contexts": ["Programming a dense multitimbral sequence on a hardware workstation.", "Troubleshooting sustained notes that get cut off during a live keyboard performance.", "Choosing a synth whose voice count suits a heavily layered pad patch."]}, "1dbd0b5c-7f9d-47d4-b9b4-1e74d73a4c30": {"definition": "A quality-control check that measures a program's dynamic range, the span between its loudest and quietest levels or a loudness-range metric, and confirms it meets a target or delivery specification such as a broadcast loudness-range requirement.", "plain_english": "It is a check that measures the gap between the loudest and quietest parts of audio. You compare that gap to the rules a project must meet, like a broadcast standard. If it is too squashed or too wide, you fix it before delivery.", "purpose_function": "It confirms audio meets loudness and dynamics delivery specs and is not over-compressed, protecting quality and compliance before release or broadcast.", "practical_application": "Before delivering a broadcast mix, an engineer uses a loudness meter to check integrated loudness and loudness range against the R128 or ATSC target and adjusts if it fails.", "category": "Metering & QC", "related_terms": ["Dynamic range", "Loudness", "Loudness range", "Metering", "Mastering", "True peak"], "common_mistakes": ["Confusing peak level with dynamic range; a loud peak does not mean the audio has wide dynamics.", "Over-compressing to hit a loudness target and then failing the dynamics or loudness-range spec.", "Reading only a peak meter and ignoring integrated loudness and loudness range."], "scenario_contexts": ["QC of a broadcast mix against EBU R128 or ATSC A/85.", "Checking a master's dynamic-range value before release.", "Verifying a podcast meets a streaming loudness target."]}, "6020c0db-3bbd-43e4-814f-f5ddb91437b4": {"definition": "How well a finished mix holds up, in its balance, bass, vocal level, and clarity, when played back on earbuds and other small consumer earphones rather than on studio monitors. It is one aspect of overall mix translation across playback systems.", "plain_english": "It is how good your mix still sounds on cheap earbuds, not just big studio speakers. A mix can sound great in the studio but lose its bass or hide the vocal on earbuds. Checking this makes sure it works everywhere.", "purpose_function": "It makes sure a mix works on the small, limited playback devices most listeners actually use, catching balance problems that studio monitors can hide.", "practical_application": "After mixing on monitors, an engineer checks the mix on earbuds to confirm the bass, vocal, and lead still balance well, then fixes anything that falls apart.", "category": "Mix Translation", "related_terms": ["Mix translation", "Reference monitors", "Nearfield monitors", "Frequency balance", "Mono compatibility", "Reference track"], "common_mistakes": ["Mixing only on one system and never checking earbud or phone playback.", "Piling on sub-bass that earbuds cannot reproduce, so the kick and bass balance is wrong there.", "Setting the vocal or lead too low, so it disappears on small earphones."], "scenario_contexts": ["Referencing a mix on earbuds before finalising it.", "Fixing a bass balance that only sounds right on big monitors.", "Checking a mostly-streamed release plays well on phone earbuds."]}, "29988c6f-0b01-4572-b245-44710c365d18": {"definition": "In a DAW's edit (arrange) window, the edit cursor is the blinking insertion point placed with the selector tool that marks the exact timeline location where editing operations begin. It defines a zero-length edit position on a track, distinct from the moving playback cursor.", "plain_english": "The edit cursor is the blinking marker that shows where you clicked on a track. It tells the software where your next edit or paste will land, like the text cursor in a word app.", "purpose_function": "It gives every edit a single, precise reference point on the timeline so cuts, pastes, and inserts happen exactly where intended rather than approximately.", "practical_application": "A technician clicks with the selector to place the edit cursor before pasting a clip, spotting a marker, or setting where a fade or punch-in will start.", "category": "Editing", "related_terms": ["Edit Selection", "Edit Group", "Playback Cursor", "Selector Tool", "Timeline"], "common_mistakes": ["Confusing the edit cursor (a fixed insertion point) with the moving playback cursor.", "Assuming the cursor stays put after clicking elsewhere; a new click moves it.", "Placing the cursor on the wrong track so an edit lands where it was not intended."], "scenario_contexts": ["Placing the edit cursor before pasting a copied clip at a precise bar line.", "Setting the point where a punch-in recording will begin.", "Clicking to position the cursor before spotting a sound effect to picture."]}, "d84cf8b9-464d-4a21-acd1-d9407362b8c1": {"definition": "An edit group is a set of tracks linked so that editing actions performed on any member, such as selecting, cutting, trimming, fading, or moving material, are applied identically to all members. In Pro Tools a group can be edit-only, mix-only, or linked for both.", "plain_english": "An edit group ties several tracks together so they act as one when you edit. Cut or move one track and the same change happens to the rest, like sliding a whole stack of paper instead of one sheet.", "purpose_function": "It keeps related tracks, such as a multi-mic drum kit, time-aligned by ensuring edits apply to every member at once.", "practical_application": "An engineer groups all drum tracks so trimming or sliding one clip keeps the whole kit in sync, then suspends the group to edit a single track.", "category": "Editing", "related_terms": ["Edit Selection", "Edit Cursor", "Mix Group", "Track", "Playlist"], "common_mistakes": ["Forgetting a group is active and editing every track when only one was intended.", "Confusing edit groups with mix groups, which link fader and mute moves instead of edits.", "Not suspending the group before editing a single member."], "scenario_contexts": ["Grouping multi-mic drum tracks so edits keep the kit aligned.", "Trimming a whole band's tracks to a new song start at once.", "Suspending a group to slide just one tom hit into place."]}, "4df8d7ec-560b-4733-8160-6748d1aa1d25": {"definition": "An edit selection is the highlighted range of material, on one or more tracks over a span of time, that defines what an editing command will act upon. Its start and end points set the boundaries for operations such as cut, copy, fade, or process.", "plain_english": "An edit selection is the part of the audio you highlight so the software knows what to work on. It is like selecting words in a document before you delete or copy them.", "purpose_function": "It scopes every edit and process to a defined region so a command affects only the chosen material and nothing else.", "practical_application": "A technician drags across a clip to make an edit selection, then applies a fade, deletes noise, or renders a plug-in over exactly that range.", "category": "Editing", "related_terms": ["Edit Cursor", "Edit Group", "Timeline Selection", "Selector Tool", "Playlist"], "common_mistakes": ["Confusing an edit selection with a timeline selection when the two are unlinked.", "Leaving a selection active so the next command affects more material than expected.", "Selecting across the wrong tracks and processing material unintentionally."], "scenario_contexts": ["Highlighting a breath in a vocal take to silence it.", "Selecting a chorus section to duplicate it later in the song.", "Choosing a range to bounce or consolidate to a new file."]}, "3cde4aa9-cd20-438c-9d17-ce6814f89f82": {"definition": "An effects (FX) channel track is a dedicated auxiliary channel that hosts one or more send effects such as reverb or delay; other channels feed it through their sends, and its processed output returns to the mix. It lets several sources share a single effect instance.", "plain_english": "An effects channel is a special track that holds an effect like reverb. You send a bit of each track's sound to it, and it adds the same reverb to all of them, like everyone dipping into one shared pot of sauce.", "purpose_function": "It centralizes a send effect so many tracks can share it, saving processing power and giving one fader to control the whole effect return.", "practical_application": "An engineer creates an FX channel loaded with a reverb, raises each vocal and snare send to place them in the same space, and sets the wet level with the channel's fader.", "category": "Signal Routing", "related_terms": ["Aux Send", "Send Effect", "Return Track", "Bus", "Effects mixer"], "common_mistakes": ["Leaving the effect's mix below 100% wet on the channel, which doubles the dry signal.", "Confusing an FX channel (a shared send effect) with an insert effect on the source track.", "Routing the channel's output to the wrong bus so the effect is not heard."], "scenario_contexts": ["Adding one reverb FX channel that several vocals share.", "Creating a delay FX channel fed from guitar and synth sends.", "Automating the FX channel fader to swell reverb into a chorus."]}, "ec6ab903-7677-4409-a8f9-d49b9ae1d707": {"definition": "In post-production sound, effects fill is background sound-effects or ambience material laid continuously beneath a scene to bridge the silent gaps between individual spot effects and smooth edits, giving the effects track an unbroken, natural bed.", "plain_english": "Effects fill is quiet background sound, like wind or city hum, spread under a scene to cover gaps between louder effects. It stops the track from dropping to sudden silence, like a steady base coat under the big details.", "purpose_function": "It keeps an effects track continuous and natural so the audience never hears an abrupt drop to silence between separate effects.", "practical_application": "A sound editor lays an ambience or backgrounds track as effects fill under a scene, then places spot effects like footsteps and door slams on top.", "category": "Post-Production", "related_terms": ["Room Tone", "Ambience", "Effects premix", "Effects-only stem", "Sound Effects"], "common_mistakes": ["Confusing effects fill (a bed under effects) with room tone used under dialogue.", "Leaving gaps in the fill so the background pops in and out.", "Setting fill too loud so it competes with dialogue and spot effects."], "scenario_contexts": ["Laying a city ambience as fill under an exterior street scene.", "Filling gaps between separate gunshots with a continuous battlefield background.", "Smoothing effect edits with a steady room ambience bed."]}, "c0b67a6a-9e78-4038-8833-c20e051de850": {"definition": "On a film or television dubbing stage staffed by more than one operator, the effects mixer is the re-recording mixer responsible for balancing and processing the sound-effects elements, including spot effects, Foley, and backgrounds, while colleagues handle dialogue and music.", "plain_english": "An effects mixer is the person on a film mix team who blends all the sound effects, like footsteps, doors, and crashes. On big projects the job is split, so one mixer handles only effects while others handle voices and music.", "purpose_function": "Splitting the mix among specialists lets one experienced operator concentrate on the many effects elements, speeding a large mix and improving its balance and detail.", "practical_application": "During a re-recording session, the effects mixer rides the Foley and backgrounds faders and adds EQ and reverb to seat the effects with the picture while the dialogue mixer works alongside.", "category": "Post-Production", "related_terms": ["Re-recording Mixer", "Effects premix", "Effects-only stem", "Foley", "Backgrounds"], "common_mistakes": ["Assuming one person always mixes everything; large films split the roles.", "Confusing the effects mixer (a person) with an effects submixer or FX channel (a signal path).", "Thinking the effects mixer creates the effects rather than balancing already-edited elements."], "scenario_contexts": ["A multi-operator dubbing stage where the effects mixer handles all FX.", "Balancing Foley and backgrounds during a final mix.", "Building an effects premix before the final dub."]}, "125c823b-6fb4-46ba-bb5f-e23d56aa39f2": {"definition": "An effects premix, or predub, is a preliminary re-recording pass that combines and balances the many sound-effects elements (spot effects, Foley, and backgrounds) into a smaller set of tracks or stems, done before the final mix. It cuts track count and locks in effects balances ahead of the final dub.", "plain_english": "An effects premix is a rough mix that blends all the sound effects together before the final movie mix. It shrinks hundreds of effect tracks down to a few, so the last mixing stage is easier to handle.", "purpose_function": "It manages complexity by pre-balancing effects into manageable stems, letting the final mix focus on blending effects with dialogue and music rather than juggling every element.", "practical_application": "A re-recording mixer creates an effects premix of Foley and backgrounds, then brings that premix into the final dub to balance against dialogue and music.", "category": "Post-Production", "related_terms": ["Effects mixer", "Effects-only stem", "Backgrounds", "Foley", "Final Mix"], "common_mistakes": ["Committing effects premixes too hard, leaving no room to rebalance in the final mix.", "Confusing a premix (an intermediate stage) with the final effects stem delivered at the end.", "Not documenting premix routing, which makes later revisions difficult."], "scenario_contexts": ["Premixing dozens of background tracks into a few before the final dub.", "Balancing Foley into an effects premix for a TV episode.", "Recalling an effects premix to adjust a scene during the final mix."]}, "15a2f67d-85e8-4976-ae3a-97617870fb37": {"definition": "An effects-only stem is a final mix delivered as a separate sub-mix containing just the sound-effects elements (spot effects, Foley, and backgrounds), kept apart from the dialogue and music stems. Summed together, the dialogue, music, and effects stems reproduce the full mix.", "plain_english": "An effects-only stem is a copy of the finished soundtrack that holds just the sound effects. It has no voices and no music. Keeping the effects on their own makes it easy to swap languages or change the mix later, like keeping each paint color in its own jar.", "purpose_function": "It lets the effects be reused, rebalanced, or combined with new dialogue and music, which is essential for foreign-language versions and future remixes.", "practical_application": "For delivery, a mixer prints dialogue, music, and effects stems; the effects-only stem is combined with translated dialogue to build a foreign dub or an M&E master.", "category": "Post-Production", "related_terms": ["Stem", "M&E", "Effects premix", "Effects mixer", "Music Stem"], "common_mistakes": ["Confusing an effects-only stem with M&E, which also includes music.", "Leaving processing on the master bus so the stems do not sum back to the original mix.", "Forgetting to include backgrounds and Foley, leaving the effects stem incomplete."], "scenario_contexts": ["Delivering separate dialogue, music, and effects stems to a studio.", "Combining the effects stem with a new language track for a foreign dub.", "Rebalancing effects during a remix without re-editing."]}, "e780c840-4a05-43bb-aa6c-46b1d35aad34": {"definition": "An Elastic Audio track in Pro Tools is an audio track with Avid's Elastic Audio time-stretching engine enabled, letting clips be tempo-conformed, quantized, and warped, compressing or expanding audio in time without creating a new file. Warp markers anchor and stretch chosen points in the audio.", "plain_english": "An Elastic Audio track lets you stretch or squeeze recorded sound to fix its timing. You do not have to record it again. It works like a rubber band, so a note that lands a little late can snap onto the beat.", "purpose_function": "It lets recorded performances be matched to a session's tempo or tightened rhythmically, so timing can be fixed and material can follow tempo changes.", "practical_application": "An engineer enables Elastic Audio on a drum loop to conform it to the session tempo, then drags warp markers to nudge individual hits into time.", "category": "Editing", "related_terms": ["Warp Marker", "Time Stretch", "Quantize", "Edit Selection", "Tempo Map"], "common_mistakes": ["Choosing the wrong warp algorithm, such as Monophonic on a full mix, which causes artifacts.", "Applying heavy stretching that introduces audible smearing or warble.", "Forgetting Elastic Audio is enabled, so clips shift unexpectedly with tempo changes."], "scenario_contexts": ["Conforming a recorded loop to the session tempo.", "Tightening a live drum take by warping individual hits.", "Matching a doubled vocal to the timing of the lead."]}, "ccfa686b-4e4a-4e15-82c7-b0c0454ad3c9": {"definition": "The process of balancing and blending the individual tracks of a musical score built mainly from electronic and synthesized sources - synths, drum machines, samplers, and programmed parts - into a finished stereo or surround mix for film, television, or games. It applies standard mixing craft (level, panning, EQ, dynamics, and effects) to primarily electronic material rather than acoustically recorded ensembles.", "plain_english": "This is mixing a piece of music built mostly from synths, drum machines, and computer sounds. You set each part's volume, place it left or right, and shape its tone. The goal is one clear, balanced track for a film, show, or game.", "purpose_function": "It turns a collection of separate electronic parts into a cohesive, release-ready piece of music, so every element sits at the right level and tone and the score supports the picture without masking dialogue or effects.", "practical_application": "A technician loads the composer's session, groups the synth, bass, drum, and pad tracks, and uses faders, panning, EQ, and compression to balance them, then delivers stems and a final mix that meet the project's loudness and format specs.", "category": "Mixing", "related_terms": ["Stems", "Automation", "Panning", "Bus", "Loudness normalization"], "common_mistakes": ["Treating loud synth patches as raw material and stacking more EQ and compression on top, when many electronic sounds are already processed and turn harsh.", "Letting several sub and bass patches pile up in the same low range until the mix overloads and loses clarity.", "Mixing too loud and clipping the master bus instead of leaving headroom for mastering.", "Forgetting to leave space for dialogue and effects when the score is for picture."], "scenario_contexts": ["Mixing a synth-based cue for a sci-fi film so it sits under the dialogue.", "Balancing programmed drums, bass, and pads for a game's menu music.", "Preparing stems of an electronic TV theme for the dub stage."]}, "c25caee0-8614-416f-970e-508a0c0ae1ac": {"definition": "eMastered is a commercial cloud-based automated mastering platform that uses machine-learning algorithms to analyze an uploaded mix and apply mastering processing such as EQ, compression, stereo-width, and level adjustment, producing a finished master with user controls for intensity and reference-track matching.", "plain_english": "It is an online service that masters your song for you using software instead of a person. You upload your mix, and it polishes the sound and gives you a finished, louder version.", "purpose_function": "It offers a fast, low-cost route to a release-ready master without booking a mastering engineer, aimed mainly at independent artists working to a budget.", "practical_application": "A producer uploads a stereo mixdown, picks a mastering intensity or a reference track, previews the result, and downloads the master, often as a quick check before deciding whether to hire a human engineer.", "category": "Mastering Tools", "related_terms": ["Mastering", "Reference track", "Loudness normalization", "Dynamic-range validation", "Final release authorization"], "common_mistakes": ["Treating an automated master as a fix for a poor mix, when mastering cannot repair balance or arrangement problems", "Chasing maximum loudness and losing dynamic range and transient punch", "Skipping a critical listen and QC of the returned master on trusted monitors"], "scenario_contexts": ["An independent artist mastering a single on a tight budget before a streaming release", "A producer generating a quick reference master to gauge how a mix compares to commercial tracks", "A songwriter creating a polished demo to pitch to a label"]}, "91d3b84b-39a0-4128-b8c8-31d3b262cc08": {"definition": "Pre-prepared audio held ready to play - automatically or manually - the moment a program's main source fails or falls silent, so a broadcast, performance, or installation is never left in dead air. It is the contingency layer of a playback chain, often triggered by a silence detector that switches to a backup player when the primary signal drops.", "plain_english": "This is backup audio kept ready in case the main sound suddenly stops. If the live feed or main player fails, the backup starts so the audience never hears silence. Think of it like a spare tire that swaps in the moment the main one goes flat.", "purpose_function": "It protects a show or station from dead air by guaranteeing that approved audio keeps playing when the primary source drops out, buying the operator time to find and fix the fault.", "practical_application": "A broadcast engineer loads a backup playlist into a silence-monitoring player so that, if the studio feed goes quiet for a set number of seconds, the unit automatically switches to the emergency audio and raises an alarm.", "category": "Playback", "related_terms": ["Dead air", "Silence detection", "Backup player", "Redundancy", "Playback cue"], "common_mistakes": ["Loading emergency audio but never testing the automatic switchover, so it fails when actually needed.", "Setting the silence threshold or delay wrong, so the backup either triggers on quiet passages or waits too long.", "Forgetting to update the backup content, leaving stale or wrong material to air during a failure."], "scenario_contexts": ["A radio station's studio link drops and a silence monitor rolls the backup playlist automatically.", "A live show's playback laptop crashes and the operator fires a redundant machine holding the same tracks.", "An installed AV system loses its media server and falls back to a looped emergency message."]}, "eb9da154-a60f-4f7c-84dc-f4fa9f336370": {"definition": "The audible change in a room's sound when it is empty of people and soft furnishings: with little absorptive material present, reflections build up, reverberation time lengthens, and the space sounds brighter, boomier, and more echoey than when occupied. Adding an audience, seating, and drapes raises absorption and shortens reverberation, which is why a room measured empty behaves differently once it is full.", "plain_english": "An empty room sounds more echoey than a full one. With no people, curtains, or soft seats to soak up sound, the noise bounces around longer and the room rings. This is why a hall can sound boomy at soundcheck but tighter once the crowd fills it, because bodies and coats absorb sound.", "purpose_function": "Knowing about it lets engineers predict how a space will sound once occupied, so they tune and set levels for the full-room condition instead of being fooled by the livelier empty-room measurement.", "practical_application": "During an empty-hall soundcheck a technician expects the room to deaden and lose some high-frequency ring once the audience arrives, so they avoid over-damping the system and re-check EQ and levels after doors open.", "category": "Acoustics", "related_terms": ["Reverberation time", "Absorption coefficient", "Room modes", "Early reflections", "Soundcheck"], "common_mistakes": ["Tuning the PA to sound perfect in the empty room, then finding it dull and quiet once the crowd absorbs the highs.", "Assuming reverberation time is fixed, when occupancy and furnishings change it significantly.", "Confusing the empty-room liveliness with a system EQ problem and over-correcting."], "scenario_contexts": ["Sound-checking a PA in an empty theatre before a full-house show.", "Measuring reverberation time in an unoccupied hall for acoustic treatment planning.", "Setting up a house-of-worship system that must work both sparsely and fully attended."]}, "74b5531a-09bd-40d0-848f-ab394dab27cb": {"definition": "The formal, documented approval by the responsible engineer that a mix, master, or installed system meets its agreed technical specification and is cleared for delivery, broadcast, or client use. It marks the transition from work-in-progress to accepted deliverable and typically records who approved it, against what specification, and when.", "plain_english": "This is the moment an engineer officially says the work is done and passes. They check it against the agreed rules, like loudness limits or system tests, and then approve it in writing. It is like a final inspection stamp before the job is handed over.", "purpose_function": "It creates a clear point of accountability and quality control, confirming the deliverable met spec so responsibility passes cleanly to the next stage and any dispute traces back to a documented decision.", "practical_application": "Before a mix goes to the client, an engineer checks it against the delivery spec - format, sample rate, and loudness target - and records a sign-off, or completes a system-verification checklist and signs the handover on an install job.", "category": "Workflow", "related_terms": ["Delivery specification", "Quality control", "Loudness normalization", "Commissioning", "Session archiving"], "common_mistakes": ["Signing off without checking against the written delivery spec, so a format or loudness error slips through.", "Skipping documentation, leaving no record of what was approved or by whom.", "Treating sign-off as a formality rather than a real quality-control gate."], "scenario_contexts": ["Approving a finished master against a streaming platform's loudness and format spec.", "Completing a system-verification checklist before handing a new install to the client.", "Clearing a broadcast deliverable through QC before it airs."]}, "10bc385c-72fe-4fa6-96d2-8feceb302d44": {"definition": "A prearranged signal that tells a performer, operator, or playback element exactly when to begin. In live and studio production it may be a conductor's gesture, a talkback or light cue, or a marked point in a session or show-control list that triggers a track, sound, or musician's entrance.", "plain_english": "An entry cue is the 'go' signal that tells someone or something when to start. It might be a nod from the conductor, a light, a word in the headphones, or a marker in the software. It works like a green light for the exact moment to come in.", "purpose_function": "It keeps everyone tightly in sync by defining the precise start moment for each part, so entrances land together and nothing comes in early or late.", "practical_application": "An engineer places entry cues as session markers so a backing track, sample, or overdub starts on the right beat, or gives a talkback count-in so a musician knows exactly when to play.", "category": "Cueing", "related_terms": ["Exit cue", "Count-in", "Talkback", "Session marker", "Click track"], "common_mistakes": ["Placing the cue marker slightly off the beat, so the entrance feels early or late.", "Relying on a spoken cue without a click, so timing drifts.", "Not agreeing the cue with the performer beforehand, causing missed entrances."], "scenario_contexts": ["Cueing a vocalist's first line during a live broadcast.", "Marking the exact bar where a sampled hit must trigger in a DAW.", "Giving a count-in so a session player enters on the downbeat."]}, "eeffdc4d-16b5-4961-9356-f96e2be6105a": {"definition": "A rhythmic pattern in which a given number of onsets (hits) is spread as evenly as possible across a fixed number of steps, produced by applying the Euclidean algorithm. Described by Godfried Toussaint, these maximally even distributions coincide with many traditional world-music patterns and are widely built into sequencers, which generate the rhythm from two numbers: hits and steps.", "plain_english": "A Euclidean rhythm spreads a set number of beats as evenly as possible over a set number of steps. You pick two numbers, how many hits and how many slots, and the math spaces the hits out for you. For example, 3 hits over 8 steps gives a common, danceable pattern found in music worldwide.", "purpose_function": "It lets musicians and machines generate balanced, musical rhythms instantly from two simple settings, so you can create and vary grooves without programming every step by hand.", "practical_application": "On a drum machine or modular sequencer a technician sets the hit and step counts (and often a rotation) to dial in kick, hi-hat, or percussion patterns, then layers several Euclidean tracks to build a full groove.", "category": "Sequencing", "related_terms": ["Step sequencer", "Polyrhythm", "Onset", "Rotation", "Gate"], "common_mistakes": ["Assuming the hits are placed randomly, when they are spaced as evenly as the numbers allow.", "Forgetting that rotating the pattern changes where the first hit lands, which shifts the feel.", "Overlapping several dense Euclidean tracks until the groove becomes cluttered."], "scenario_contexts": ["Programming an interlocking percussion groove on a Eurorack Euclidean module.", "Using a drum machine's Euclidean mode to quickly sketch a beat.", "Generating evolving hi-hat patterns by rotating a Euclidean sequence."]}, "b4e1dabf-efb4-413e-ae00-68cd6602b8d1": {"definition": "A prearranged signal that tells a performer, operator, or playback element exactly when to stop or leave. In production it marks the end point of a section, track, or performer's part - a gesture, spoken cue, light, or marked point in a session or show-control list that ends or fades an element cleanly.", "plain_english": "An exit cue is the 'stop' signal that tells someone or something when to finish. It might be a hand signal, a word in the headphones, a light, or a marker in the software. It works like a red light for the exact moment to come out.", "purpose_function": "It makes sure elements end together and on time, so fades, cutoffs, and performer exits happen cleanly instead of trailing off or overlapping the next section.", "practical_application": "An engineer sets an exit cue as a session marker to end a backing track or trigger a fade, or signals a performer over talkback so they stop exactly on the agreed beat.", "category": "Cueing", "related_terms": ["Entry cue", "Fade-out", "Session marker", "Talkback", "Crossfade"], "common_mistakes": ["Placing the exit marker late, so the element overruns into the next section.", "Cutting a track dead instead of fading, causing an abrupt or clicky ending.", "Not rehearsing the cue, so a performer misses the exit."], "scenario_contexts": ["Fading out a backing track on cue at the end of a live song.", "Marking where a sound effect must stop in a show-control list.", "Signaling a presenter to wrap up before a hard break."]}, "0438361c-97f4-440f-bf92-adc7cf61ebee": {"definition": "In game audio, the music cue or state that plays while the player is freely exploring the game world, as distinct from combat, menu, or cutscene music. It is usually calmer and more ambient, and in adaptive scores it transitions to and from other states, such as combat, as gameplay changes.", "plain_english": "This is the background music that plays while you wander and explore in a video game. It is usually calm and atmospheric, setting the mood without grabbing your attention. When the action starts, the game swaps it for tenser combat music.", "purpose_function": "It sets the mood of the game world during low-tension play and, in adaptive scores, gives a musical baseline the game shifts away from and back to as the situation changes, keeping the soundtrack matched to what the player is doing.", "practical_application": "A game-audio implementer authors an exploration track as a loop or layered stems in middleware, then sets the rules that fade it up during free roaming and cross-fade to combat music when a fight begins.", "category": "Game audio", "related_terms": ["Adaptive music", "Vertical layering", "Music state", "Combat music", "Middleware"], "common_mistakes": ["Making exploration music too busy or catchy, so it tires the player over long sessions.", "Forgetting smooth transitions, so the switch to combat music feels jarring.", "Looping a track with an audible seam, so the join is obvious."], "scenario_contexts": ["Scoring an open-world game's overworld where players roam between quests.", "Setting up a middleware music system that fades from exploration to combat states.", "Composing a calm ambient loop for a puzzle or adventure exploration area."]}, "a3b9da75-014c-46e1-b97c-38c537666526": {"definition": "The quality-control step of confirming that a rendered (bounced) mix or master file actually meets its target specification before delivery: verifying the correct file format, sample rate and bit depth, absence of clipping or overs, no dropouts or plug-in glitches, correct start/end points and length, appropriate loudness and metadata, and that the file sounds identical to the monitored mix.", "plain_english": "It means checking your finished exported file to make sure nothing went wrong. You confirm it is the right format, has no clipping or gaps, and sounds just like the mix you heard while working.", "purpose_function": "It catches rendering errors such as wrong settings, clipped peaks, muted tracks, dropouts or plug-in glitches before a file reaches the client, mastering engineer or distributor, where mistakes are costly to fix.", "practical_application": "After bouncing, a technician imports the exported file back into the session or a media player, listens start to finish, checks the meters for overs, and confirms the format, length and file name against the delivery spec.", "category": "Delivery & QC", "related_terms": ["Bouncing", "Mastering", "Dithering", "Loudness normalization", "Sample rate", "Headroom"], "common_mistakes": ["Delivering the file without listening back, so a muted track, clipped peak or dropout goes unnoticed.", "Exporting at the wrong sample rate or bit depth for the target platform.", "Ignoring inter-sample overs because the DAW meter read just under 0 dBFS.", "Trusting the settings and file name without confirming the render actually captured real-time external effects."], "scenario_contexts": ["Confirming a stereo master matches the loudness and format spec before uploading to a streaming distributor.", "Checking exported stems all start at the same point and are the correct length before sending to a mastering engineer.", "Verifying a real-time export captured hardware-processed audio that a normal offline bounce would not print."]}, "6264fae3-6e8a-4d45-ae28-9b87851f5d8f": {"definition": "A DAW device that inserts a piece of external hardware, such as an outboard compressor, EQ or reverb, into the signal path by routing audio out through chosen audio-interface outputs to the hardware and back through chosen inputs, with a hardware-latency control that keeps the returned signal in time. Ableton Live names a device this way; Cubase's External FX and Logic's I/O plug-in fill the same role.", "plain_english": "It is a tool in your music software that lets you use a real hardware effect box as if it were a plug-in. The software sends the sound out to the box, the box changes it, and the sound comes back in, while a delay control keeps it lined up in time.", "purpose_function": "It lets engineers use the sound of outboard analog processors inside an otherwise in-the-box session while automatically compensating for the round-trip delay of leaving and re-entering the computer.", "practical_application": "A technician patches an interface output to the hardware input and the hardware output back to an interface input, loads the device on a track or return, and sets the hardware-latency value so the processed audio stays in sync.", "category": "Signal Routing", "related_terms": ["External Instrument", "Insert", "Return track", "Outboard gear", "Latency compensation", "Audio interface"], "common_mistakes": ["Forgetting the effect is not printed to disk until a real-time export is done, so an offline bounce loses it.", "Not setting the hardware-latency value, leaving the returned audio out of time.", "Routing the hardware return back into its own send and creating a feedback loop.", "UNSAFE: Making or breaking these connections with monitor levels up can cause a loud pop that can damage speakers and hearing, so mute or lower levels first."], "scenario_contexts": ["Running a mix bus through an analog hardware compressor from inside the DAW.", "Using a vintage outboard EQ on a vocal return without leaving the software session.", "Printing the externally processed signal back to an audio track via a real-time export."]}, "46c7c9ef-a19e-4b72-8851-780e81ae9036": {"definition": "A DAW device that integrates a hardware synthesizer or sound module into a track like a software instrument: it sends MIDI out to a chosen port and channel to play the hardware and returns the hardware's audio into the same track, with a latency-compensation control. Ableton Live and Steinberg Cubase both provide a device of this name.", "plain_english": "It is a tool that lets you play a real hardware synth from inside your music software as if it were a built-in instrument. The software sends the notes out to the synth, and the synth's sound comes back into the track.", "purpose_function": "It combines the sound of external hardware synths with the convenience of software, since one device handles both the MIDI going out and the audio coming back and compensates for the resulting delay.", "practical_application": "A technician connects a MIDI output to the synth and the synth's audio to an interface input, loads the device, selects the MIDI port, channel and audio input, then records or renders the returned audio.", "category": "Signal Routing", "related_terms": ["External Audio Effect", "MIDI", "Sound module", "Audio interface", "Latency compensation", "Virtual instrument"], "common_mistakes": ["Expecting the synth audio to record automatically, when you must arm and print the returned audio, often via a real-time render.", "Mismatching the MIDI channel so the hardware does not respond.", "Not accounting for the hardware's own latency, so parts drift out of time.", "Leaving the track's monitoring on so you hear a delayed doubling of the audio."], "scenario_contexts": ["Sequencing a hardware analog synth from the DAW timeline and recording its audio.", "Playing a rack sound module across a song and printing the result to an audio track.", "Layering a hardware synth with software instruments while keeping everything in time."]}, "08381517-2725-4934-8b62-752a2b9024d4": {"definition": "The mistaken belief that a channel fader's position indicates, or should be used to set, the actual signal level or gain in a chain. A fader only applies gain or attenuation at the mixing stage, downstream of the input/trim gain; proper gain staging is set with input gain rather than by where the fader sits, and DAW faders are deliberately scaled for fine control near unity rather than as a level indicator.", "plain_english": "It is the wrong idea that where a fader sits tells you how loud a track really is. A fader only turns a sound up or down at the end of the chain. You set the real working level earlier, with the input gain, not by moving the fader.", "purpose_function": "Understanding the fallacy stops students from judging or fixing levels by fader position, which protects the signal-to-noise ratio and headroom and keeps gain staging correct through the whole chain.", "practical_application": "Instead of pushing faders to balance levels, a technician sets each source with input or clip gain, aiming for healthy meters with headroom, then uses faders near unity only for the final balance.", "category": "Gain Staging", "related_terms": ["Gain staging", "Unity gain", "Headroom", "Signal-to-noise ratio", "Clip gain", "Trim"], "common_mistakes": ["Assuming a fader at 0 dB (unity) means the track is at a correct level.", "Riding faders to the top for level instead of raising input gain, adding noise or clipping upstream.", "Reading fader position as if it were a loudness meter.", "Pulling a clipping channel's fader down and thinking the clipping is fixed, when the overload happened before the fader."], "scenario_contexts": ["Setting initial DAW levels with clip or input gain while leaving faders near unity.", "Troubleshooting a distorted channel whose fader is low but whose input stage is overloaded.", "Teaching new engineers why a low fader does not mean a quiet or clean signal."]}, "c519af9f-e40e-49a3-a173-40c302fa0e90": {"definition": "The post-production process of bringing a location field recorder's multitrack audio into an editing system and matching it to picture: a guide mixdown recorded alongside the isolated (iso) channels is synced by timecode, then expanded using the files' embedded metadata to reveal and edit the individual channels and alternate takes. It relies on Broadcast Wave/iXML metadata and SMPTE timecode written by the recorder.", "plain_english": "It is how sound from an on-location recorder gets loaded into editing software and lined up with the video. First a simple mixed track is matched to picture by timecode. Then it is opened up to show every separate mic track, so the editor can pick the best one.", "purpose_function": "It lets dialogue editors work quickly from a single guide track yet still reach every individual mic channel the field recorder captured, using metadata and timecode so nothing has to be lined up by hand.", "practical_application": "A dialogue editor cuts the production mixdown to picture, then expands each region to swap in the cleanest iso mic, for example a lav instead of the boom, using the recorder's metadata.", "category": "Post-Production", "related_terms": ["Timecode", "Broadcast Wave (BWF)", "iXML metadata", "Double-system sound", "Iso track", "Dialogue editing"], "common_mistakes": ["Recording without valid timecode or metadata, forcing manual, error-prone syncing.", "Assuming the guide mixdown is the only usable audio and never expanding to the iso channels.", "Ignoring sample-rate or frame-rate mismatches between recorder and session.", "Losing the original file metadata by re-exporting through software that strips it."], "scenario_contexts": ["Conforming double-system location sound to a film's picture edit.", "Expanding a two-track mixdown to individual lav and boom channels for cleaner dialogue.", "Importing a day's field recordings with timecode and scene/take metadata for editing."]}, "be7d5a9f-517c-4d41-ab4a-ab6cc25b21e3": {"definition": "Tempo information stored inside an audio file or its metadata that tells software the file's musical tempo in beats per minute, and often its beat or slice positions, so a DAW can automatically time-stretch or warp the file to the project tempo. Common carriers include ACIDized WAV files, Apple Loops, and REX/sliced-loop files.", "plain_english": "It is tempo information saved inside an audio file that says how fast it is, in beats per minute. Music software reads it so a loop can automatically speed up or slow down to fit the song you are working on.", "purpose_function": "It lets loops and samples conform to a project's tempo automatically, so a technician can drop in a loop and have it lock to the beat without manually stretching it.", "practical_application": "When a technician drags an ACIDized or Apple Loops file into a DAW, the software reads its tempo tag and stretches the loop to the session tempo; exporting a loop with correct tempo metadata lets others use it the same way.", "category": "Metadata", "related_terms": ["Warping", "Time-stretching", "BPM", "ACIDized WAV", "Apple Loops", "REX file"], "common_mistakes": ["Assuming every WAV carries tempo data, when a plain WAV does not and will not auto-stretch.", "Trusting an incorrect embedded tempo, such as half- or double-time, and getting timing errors.", "Losing tempo metadata by converting or re-exporting through software that strips it.", "Confusing file tempo metadata with the project tempo, since changing one does not change the other."], "scenario_contexts": ["Dropping a loop-library file into a session and having it match tempo automatically.", "Exporting a construction-kit loop with an embedded BPM tag for other producers.", "Diagnosing why an imported loop plays at the wrong speed because its tempo tag is wrong or missing."]}, "52708dac-3239-4c30-9122-6a5ca2b1ac3f": {"definition": "A cue, meaning a marker, count or signal, indicating the point at which a fill (a short transitional passage that bridges two sections of music) should be played or launched. It coordinates performers, or triggers fill/transition material at the right moment, in an arrangement or performance.", "plain_english": "It is a signal that tells you exactly when to play a fill, which is a short burst of music that connects one part of a song to the next. Like a nod from the band leader, it says to play the fill now.", "purpose_function": "It keeps everyone lined up so a fill lands on the right beat going into a new section, whether the cue comes from a person, a click, a marker, or an arranger keyboard's indicator.", "practical_application": "A performer or playback operator watches or listens for the fill cue, such as a hand signal, a session marker or a count, and plays or launches the fill so it resolves cleanly into the next section.", "category": "Arrangement", "related_terms": ["Fill trigger", "Fill", "Cue", "Arrangement", "Transition", "Click track"], "common_mistakes": ["Missing the cue and starting the fill on the wrong beat, so it does not resolve into the next section.", "Confusing the fill cue, which is when to play it, with the fill trigger, which is the control that fires it.", "Playing a fill so long it overruns the cue point and steps on the downbeat."], "scenario_contexts": ["A band leader signalling the drummer to play a fill into the chorus.", "A marker in a DAW session cueing where a transitional fill drops in.", "An arranger keyboard's on-screen indicator showing when a fill will play."]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"4e2c9168-6026-4bdb-a19d-13445ee9a86c": {"definition": "A control, such as a button, pad, MIDI note or marker, that launches a fill: a short transitional passage, often drums, between sections. Examples include the Fill In button on drum machines and arranger keyboards, which fires a fill variation, and a sampler pad assigned to a drum-fill sample.", "plain_english": "It is a button, pad, or note that fires off a fill, which is a short drum or music burst that leads into the next part of a song. Press it and the fill plays, like hitting a play-the-fill-now button.", "purpose_function": "It lets a player or the software launch a ready-made fill on demand, adding a transition without having to perform it note by note.", "practical_application": "A technician assigns a fill to a pad or the Fill In button, then triggers it at the end of a phrase so the fill plays and leads into the next section or pattern.", "category": "Arrangement", "related_terms": ["Fill Cue", "Fill", "Drum trigger", "Sampler pad", "Arranger keyboard", "Pattern variation"], "common_mistakes": ["Triggering the fill too early or late so it does not line up with the phrase.", "Assuming every pad or button is a fill trigger when it is mapped to something else.", "Forgetting that an auto-fill may also fire when changing pattern or variation, causing a doubled fill."], "scenario_contexts": ["Pressing a drum machine's Fill In button to lead into a new section.", "Hitting a sampler pad to fire a recorded drum fill during a live set.", "Mapping a MIDI note to launch a fill clip at a transition in a DAW."]}, "3027300d-c3b7-4bbb-a058-be540ca78426": {"definition": "The process of mixing recorded musical score for film and television: balancing orchestral sections, instruments and recorded stems into a coherent music mix, and delivering that music, often as stems, to the re-recording (dub) stage, where it is balanced against dialogue and sound effects. It emphasizes clarity and dynamics that leave room for dialogue and support the picture.", "plain_english": "It is mixing the music written for a movie or TV show so all the instruments sit together well. The finished music is then handed over. It gets blended with the dialogue and sound effects for the final soundtrack.", "purpose_function": "It shapes the score to support the story and emotion of a scene while leaving space, in level and frequency, for dialogue and effects at the final mix.", "practical_application": "A score mixer balances the orchestra and overdubs, prints music stems such as strings, brass, percussion and synths, and delivers them so the re-recording mixer can fit the music around dialogue and effects.", "category": "Post-Production", "related_terms": ["Stems", "Re-recording mix", "Dialogue", "Orchestral balance", "Scoring stage", "Music cue"], "common_mistakes": ["Mixing the score too dense or bright so it fights dialogue at the dub stage.", "Not delivering separated stems, leaving the re-recording mixer no control over the music balance.", "Over-compressing the music and losing the dynamics a scene needs.", "Ignoring the picture and mixing the music as a standalone album track."], "scenario_contexts": ["Balancing a recorded orchestra into a music mix for a film cue.", "Delivering music stems to a re-recording mixer for the final soundtrack.", "Adjusting a score mix so it sits under dialogue in a dramatic scene."]}, "e94f4160-4984-490e-b24c-385093a8bb92": {"definition": "In film and television post-production, the final dub (also called the final mix or re-recording mix) is the last mixing pass in which the dialogue, music, and sound-effects premixes are balanced together and printed to the finished soundtrack for delivery.", "plain_english": "The final dub is the last step where all of a show's sound is mixed together. The voices, music, and sound effects are balanced into one finished soundtrack.", "purpose_function": "It combines and balances every separate sound element into a single approved soundtrack, ensuring clear dialogue, musical balance, and consistent loudness before the program is delivered.", "practical_application": "A re-recording mixer runs the final dub on a mix stage, adjusting premix levels and printing the master soundtrack that will be married to picture for broadcast or release.", "category": "Post-Production Mixing", "related_terms": ["Final mix session", "Final mix stage", "Stems", "Premix", "Mastering"], "common_mistakes": ["Confusing the final dub with mastering, which is a separate later stage", "Assuming the final dub can fix problems that are better solved in the premixes", "Not checking dialogue intelligibility against loudness targets during the dub"], "scenario_contexts": ["Balancing dialogue, music, and effects premixes into the finished soundtrack for a TV episode", "Printing a delivery master after client approval on a film mix stage", "Meeting broadcast loudness specs during the final mix of a documentary"]}, "55a73748-5fc1-4b27-bf47-ae2b2111d1f4": {"definition": "The final mix session is the DAW project or console setup in which the approved, definitive mix of a song or program is created, balanced, and rendered - the last mix before mastering and delivery.", "plain_english": "This is the project file where the final version of the mix is made. It is the last mixing step before the song goes to mastering.", "purpose_function": "It holds every track, level, effect, and automation move needed to produce the finished sign-off mix, so the result can be recalled and rendered exactly.", "practical_application": "A mix engineer opens the final mix session to make last balance tweaks, then bounces the stereo mix and stems for the mastering engineer.", "category": "Mixing Workflow", "related_terms": ["Final mix stage", "Final dub", "Stems", "Mixdown", "Mastering"], "common_mistakes": ["Not saving a clearly labeled version, so the final mix session gets confused with earlier drafts", "Deleting unused tracks or plugins that may still be needed for recall", "Forgetting to render matching stems alongside the stereo mix"], "scenario_contexts": ["Making final client-requested tweaks before bouncing the mix", "Rendering the stereo mix and stems for mastering", "Archiving the approved session for future recalls or revisions"]}, "3c70b70d-d3bb-45b8-9c6e-f463131728fb": {"definition": "The final mix stage is the concluding phase of the mixing workflow, in which the balances, processing, and automation are completed and the mix is finalized and approved for delivery to mastering.", "plain_english": "This is the last part of the mixing process. Here the mix is finished, checked, and approved before it moves on to mastering.", "purpose_function": "It exists to lock in the finished balance and creative decisions, producing an approved mix that mastering and delivery can rely on.", "practical_application": "At the final mix stage, the engineer checks the mix on several playback systems, makes last adjustments, and gets client sign-off before rendering.", "category": "Mixing Workflow", "related_terms": ["Final mix session", "Final dub", "Mixdown", "Mastering", "Reference monitoring"], "common_mistakes": ["Rushing the final mix stage without checking the mix on multiple systems", "Making big arrangement changes this late instead of during earlier mixing", "Confusing this final phase with mastering"], "scenario_contexts": ["Checking a nearly finished mix on studio monitors, headphones, and a car system", "Getting client approval before rendering the final files", "Preparing an approved mix to hand off to mastering"]}, "29211841-fef3-4d66-8d29-000272e0b0dd": {"definition": "The complete set of finished deliverables handed off at the end of a production, typically including the approved final mix and master, alternate versions and stems, session or project files, and accompanying documentation such as track sheets, metadata, and cue sheets.", "plain_english": "It is the full bundle of finished files you hand over when a project is done. It holds the final song plus extras like stems, notes, and the session, so others can use or revisit the work later.", "purpose_function": "It gathers everything a client, label, or post house needs to release, archive, or revise the project, so nothing essential is missing after the team moves on.", "practical_application": "At project close, an engineer bounces the master and stems, exports session files, writes up track and metadata sheets, and delivers them together as one organized, labeled package.", "category": "Deliverables", "related_terms": ["Final mix session", "Music-only stem", "Final release authorization", "Engineering sign-off", "Nearfield printmaster"], "common_mistakes": ["Delivering only the final master and forgetting stems, alternate mixes, or session files the client later needs", "Sending files with vague names and no track sheet or metadata, causing confusion downstream", "Not confirming the client's required formats, sample rates, and bit depths before packaging"], "scenario_contexts": ["Handing a finished album's masters, stems, and documentation to a record label for release", "Delivering a film mix package to a post-production house for the final conform", "Archiving a completed project so it can be reopened and revised years later"]}, "cddaf31d-5989-471b-b443-8363dbfcd302": {"definition": "The formal approval that a finished master is cleared for release or distribution, given after quality control and client or label sign-off; it marks the point at which no further changes will be made and the audio can be manufactured, uploaded, or published.", "plain_english": "It is the final 'yes, this is done, send it out' step. Once the client signs off and the checks pass, the song is locked and ready to release.", "purpose_function": "It creates a clear, documented go/no-go point so files are not released before they are checked and approved, preventing costly recalls of wrong or faulty audio.", "practical_application": "Before a distributor upload or disc replication, the engineer confirms QC has passed and obtains written client approval, then treats the master as final and locked.", "category": "Workflow", "related_terms": ["Engineering sign-off", "Final production package", "Distortion validation", "Final mix stage", "Dynamic-range validation"], "common_mistakes": ["Releasing or sending files to manufacturing before written approval, then discovering an error too late", "Skipping a final QC listen because the deadline is tight", "Authorizing release from an unchecked or wrong file version, so the released audio differs from the approved one"], "scenario_contexts": ["Approving a master for upload to streaming platforms after client sign-off", "Clearing a mastered album for CD or vinyl manufacturing", "Signing off a broadcast mix as ready for air"]}, "204309c6-53bb-45bc-a01b-cebd2b4f0c88": {"definition": "Fine pitch is a small-resolution tuning adjustment, usually calibrated in cents (hundredths of a semitone), used to detune or precisely align the pitch of an oscillator, sample, or track; it complements a coarse control that shifts pitch in whole semitones.", "plain_english": "Fine pitch is a control that changes pitch by very small amounts. It lets you nudge a sound a little sharp or flat so it is tuned just right. One hundred of these tiny steps, called cents, make up one half step.", "purpose_function": "It provides precise control over pitch beyond whole semitones, letting engineers match tuning between layers, add subtle detuning for a thicker sound, or correct small tuning errors.", "practical_application": "A producer uses a fine pitch or fine-tune knob to detune a second oscillator a few cents for a wider sound, or to nudge a sampled note into tune with the track.", "category": "Tuning Control", "related_terms": ["Coarse tune", "Cents", "Detune", "Transpose", "Pitch correction"], "common_mistakes": ["Confusing fine pitch (cents) with coarse pitch (whole semitones)", "Over-detuning until layers sound out of tune instead of wide", "Forgetting that 100 cents equals one semitone when dialing in values"], "scenario_contexts": ["Detuning oscillators a few cents to thicken a synth pad", "Matching a sampled instrument's tuning to a song's reference pitch", "Making small tuning corrections on a doubled vocal or guitar layer"]}, "4381208f-433a-4a29-b1a0-1d895453417c": {"definition": "In REAPER, a fixed item lane is one of multiple horizontal lanes within a single track (up to 128) used to record, layer, edit, and comp media items; the lanes behave like 'tracks within a track,' and comping copies the chosen sections into new items while leaving the source lanes unmodified.", "plain_english": "In REAPER, fixed item lanes are like stacked rows inside one track. You can record many takes on separate rows. Then you pick the best parts from each to build one great take. The original recordings stay unchanged.", "purpose_function": "They keep multiple takes and layers organized within one track so performances can be compared, edited, and comped non-destructively instead of being spread across many separate tracks.", "practical_application": "A tracking engineer records several vocal passes into separate lanes, then swipes across the best phrases to comp a final take into a new lane.", "category": "DAW Editing", "related_terms": ["Comping", "Take", "Swipe comping", "Punch-in", "Non-destructive editing"], "common_mistakes": ["Confusing fixed item lanes with REAPER's older takes system", "Thinking comping alters the source lanes when it actually copies into new items", "Recording all passes into one lane so they overwrite instead of stacking"], "scenario_contexts": ["Recording multiple vocal or solo passes for later comping", "Layering doubled parts on separate lanes within one track", "Building a composite take by swiping across lanes"]}, "52451896-deb6-4305-9acb-94110e558703": {"definition": "Flam programming is the sequencing of a flam - a drum rudiment of two nearly simultaneous strokes, a soft grace note placed just before the main accented note - by entering two hits a few milliseconds apart (typically with the grace note at lower velocity) in a drum machine or DAW sequencer.", "plain_english": "A flam is two drum hits played almost together, a quiet one just before a louder one, making a fatter sound. Flam programming means placing those two hits slightly apart in a drum sequencer to copy that sound.", "purpose_function": "It recreates the natural thickness and human feel of an acoustic flam in programmed drums, adding weight and realism to snare or tom hits.", "practical_application": "A beatmaker duplicates a snare hit a few milliseconds early at a lower velocity to program a flam, adjusting the gap and level until it feels natural.", "category": "Drum Programming", "related_terms": ["Velocity", "Quantization", "Grace note", "Ghost note", "Drum sequencer"], "common_mistakes": ["Spacing the two hits too far apart, so the flam turns into an audible double hit", "Giving both hits equal velocity instead of a softer grace note", "Quantizing the flam so tightly that the offset disappears"], "scenario_contexts": ["Programming a realistic snare flam in a drum machine pattern", "Adding flams to toms in a programmed drum fill", "Humanizing sequenced drums with flams and velocity changes"]}, "99b43f74-91fb-487b-9fad-ef9082dbbfb0": {"definition": "In Ableton Live, Flatten is a command that permanently replaces a frozen track's original clips and device chain with the rendered ('frozen') audio, committing all processing to a new audio clip and removing the source devices to save CPU.", "plain_english": "In Ableton Live, Flatten turns a track into plain audio for good. It takes a frozen track and swaps its instruments and effects for a recording of them. That frees up computer power.", "purpose_function": "It permanently commits a track's instruments, effects, and warping to audio, reducing CPU load and simplifying a project, at the cost of no longer being able to edit the original devices.", "practical_application": "After freezing a CPU-heavy instrument track, an engineer flattens it to lock in the sound and free up processing power for the rest of the mix.", "category": "DAW Editing", "related_terms": ["Freeze track", "Consolidate", "Mixdown", "Warp", "CPU load"], "common_mistakes": ["Flattening a track before the sound is final, since it removes the original devices and is not reversible", "Confusing Flatten with Freeze, because Freeze is reversible while Flatten is permanent", "Flattening a track that may still need editing, losing the instrument and effect settings"], "scenario_contexts": ["Committing a CPU-heavy software instrument to audio to free processing power", "Locking in a finished synth part before sharing the project", "Simplifying a busy Live set by flattening frozen tracks before a performance"]}, "4b8940c0-aadd-4578-b342-ba0a6e1645e7": {"definition": "In Logic Pro, a flex marker is an editable anchor point placed on an audio waveform, usually at a detected transient, that you drag to time-stretch or compress the surrounding audio without cutting or crossfading the region.", "plain_english": "A flex marker is a handle you pin onto a sound wave. When you drag it, the nearby audio stretches or squeezes so a note lands on the beat. It works a bit like pulling a rubber band.", "purpose_function": "It gives a precise, non-destructive way to move a single beat or note in time, so audio can be tightened to the grid or lined up with other tracks.", "practical_application": "A technician clicks a transient to drop a flex marker, then drags it onto the nearest grid line to fix a late snare hit or align a doubled guitar part.", "category": "Flex Editing", "related_terms": ["Flex Time", "Flex mode", "Flex Pitch", "Transient", "Quantization", "Time stretching"], "common_mistakes": ["Confusing flex markers with arrangement markers or region edit points; flex markers only exist inside Flex-enabled audio.", "Placing too many flex markers close together, which creates audible stretching artifacts.", "Forgetting to enable Flex and choose a Flex mode first, so a marker cannot be added."], "scenario_contexts": ["Tightening a slightly rushed vocal syllable to the beat.", "Aligning a live drum take to the project tempo grid.", "Matching a double-tracked rhythm guitar to the original take."]}, "6ba9e234-e9df-4acb-85f1-2eb4b482fe0b": {"definition": "In Logic Pro, Flex mode is the per-track setting, chosen from the Flex Mode pop-up menu, that selects the algorithm used to analyze and edit audio timing or pitch, either Flex Pitch or one of the Flex Time algorithms (Slicing, Rhythmic, Monophonic, Polyphonic, Speed, or Tempophone).", "plain_english": "Flex mode is the setting that tells Logic how to stretch or tune a track's audio. You pick the type that matches the sound, like a drum setting for drums or a single-voice setting for a solo vocal.", "purpose_function": "Different audio, such as drums, single notes, or full chords, needs different processing, so the Flex mode picks the right algorithm to get clean results with the fewest artifacts.", "practical_application": "Before editing timing, a technician sets Monophonic for a solo bass line or Slicing for a drum loop, choosing the mode that best fits the material.", "category": "Flex Editing", "related_terms": ["Flex Time", "Flex Pitch", "Flex marker", "Time stretching", "Transient", "Phase vocoder"], "common_mistakes": ["Leaving a default mode on material it does not suit instead of choosing a mode matched to the source.", "Assuming every Flex mode preserves pitch; Speed and Tempophone deliberately change pitch and character.", "Using the processor-heavy Polyphonic mode on every track and overloading the CPU."], "scenario_contexts": ["Choosing Slicing before quantizing a drum loop.", "Selecting Monophonic to correct the timing of a solo vocal.", "Using Polyphonic mode to stretch a full chordal guitar part."]}, "f4bd13cb-6d11-4d0a-a254-232790b0ded0": {"definition": "Flex Pitch is Logic Pro's pitch-editing Flex mode that analyzes monophonic audio, displays each detected note as an editable block in the Audio Track Editor or Piano Roll, and lets you correct or reshape pitch, timing, and level non-destructively.", "plain_english": "Flex Pitch lets you retune recorded audio, like fixing an out-of-tune vocal. It shows each note as a block you drag up or down to the right pitch, much like moving notes on a piano roll.", "purpose_function": "It exists to correct tuning and shape performance details such as vibrato, drift, and level directly on the recorded audio, without re-recording or bouncing to a separate plug-in.", "practical_application": "A technician turns on Flex Pitch for a lead vocal, then drags flat notes up to pitch and reduces excess vibrato before mixing.", "category": "Flex Editing", "related_terms": ["Flex Pitch note", "Flex mode", "Pitch correction", "Formant", "Vibrato", "Flex Time"], "common_mistakes": ["Dragging every note to perfect pitch, producing an unnatural, over-tuned sound.", "Expecting Flex Pitch to cleanly separate notes in dense chords or polyphonic material.", "Confusing Flex Pitch (pitch editing) with Flex Time (timing editing)."], "scenario_contexts": ["Tuning a lead vocal take before a mix.", "Fixing a single sour note in an otherwise good bass line.", "Reducing heavy vibrato at the end of a sustained vocal note."]}, "be2ce275-9f17-4a58-b872-65dd87f8c72a": {"definition": "A Flex Pitch note is a single detected note-event in Logic Pro's Flex Pitch view, shown as a block whose hotspots let you edit its pitch, fine pitch, gain, vibrato, pitch drift at the start and end, and formant, along with its time position and length.", "plain_english": "A Flex Pitch note is one note that Logic finds in your audio and shows as a small block. Its corners and edges are handles you grab to change the note's pitch, loudness, or wobble.", "purpose_function": "It breaks a continuous recording into individual, editable pieces so you can adjust one note's tuning or expression without affecting the notes around it.", "practical_application": "A technician clicks a single Flex Pitch note, drags its center to correct pitch, and uses the lower-corner hotspots to trim gain or shift the formant so the fix sounds natural.", "category": "Flex Editing", "related_terms": ["Flex Pitch", "Formant", "Fine pitch", "Vibrato", "Gain", "Pitch drift"], "common_mistakes": ["Grabbing the wrong hotspot and changing gain or formant when only pitch was intended.", "Merging or splitting notes incorrectly, so Logic mis-tracks the pitch.", "Ignoring the fine-pitch hotspot and leaving small tuning errors within a corrected note."], "scenario_contexts": ["Nudging one flat syllable up to pitch in a vocal line.", "Lowering the gain of a single note that jumps out in level.", "Shifting the formant of one note to keep a pitch-corrected vocal natural."]}, "6201a8fd-99d7-4b6f-a0f9-30528bf2e6f3": {"definition": "Flex Time is Logic Pro's set of Flex modes for editing the timing of audio, moving, quantizing, stretching, or compressing individual beats and notes within a region using flex markers and transient analysis, without cutting or crossfading.", "plain_english": "Flex Time lets you move the timing of recorded audio, like nudging a late drum hit onto the beat. It stretches or squeezes the sound instead of cutting it, so the edit stays smooth.", "purpose_function": "It exists to correct or quantize the timing of recorded audio directly on the waveform, saving the manual slicing and crossfading that older editing required.", "practical_application": "A technician enables a Flex Time mode, then quantizes a drum take or drags flex markers to tighten a loose bass performance to the grid.", "category": "Flex Editing", "related_terms": ["Flex marker", "Flex mode", "Flex Pitch", "Quantization", "Transient", "Time stretching"], "common_mistakes": ["Applying heavy time correction that creates audible stretching artifacts.", "Choosing the wrong Flex mode for the material, causing glitches.", "Confusing Flex Time (timing) with Flex Pitch (tuning)."], "scenario_contexts": ["Quantizing a live drum performance to the tempo grid.", "Tightening a bass line that drifts behind the beat.", "Aligning a doubled rhythm part to the main take."]}, "b66fd8cb-8c62-4bcd-989a-51b2d713aeb7": {"definition": "A fold track, commonly called a folder track, is a container track in a DAW arrangement that holds a group of other tracks and can be folded (collapsed) or unfolded (expanded) to hide or reveal them; its header often mirrors mute, solo, and record controls to the enclosed tracks.", "plain_english": "A fold track is a folder in your song's track list that holds a group of related tracks. You can fold it shut to hide those tracks and tidy the screen, like closing a folder on your computer.", "purpose_function": "It exists to organize large projects, letting you collapse related tracks such as all drums or all vocals into one row and often mute, solo, or move them together.", "practical_application": "A technician packs all the drum tracks into a fold track, collapses it to clean up the arrange window, and can solo the whole group with one click.", "category": "Track Organization", "related_terms": ["Folder Stack", "Folder routing", "Track group", "Bus", "Summing stack", "Subgroup"], "common_mistakes": ["Assuming folding a track combines its audio; folding only hides tracks visually and does not sum them.", "Confusing a plain fold or folder track (organization) with a summing group that also routes audio.", "Losing track of parts by forgetting they are hidden inside a collapsed fold track."], "scenario_contexts": ["Collapsing all drum tracks into one row to reduce clutter.", "Muting an entire instrument section by muting its folder track.", "Grouping background vocals so they can be moved together in the timeline."]}, "aa0eb7ab-aff0-48d6-85c1-0f15fead17f6": {"definition": "A fold-down master is a master or monitor output that downmixes (folds down) a multichannel program, such as a 5.1 surround or immersive mix, to fewer channels, typically stereo or mono, using set summing coefficients so the mix can be checked for compatibility on smaller playback systems.", "plain_english": "A fold-down master combines a surround mix down into stereo or a single mono speaker. It lets you check that your big multi-speaker mix still sounds right for listeners who only have two speakers or one.", "purpose_function": "It exists so engineers can confirm that a surround or immersive mix stays balanced and free of level or phase problems when a listener's system collapses it to stereo or mono.", "practical_application": "A post engineer routes the surround bus to a fold-down master and switches monitoring to the stereo or mono fold-down to confirm dialogue and balance survive the downmix.", "category": "Monitoring & Downmix", "related_terms": ["Downmix", "Surround", "Mono compatibility", "Master bus", "Stereo", "Phase"], "common_mistakes": ["Assuming a surround mix folds down cleanly without checking; center and surround levels can overpower or cancel in stereo or mono.", "Ignoring phase problems that only appear when channels sum in the mono fold-down.", "Confusing the fold-down (a derived stereo or mono check) with the actual multichannel master."], "scenario_contexts": ["Checking a 5.1 film mix for stereo compatibility before delivery.", "Verifying dialogue stays clear in a mono fold-down for broadcast.", "Testing whether surround effects cause cancellation when summed to mono."]}, "440d6136-97f2-4979-9598-cc78574d8eed": {"definition": "Folder routing is the practice of sending several tracks through a folder, group, or summing track so their combined signal shares one set of processing, level, and output controls, letting an engineer treat a group of related sources as a single mix element.", "plain_english": "Folder routing sends a group of tracks, say all the drums, into one folder or group channel. Then you can control their volume and add effects to the whole group at once, instead of one track at a time.", "purpose_function": "It exists to simplify mixing by combining related tracks into a subgroup, so shared processing and level are applied once to the whole group and the balance is easier to manage.", "practical_application": "A technician routes every drum track's output to a drum folder or group, then compresses and fades the entire kit from that single channel.", "category": "Signal Routing", "related_terms": ["Folder Stack", "Summing stack", "Subgroup", "Bus", "Aux send", "Fold track"], "common_mistakes": ["Confusing an organization-only folder (no audio summing) with a routing folder or group that actually combines signals.", "Routing tracks to a group but also leaving them going straight to the main output, doubling the signal.", "Adding heavy processing on the folder without noticing it stacks with processing already on the individual tracks."], "scenario_contexts": ["Bussing all drum mics to one group for shared compression.", "Grouping backing vocals to ride their overall level with one fader.", "Sending a synth section to a folder for a single reverb and EQ pass."]}, "dd606d69-178e-444d-90eb-fe9e6ac21075": {"definition": "In Logic Pro, a Folder Stack is a type of Track Stack that groups selected tracks under one main folder track purely for organization; the subtracks keep their own individual channel-strip outputs, so folding the stack hides or shows them without changing how their audio is routed, unlike a Summing Stack, which routes the subtracks to a shared aux or bus.", "plain_english": "A Folder Stack is a Logic feature that tucks several tracks under one header to keep things tidy. It only hides or shows the tracks; it does not combine their sound, unlike a Summing Stack, which sends them all to one channel.", "purpose_function": "It exists to declutter the track list by collapsing related tracks into one row while leaving each track's routing and output untouched.", "practical_application": "A technician selects a group of tracks and creates a Folder Stack to collapse them, keeping the arrange window clean while every track still feeds its own output.", "category": "Track Organization", "related_terms": ["Summing stack", "Track Stack", "Fold track", "Folder routing", "Subgroup", "Channel strip"], "common_mistakes": ["Expecting a Folder Stack to sum or bus its tracks; that is a Summing Stack, while a Folder Stack is organizational only.", "Adding plug-ins to a Folder Stack's main track expecting them to process the audio, when that track has no audio path.", "Confusing the two stack types when parallel processing is needed."], "scenario_contexts": ["Collapsing all microphone tracks of a drum kit for a tidy arrangement.", "Organizing layered synth tracks under one header without changing routing.", "Grouping comped vocal takes visually while keeping separate outputs."]}, "4900cbbc-e617-4101-be84-55915b618358": {"definition": "Foley performed and recorded specifically to supply the incidental human-made sounds — footsteps, cloth movement, prop handling — that exist only on the production dialogue track, so they remain present in the effects/M&E stem once dialogue is removed. It fills the gaps in effects coverage needed for a complete music-and-effects deliverable.", "plain_english": "Extra Foley made to cover small everyday sounds, like footsteps or rustling clothes. Those sounds were only picked up along with the actors' voices. Foley fill adds them back in. That way they stay in the film when the voices are taken out for a dubbed version.", "purpose_function": "It makes sure the music-and-effects (M&E) stem carries every incidental sound, so a film can be dubbed into another language without losing footsteps, movement, or prop noise.", "practical_application": "A Foley editor spots the dialogue track for sounds that would vanish if dialogue were muted, then records Foley fill to cover them for the M&E deliverable.", "category": "Foley & Post", "related_terms": ["Foley premix", "Foley stem", "M&E stem", "Foreign-language mix", "Dialogue stem", "Effects stem"], "common_mistakes": ["Assuming production-recorded footsteps and moves are safe when they live only on the dialogue track and will vanish in the dub.", "Recording Foley fill with the wrong perspective or room so it does not match the picture.", "Covering only obvious footsteps and missing quieter prop and cloth sounds needed for a full M&E."], "scenario_contexts": ["Filling in movement sounds for a dialogue-heavy scene so the M&E stem stays complete.", "Preparing a title for foreign dubbing where every incidental sound must exist off the dialogue track."]}, "8e13b16a-ea34-445e-b5f6-fb0138bea843": {"definition": "An intermediate mix that combines and balances the many individual Foley recordings — footsteps, movement, and prop sounds — into a smaller set of pre-balanced tracks or a submix, ready to be brought into the final re-recording mix.", "plain_english": "A rough mix of just the Foley sounds. All the footsteps, clothing, and prop noises are balanced together first, so they are easier to handle in the final mix.", "purpose_function": "It streamlines the final re-recording mix by pre-balancing dozens of Foley tracks down to a tidy, consistent set before dialogue, music, and effects are combined.", "practical_application": "A Foley mixer premixes the recorded Foley to even out footstep levels and perspective, delivering a clean premix that the re-recording mixer folds into the final.", "category": "Foley & Post", "related_terms": ["Foley stem", "Foley fill", "Premix", "Re-recording mix", "Effects stem", "M&E stem"], "common_mistakes": ["Premixing so aggressively that the re-recording mixer loses control over individual sounds.", "Baking in heavy processing that cannot be undone in the final mix.", "Ignoring perspective and space so the premix does not match the picture."], "scenario_contexts": ["Balancing a scene's footsteps and cloth passes into one premix before the final dub.", "Delivering Foley premixes to the re-recording stage for a feature's final mix."]}, "4c22c483-748d-45ef-ab12-ea864e754bed": {"definition": "A stem — an isolated submix printed as part of the final mix deliverables — that contains only the mixed Foley elements, kept separate from dialogue, music, and other effects so it can be recombined or replaced later.", "plain_english": "A separate track that holds only the finished Foley sounds. Keeping it on its own means it can be reused or swapped without touching the music or dialogue.", "purpose_function": "It preserves the Foley as an independent layer of the final mix, supporting music-and-effects versions, foreign dubs, and future re-mixes or format changes.", "practical_application": "At the end of a mix, the Foley is printed to its own stem alongside dialogue, music, and effects stems so the film can be re-versioned for TV or overseas release.", "category": "Foley & Post", "related_terms": ["Stem", "Foley premix", "Effects stem", "Dialogue stem", "M&E stem", "Foley-only stem"], "common_mistakes": ["Confusing a stem with the full final mix — a stem is only one isolated layer.", "Merging Foley into the general effects stem, which breaks M&E and dubbing versions.", "Failing to keep stem levels matched so they sum back to the approved final mix."], "scenario_contexts": ["Printing a separate Foley stem so a title can be conformed for airline and broadcast versions.", "Delivering discrete Foley stems for an M&E package used in foreign-language dubbing."]}, "2e3bf00a-159e-493c-8c92-46564676efad": {"definition": "A deliverable stem carrying exclusively Foley content, separated from hard effects and backgrounds, so Foley can be handled on its own within a music-and-effects package or re-versioning workflow.", "plain_english": "A stem with nothing but Foley on it, no other effects mixed in. Keeping Foley by itself makes it easy to reuse or replace when a film is prepared for another language or format.", "purpose_function": "It isolates Foley from other sound-effects layers so localization and re-versioning teams can adjust or rebuild Foley without disturbing designed effects or backgrounds.", "practical_application": "A mixer delivers a Foley-only stem within the M&E package so a dubbing studio can rebalance footsteps and movement independently of the effects stem.", "category": "Foley & Post", "related_terms": ["Foley stem", "Effects stem", "M&E stem", "Stem", "Foley premix", "Foley fill"], "common_mistakes": ["Bundling Foley with hard effects, which defeats the point of a Foley-only stem.", "Assuming a single combined effects stem is enough for full M&E and dubbing needs.", "Leaving level offsets that stop the stems summing to the approved mix."], "scenario_contexts": ["Supplying a Foley-only stem so a localization vendor can re-time footsteps for a dubbed cut.", "Including a Foley-only stem in deliverables for a streaming platform's international versions."]}, "cde569a5-603a-4237-a0d4-f840b8517d59": {"definition": "A mixing approach in which level, automation, panning, and effects evolve section by section to support the musical arrangement, foregrounding whichever element is most important at each moment rather than holding a single static balance across the whole song.", "plain_english": "Changing the mix as the song moves along so the right part is always in front. In the verse you might feature the voice, then let the guitars grow in the chorus.", "purpose_function": "It keeps a mix clear and engaging by making sure the most important part of each section is heard, matching the emotional shape the arrangement was written to create.", "practical_application": "An engineer writes fader and effect automation across the timeline, pushing lead vocals up in the chorus or pulling a busy pad down under a solo so each section reads clearly.", "category": "Mixing Technique", "related_terms": ["Automation", "Fader ride", "Arrangement", "Static mix", "Dynamic mix", "Focal point"], "common_mistakes": ["Setting one static balance for the whole song and never adjusting it section to section.", "Automating so hard that levels jump unnaturally and distract the listener.", "Featuring every element at once so nothing actually stands out."], "scenario_contexts": ["Riding the lead vocal up a decibel in the chorus and back down in the verse.", "Bringing a synth pad forward during an instrumental break, then tucking it under the returning vocal."]}, "6dc664f0-6717-4f7a-a51b-5c4a6b1bb3e9": {"definition": "A version of a program's final mix prepared for release in another language, typically built from the music-and-effects (M&E) stems with the original dialogue removed so that translated, re-recorded dialogue can be added in its place.", "plain_english": "A copy of the film's sound made ready for another language. The original talking is taken out, but the music and sound effects stay, so new voices in the new language can be dropped in.", "purpose_function": "It lets a film or show be released internationally by allowing dubbed dialogue to replace the original while keeping all music and effects exactly as mixed.", "practical_application": "A re-recording mixer delivers M&E stems and a foreign-language mix template so a dubbing studio can add localized dialogue without rebuilding the effects and music.", "category": "Post Deliverables", "related_terms": ["M&E stem", "Dialogue stem", "Foley fill", "Foley stem", "Re-recording mix", "Effects stem"], "common_mistakes": ["Leaving incidental sounds only on the dialogue track, so they disappear in the dubbed version.", "Assuming a stereo print master can be dubbed instead of delivering proper M&E stems.", "Forgetting narration or on-screen source cues that the foreign version still needs to reproduce."], "scenario_contexts": ["Preparing M&E stems so a series can be dubbed into Spanish and German for international streaming.", "Delivering a fully filled M&E mix to a localization vendor for theatrical release abroad."]}, "0daf7485-6c92-46cd-b35a-fc58b42ab14e": {"definition": "In flexible pitch-editing tools, a parameter that raises or lowers a sound's formants — the fixed resonant peaks that give a voice or instrument its timbral character — independently of pitch, altering the perceived vocal-tract size or tone without changing the note.", "plain_english": "A control that changes the size or character of a voice without changing the note it sings. Push it up and a singer sounds smaller or brighter; pull it down and they sound bigger or deeper.", "purpose_function": "It lets an editor reshape timbre after pitch changes — keeping a pitch-shifted voice natural, or deliberately making it sound larger, smaller, or more like a different singer.", "practical_application": "When tuning a vocal with Flex Pitch or VariAudio, an engineer nudges the formant shift to undo the thin, chipmunk sound that large pitch moves cause, or to thicken a backing vocal.", "category": "Pitch Editing", "related_terms": ["Flex Pitch", "VariAudio", "Pitch correction", "Formant", "Pitch shift", "Time stretch"], "common_mistakes": ["Confusing formant shift with pitch shift — formants change tone, not the note.", "Pushing formants so far that the voice sounds robotic or unnatural.", "Forgetting that large pitch edits usually need a matching formant tweak to stay believable."], "scenario_contexts": ["Fixing a lead vocal that was pitched up several semitones and now sounds thin and chipmunky.", "Shaping a doubled backing vocal to sit slightly larger or brighter than the lead."]}, "c84c55bc-9da7-4ead-9db1-ed5159a727df": {"definition": "A two-stage DAW process in which a track is first frozen — its instruments and effects temporarily rendered to audio to save CPU — and then flattened, which permanently replaces the track's original devices and MIDI with that rendered audio.", "plain_english": "A two-step trick to save computer power. First you freeze a track, turning its live effects into a plain audio recording. Then you flatten it to make that change permanent.", "purpose_function": "It frees up processing power and locks in a sound: freezing gives temporary relief, while flattening commits the result so heavy plugins or virtual instruments can be removed for good.", "practical_application": "When a project runs low on CPU, an engineer freezes CPU-heavy virtual-instrument tracks, then flattens the ones that are finished to reclaim resources permanently.", "category": "DAW Workflow", "related_terms": ["Freeze audio track", "Bounce in place", "Commit", "CPU load", "Virtual instrument", "Rendering"], "common_mistakes": ["Flattening before a part is final, since it removes the original plugins and MIDI for good.", "Assuming freezing is permanent — it stays reversible until you flatten.", "Forgetting that a flattened track can no longer have its instrument or effect settings changed."], "scenario_contexts": ["Flattening finished software-instrument tracks in a large session to permanently lower CPU use.", "Committing a resource-heavy synth part so the project opens and plays reliably on a slower machine."]}, "2e1cae46-0984-4ad6-90ed-c56311bbbd79": {"definition": "A DAW function that temporarily renders a track's real-time processing — plugins and, for instrument tracks, the virtual instrument — to a hidden audio file so it plays back without ongoing CPU load, while remaining reversible so the original settings can be restored by unfreezing.", "plain_english": "A button that records a track's effects into a temporary file so the computer stops working hard to play them. You can unfreeze it later to change the settings again.", "purpose_function": "It reduces CPU and disk load in large sessions by playing a pre-rendered version of a track, letting a machine handle projects that would otherwise stutter or overload.", "practical_application": "When a mix starts glitching from too many plugins, an engineer freezes the heaviest tracks to keep playback smooth, then unfreezes any track that needs further editing.", "category": "DAW Workflow", "related_terms": ["Freeze and flatten", "Bounce in place", "Commit", "CPU load", "Latency", "Virtual instrument"], "common_mistakes": ["Trying to edit or automate a track's plugins while it is frozen — you must unfreeze first.", "Confusing freezing with bouncing; freezing is reversible and stays on the track.", "Freezing a track with live inputs or sidechains and losing that routing until it is unfrozen."], "scenario_contexts": ["Freezing several software-synth tracks so a laptop can play back a dense arrangement without dropouts.", "Freezing a CPU-hungry, reverb-laden track to free processing for mixing the rest of the session."]}, "e81212e5-6db9-4f7c-9020-29bb11db645c": {"definition": "In Ableton Live, a command that temporarily renders a track's complete output — including all of its instruments and effects — to a hidden audio file, so those devices no longer have to be processed in real time. The track can be unfrozen to resume editing its devices, or flattened to permanently replace them with the rendered audio.", "plain_english": "Freezing a track in Ableton records it to a hidden sound file so the computer no longer has to run its plug-ins live. This frees up computer power, like saving a finished drawing as a photo so you do not have to redraw it each time. You can unfreeze the track later if you want to change the plug-ins again.", "purpose_function": "It lowers real-time CPU load by playing back a pre-rendered audio file instead of continuously processing CPU-heavy instruments and effects, letting a large project keep running smoothly on limited hardware.", "practical_application": "When playback starts to stutter or drop out, an engineer freezes the most demanding tracks to recover CPU headroom, then unfreezes them only if the devices still need editing.", "category": "DAW Workflow", "related_terms": ["Bounce in place", "CPU load", "Rendering", "Virtual instrument", "Flatten", "Latency"], "common_mistakes": ["Trying to adjust a frozen track's instrument or effects without unfreezing first, since the devices are locked while frozen.", "Forgetting that freezing captures the current device settings, so later changes require unfreezing and re-freezing.", "Confusing Freeze (reversible) with Flatten (permanent), and flattening before the edits are final."], "scenario_contexts": ["A dense electronic project with many software synths begins to crackle, so the producer freezes the synth tracks to keep playback stable.", "Preparing a laptop set for a show, a musician freezes CPU-heavy tracks to guarantee reliable playback on stage.", "Before sending a session to a collaborator who lacks the same plug-ins, tracks are frozen so the sound is preserved."]}, "2e975f54-c648-431e-a33b-54310f1efbad": {"definition": "The process of measuring a device's or system's output level across the audible frequency band and comparing it against a target curve or published specification to confirm it responds within an allowed tolerance. It typically uses a calibrated measurement microphone with a dual-channel transfer-function analyzer or a swept/pink-noise test signal.", "plain_english": "This means checking that a speaker or piece of gear plays every pitch — from low bass to high treble — at about the right loudness. You feed it a test sound, measure the result, and compare it to how it should look. It is like checking that every key on a piano sounds at the correct volume.", "purpose_function": "It verifies that a signal chain or loudspeaker reproduces all frequencies evenly, or matches a defined target, catching problems like dips, peaks, or roll-off before they affect the mix or the audience.", "practical_application": "A technician runs a measurement sweep through a PA using a transfer-function analyzer, then adjusts EQ or checks wiring until the measured response matches the intended target within tolerance.", "category": "Measurement", "related_terms": ["Frequency response", "Pink noise", "Transfer function", "Measurement microphone", "Equalization", "Room correction"], "common_mistakes": ["Judging response by ear alone instead of using a calibrated microphone and analyzer.", "Ignoring the effect of the room, so measured dips and peaks are wrongly blamed on the equipment.", "Using an uncalibrated mic and trusting its own colored response as the true system curve."], "scenario_contexts": ["Commissioning a new PA, an engineer validates each loudspeaker's response against the manufacturer's published curve.", "After repairing a mixing-console channel, a tech confirms its frequency response is flat before returning it to service.", "Setting up a monitoring room, an engineer validates the response at the listening position to plan corrective EQ."]}, "bf57e46b-4ae7-430c-8752-9e914822b3af": {"definition": "In film and television post-production, a sound-effects stem that contains every effect element — hard effects, backgrounds/ambiences, and Foley — needed to reproduce the program's complete effects soundtrack, including effects that originally played underneath dialogue. 'Fully filled' means no effect is missing when the dialogue is removed, so the track stands on its own for foreign-language dubbing or reversioning.", "plain_english": "This is a separate track holding all of a show's sound effects, like footsteps, doors, and background noise, with nothing left out. It even includes sounds that were hidden under people talking. That way, when the original voices are removed for another language, the world still sounds complete.", "purpose_function": "It exists so a program can be re-voiced in other languages or re-edited without losing any sound effects, since the effects are delivered separately and completely from the dialogue.", "practical_application": "A post-production mixer builds the fully filled effects track by adding Foley and effects for moments that were masked by dialogue, then checks that it plays convincingly with the dialogue muted.", "category": "Post-Production Deliverable", "related_terms": ["M&E track", "Fully Filled Music-and-Effects Track", "Foley", "Stem", "Dialogue stem", "Backgrounds/Ambience"], "common_mistakes": ["Leaving gaps where effects were originally covered by dialogue, so the track is not truly 'fully filled'.", "Assuming production sound captured under dialogue can substitute for clean, separate Foley and effects.", "Confusing the effects-only track with the combined music-and-effects (M&E) track."], "scenario_contexts": ["A series is sold to an overseas broadcaster who will dub it, requiring a fully filled effects track so no sound is lost.", "During QC, a reviewer mutes the dialogue and finds missing footsteps, sending the effects track back to be fully filled.", "A streaming platform's delivery spec demands separate, fully filled effects for localization."]}, "87f5d26e-95f5-4953-81f1-06ea6be504cd": {"definition": "A composite deliverable stem containing all of a program's music and sound effects but no dialogue, mixed so the full soundtrack can be recreated except for the voices. 'Fully filled' means every effect and music cue is present, including material that originally played under dialogue, so the music-and-effects (M&E) track stands alone when foreign-language dialogue is added.", "plain_english": "This is one track that has all the music and sound effects from a show but none of the talking. 'Fully filled' means nothing is missing, even sounds that were hidden under the voices. A studio in another country can add their own language on top and everything else still sounds right.", "purpose_function": "It lets a program be translated and re-voiced for other markets while keeping the original music and effects intact, which is why broadcasters and streamers require it as a standard deliverable.", "practical_application": "When mixing for delivery, the re-recording mixer creates and checks the fully filled M&E by muting the dialogue stem and confirming that music and effects still cover every moment.", "category": "Post-Production Deliverable", "related_terms": ["Fully Filled Effects Track", "Foley", "Stem", "Dialogue stem", "Re-recording mix", "Deliverables"], "common_mistakes": ["Delivering an M&E with holes where dialogue used to mask effects, failing the 'fully filled' requirement.", "Accidentally leaving dialogue or narration bleeding into the M&E stem.", "Forgetting music cues that were low under dialogue, which leaves silent gaps."], "scenario_contexts": ["A distributor requires a fully filled M&E before licensing a film to non-English territories.", "A dubbing studio uses the M&E to replace the original voices with a new-language cast.", "A network's QC rejects an M&E because effects drop out where the dialogue was removed."]}, "084b08f9-4c9a-44ed-bd67-410e63042611": {"definition": "In Logic Pro's Flex Pitch editor, the Gain 'hotspot' on each detected note (with a matching Gain control in the inspector) that raises or lowers that individual note's level without affecting neighboring notes. It lets an engineer balance the loudness of specific words or syllables within a monophonic audio region during pitch editing.", "plain_english": "In Logic Pro, Flex Pitch shows each sung note as a block you can edit. The gain control lets you make one single note louder or quieter without touching the notes around it. It is like turning up just one word in a vocal line.", "purpose_function": "It provides note-by-note level control so an engineer can even out a performance — lifting weak notes and taming loud ones — right in the pitch editor instead of drawing volume automation.", "practical_application": "While tuning a lead vocal with Flex Pitch, an engineer drags a note's Gain hotspot to bring a buried word forward or pull back an overly loud one before compression.", "category": "Pitch/Audio Editing", "related_terms": ["Flex Pitch", "Pitch correction", "Volume automation", "Gain staging", "Compression", "Comping"], "common_mistakes": ["Confusing the note Gain hotspot with the region's overall gain or the channel fader.", "Boosting a note's gain so far that it distorts or exposes noise, instead of using compression.", "Assuming gain changes also fix pitch, when Gain only affects level and not tuning."], "scenario_contexts": ["Evening out a vocal take where one line was sung too softly, note by note.", "Reducing a single popped or shouted word that jumps out of an otherwise smooth vocal.", "Balancing individual notes of a bass or backing-vocal part during detailed editing."]}, "9f12be77-0c6c-4027-9747-7d461cc251b4": {"definition": "To create a quick, preliminary balance of a multitrack recording — setting basic levels, panning, and perhaps light EQ and effects — without the detailed processing of a final mix. A rough mix captures the song's overall shape early and serves as a reference for the artist, producer, and later mixing.", "plain_english": "A rough mix is a fast, first version of a song where you just balance the levels so everything can be heard. It is not the polished final version, more like a rough sketch before the finished painting. Artists and producers use it to judge the song and share ideas.", "purpose_function": "It gives everyone an early, listenable version of the song to evaluate the arrangement and performances, and it acts as a reference that guides decisions in the final mix.", "practical_application": "During or right after tracking, an engineer quickly balances faders and panning to bounce a rough mix for the band to take home and for the mix engineer to reference later.", "category": "Mix Workflow", "related_terms": ["Rough mix", "Reference mix", "Balance", "Final mix", "Bounce", "Monitor mix"], "common_mistakes": ["Over-processing a rough mix and wasting time that belongs in the final mix stage.", "Committing rough-mix effects or levels permanently instead of keeping them adjustable.", "Ignoring the rough mix as a reference and losing the vibe that first excited the artist."], "scenario_contexts": ["After a tracking session, the engineer bounces a rough mix so the band can listen at home.", "A producer asks for a rough mix to judge whether an arrangement is working before overdubs.", "A mix engineer plays the artist's rough mix as a reference to match the intended feel."]}, "abde7f24-48cb-4a32-93f2-412e6a448e39": {"definition": "The practice of entering very low-velocity notes — most often light snare or hi-hat hits between the main accents — into a programmed MIDI drum pattern to imitate the subtle, near-silent 'ghost notes' a live drummer plays for groove and feel. The notes are deliberately quiet so they add rhythmic texture without competing with the backbeat.", "plain_english": "Ghost notes are the tiny, quiet drum hits a real drummer sneaks in between the loud beats to make a groove feel human. Programming them means adding those soft hits to a computer drum part using low velocity, so it does not sound stiff. It is like faint pencil marks that make a drawing feel alive.", "purpose_function": "It makes programmed drums feel more natural and groovy by restoring the quiet in-between hits that give a real performance its swing and momentum.", "practical_application": "A producer draws extra low-velocity snare hits between the main backbeats in the piano roll, adjusting their velocity until the pattern grooves like a live drummer.", "category": "MIDI Programming", "related_terms": ["Velocity", "MIDI programming", "Quantization", "Humanize", "Groove", "Backbeat"], "common_mistakes": ["Setting ghost-note velocities too high, so they compete with the main backbeat instead of sitting under it.", "Placing ghost notes rigidly on the grid, which keeps the groove stiff instead of loose.", "Adding so many ghost notes that the pattern becomes cluttered and loses its pulse."], "scenario_contexts": ["Programming a funk or R&B drum part where light snare ghost notes drive the groove.", "Making a stiff drum-machine pattern feel human before a session.", "Layering quiet hi-hat and snare hits under a straight beat to add motion."]}, "f898d821-ee6f-4b18-986d-8118642fe1b7": {"definition": "In Logic Pro, a set of special tracks displayed below the ruler that control project-wide, time-based parameters rather than audio or MIDI content — including the Tempo, Signature (time and key), Marker, Arrangement, Transposition, Beat Mapping, and Movie tracks. Their events apply to the whole project at their positions on the timeline.", "plain_english": "Global Tracks in Logic Pro are special lanes that control things for the whole song, not just one instrument. They hold the tempo, the time and key signature, section markers, and more. Think of them as the song's master settings shown along the top of the timeline.", "purpose_function": "They give one central place to control and edit project-level events like tempo changes, key and time signatures, and song sections, so these apply consistently across every track.", "practical_application": "An engineer opens the Global Tracks to add a tempo change for a breakdown, drop a marker on the chorus, or set a key-signature change, then hides them again to reclaim screen space.", "category": "DAW Workflow", "related_terms": ["Tempo track", "Marker", "Arrangement track", "Transposition track", "Signature track", "Beat mapping"], "common_mistakes": ["Leaving Global Tracks hidden and not realizing tempo or signature changes can be edited there.", "Confusing the project-wide Transposition track with transposing a single region.", "Editing tempo in the wrong place instead of the Tempo global track, which causes sync problems."], "scenario_contexts": ["Adding a ritardando by drawing tempo changes in the Tempo global track.", "Marking song sections with the Marker track to navigate a large arrangement.", "Reorganizing verses and choruses using arrangement markers in the Arrangement track."]}, "5977257a-9c5f-47eb-9c7e-c89ea04c6a77": {"definition": "A subjective mix descriptor for a sound in which separate elements feel bonded into one cohesive whole rather than sitting apart, often the result of gentle bus ('glue') compression, shared reverb, and consistent tonal treatment across a group. A 'gluey' mix or bus sounds unified and connected.", "plain_english": "'Gluey' describes a mix where all the parts feel stuck together as one solid sound, instead of separate pieces. Engineers often get this with gentle compression on a group of tracks. It is like glue holding a collage into a single picture.", "purpose_function": "The term communicates a goal of cohesion — making a group of tracks or a full mix sound like one connected performance rather than a stack of isolated parts.", "practical_application": "An engineer chasing a 'gluey' drum bus applies light bus compression and a shared room reverb so the kit sounds like one instrument in one space.", "category": "Mix Terminology", "related_terms": ["Glue compression", "Bus compression", "Cohesion", "Mix bus", "Parallel compression", "Reverb"], "common_mistakes": ["Over-compressing the bus to force 'glue', which flattens the dynamics and causes pumping.", "Assuming glue comes only from compression, ignoring shared reverb and tonal balance.", "Treating 'gluey' as an exact spec rather than a subjective description to judge by ear."], "scenario_contexts": ["Placing gentle compression across the drum bus to make the kit sound glued together.", "Using a mix-bus compressor to help a full mix feel cohesive.", "Sharing one reverb across backing vocals so they blend into a single, gluey texture."]}, "925184f3-3c7d-4458-877a-b35a50431f9e": {"definition": "In Avid Pro Tools, an edit-mode tool used to select, move, separate, and place audio or MIDI clips (regions) within a track or between tracks; it has Time, Separation, and Object variants for different selection behaviors.", "plain_english": "The Grabber is a Pro Tools tool that works like a hand for sound clips. You click a clip and drag it to move it where you want on the timeline.", "purpose_function": "It gives the editor a direct way to grab and reposition clips on the timeline, which is essential for arranging takes and edits.", "practical_application": "An editor switches to the Grabber to drag a vocal clip into time, move a sound effect to line up with picture, or relocate a section during editing.", "category": "Editing Tool", "related_terms": ["Selector Tool", "Smart Tool", "Trim Tool", "Clip (Region)", "Edit Window", "Nudge"], "common_mistakes": ["Confusing the Grabber with the Selector, which makes a timeline selection rather than moving a clip", "Using the Time Grabber when the Object Grabber is needed to pick several non-adjacent clips", "Dragging a clip off the grid because Grid mode is not enabled"], "scenario_contexts": ["Dragging a comped vocal clip earlier to fix timing", "Moving a sound effect to line up with picture", "Relocating a chorus section in an arrangement"]}, "2584d96c-a628-4b77-ba6b-3d9d8282bc66": {"definition": "A groove-quantize parameter that sets how strongly the timing (and sometimes velocity and duration) of events is pulled toward a groove template's reference positions, typically expressed as a percentage from 0% (no change) to 100% (full match).", "plain_english": "Groove amount controls how much a groove is applied to your notes. At a low setting the notes barely move; at full the notes lock right onto the groove's feel.", "purpose_function": "It lets you blend a part's original timing with a groove template, so you can add feel without making the performance sound stiff or fully machine-locked.", "practical_application": "When applying a swing groove to programmed drums, an engineer lowers the groove amount so the hats keep some of their original feel instead of snapping hard to the template.", "category": "Groove Editing", "related_terms": ["Groove application", "Groove template extraction", "Groove track", "Quantize", "Swing", "Velocity"], "common_mistakes": ["Setting the amount to 100% and losing all natural feel", "Confusing groove amount (strength) with the groove's own swing value", "Expecting amount to fix notes that are far off the grid, which may still need manual editing"], "scenario_contexts": ["Dialing in partial swing on a hi-hat pattern", "Blending a real drummer's feel onto programmed percussion", "Softening tightly quantized MIDI to sound more human"]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"d63cd173-d580-4e72-aed1-308e5319f71d": {"definition": "The process of imposing a groove template's timing (and optionally velocity and duration) onto MIDI or audio events, shifting them toward the template's rhythmic feel by a chosen amount.", "plain_english": "Groove application means putting a chosen groove onto your notes so they take on that rhythmic feel. It is like copying the timing swing of one part onto another.", "purpose_function": "It exists so a programmed or recorded part can borrow the timing feel of a reference groove, helping separate tracks lock together rhythmically.", "practical_application": "A producer applies a groove taken from the drum loop to the bass part so both parts breathe together.", "category": "Groove Editing", "related_terms": ["Groove template extraction", "Groove amount", "Groove track", "Quantize", "Swing", "MIDI"], "common_mistakes": ["Applying a groove at full strength and flattening the part's natural feel", "Applying a groove built at a different tempo or meter and getting odd timing", "Forgetting to set the amount, so the shift is stronger or weaker than expected"], "scenario_contexts": ["Matching a bass line to a drum loop's feel", "Adding a swung feel to straight programmed percussion", "Locking a keyboard part to the drummer's timing"]}, "75af7b7c-1cb1-4401-811e-92868449a8f6": {"definition": "The process of analyzing an existing audio or MIDI performance and capturing its timing (and often velocity and duration) into a reusable groove template that can later be applied to other material.", "plain_english": "This means pulling the timing feel out of one performance and saving it as a template. Later you can stamp that same feel onto other tracks.", "purpose_function": "It lets an engineer reuse the natural feel of a good take, or match new parts to the timing of an existing groove.", "practical_application": "Using a tool such as Beat Detective, an engineer extracts the groove from a live drum take and applies it to the programmed percussion.", "category": "Groove Editing", "related_terms": ["Groove application", "Groove amount", "Groove track", "Beat Detective", "Quantize", "MIDI"], "common_mistakes": ["Extracting from a poorly timed take and spreading its errors to other tracks", "Extracting with an incorrect grid or tempo, so the template does not line up", "Confusing extracting a groove with simply quantizing to the grid"], "scenario_contexts": ["Capturing the feel of a live drum take for reuse", "Building a house groove template from a favorite loop", "Extracting a bassist's timing to apply to synth parts"]}, "66362eea-b7a7-4424-8ebc-856e65424ccb": {"definition": "In Apple Logic Pro, a track designated as the timing reference so that the timing of other selected tracks is matched to (follows) its feel; only one Groove Track can be active at a time.", "plain_english": "A Groove Track is one track you pick as the timing boss in Logic Pro. Other tracks you tie to it will follow its rhythmic feel.", "purpose_function": "It provides a quick way to lock several tracks to the feel of a single reference part, without extracting and applying groove templates by hand.", "practical_application": "A Logic user sets the drum track as the Groove Track and enables other tracks to follow it, tightening the whole arrangement to the drummer's feel.", "category": "Groove Editing", "related_terms": ["Groove application", "Groove template extraction", "Groove amount", "Quantize", "Flex Time", "Track"], "common_mistakes": ["Expecting more than one Groove Track at a time, when only one can be active", "Forgetting to enable follow tracks, so nothing changes", "Choosing a loosely timed track as the reference and dragging others off"], "scenario_contexts": ["Making all tracks follow the drummer's feel in Logic", "Tightening a band recording to one reference part", "Locking overdubs to the groove of the rhythm section"]}, "8ac1feda-72ac-4c8e-b37f-24fb0a74ca49": {"definition": "In post-production dubbing, a premix (predub) that combines and processes the ADR (re-recorded studio dialogue) tracks as a group into a submixed stem, ready to be balanced against production dialogue, effects, and music in the final mix.", "plain_english": "This is a combined rough mix of all the re-recorded studio dialogue lines, bundled together before the final movie mix. ADR means lines actors re-record in a studio. It tidies those redone voice tracks into one neat bundle.", "purpose_function": "It reduces track count and pre-balances re-recorded dialogue so the re-recording mixer can handle it as one manageable element in the final mix.", "practical_application": "A dialogue editor delivers a group ADR premix so the re-recording mixer can blend the studio-recorded lines smoothly with the on-set dialogue.", "category": "Post Production", "related_terms": ["ADR", "Premix (Predub)", "Dialogue editing", "Stem", "Submix", "Re-recording mixer"], "common_mistakes": ["Confusing a premix or predub with the finished final mix", "Not matching ADR level and tone to the production dialogue before premixing", "Over-committing processing so elements can no longer be adjusted in the final"], "scenario_contexts": ["Preparing dialogue stems for a film final dub", "Grouping many ADR lines for a TV episode before the final mix", "Delivering a dialogue predub to the re-recording stage"]}, "ba3b5c4c-8574-4323-aba1-db2ff5bf1913": {"definition": "In Avid Pro Tools, the settable properties of a Mix or Edit group that determine which tracks belong to it and which controls (such as volume, mute, solo, automation mode, and record/input) are linked across the grouped tracks.", "plain_english": "Group attributes are the settings that say which tracks are in a group and which of their controls move together. It is like choosing which buttons on several channels are tied to the same string.", "purpose_function": "They let you control exactly how tightly grouped tracks behave together, so you can link only the functions you want, for example volumes but not mutes.", "practical_application": "In the Modify Groups dialog, an engineer sets group attributes so one drum fader moves them all, while leaving solo buttons independent.", "category": "Track Grouping", "related_terms": ["Mix Group", "Edit Group", "Group Override", "VCA Master", "Submix", "Fader"], "common_mistakes": ["Assuming a group links every control, when attributes may link only some", "Forgetting that changing attributes affects all member tracks", "Confusing Mix group attributes with Edit group attributes"], "scenario_contexts": ["Setting a drum group to link faders but not mutes", "Editing which tracks belong to a group", "Choosing whether automation mode is linked across a group"]}, "b839f670-5dad-4b03-990c-0c8f19db19db": {"definition": "In Steinberg Cubase and Nuendo, a track type that creates a group (submix) bus to which several audio channels can be routed, allowing them to be processed and level-controlled together before reaching the output.", "plain_english": "A Group Channel track is a single fader that several tracks feed into, so you can control them all at once. Think of routing all your drum mics into one drums fader.", "purpose_function": "It lets you submix related tracks, apply shared processing, and control their combined level with one fader, which simplifies the mix.", "practical_application": "A Cubase user routes all backing-vocal tracks to a Group Channel track to add one shared reverb and ride the whole group's level together.", "category": "Track Grouping", "related_terms": ["Submix", "Bus", "Group Attributes", "VCA Master", "Send", "Output Routing"], "common_mistakes": ["Confusing a Group Channel (an audio summing bus) with a VCA or mix group that only links faders", "Adding the same plug-in on every channel instead of once on the group", "Forgetting to route channels to the group, so it stays silent"], "scenario_contexts": ["Summing all drum mics to one drum group", "Bussing backing vocals for shared compression", "Grouping instrument tracks to control a submix level"]}, "768f714e-fad1-4363-b18b-b014349b46b3": {"definition": "In Avid Pro Tools, temporarily suspending a group's linking for a single action so that an adjustment (for example to one fader) affects only that track rather than all members, typically done by holding a modifier key while making the move.", "plain_english": "Group override lets you tweak just one track in a group without the others moving with it. It is like briefly untying one channel from the group so you can adjust it alone.", "purpose_function": "It lets an engineer make a quick fix to a single grouped track without having to disable and re-enable the whole group.", "practical_application": "With a drum group active, an engineer holds the override modifier to nudge only the snare fader while the rest of the group stays put.", "category": "Track Grouping", "related_terms": ["Mix Group", "Edit Group", "Group Attributes", "Suspend Groups", "Fader", "Solo"], "common_mistakes": ["Expecting an override to stick, when it only affects the single move", "Adjusting a grouped control without overriding and accidentally moving every member", "Confusing a group override with suspending all groups globally"], "scenario_contexts": ["Nudging one fader within an active mix group", "Fixing the level of a single mic in a grouped drum kit", "Making a quick change to one member of a group"]}, "9c7b2c5e-c14e-4423-bbb6-964acbfe1a99": {"definition": "Temporarily disabling the linking of mix or edit groups so that an action such as a fader move, edit, or automation change affects only the selected track instead of every member of the group; in Pro Tools this is the Suspend Groups command.", "plain_english": "It is a way to switch off track grouping for a moment so you can tweak just one channel. Normally moving one grouped fader moves them all, so you pause the group to fix a single track.", "purpose_function": "It lets an engineer make a quick, isolated adjustment to one grouped track without permanently ungrouping it, then restore linked control instantly.", "practical_application": "While mixing a grouped drum kit, the engineer suspends groups (Command/Ctrl+Shift+G in Pro Tools) to nudge the snare fader alone, then re-enables groups to keep the kit linked.", "category": "Mix Groups", "related_terms": ["Grouping matrix", "VCA group", "Mute group", "Hands-on-faders", "Mute automation pass"], "common_mistakes": ["Forgetting groups are suspended and then wondering why grouped moves no longer track together", "Ungrouping tracks entirely to make one tweak, instead of briefly suspending groups", "Assuming it affects only one group when the command disables group behavior globally"], "scenario_contexts": ["Nudging one drum in a grouped kit without moving the whole group", "Fixing a single track's automation inside a linked edit group", "Temporarily balancing one channel within a VCA-controlled section"]}, "48faaade-fb19-4636-837a-8fc5ee91cdca": {"definition": "A grid-style routing scheme on a mixing console or DAW in which input channels are assigned to shared group or subgroup buses, and those buses can in turn be fed to multiple mix or matrix outputs. It defines which sources feed which group, and which group feeds each destination, so related channels can be combined and controlled together.", "plain_english": "A grid on a mixer that lets you send many channels into shared groups. Once channels share a group, you control them all with one fader, like putting many files into one folder.", "purpose_function": "It organises a large channel count into a few manageable groups, so the engineer can adjust, process, or mute related sources together instead of one channel at a time.", "practical_application": "On a big show a tech routes all the drum channels into a drum group and all vocals into a vocal group, then rides those group faders to balance the mix quickly.", "category": "Signal Routing", "related_terms": ["Subgroup", "VCA group", "Matrix output", "Bus routing", "Mute group"], "common_mistakes": ["Confusing a group, which carries audio through a bus, with a VCA/DCA, which only links fader levels.", "Assigning a channel to a group but forgetting to route the group on to the main mix, so it is never heard.", "Double-routing a channel to both a group and the main bus, so it is summed twice and sounds too loud."], "scenario_contexts": ["Grouping all drum mics to one subgroup for combined level and compression during a live set.", "Sending backing vocals to a group so one fader controls the whole stack in a mix.", "Using a console's matrix to send different group blends to the main PA, monitors, and a recording feed."]}, "5ddb5d68-bd9b-4cb3-9cd5-713883bb8047": {"definition": "An editing-window tool in a DAW or audio editor, shown as a hand icon, that lets the user click and drag to scroll or pan the view of the timeline rather than select or move audio. It changes which part of the project is visible without altering any clips or data.", "plain_english": "A hand-shaped cursor in music software that lets you grab the screen and slide it around to see other parts of your song. It moves your view, not the sounds, like dragging a map on your phone.", "purpose_function": "It gives a quick way to move around a large project view without using scroll bars, keeping navigation fast during editing.", "practical_application": "An engineer switches to the hand tool to drag along a long timeline and reach a later section, then switches back to the selector tool to edit.", "category": "Editing Tools", "related_terms": ["Zoom tool", "Selector tool", "Grabber tool", "Timeline", "Playhead"], "common_mistakes": ["Expecting the hand tool to move or edit clips, when it only scrolls the view.", "Forgetting to switch back to an edit tool afterward and then being unable to make a selection.", "Confusing it with the grabber or move tool that actually relocates audio regions."], "scenario_contexts": ["Scrolling through a long arrangement to find a chorus far down the timeline.", "Panning the view horizontally while zoomed in on a detailed edit.", "Navigating a wide session when the scroll bars are awkward to use."]}, "3262e305-a75a-4027-84f2-10f03e3ce0c8": {"definition": "A manual mixing approach in which the engineer actively rides physical faders in real time to balance levels, rather than relying on stored automation or static settings. It describes hands-on, moment-to-moment level control, most common in live sound.", "plain_english": "Mixing by keeping your hands on the sliders and moving them live as the music plays, instead of letting the computer do it. It is like steering a car yourself the whole way instead of using cruise control.", "purpose_function": "It lets an engineer react instantly to a performance, pushing up a solo or pulling back a loud part as it happens, which stored automation cannot always predict.", "practical_application": "A front-of-house engineer keeps a hand on the vocal and solo faders through a show, riding them up and down so every lead sits right in the mix.", "category": "Mix Workflow", "related_terms": ["Fader riding", "Automation", "VCA group", "Front of house", "Gain riding"], "common_mistakes": ["Riding faders so much that the overall balance becomes inconsistent between songs.", "Focusing on one fader and neglecting other channels that also need attention.", "Assuming automation fully replaces hands-on riding when a live show changes unpredictably."], "scenario_contexts": ["Riding the lead vocal fader during a live concert to keep it above the band.", "Manually pushing up an instrumental solo the moment it starts.", "Mixing a fast-changing live broadcast where preset recall alone is not enough."]}, "04fd1826-6be9-455e-96cb-7c2dc56f17a9": {"definition": "A physical output connection on an audio interface or console, together with the DAW output path that maps a mix or bus to it. Tracks and buses are routed to a hardware output so the signal leaves the system to monitors, recorders, or outboard gear.", "plain_english": "A real, physical socket that sends audio out of your interface or mixer to speakers, recorders, or other gear. In your software you pick which output a sound uses, like choosing which door it leaves by.", "purpose_function": "It defines where audio physically exits the system, letting the engineer route mixes and sends to monitors, headphones, hardware processors, or recording devices.", "practical_application": "A tech assigns the main mix bus to hardware outputs 1-2 feeding the studio monitors, and sends a separate bus to outputs 3-4 for a headphone amp.", "category": "Signal Routing", "related_terms": ["Bus", "I/O setup", "Hardware insert", "Audio interface", "Output path"], "common_mistakes": ["Assigning a mix to a hardware output that is not physically connected, so nothing is heard.", "Confusing a hardware output, which is a physical socket, with an internal bus, which is virtual routing.", "Routing two mixes to the same hardware output and getting an unexpected blend."], "scenario_contexts": ["Sending the main mix to interface outputs 1-2 for the control-room monitors.", "Routing a stem to a spare hardware output to record it onto an external device.", "Feeding a hardware output into an outboard compressor as part of a hardware insert."]}, "79873158-cf15-43f4-9836-c16086580097": {"definition": "A recorded or programmed part that adds harmony notes above or below a main melody and is blended into the mix as a supporting layer. In vocal work it is a stacked harmony line sung against the lead, and the same idea applies to layered instrument harmonies.", "plain_english": "An extra part that sings or plays notes that fit with the main tune, added underneath to make it fuller. Think of a choir where some voices sing a different note that still matches the lead singer.", "purpose_function": "It thickens and enriches a part by adding musical harmony, giving a mix more depth and a bigger, more polished sound.", "practical_application": "A producer records two or three harmony vocal takes, then blends them quietly under the lead so the chorus sounds fuller without covering the main voice.", "category": "Arrangement & Layering", "related_terms": ["Double tracking", "Backing vocals", "Vocal stacking", "Lead vocal", "Blend"], "common_mistakes": ["Mixing harmony layers as loud as the lead, so they compete instead of support it.", "Stacking so many harmony layers that the mix becomes cluttered and muddy.", "Not tuning or timing the harmonies tightly, which makes the stack sound smeared."], "scenario_contexts": ["Adding thirds and fifths above a lead vocal in a pop chorus.", "Layering a harmony guitar line under a lead melody.", "Building a stacked vocal harmony for a big final chorus."]}, "ac8e05a0-9758-4715-9c20-9744522fc56b": {"definition": "The practice of keeping enough spare level between the working signal and the maximum before clipping or overload, so peaks are not squashed or distorted. It means setting gain and fader levels conservatively at each stage to protect that safety margin through the signal chain.", "plain_english": "Leaving some spare room at the top of your levels so loud peaks do not hit the ceiling and distort. It is like not filling a glass to the very brim so it does not spill when you move it.", "purpose_function": "It protects audio quality by preventing clipping and overload, and it leaves room for later processing, summing, and mastering without distortion.", "practical_application": "A mix engineer keeps track and bus levels so the mix bus peaks well below 0 dBFS, leaving several dB of headroom for the mastering stage.", "category": "Gain Staging", "related_terms": ["Headroom", "Gain staging", "Clipping", "0 dBFS", "Signal-to-noise ratio"], "common_mistakes": ["Pushing every fader and plugin hot so the mix bus clips with no headroom left.", "Confusing loudness with quality and giving up all headroom just for level.", "Forgetting that summing many channels adds level, which eats headroom on the master bus."], "scenario_contexts": ["Leaving 3 to 6 dB of headroom on the mix bus before sending a track to mastering.", "Setting conservative input gains during tracking to avoid clipping loud transients.", "Managing gain across plugins so no stage in the chain overloads."]}, "2018a6bf-7aac-4982-b9d8-df7dbd5463b4": {"definition": "In drum sampling and programming, a choke or exclusive group behavior in which triggering the closed hi-hat sample immediately cuts off a ringing open hi-hat sample, so only one hi-hat sound plays at a time. It reproduces how a real closed hi-hat silences an open one.", "plain_english": "A setting that makes a closed hi-hat sound instantly stop the open hi-hat sound, so both never ring at once. It copies a real drum kit, where clamping the pedal shut cuts off the open sizzle.", "purpose_function": "It makes programmed hi-hats sound realistic by stopping open and closed samples from overlapping, mirroring the physical behavior of a hi-hat pedal.", "practical_application": "A producer puts the open and closed hi-hat samples in the same choke group in a drum sampler, so each closed hit cleanly stops any open hat still ringing.", "category": "Drum Programming", "related_terms": ["Choke group", "Open hi-hat", "Closed hi-hat", "Sample trigger", "Drum sampler"], "common_mistakes": ["Forgetting to assign the open and closed hats to the same choke group, so they ring over each other.", "Setting the group's voice count above one, which stops the choke from working.", "Applying choke to samples that should overlap, cutting off sustain you wanted to keep."], "scenario_contexts": ["Programming a realistic hi-hat pattern with alternating open and closed hits.", "Setting up a Battery or drum-rack kit so closed hats choke open hats.", "Cleaning up an overlapping hi-hat groove that sounds muddy."]}, "778298cd-c0e4-4e86-8adf-c2029ed30d71": {"definition": "A recorded audio sample of a hi-hat cymbal, used in samplers, drum machines, and DAW drum kits to trigger the sound. Kits typically include separate closed, open, and pedal hi-hat samples mapped to different notes or pads.", "plain_english": "A short recording of a hi-hat cymbal that music software plays back when triggered. Instead of miking a real cymbal, you press a pad or key and the saved hi-hat sound plays.", "purpose_function": "It lets producers add hi-hat sounds to programmed beats without recording a live drummer, giving consistent and easily edited percussion.", "practical_application": "A beatmaker loads closed and open hi-hat samples onto pads and programs a groove, tweaking each hit's timing and level.", "category": "Drum Programming", "related_terms": ["Closed hi-hat", "Open hi-hat", "Drum sampler", "One-shot", "Hi-hat choke"], "common_mistakes": ["Using the same hi-hat sample on every hit, which sounds robotic without velocity or round-robin variation.", "Layering open and closed hat samples without a choke group, causing unrealistic overlap.", "Ignoring sample tuning and level so the hats sit poorly in the mix."], "scenario_contexts": ["Building a hip-hop beat from closed and open hi-hat one-shots.", "Layering a sampled hi-hat over a live kit to add crispness.", "Programming rapid hi-hat rolls in a trap groove using a single sample."]}, "486e4b04-19ea-4d6e-b1c1-db6e0c444f2b": {"definition": "A version of a film, television, or streaming program's soundtrack that is re-balanced and mastered specifically for consumer playback systems such as televisions, soundbars, and headphones, rather than the large-format theatrical mix made for cinemas. Compared with the theatrical mix it typically has raised dialogue levels and reduced dynamic range so it translates well at the lower listening levels found in the home.", "plain_english": "A home mix is a version of a movie's sound made for watching at home, not in a big theater. The voices are turned up. The very loud and very quiet parts are brought closer together. This way it sounds clear on a TV, soundbar, or headphones.", "purpose_function": "It exists because a cinema mix is calibrated for a large, loud room with a wide dynamic range, so it can sound muddy or force listeners to ride the volume at home; the home-entertainment mix adapts level balance and dynamics for smaller, quieter consumer environments.", "practical_application": "A re-recording mixer creates it from the theatrical mix stems, raising dialogue, compressing the dynamic range, and checking translation on near-field monitors, a TV, and headphones before delivering to a streaming platform or disc.", "category": "Mix Deliverable", "related_terms": ["Theatrical mix", "Printmaster", "Dynamic range", "Stems", "Dialnorm", "Near-field monitoring"], "common_mistakes": ["Assuming the theatrical mix can be delivered as-is for home viewing without re-balancing dialogue and dynamics", "Over-compressing the dynamic range until the mix sounds flat and lifeless", "Only checking the mix on high-end studio monitors and never on a TV, soundbar, or headphones", "Confusing the home-entertainment mix with a simple stereo downmix of the surround master"], "scenario_contexts": ["Preparing a feature film's soundtrack for Blu-ray and streaming release after the cinema run", "Delivering a near-field mix that meets a streaming platform's loudness and dynamic-range specification", "Re-balancing dialogue so speech stays intelligible on a small TV speaker", "Creating separate cinema and home versions of a documentary's mix"]}, "b63d7ff8-35db-4471-b136-7ccfe70c8583": {"definition": "A horizontal-resequencing technique in interactive game music in which the score is built from pre-composed musical segments that branch to different follow-on segments at set decision points, so the order of music played changes in response to gameplay while remaining musically coherent.", "plain_english": "In games, the music is split into short chunks. At certain points the game can branch to a different next chunk depending on what you do. It is like a choose-your-own-path story, but with pieces of music instead of pages.", "purpose_function": "It lets a game's music follow the player's choices and changing situations without a composer having to write a separate fixed track for every possible path, keeping the score reactive yet continuous.", "practical_application": "A game composer or audio implementer builds the segments and defines the branch points and rules in middleware such as Wwise or FMOD, so the engine picks the next segment based on game state like entering combat or completing an objective.", "category": "Interactive Music", "related_terms": ["Horizontal resequencing", "Vertical layering", "Immediate transition", "Adaptive music", "Music segment", "Transition marker"], "common_mistakes": ["Confusing horizontal branching with vertical layering, which adds or removes instrument layers instead of changing the segment order", "Placing branch points off the musical grid so transitions sound abrupt or out of time", "Writing segments that do not share key or tempo, making branches clash musically", "Creating so many branches that the system becomes hard to test and maintain"], "scenario_contexts": ["Scoring a game level whose music branches between explore, tension, and combat states", "Building a boss fight that branches to a victory segment when the enemy is defeated", "Implementing music that branches based on which path the player chooses in an open world", "Prototyping an adaptive score in Wwise using branch points tied to game parameters"]}, "de2e8292-0675-4921-a222-394f289a3323": {"definition": "An interactive game-music technique in which pre-composed musical segments are reordered, repeated, or swapped along the timeline in real time in response to game events, changing what plays next without altering the instrumentation within any single segment.", "plain_english": "This is a way to make game music change by rearranging chunks of a song as you play. The game decides which chunk comes next, so the same music can be reshuffled to fit the action. Think of it like a DJ picking the next section on the fly.", "purpose_function": "It keeps a game's soundtrack fresh and responsive over long, unpredictable play sessions by rearranging existing music instead of looping one fixed track, so the score can follow shifts in pace and mood.", "practical_application": "A composer writes interchangeable segments and transition rules, then an implementer sets them up in middleware such as Wwise or FMOD so the correct next segment is triggered when the game state changes.", "category": "Interactive Music", "related_terms": ["Horizontal branching", "Vertical layering", "Adaptive music", "Immediate transition", "Music segment", "Loop"], "common_mistakes": ["Mixing up horizontal resequencing (reordering segments) with vertical layering (adding or muting layers)", "Not matching tempo and key across segments, so re-sequenced sections do not join cleanly", "Transitioning between segments off the beat or bar, causing audible glitches", "Forgetting to author transition segments, leaving jarring jumps between musical sections"], "scenario_contexts": ["Reordering exploration music segments as a player moves through a level", "Swapping to a more intense segment when enemies appear", "Looping and reshuffling background score during an open-ended puzzle", "Setting up segment playlists and transition rules in game audio middleware"]}, "c91e8722-b61c-4162-9c6e-04461ef4a07d": {"definition": "In a digital audio workstation or editor, horizontal zoom is the control that expands or contracts the view along the time axis, showing a longer span of the timeline at lower magnification or a shorter span in greater detail, without changing track height.", "plain_english": "Horizontal zoom stretches or squeezes the timeline from left to right on your screen. Zoom in to see a tiny slice of time up close for fine edits. Zoom out to see the whole song at once. It changes the view only, not the audio itself.", "purpose_function": "It lets an editor move between a broad overview of a whole session and a close-up of individual waveforms or events, which is essential for both arranging and sample-accurate editing.", "practical_application": "An engineer uses horizontal zoom, via keyboard shortcuts, a zoom tool, or a scroll gesture, to zoom in tight on a waveform to place an edit or crossfade, then zooms out to check the arrangement across the whole timeline.", "category": "DAW Navigation", "related_terms": ["Vertical zoom", "Timeline", "Waveform", "Zoom tool", "Edit window", "Playhead"], "common_mistakes": ["Confusing horizontal (time-axis) zoom with vertical zoom, which changes waveform or track height", "Assuming zooming changes the audio itself rather than just the on-screen view", "Editing while zoomed too far out to see the exact edit point, causing sloppy cuts", "Forgetting the zoom keyboard shortcuts and losing time navigating menus"], "scenario_contexts": ["Zooming in to place a precise edit or crossfade on a vocal take", "Zooming out to view and arrange a full song timeline", "Lining up a sound effect to a video frame in post-production", "Using zoom shortcuts to move quickly between detail and overview while comping"]}, "983d08bc-118e-4018-9f6a-5d44f7464c12": {"definition": "In sound reinforcement, a hot spot is a localized area within a system's coverage where the sound pressure level is noticeably higher than in surrounding areas, typically directly in front of or beneath a loudspeaker, producing uneven coverage across the audience.", "plain_english": "A hot spot is a small area where the sound is much louder than everywhere else, usually right in front of or under a speaker. People standing there get blasted while others farther away hear less. Sound techs work to smooth these out for even coverage.", "purpose_function": "Spotting hot spots matters because even, consistent level across the listening area is a core goal of system design; a hot spot flags a coverage problem that can cause listener discomfort and an inconsistent mix from seat to seat.", "practical_application": "During system tuning a technician finds hot spots by walking the room or measuring SPL at many positions, then reduces them by re-aiming or re-angling loudspeakers, adjusting relative levels, or adding fill speakers for the under-covered areas.", "category": "System Coverage", "related_terms": ["Coverage pattern", "Sound pressure level", "Even coverage", "Fill speaker", "Loudspeaker aiming", "Sweet spot"], "common_mistakes": ["Turning the whole system down to tame a hot spot instead of re-aiming the loudspeaker causing it", "Confusing a coverage hot spot with the monitoring sweet spot", "UNSAFE: Standing in a hot spot close to a loudspeaker for long periods without hearing protection, risking noise exposure above safe OSHA limits", "Judging coverage from one mix position only and missing hot spots elsewhere in the room"], "scenario_contexts": ["Tuning a live PA and finding the front rows are far louder than the back", "Evening out coverage under a flown line array where seats directly below are too loud", "Measuring SPL across a venue to locate and reduce hot spots before doors", "Positioning fill speakers to balance a hot spot near the main hangs"]}, "25c2688d-c1bb-4491-a482-cea03e28d9fd": {"definition": "The mixing of a hybrid musical score, one that combines live acoustic recordings such as orchestra or soloists with electronic and programmed elements such as synthesizers, samples, and processed sounds, balancing and blending the acoustic and electronic material into a cohesive whole.", "plain_english": "A hybrid score combines real recorded instruments with electronic and computer-made sounds. A hybrid score mix is the engineer's job of blending those two kinds of sound into one. It is like combining a live band and a synth setup into a single, smooth sound.", "purpose_function": "It exists because modern film, TV, and game music often blends orchestra with synths and samples, and these sources have very different tone and dynamics; the mix reconciles them so neither the acoustic nor the electronic side sounds pasted on.", "practical_application": "A score mixer balances recorded orchestral stems against synthetic layers using level, EQ, reverb, and spatial placement so the electronic parts sit naturally with the live players, often matching reverbs and low end so the elements share one space.", "category": "Score Mixing", "related_terms": ["Stems", "Orchestral recording", "Synthesizer", "Reverb", "Submix", "Immersive printmaster"], "common_mistakes": ["Letting synthetic low end and orchestral low end pile up and mask each other instead of carving space with EQ", "Placing electronic elements in a different-sounding reverb space than the live players, breaking the illusion of one ensemble", "Balancing only in stereo and ignoring how the blend holds up in surround or immersive formats", "Treating the electronic layers as an afterthought rather than mixing them as part of the ensemble"], "scenario_contexts": ["Mixing a film cue that layers a recorded string section over synth pads and programmed percussion", "Blending sampled instruments with a live soloist for a game soundtrack", "Matching reverb and low end between orchestra and electronics in a trailer cue", "Delivering a hybrid score stem set for a re-recording mix"]}, "e3f8d760-a976-460c-80f0-b78e867128ee": {"definition": "In interactive game music, an immediate transition is a change from one musical segment or state to another that happens right away when triggered, without waiting for a musical sync point such as the next beat, bar, or cue, prioritizing responsiveness over rhythmic smoothness.", "plain_english": "An immediate transition means the game switches the music the instant something happens, instead of waiting for the next beat or bar. It reacts fast, which is great for sudden events. The trade-off is the change can sound a little abrupt.", "purpose_function": "It exists to make music respond instantly to urgent gameplay moments, such as a sudden ambush, where waiting for a musical boundary would feel too slow or disconnected from the action.", "practical_application": "An audio implementer selects an immediate transition in middleware such as Wwise or FMOD for events that must react without delay, often pairing it with a short crossfade or a stinger to soften the otherwise abrupt cut.", "category": "Interactive Music", "related_terms": ["Horizontal resequencing", "Horizontal branching", "Transition marker", "Crossfade", "Stinger", "Sync point"], "common_mistakes": ["Using immediate transitions everywhere, so the music constantly jumps and loses its musical flow", "Forgetting to add a crossfade or stinger, leaving an abrupt, clicky cut", "Confusing an immediate transition with a synced transition that waits for the next bar or beat", "Not testing immediate transitions against real gameplay timing, so they fire at awkward moments"], "scenario_contexts": ["Snapping instantly to combat music the moment an enemy attacks", "Cutting immediately to a game-over sting when the player dies", "Switching states right away during a scripted jump-scare", "Choosing between immediate and beat-synced transitions while tuning a score in Wwise"]}, "4498171b-d42d-4501-8699-bfefba2df953": {"definition": "An immersive printmaster is the final, fully-mixed master of a program's soundtrack delivered in an immersive, object-based format such as Dolby Atmos, containing the completed mix of channel beds plus audio objects with positional metadata, from which distribution encodes and renders are produced.", "plain_english": "A printmaster is the finished, final version of a movie's soundtrack. An immersive printmaster is that final master in a 3D sound format like Dolby Atmos. In that format, sounds can be placed all around you and even above you. It is the master copy that everything else is made from.", "purpose_function": "It serves as the authoritative final deliverable of the immersive mix, preserving the full object-based mix so that cinema, home, and streaming versions can all be rendered from one master rather than re-mixed for each format.", "practical_application": "A re-recording mixer finalizes the immersive printmaster on a Dolby Atmos stage, then delivers it, typically as an ADM BWF master file, so the distributor can generate theatrical, home, and binaural renders from the same source.", "category": "Mix Deliverable", "related_terms": ["Printmaster", "Home-entertainment mix", "Dolby Atmos", "Audio object", "Bed", "Stems"], "common_mistakes": ["Thinking the immersive printmaster is a single stereo or 5.1 file rather than an object-based master with metadata", "Confusing the printmaster (final master) with intermediate stems or the mix session", "Delivering without confirming the format meets the platform's immersive spec such as bed layout, object count, and loudness", "Assuming the immersive master alone covers home delivery without a re-rendered or re-balanced home mix"], "scenario_contexts": ["Delivering a feature film's final Dolby Atmos mix to the distributor", "Creating the master from which cinema, home, and binaural renders are made", "Archiving the object-based master at the end of a re-recording mix", "Delivering an immersive printmaster that meets a streaming platform's Atmos home spec"]}, "215a3b74-0e90-4d20-81ae-01776442bca3": {"definition": "Import Session Data is a Pro Tools command that copies selected elements, such as tracks, audio and video clips, automation, plug-in and mixer settings, tempo/meter maps, and window views, from another Pro Tools session into the current one, with options to match or create tracks and to reference or copy the source media.", "plain_english": "Import Session Data is a Pro Tools command that pulls parts of one project into another. You pick what you want, like certain tracks, their volume moves, or the tempo, and it drops them into the session you have open. It saves you from rebuilding things by hand.", "purpose_function": "It exists to move work between sessions, letting engineers reuse tracks, templates, settings, and edits, or gather material from several sessions, without manually recreating them.", "practical_application": "An engineer opens Import Session Data, selects a source session, chooses which tracks and data to bring in and how to match them to existing tracks, then imports, for example pulling approved vocal tracks or a mix template into the current project.", "category": "Session Management", "related_terms": ["Session", "Track", "Automation", "Template", "Consolidate", "Clip"], "common_mistakes": ["Choosing 'copy from source media' versus referencing without understanding the difference, leading to missing files or duplicated audio", "Importing to new tracks when you meant to match existing ones, creating duplicates", "Overlooking that plug-in settings and automation can come in with the tracks, overwriting current settings", "Forgetting that sample-rate or bit-depth differences may require conversion on import"], "scenario_contexts": ["Bringing approved tracks from an older session into a new one", "Loading a mix template's routing and plug-in setup into a fresh session", "Consolidating alternate takes recorded in separate sessions", "Recovering specific tracks after a session file becomes corrupted"]}, "35acf5b1-fe39-4327-ae72-b2fce54a688c": {"definition": "A series of effects processors placed on a channel's incoming signal path so they act on the audio as it arrives at the input, before it is recorded to disk. In DAWs such as REAPER it is a distinct chain from the track (playback) FX chain, letting the engineer commit processing to the recorded file or monitor it live without altering the stored track effects.", "plain_english": "This is a set of effects that treat a sound the moment it comes in, before it is saved. You can record with the effect baked in, or just use it to hear the sound while you play. Think of it like a filter on a camera lens that shapes the picture before the photo is taken.", "purpose_function": "It lets you shape or clean up a source at the input stage, such as gating noise or setting a tone, so the sound is processed on the way in rather than only on playback.", "practical_application": "A technician adds a gate, EQ, or amp simulator to a track's input FX chain so a guitar or vocal is monitored and, if wanted, recorded with that processing already applied.", "category": "Signal processing", "related_terms": ["Track FX chain", "Insert effect", "Monitoring", "Printing effects", "Signal chain", "Noise gate"], "common_mistakes": ["Confusing the input FX chain with the track FX chain, then wondering why the effect is not heard on playback.", "Accidentally recording an input effect that was only meant for monitoring, leaving it permanently on the file.", "Stacking heavy processing on the input, which adds latency and makes real-time monitoring feel sluggish."], "scenario_contexts": ["Adding a noise gate to a vocal input so breaths and room noise are cleaned up as it records.", "Monitoring a DI guitar through an amp simulator placed in the input FX chain.", "Committing a compressor to a bass part by recording it through the input chain."]}, "c0e8f150-cb6d-4461-ae71-00470457515a": {"definition": "The on-screen marker, usually a vertical blinking line, that shows the current position on a track or timeline where recording, pasting, or editing will begin. It sets the point at which new material is inserted and from which many edit and playback commands operate.", "plain_english": "This is the blinking line that marks your spot on the timeline. Whatever you paste or record drops in right there. It works just like the flashing cursor in a word processor, but for sound.", "purpose_function": "It gives every edit and paste a precise starting point, so the software knows exactly where to place new audio or apply a command.", "practical_application": "A technician clicks on the timeline to set the insertion cursor at a bar line, then pastes a copied section or begins recording from that exact point.", "category": "Editing", "related_terms": ["Playhead", "Insertion Follows Playback", "Edit selection", "Timeline", "Snap", "Grid"], "common_mistakes": ["Leaving the cursor in the wrong place, so pasted audio lands at the wrong point in the song.", "Confusing the insertion cursor with the moving playback cursor, and losing the edit position after pressing stop.", "Forgetting that snap is off, so the cursor sits slightly off the grid and edits are misaligned."], "scenario_contexts": ["Placing the cursor at the start of a chorus before pasting a copied vocal take.", "Setting the insertion point to punch in a re-recorded line.", "Clicking a bar line so a new marker is added at that exact spot."]}, "1547ccf9-ae95-435f-a639-3b2c5d6f2472": {"definition": "A Pro Tools option (the Timeline Insertion/Play Start Marker Follows Playback preference) that, when enabled, moves the edit insertion point to wherever playback stops instead of returning it to where playback began. It makes the cursor behave like a tape machine, so the next play starts from the last stop position.", "plain_english": "This is a setting that decides where the cursor lands when you press stop. Turn it on and the cursor stays where you stopped, so you carry on from there. Turn it off and the cursor jumps back to where you started, like rewinding a tape.", "purpose_function": "It lets you choose whether the cursor holds its start position for repeated review of the same spot, or moves forward with playback for tape-style, continue-from-here working.", "practical_application": "An engineer turns it off to keep auditioning the same edit point again and again, or turns it on to keep moving through a session from wherever they last stopped.", "category": "Editing", "related_terms": ["Insertion Cursor", "Playhead", "Edit selection", "Timeline", "Loop playback"], "common_mistakes": ["Leaving it on by accident, then losing a carefully placed edit selection every time playback stops.", "Blaming the software for 'moving' the cursor when this preference is simply enabled.", "Not knowing the shortcut toggles it, so the behavior changes unexpectedly mid-session."], "scenario_contexts": ["Disabling it so a tricky crossfade can be reviewed from the same start point repeatedly.", "Enabling it to work through a long session like a tape machine, continuing from each stop.", "Troubleshooting why a student's insertion point keeps jumping after playback."]}, "35fc2d67-bfe6-4981-8fe1-903711097b0f": {"definition": "In Steinberg Cubase, the Inspector is the panel in the left zone of the Project window that shows the settings and controls for the selected track, or, in an editor, for the shown event or part. It groups a track's parameters, such as routing, inserts, sends, EQ, and channel settings, into collapsible sections for quick access.", "plain_english": "In Cubase, the Inspector is a panel down the left side that shows the settings for the track you clicked. Instead of opening lots of windows, you find volume, effects, and routing in one place. Think of it as a details page for the selected track.", "purpose_function": "It puts a track's most-used settings in one place so you can view and change routing, inserts, sends, and EQ without opening separate windows.", "practical_application": "A Cubase user selects a track and opens the Inspector to change its output routing, add an insert effect, or set up a send, all from the left zone.", "category": "DAW interface", "related_terms": ["Inspector panel", "Track", "Insert effect", "Channel strip", "Send", "Routing"], "common_mistakes": ["Not realizing the Inspector always follows the selected track, so it seems to change on its own when a different track is clicked.", "Overlooking the collapsible sections and missing controls that are simply hidden.", "Confusing the Inspector's settings with the separate Channel Settings or MixConsole view."], "scenario_contexts": ["Re-routing a MIDI track's output to a virtual instrument from the Inspector.", "Adding an EQ or insert to the selected audio track using its Inspector sections.", "Checking a track's input and monitoring status before recording."]}, "d852d49b-bf2a-49d9-a0f4-cad0f719d2e4": {"definition": "A context-sensitive panel in a DAW or editing application that displays the properties and controls of whatever item is currently selected, typically a track, clip, or event. It updates automatically as the selection changes, gathering the relevant settings in one editable location.", "plain_english": "This is a side panel that shows the settings for whatever you have selected. Click a track or clip and its details appear there to view and change. It is like an info page that updates each time you pick something new.", "purpose_function": "It centralizes the settings of the selected item so you can inspect and edit them in one spot instead of hunting through menus or separate windows.", "practical_application": "A technician selects a clip or track and uses the inspector panel to adjust its properties, such as name, color, gain, routing, or effects, then clicks another item to edit that one.", "category": "DAW interface", "related_terms": ["Inspector (Cubase)", "Channel strip", "Track", "Clip", "Properties"], "common_mistakes": ["Forgetting the panel is context-sensitive, so it looks empty or wrong when nothing is selected.", "Editing the inspector while the wrong item is selected, changing the wrong track or clip.", "Hiding the panel and then assuming its controls are gone entirely."], "scenario_contexts": ["Renaming and recoloring a selected track from the inspector panel.", "Adjusting a selected clip's gain or fade settings.", "Reviewing a track's routing before a mix session."]}, "ea585e7b-0b11-4ef3-8d1e-c25059c3ba18": {"definition": "Digital signal processing that analyzes the audio, and sometimes the acoustic environment, in real time and automatically adjusts its own settings to reach a target result, rather than applying fixed, manually set parameters. It underlies adaptive tools such as automatic mixers, feedback suppressors, and self-adjusting EQ and dynamics.", "plain_english": "This is digital sound processing that listens to the audio and adjusts itself. Instead of you dialing in every setting, it decides what to change to hit a goal. It is like cruise control for sound, easing off or pushing on by itself.", "purpose_function": "It offloads routine, moment-to-moment decisions to the processor, aiming for a consistent result with less manual tweaking and faster setup.", "practical_application": "A technician uses an automatic mixer or adaptive processor whose intelligent DSP raises, lowers, or shapes signals on its own, then checks and limits its behavior rather than setting every parameter by hand.", "category": "Signal processing", "related_terms": ["Intelligent EQ", "Intelligent dynamics", "Automatic mixer", "Feedback suppression", "Adaptive processing"], "common_mistakes": ["Trusting the automation blindly and not checking the result, so odd decisions slip through.", "Assuming intelligent means flawless, when the tool still needs sensible targets and limits.", "Stacking several adaptive tools that fight each other, causing pumping or unstable tone."], "scenario_contexts": ["Using an automatic mic mixer at a conference so open mics are managed without a live operator.", "Applying an adaptive processor to even out a podcast voice track.", "Letting an adaptive feedback suppressor tame ringing in a live room."]}, "3670ade6-0249-4388-b66f-7668631033f0": {"definition": "A dynamics processor (compressor, limiter, or gate) that analyzes the program material and automatically adapts its parameters, such as threshold, ratio, attack, or release, to suit the signal instead of holding fixed manual settings. The aim is transparent, program-dependent level control that reacts to what the audio is doing.", "plain_english": "This is a compressor that adjusts itself to the sound. It watches the audio and changes how hard and how fast it works, so you do not have to set every knob. Think of it as a volume helper that reacts to the music on its own.", "purpose_function": "It delivers consistent, natural-sounding level control on varied or unpredictable material without the engineer constantly re-tuning settings.", "practical_application": "A technician places an adaptive compressor on a lively vocal or a live speech feed and lets it track the changing dynamics, then sets a target and checks that it is not over-working.", "category": "Dynamics processing", "related_terms": ["Compressor", "Limiter", "Intelligent EQ", "Intelligent DSP", "Auto release", "Adaptive processing"], "common_mistakes": ["Assuming an adaptive setting removes the need to listen, so heavy pumping goes unnoticed.", "Using it on already-consistent material where fixed settings would be simpler and cleaner.", "Not setting a sensible target level, so the processor works too hard or barely at all."], "scenario_contexts": ["Smoothing an inconsistent vocal take with an adaptive compressor.", "Controlling a live speech mic whose level changes as the presenter moves.", "Evening out a dialogue track for broadcast loudness."]}, "15c21576-dccf-4ad3-b09a-71aa1b591418": {"definition": "An equalizer that analyzes the incoming signal and automatically adjusts its frequency response, continuously or as a suggested starting curve, to improve tonal balance or reduce masking, rather than relying only on fixed, manually set bands. Tools of this type model hearing or compare the audio to a reference to decide what to boost or cut.", "plain_english": "This is an EQ that listens to the sound and adjusts the tone for you. It finds frequencies that are too strong or too weak and fixes the balance. It is like a smart tone control that shapes the sound automatically.", "purpose_function": "It speeds up tonal balancing and helps unmask elements by letting the processor find and correct problem frequencies that a beginner might miss.", "practical_application": "A technician inserts an adaptive EQ on a track or mix bus, lets it analyze and adjust the frequency balance, then dials back its strength to taste rather than setting each band by hand.", "category": "Equalization", "related_terms": ["Equalizer", "Dynamic EQ", "Masking", "Intelligent dynamics", "Intelligent DSP", "Frequency balance"], "common_mistakes": ["Treating the automatic result as final instead of a starting point to refine by ear.", "Applying it at full strength, which can hollow out or over-correct the tone.", "Confusing an adaptive EQ with a plain static EQ and expecting fixed, unchanging bands."], "scenario_contexts": ["Balancing a dense mix bus where instruments mask each other.", "Getting a fast tonal starting point on an unfamiliar vocal recording.", "Reducing harsh resonances on a live-streamed source automatically."]}, "66076ce3-6c77-449b-b95b-ad31c9eb849c": {"definition": "A harmonic exciter or psychoacoustic enhancer that adds or redistributes high-frequency harmonics in a program-dependent way, applying more enhancement to transients or masked detail and less elsewhere, rather than boosting a fixed band. It aims to increase perceived brightness, presence, and detail while adapting to the material.", "plain_english": "This is a brightness tool that adds sparkle to a sound, but only where it helps. It puts more shine on sharp, detailed parts and less on the rest. Think of it as a smart polish that knows which spots need buffing.", "purpose_function": "It brings out clarity and air more naturally than a plain treble boost by generating or lifting harmonics in step with what the audio is doing.", "practical_application": "A technician adds an exciter to a dull vocal or full mix and lets its adaptive processing lift presence on the detailed parts, then keeps the amount subtle to avoid harshness.", "category": "Signal processing", "related_terms": ["Exciter", "Harmonic enhancement", "Psychoacoustic enhancer", "Intelligent EQ", "High-frequency enhancement"], "common_mistakes": ["Adding too much, which makes the sound harsh, brittle, or fatiguing.", "Using an exciter to fix a dull recording that really needs better EQ or a better source.", "Judging the effect only in solo, then finding it too bright in the full mix."], "scenario_contexts": ["Adding air and presence to a muffled vocal without a harsh treble boost.", "Restoring detail to a dull archival or transferred recording.", "Lifting clarity on a full mix during mastering."]}, "46f4d107-1c11-4bec-8fae-e19f8188b5b5": {"definition": "The practice of detecting and limiting inter-sample peaks, which are levels the reconstructed analog waveform reaches between digital sample points and can exceed a signal's highest sampled peak and 0 dBFS. It relies on true-peak (oversampled) metering per ITU-R BS.1770 and true-peak limiting, typically leaving headroom such as -1 dBTP.", "plain_english": "Digital audio is stored as a row of dots. When those dots turn back into a real wave, the wave can rise higher between the dots than any single dot shows. That extra height can cause harsh distortion. Inter-sample peak control uses special meters and limiters to find and hold down those hidden peaks.", "purpose_function": "It prevents distortion in digital-to-analog converters, sample-rate converters, and lossy codecs such as MP3 and AAC that would otherwise clip on peaks hidden between samples, keeping loud, limited masters clean and codec-safe.", "practical_application": "When mastering or preparing a mix for streaming, an engineer switches the limiter and meter to true-peak mode and sets a ceiling around -1 dBTP so the file stays clean after encoding and on consumer converters.", "category": "Loudness & Metering", "related_terms": ["True peak", "dBFS", "Brickwall limiter", "Loudness normalization", "Headroom", "Sample rate conversion"], "common_mistakes": ["Trusting a sample-peak reading of 0 dBFS and assuming there is no clipping, when the true peaks between samples exceed it", "Mastering to exactly 0 dBFS or 0 dBTP, leaving no margin for codec-induced inter-sample overs", "Confusing true-peak level (dBTP) with integrated loudness (LUFS) and treating them as the same target"], "scenario_contexts": ["Setting a -1 dBTP ceiling before uploading a master to a streaming platform", "Checking a heavily limited loud mix on a true-peak meter to reveal overs invisible on a normal peak meter", "Preparing broadcast deliverables that must meet EBU R128 true-peak limits"]}, "1a990aca-54a4-4e79-b8fc-bd8bc5d7a80c": {"definition": "A musical score for a game or other interactive medium that is not fixed but changes in real time in response to user actions or program state, typically by re-sequencing, layering, or transitioning between pre-composed musical segments. It is authored as modular assets and playback rules rather than a single linear rendered track.", "plain_english": "In a game, the music is not one fixed recording. An interactive score is written so it can change as you play. It might add layers, switch sections, or shift mood when the action does. The music is built from small pieces that software rearranges live.", "purpose_function": "It lets music follow the player's experience, raising tension in combat or easing during exploration, so the soundtrack stays emotionally in step with unpredictable, branching gameplay.", "practical_application": "A game composer writes stems and short segments, then an audio programmer or middleware such as Wwise or FMOD triggers, layers, and cross-fades them based on game events.", "category": "Adaptive Music", "related_terms": ["Adaptive music", "Horizontal resequencing", "Vertical layering", "Stems", "Audio middleware", "Crossfade"], "common_mistakes": ["Composing one long linear cue and expecting it to adapt without modular segments or transition logic", "Ignoring musical transition points, causing jarring cuts when the game switches states", "Failing to match tempo and key across segments so layers and transitions stay musical"], "scenario_contexts": ["Scoring a video game where combat music intensifies as enemies appear", "Building a museum or theme-park installation whose music reacts to visitor movement", "Authoring a mobile game soundtrack in FMOD that layers instruments as the player progresses"]}, "3f11f47b-547b-42e5-916c-a8b418826ade": {"definition": "An alternate mix delivered without the lead vocal but with the full instrumental and the backing or harmony vocals intact, so a lead vocal in another language can be recorded over it. It is one of several standard alternate deliverables prepared alongside the main mix.", "plain_english": "This is a special version of a song's mix. It keeps all the music and the backing singers, but leaves out the main vocal. That empty space lets a singer add a lead vocal in another language. It helps a song reach listeners in different countries.", "purpose_function": "It exists so a song can be re-voiced for foreign-language markets or covers without remixing the whole track, reusing the original production behind a new lead vocal.", "practical_application": "At mixdown the engineer prints a version with the lead vocal muted but the backing vocals kept, labels it 'international', and delivers it alongside the main, instrumental, and TV mixes.", "category": "Mix Deliverables", "related_terms": ["Instrumental mix", "TV mix", "Stems", "A cappella", "Mixdown", "Alternate mix"], "common_mistakes": ["Confusing the international version with a full instrumental, when the international version keeps backing vocals and the instrumental removes all vocals", "Leaving lead-vocal bleed or reverb tails in the muted lead path", "Forgetting to include it in the set of alternate versions requested by the label"], "scenario_contexts": ["A label plans to release a hit with a new lead vocal recorded in another language", "Preparing a full delivery package of main, instrumental, TV, and international mixes for a pop single", "A foreign artist wants to cover a song over the original backing production"]}, "121aa9fe-1652-4576-a899-56224272e496": {"definition": "In REAPER, an FX chain applied to an individual media item, acting on its active take, so it processes only that item's audio or MIDI rather than the whole track. Opened from the item's FX button, it runs before the track FX and is technically the take FX chain.", "plain_english": "In the REAPER program, effects usually sit on a whole track. Item FX instead put effects on just one clip. Only that clip's sound passes through them. It is handy when one piece of audio needs its own treatment.", "purpose_function": "It lets a technician process a single clip, fixing or shaping just that region without affecting other items on the same track, and it runs before the track's own FX.", "practical_application": "An engineer drops a de-esser or EQ as item FX on one problem vocal phrase, or a pitch plug-in on a single guitar clip, leaving the rest of the take untouched.", "category": "DAW Effects", "related_terms": ["Take FX", "Track FX", "FX chain", "Media item", "Insert effect", "Signal chain"], "common_mistakes": ["Adding a plug-in as item FX when it was meant for the whole track, so it affects only one clip", "Forgetting item FX exist and searching the track chain for an effect that is actually on the item", "Copying an item without realizing its item FX travel with it, duplicating processing unexpectedly"], "scenario_contexts": ["Fixing a single harsh 's' on one vocal clip without touching the rest of the track", "Applying a one-off filter or tape-stop effect to a single loop", "Pitch-correcting just one guitar note printed on its own item"]}, "8663da26-6816-47b5-b554-3d593029990a": {"definition": "In REAPER, an item timebase setting that ties a media item to the project tempo map, so its position and length are measured in beats and it time-stretches (audio) or scales (MIDI) to stay in sync when the project tempo changes. With it off, the item is anchored in absolute time and ignores tempo changes.", "plain_english": "This setting tells a clip to follow your song's tempo. If you speed up or slow down the project, the clip stretches to stay in time. Without it, the clip plays at its own fixed speed and drifts out of sync. It keeps loops locked to the beat.", "purpose_function": "It keeps imported loops and recorded parts musically aligned to the session's beat grid, so changing the project tempo does not throw them out of time.", "practical_application": "When importing a drum loop recorded at a different tempo, the technician sets the item to follow project tempo so REAPER stretches the loop to match the project's BPM and it stays on the grid.", "category": "DAW Tempo", "related_terms": ["Project tempo", "Item timebase", "Time stretching", "Tempo map", "Beat grid", "BPM"], "common_mistakes": ["Leaving items in a time-based timebase and wondering why they drift when the tempo changes", "Stretching audio far from its original tempo and introducing audible artifacts", "Assuming MIDI and audio follow tempo the same way, when audio must be time-stretched to conform"], "scenario_contexts": ["Dropping a purchased 120 BPM loop into a 100 BPM project and having it conform automatically", "Building a tempo-mapped edit where the whole arrangement follows a changing tempo", "Keeping a recorded rhythm part in sync after adjusting the session tempo"]}, "8157f1f8-aa50-4822-92f4-7bf7c515b96a": {"definition": "The term used in DAWs such as Apple Logic Pro and Steinberg Cubase and Nuendo for keyboard shortcuts: user-assignable key and modifier combinations mapped to program functions, managed in a dedicated Key Commands window or editor. They can be customized and saved as presets.", "plain_english": "Key commands are keyboard shortcuts inside music software. Instead of clicking through menus, you press a key to do a job fast. You can also change them to keys you like. Editors call the shortcut list 'Key Commands'.", "purpose_function": "They speed up editing and mixing by letting a technician trigger common actions from the keyboard instead of hunting through menus, and they can be tailored to a personal or facility workflow.", "practical_application": "An engineer assigns or learns key commands for split, fade, save, and cycle, and imports a saved key-command set when moving between studios.", "category": "DAW Workflow", "related_terms": ["Shortcut", "Macro", "Modifier key", "Preset", "Transport", "Tool switching"], "common_mistakes": ["Assuming default key commands are identical across different DAWs or versions", "Overwriting an existing shortcut assignment and losing a needed command", "Not exporting or backing up a customized key-command set before reinstalling"], "scenario_contexts": ["Customizing shortcuts in Logic Pro's Key Commands window for faster editing", "Loading a facility-standard key-command preset in Cubase on a new machine", "Learning transport and edit shortcuts to keep hands off the mouse during a session"]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"e5bfaaf1-d777-43e0-8a3a-ad2e3a97c2e4": {"definition": "In a sampler or software instrument, the contiguous range of MIDI note numbers across which a given sample (zone) is assigned to sound; notes played inside it trigger that sample, usually transposed relative to its root key. Multiple key zones map different samples across the keyboard for multisampling.", "plain_english": "A sampler plays recorded sounds from your keyboard. A key zone is the group of keys that plays one sound. Press a key inside that zone and you hear that recording, shifted up or down in pitch. Different zones let different keys play different recordings.", "purpose_function": "It lets one recorded sample cover a span of pitches and lets a builder place many samples side by side, so an instrument sounds natural across its whole range.", "practical_application": "When building a sampler instrument, a technician sets each sample's key zone with a low and high note plus a root key so the keyboard plays smoothly from one sample to the next.", "category": "Sampling", "related_terms": ["Root key", "Velocity layer", "Multisample", "Sampler", "Key mapping", "Keyswitch"], "common_mistakes": ["Overlapping key zones by accident so two samples sound on the same note", "Setting the wrong root key, so samples in a zone play out of tune", "Stretching one sample across too wide a key zone, causing unnatural or dull transposition"], "scenario_contexts": ["Mapping a multisampled piano so each note range plays its own recording", "Assigning a keyswitch zone at the bottom of the keyboard to change articulations", "Building a drum kit where each key zone triggers a different hit"]}, "85231036-ef2b-4dac-a6bb-3697ab8ae1e2": {"definition": "A production technique of combining two or more kick-drum sounds, commonly one sample chosen for low-end weight and another for attack or click, into a single composite kick, with the layers level-balanced and phase-aligned. It builds a kick with both sub energy and definition that a single sound may lack.", "plain_english": "One kick-drum sound may not have everything you want. Kick layering stacks two or more kicks together. One brings the deep low boom, another brings the sharp click you hear on small speakers. Lined up in time, they act as one bigger kick.", "purpose_function": "It lets an engineer design a kick that has both deep sub weight and clear attack, so it translates on both large systems and small speakers like phones and laptops.", "practical_application": "In a dance or hip-hop mix, the producer layers a sub-heavy kick sample under a clicky top sample, checks their phase, and balances the levels to taste.", "category": "Drum Production", "related_terms": ["Kick sample", "Layering", "Phase alignment", "Sub bass", "Transient", "Sample replacement"], "common_mistakes": ["Stacking layers without phase-aligning them, causing low-end cancellation and a weak kick", "Layering two sub-heavy kicks and building a muddy, boomy low end", "Not high-pass filtering the click layer, leaving competing low frequencies"], "scenario_contexts": ["Designing a club kick that hits hard on a big PA and still clicks on earbuds", "Reinforcing a thin recorded kick by layering a sample beneath it", "Building a signature kick sound for an electronic track"]}, "310601e9-eb71-4473-8166-8dcb2ea36daa": {"definition": "A recorded or synthesized audio sample of a single kick (bass) drum hit, loaded into a sampler, drum machine, or DAW and triggered to sound the kick. It can stand alone as the kick source or reinforce or replace a recorded acoustic kick.", "plain_english": "A kick sample is a short recording of one kick-drum hit. You load it into software and trigger it to play the kick in a song. Many electronic tracks build their beat from kick samples. It can also be added under a real kick to make it stronger.", "purpose_function": "It provides a consistent, tunable kick sound on demand, useful when programming beats or when a recorded kick is too weak or uneven to use on its own.", "practical_application": "A producer auditions kick samples in a drum sampler, tunes and shapes one to fit the track, and triggers it from MIDI or uses it to replace a recorded kick.", "category": "Drum Production", "related_terms": ["Kick layering", "Sampler", "Sample replacement", "Drum machine", "One-shot", "MIDI trigger"], "common_mistakes": ["Using a kick sample at its default tuning so it clashes with the song's key", "Picking a kick sample that sounds good on its own but disappears in the full mix", "Leaving an unwanted room tail on a one-shot that muddies tight programming"], "scenario_contexts": ["Programming a beat from a kick sample in a drum sampler", "Replacing an uneven live kick with a triggered sample for a tight, consistent sound", "Choosing a kick sample that matches the genre and energy of a track"]}, "435ca4ec-3c52-4f0d-b5b0-5efc1e8d4633": {"definition": "LANDR is an online, algorithm-driven platform providing automated audio mastering and music distribution. A user uploads a finished stereo mix and the service analyzes it and applies mastering processing (equalization, dynamics control, and limiting) to generate a mastered file without a human mastering engineer.", "plain_english": "LANDR is a website that masters your song for you. You upload your finished mix, and a computer program polishes the sound and makes it louder. It works a bit like a photo filter, but for music.", "purpose_function": "It gives musicians a fast, low-cost way to obtain a polished, loudness-balanced version of a track without hiring a mastering engineer or owning mastering tools.", "practical_application": "An artist or technician uploads a stereo mixdown, chooses an intensity or style setting, previews the result, and downloads the master for release or streaming.", "category": "Mastering Service", "related_terms": ["Mastering", "Loudness normalization", "Limiter", "Reference track", "Mixdown", "LUFS"], "common_mistakes": ["Treating an automated master as a fix for a weak mix (poor input still yields a poor master)", "Expecting it to match a skilled human mastering engineer on complex or unusual material", "Uploading a lossy MP3 instead of a high-resolution WAV", "Pushing the intensity setting too high, causing over-limiting and distortion"], "scenario_contexts": ["An independent artist mastering a single for streaming on a tight budget", "Generating a quick loud reference version to compare against a manual master", "Batch-mastering demo tracks for a quick listen"]}, "6dc9a659-658b-442d-b3b2-5a7cdb61384b": {"definition": "Lane comping is the practice of assembling a single best composite performance from multiple recorded takes stacked as separate horizontal take lanes under one track, by selecting and stitching together the strongest sections of each take.", "plain_english": "Lane comping means building one perfect take out of many. You record a part several times and stack the takes in rows. Then you pick the best bit from each row and join them into one smooth take.", "purpose_function": "It lets an engineer keep every take and later combine the best moments into one flawless performance, raising quality without asking the performer to nail the whole part in a single pass.", "practical_application": "After recording several vocal or solo passes into take lanes, the engineer auditions each lane phrase by phrase and selects the best sections to form the comp used in the mix.", "category": "Editing", "related_terms": ["Comping", "Take lane", "Playlist", "Crossfade", "Cycle recording", "Punch-in"], "common_mistakes": ["Forgetting to crossfade edit points, so the joins click or pop", "Comping across takes with different tuning or timing, causing audible jumps", "Not keeping a backup or flat version of the original takes", "Choosing takes by how the waveform looks instead of by listening"], "scenario_contexts": ["Comping a lead vocal from ten looped takes", "Building a guitar solo from several recorded passes", "Assembling a clean voiceover from multiple reads"]}, "8ecf31f7-3a22-4df8-8e45-b4dee4b85430": {"definition": "Laptop translation refers to how well a mix keeps its intended balance, clarity, and impact when played through the small, bass-limited built-in speakers of a laptop. It is one reference point when checking that a mix translates across a range of playback systems.", "plain_english": "Laptop translation is about whether your mix still sounds good on a laptop's tiny speakers. Those small speakers cannot make deep bass. So you check that the song does not fall apart when it plays on them.", "purpose_function": "Because many listeners hear music on laptop or phone speakers, checking laptop translation ensures the mix's key elements stay clear and balanced on small, low-bass systems, not just on studio monitors.", "practical_application": "A mixer periodically switches playback to the laptop's internal speakers to confirm that vocals, kick, and bass remain audible and balanced before finalizing the mix.", "category": "Monitoring", "related_terms": ["Mix translation", "Reference monitor", "Mono compatibility", "Grot box", "Frequency balance", "Nearfield monitor"], "common_mistakes": ["Mixing only on large monitors and never checking small speakers", "Boosting sub-bass that laptop speakers cannot reproduce, hiding balance problems", "Assuming a mix that works on laptops automatically works on full-range systems"], "scenario_contexts": ["A final mix check on a laptop's built-in speakers", "Verifying a podcast stays intelligible on laptop playback", "Comparing balance between studio monitors and a laptop"]}, "ef032971-a446-4fa6-b2e2-c1080b037dff": {"definition": "Latch is a DAW mixer automation mode in which a control starts writing new automation data as soon as it is moved (touched) and continues writing at its last set value even after it is released, until transport playback is stopped.", "plain_english": "Latch is a setting that records your fader moves. Once you grab the fader, it starts writing. It keeps holding the last value even after you let go, until you stop playback.", "purpose_function": "It lets an engineer overwrite a stretch of existing automation with continuous hands-off holds, useful for riding a level or effect across a long section without having to keep the control moving.", "practical_application": "An engineer arms latch, plays the section, rides the vocal fader to set the level, then releases it; the fader holds its last position and keeps writing until playback stops.", "category": "Automation", "related_terms": ["Automation", "Touch mode", "Write mode", "Read mode", "Trim mode", "Fader ride"], "common_mistakes": ["Forgetting to stop playback, so latch keeps overwriting good automation past the intended section", "Confusing latch with touch, which snaps back to the old value on release while latch holds the last value", "Leaving a channel in latch and accidentally erasing automation on the next pass"], "scenario_contexts": ["Riding a lead vocal level through a chorus", "Automating a reverb send level and holding it", "Correcting one section of existing automation"]}, "7510db32-023e-4070-b22e-ef76c1492d0d": {"definition": "In Steinberg Cubase, the Left Zone is the panel area along the left edge of the Project window that houses the Inspector, Visibility, and related tabs for viewing and adjusting the settings of the selected track and for showing or hiding tracks.", "plain_english": "The Left Zone is the strip of tools down the left side of the Cubase window. It holds the Inspector, where you change the settings for the track you picked.", "purpose_function": "It groups track-editing and visibility controls in one dockable area so the engineer can see and adjust the selected track's parameters and manage which tracks are shown.", "practical_application": "A Cubase user opens the Left Zone to reach the Inspector, expand a track's insert, EQ, or send sections, or use the Visibility tab to hide unused tracks.", "category": "Interface", "related_terms": ["Inspector", "Right Zone", "Lower Zone", "Project window", "Visibility", "MixConsole"], "common_mistakes": ["Confusing the Left Zone Inspector with the separate MixConsole window", "Accidentally hiding the Left Zone and thinking the Inspector has disappeared", "Mixing up the Left, Right, and Lower zones and their contents"], "scenario_contexts": ["Opening the Inspector via the Left Zone to add an insert plug-in", "Using the Visibility tab in the Left Zone to declutter a large project", "Toggling the Left Zone off to gain screen space"]}, "cf0e7879-06c9-4ae5-a5c0-a7a6202c6b6b": {"definition": "A Library panel is a browser pane in a DAW or plug-in that lists and loads presets, patches, sounds, or channel settings for the selected track or device.", "plain_english": "The Library panel is a menu of ready-made sounds and settings. You click a track, open the Library, and pick one. This saves you from building the sound from scratch.", "purpose_function": "It gives quick access to saved presets and factory content so an engineer can audition and apply sounds or channel settings without recreating them by hand.", "practical_application": "In Logic Pro a user selects a software-instrument track, opens the Library, and clicks patches to load instrument and effect settings instantly.", "category": "Interface", "related_terms": ["Preset", "Patch", "Channel strip", "Inspector", "Browser", "Track"], "common_mistakes": ["Confusing the Library (presets and patches) with the file or media browser (audio files)", "Loading a patch that replaces existing plug-ins and losing custom settings", "Not saving custom settings as a user patch for reuse"], "scenario_contexts": ["Loading a vocal channel-strip patch from the Library", "Browsing synth patches while writing a part", "Saving a custom patch to the Library for later projects"]}, "dd0e093b-896d-458b-945c-ff002ac0fedf": {"definition": "Limiter ceiling optimization is the practice of setting a limiter's output ceiling — the maximum peak level it will allow — to the value that prevents clipping, including inter-sample (true) peaks, while preserving loudness and dynamics. In mastering it commonly means setting a true-peak ceiling around -1 dBTP for safety through lossy codecs and D/A conversion.", "plain_english": "A limiter has a ceiling, which is the loudest level it lets through. Optimizing it means picking that top level with care. The goal is a loud track that never clips or distorts.", "purpose_function": "It sets a safe maximum peak so the master stays free of clipping and codec distortion while reaching the target loudness for release.", "practical_application": "A mastering engineer sets the limiter's true-peak ceiling (for example -1 dBTP) so that encoded MP3 or AAC files and the converter do not overshoot 0 dBFS and clip.", "category": "Mastering", "related_terms": ["Brickwall limiter", "True peak", "dBTP", "Inter-sample peak", "LUFS", "Loudness normalization"], "common_mistakes": ["Setting the ceiling at 0 dBFS, allowing true-peak overs after lossy encoding", "Driving the input so hard against the ceiling that the master distorts", "Watching only sample peaks and ignoring true-peak metering"], "scenario_contexts": ["Setting a -1 dBTP ceiling before exporting a streaming master", "Preventing clipping when a track is encoded to MP3", "Balancing loudness against true-peak headroom"]}, "21bcc490-76a3-4e1b-a355-f0a502cf5246": {"definition": "A List Editor is a DAW editor that displays MIDI or other events as a numerical text list, with each event shown as a row carrying values such as position, type, pitch, velocity, and length, for precise viewing and numeric editing.", "plain_english": "A List Editor shows your MIDI notes as a written list, not dots on a grid. Each note is a row of numbers. You can read and type to change them, like a spreadsheet of notes.", "purpose_function": "It lets an editor inspect and adjust individual events by exact numeric value and find stray or hidden events, such as extra controller messages, that graphic editors can miss.", "practical_application": "A technician opens the List Editor to fix a wrong velocity, delete a stuck controller message, or move an event to an exact tick position.", "category": "MIDI Editing", "related_terms": ["Piano Roll", "Key Editor", "MIDI", "Event", "Velocity", "Controller"], "common_mistakes": ["Overlooking the List Editor and missing stray MIDI controller or sysex events", "Editing numeric values without understanding tick or PPQN position", "Confusing the List Editor with the score or notation editor"], "scenario_contexts": ["Removing a stuck sustain-pedal message", "Correcting one note's velocity by typing an exact value", "Finding hidden program-change events in a part"]}, "fe10c9a7-70d4-4051-a14e-36bbebbdb233": {"definition": "Listening-fatigue reduction refers to practices that lessen the ear tiredness and loss of discrimination that build up during prolonged listening, by controlling monitoring level and exposure time and by taming harsh or over-processed content such as excess high-mid energy, distortion, and heavy compression.", "plain_english": "This means keeping your ears fresh while you work. You keep the volume down, take breaks, and smooth out harsh sounds. Tired ears start to hear wrong, so this helps you trust your mix.", "purpose_function": "It preserves accurate hearing and judgment over a long session, and protects long-term hearing, so mix decisions stay reliable instead of drifting as tired ears mislead the engineer.", "practical_application": "An engineer monitors at a moderate reference level (commonly around 79-85 dB SPL), takes regular breaks, and tames harsh high-mid buildup so both the ears and the mix judgment stay dependable.", "category": "Monitoring", "related_terms": ["Listening fatigue", "Monitoring level", "SPL", "Reference level", "De-essing", "Hearing protection"], "common_mistakes": ["UNSAFE: Monitoring at high SPL for long periods, which causes fatigue and risks permanent noise-induced hearing loss (observe OSHA 1910.95 exposure limits)", "Turning the monitors up to hear more detail, which tires the ears faster", "Not taking breaks and then trusting fatigued judgment", "Masking harshness with volume instead of fixing it"], "scenario_contexts": ["A long mix session where scheduled breaks keep the ears fresh", "Taming a harsh vocal to reduce fatigue over a track", "Setting a safe monitoring level for an all-day tracking session"]}, "d8ac12c9-dd73-41b8-a345-0fb3b6174d5d": {"definition": "In a DAW, the left and right locators are two position markers that define a start point and an end point on the timeline, delimiting a range used for cycle (loop) playback and recording, punch in/out, and range-based export or processing.", "plain_english": "Locators are two markers that set the start and end of a section on the timeline. You use them to loop a part, record over a set range, or choose what to export. Think of them like brackets around the piece of a song you want to work on.", "purpose_function": "They give the engineer one defined time range that many DAW functions act on, so looping, cycle recording, punch, and export all share a single consistent selection instead of needing separate settings.", "practical_application": "An engineer sets the left and right locators around a chorus to loop it while adjusting the mix, or brackets a whole song to bounce it down between those two points.", "category": "Editing & Navigation", "related_terms": ["Loop points", "Cycle mode", "Punch recording", "Marker", "Bounce"], "common_mistakes": ["Confusing locators with markers, when locators define an active range and markers are just named position flags", "Forgetting the locators are still set when exporting, so only the bracketed range bounces instead of the whole song", "Setting the right locator before the left, which can leave a reversed or empty range"], "scenario_contexts": ["Looping an eight-bar section for cycle recording of a guitar overdub", "Bracketing the final mix from start to end to export a stereo bounce", "Setting a punch range so recording only replaces a flubbed vocal line"]}, "5efe9979-2aba-430a-b0c4-dc387331d0d1": {"definition": "A Logic Pro project is Apple Logic Pro's main document that stores an entire production, including audio and MIDI tracks, software instruments and plug-ins, mixer and routing settings, automation, and tempo and key information, in a single package file (.logicx).", "plain_english": "A Logic Pro project is the one file that holds your whole song in Logic Pro. It keeps your tracks, instruments, effects, and mix settings together. It works like a folder that packs everything about the song into a single item you open.", "purpose_function": "It keeps every part of a production together and recallable, so an engineer can close a session and later reopen it with all tracks, settings, and automation exactly as they were left.", "practical_application": "An engineer opens a Logic Pro project to continue a mix, and can save versions or use Save As to branch the work without losing the original.", "category": "Project Management", "related_terms": ["Logic Pro project template", "Track", "Bounce", "Automation", "Channel strip"], "common_mistakes": ["Assuming the project always contains its audio, when it may only reference external files, so moving the .logicx alone can break the session", "Not consolidating or saving assets into the project before archiving or handing it off", "Confusing a project with a single bounced audio file"], "scenario_contexts": ["Reopening a client's project a month later to make mix revisions", "Saving incremental project versions before a big arrangement change", "Handing off a project with assets included so it opens on another machine"]}, "9891c0a9-97c3-4a04-83a9-2de926ec69e1": {"definition": "A Logic Pro project template is a pre-configured starting project, with tracks, instruments, plug-ins, routing, and settings already set up, that Logic Pro opens as a new untitled project so recurring session types can be started without rebuilding them each time.", "plain_english": "A project template is a ready-made Logic Pro starting point. It already has the tracks, instruments, and effects you use most set up for you. It is like a blank form with the common boxes already drawn in, so you just fill in the rest.", "purpose_function": "It saves setup time and keeps workflows consistent by letting an engineer reuse a standard track layout and signal routing every time a similar project begins.", "practical_application": "A podcast editor keeps a template with mic tracks, EQ, and a compressor already loaded, and starts each episode from it instead of building the session from scratch.", "category": "Project Management", "related_terms": ["Logic Pro project", "Channel strip", "Preset", "Routing", "Track stack"], "common_mistakes": ["Editing the template's contents inside a working session and accidentally overwriting the template itself", "Building overly complex templates that load many unused tracks and plug-ins", "Forgetting to save a new project under a fresh name, then working on the template file directly"], "scenario_contexts": ["Starting every mixing session with a standard bus and reference-track layout", "Setting up a band-tracking template with pre-labeled drum, bass, and vocal inputs", "Creating a mastering template with metering and a set gain-staging chain"]}, "381943e5-86df-4dae-a728-6075d3c0e6c7": {"definition": "In Steinberg Cubase, the Logical Editor is a tool that processes MIDI data by first selecting events that meet user-defined filter conditions, then applying chosen functions or transformations, such as changing pitch, velocity, or position, or deleting the matching events.", "plain_english": "The Logical Editor is a Cubase tool that finds MIDI notes matching rules you set, then changes them automatically. For example, find every note softer than a set level and make it louder. It works like search-and-replace, but for MIDI performance data.", "purpose_function": "It automates repetitive or conditional MIDI edits that would be slow to do by hand, letting an engineer target exactly the events they want and transform them in one pass.", "practical_application": "An engineer uses it to raise the velocity of all notes below a threshold, strip out a stuck controller message, or shift only the notes on one MIDI channel.", "category": "MIDI Editing", "related_terms": ["MIDI", "Velocity", "Quantize", "Key Editor", "Controller data"], "common_mistakes": ["Setting filter conditions with the wrong logic, so the editor selects far more or fewer events than intended", "Applying a transform to the whole part when only a selection was meant, altering unintended notes", "Confusing Cubase's Logical Editor with Logic Pro, which are unrelated products"], "scenario_contexts": ["Boosting the velocity of all quiet MIDI notes across a programmed drum part", "Deleting every stray pitch-bend event a controller left behind", "Selecting and nudging only the notes on a specific MIDI channel"]}, "1681b358-3af6-4be3-b4dd-0fef504db6b3": {"definition": "Long-term listening balance is how the relative levels and tonal weighting of elements in a mix hold up when heard over an extended, sustained listen rather than in brief moments, revealing whether each part stays intelligible and comfortable across a whole program.", "plain_english": "Long-term listening balance is how a mix feels over a full, long listen instead of a quick check. Some parts can sound fine for a few seconds but get tiring or hard to hear over a whole song. Engineers listen the long way to catch that.", "purpose_function": "It helps an engineer make balance decisions that stay right for a full track and repeated plays, avoiding choices driven by momentary impressions or ear fatigue.", "practical_application": "An engineer plays a full mix from start to finish, often at a low level, to check that vocals, bass, and drums stay balanced rather than judging from a few loud seconds of a chorus.", "category": "Mix Evaluation", "related_terms": ["Loudness balancing", "Reference track", "Monitoring level", "Gain staging", "Masking"], "common_mistakes": ["Judging balance only from short, loud snippets, which hides parts that become fatiguing over time", "Mixing at high levels for long stretches, letting ear fatigue skew balance decisions", "Never checking the mix at low volume, where long-term balance problems often show up"], "scenario_contexts": ["Checking a mix over a full playthrough before committing to fader levels", "Comparing balance at quiet monitoring levels to catch masking that builds over time", "Revisiting a mix the next day with fresh ears to confirm the balance still holds"]}, "717cc29b-72a1-4758-854c-97678469a279": {"definition": "Long-term preservation review is the periodic reassessment of archived digital audio and its metadata to confirm that files remain intact, readable, and stored in viable formats, so recordings stay accessible as storage media, file formats, and playback systems change over time.", "plain_english": "Long-term preservation review is a regular check-up on archived recordings. You make sure the files are not damaged, can still be opened, and are saved in formats future systems can read. It is like checking old photos in storage so they have not faded or gotten stuck in a dead format.", "purpose_function": "It exists to prevent slow loss of archived audio from bit errors, failing media, or obsolete formats by catching problems early and migrating or re-copying material before it becomes unrecoverable.", "practical_application": "An archivist runs scheduled integrity checks such as checksums on stored audio, verifies backups, and migrates files to current formats when the old ones near obsolescence.", "category": "Archiving", "related_terms": ["Checksum", "File format migration", "Backup", "Metadata", "Bit depth"], "common_mistakes": ["Assuming a single stored copy is safe, when media degrade and formats become unreadable over time", "Skipping integrity checks, so file corruption goes unnoticed until the audio is needed", "Not keeping metadata with the files, which makes archived audio hard to identify later"], "scenario_contexts": ["Running annual checksum verification on a studio's master archive", "Migrating older audio files to a current preservation format before the old codec is unsupported", "Auditing offsite backup copies to confirm they are still readable"]}, "4638813d-53ec-4af1-b2bb-8de9a86cacc6": {"definition": "The Loop Browser is the Logic Pro and GarageBand panel used to find, preview, and add Apple Loops, which are pre-recorded loops that match the project tempo and key, with searching and filtering by instrument, genre, and mood.", "plain_english": "The Loop Browser is the part of Logic Pro where you find ready-made loops to drop into your song. You can search by instrument, style, or mood, and preview them in time with your track before adding one. It is like a sound library you shop from inside the app.", "purpose_function": "It gives quick access to a large library of ready-made musical parts that automatically follow the project tempo and key, letting an engineer build or sketch arrangements without recording every part.", "practical_application": "A producer opens the Loop Browser, filters for a drum loop by genre, previews a few in time with the song, then drags the chosen one onto a track.", "category": "Content Browser", "related_terms": ["Logic Pro project", "Loop points", "Tempo", "Library", "Region"], "common_mistakes": ["Not realizing Apple Loops follow the project tempo and key, then being surprised when a loop changes pitch or speed", "Overusing stock loops, so tracks end up sounding generic", "Confusing audio loops and software-instrument loops, which edit differently"], "scenario_contexts": ["Auditioning drum loops in tempo while sketching a song idea", "Layering a percussion loop under a live recording", "Searching by mood to find a pad that fits a scene"]}, "bf65770b-e172-4bba-8300-1877889a47e4": {"definition": "Loop points are the start and end markers that define the portion of audio or a region that repeats: in a sampler they bracket the sustained segment of a sample that loops to hold a note, and in a DAW they set the boundaries of a cycled playback or recording region.", "plain_english": "Loop points are the start and end marks of the part that repeats. In a sampler, they pick the middle chunk of a sound that loops, so a held note can last as long as you want. In a DAW, they set the section that plays over and over.", "purpose_function": "They let a short recording sustain or repeat seamlessly, extending a sampled note indefinitely or cycling a section for practice, layering, and recording, without needing longer source material.", "practical_application": "A sound designer sets loop points inside the steady part of a sampled string so a held key sustains smoothly, while a mix engineer sets loop points to cycle a chorus during editing.", "category": "Editing & Navigation", "related_terms": ["Locators", "Cycle mode", "Crossfade", "Sample", "Sustain"], "common_mistakes": ["Placing sampler loop points where the waveform level or phase does not match, causing an audible click or thump at the seam", "Setting loop points across a changing part of the sound, so the loop sounds unnatural", "Confusing a DAW cycle loop with a sampler's sustain loop"], "scenario_contexts": ["Setting a seamless sustain loop inside a sampled organ note", "Cycling a two-bar drum section to overdub a part", "Trimming loop points to remove a click at the loop seam"]}, "2cbb270a-d359-4b7a-ab99-56aa63381dfa": {"definition": "Loudness balancing is adjusting the relative loudness of elements or programs so they sit at intended levels, either setting the levels of parts within a mix or matching perceived loudness across songs or program segments, typically judged by ear and by loudness meters reading LUFS/LKFS per ITU-R BS.1770 and EBU R128.", "plain_english": "Loudness balancing means setting how loud things are compared to each other. Inside a mix, it keeps each part at the right level. Across songs, it makes them feel equally loud, so listeners do not keep reaching for the volume knob. Engineers judge it by ear and with loudness meters.", "purpose_function": "It ensures no element is too loud or buried and that a set of tracks plays back at a consistent, comfortable loudness, which matters for both mix clarity and delivery standards.", "practical_application": "A mastering engineer uses a LUFS meter to match integrated loudness across an album, while a mix engineer balances vocal loudness so it stays consistent from verse to chorus.", "category": "Level & Loudness", "related_terms": ["LUFS", "Gain staging", "Long-term listening balance", "Dynamic range", "Reference track"], "common_mistakes": ["Judging loudness with peak meters instead of loudness (LUFS) meters, which do not reflect perceived loudness", "Balancing at different monitor volumes, so relative levels shift when the reference level changes", "Pushing overall loudness so hard that dynamics and balance are crushed"], "scenario_contexts": ["Matching integrated loudness across all tracks on an album", "Balancing dialog, music, and effects to a broadcast loudness target", "Setting element levels so the vocal stays consistent across a song's sections"]}, "15bf9ee5-ba3a-48b2-90c0-abb34bfb4ad7": {"definition": "The property of a mix, program, or catalogue holding a stable perceived loudness over time and from track to track, typically quantified as integrated loudness in LUFS per ITU-R BS.1770 and managed against a target such as EBU R128's -23 LUFS or a streaming reference near -14 LUFS.", "plain_english": "This means the sound stays about the same volume the whole way through, and from one song to the next. It is like keeping every plate of food at a party warm, so no one dish is cold. Listeners should not have to keep grabbing the volume knob.", "purpose_function": "It exists so listeners are not forced to keep adjusting volume, and so a mix meets broadcast and streaming loudness targets for fair, comfortable playback.", "practical_application": "An engineer reads integrated loudness on a meter across a whole track and compares songs on an album, riding levels or trimming master gain so nothing jumps out as far louder or softer.", "category": "Loudness", "related_terms": ["Loudness validation", "Loudness contour", "Integrated loudness (LUFS)", "Loudness normalization", "Dynamic range", "Metering"], "common_mistakes": ["Confusing loudness (LUFS) with peak level, and assuming a track that peaks at 0 dBFS is loud enough.", "Chasing one loud moment instead of measuring integrated loudness over the whole program.", "Crushing the dynamics with a limiter just to hit a loudness number, which harms the mix."], "scenario_contexts": ["Mastering an album so every track sits at a similar perceived level.", "Preparing a podcast so speech volume stays even across episodes.", "Delivering a mix to a streaming service that normalizes to about -14 LUFS."]}, "a17a83c8-ee15-4d8c-8225-a2295b57b59b": {"definition": "A curve mapping the sound pressure levels, across frequency, that are perceived as equally loud by the average listener, as standardized in the equal-loudness contours of ISO 226 (originally the Fletcher-Munson curves); it shows the ear is less sensitive to low and very high frequencies, especially at low levels, and it underlies the 'loudness' compensation control on playback gear.", "plain_english": "Our ears do not hear every pitch as equally loud. Deep bass and very high notes seem quieter than middle sounds, mostly when the volume is low. A loudness contour is a map of this, and it is why music can sound thin when you turn it down.", "purpose_function": "It describes how human hearing weights frequency against level, which is why bass seems to vanish at low volume and why 'loudness' buttons and tonal choices are used to make up for it.", "practical_application": "Engineers keep it in mind while mixing or checking at different monitor levels, knowing bass and treble balance shift with volume, and they avoid judging tone only at very quiet or very loud settings.", "category": "Loudness perception", "related_terms": ["Loudness consistency", "Fletcher-Munson curves", "Equalization", "Monitoring level", "Frequency response", "Phon"], "common_mistakes": ["Thinking the ear hears all frequencies equally at every volume.", "UNSAFE: Turning monitors up very loud just to 'hear the bass,' risking hearing damage instead of trusting metering and moderate levels.", "Setting bass balance at only one volume, then finding it wrong when the mix is played louder or softer."], "scenario_contexts": ["Explaining why a mix loses its bass when played quietly.", "Picking a steady reference monitor level so tonal balance is judged the same way each time.", "Understanding a hi-fi 'loudness' switch that boosts bass and treble at low volume."]}, "fec0bbfa-2c95-4a9d-9f6d-82e9b2873b92": {"definition": "The process of measuring a finished mix or master against a defined loudness delivery specification-integrated loudness, loudness range, and true-peak limits per standards such as EBU R128 or ATSC A/85 using ITU-R BS.1770 metering-to confirm it passes before delivery.", "plain_english": "This is the final check that a track meets the loudness rules a platform asks for. You measure the whole thing and make sure it is not too loud or too soft, and that the peaks are safe. It is like weighing a parcel before you post it to be sure it fits the limit.", "purpose_function": "It exists to catch loudness or true-peak problems before delivery, so a program is not rejected by a broadcaster or quietly turned down by a streaming service.", "practical_application": "An engineer runs a loudness meter or offline analysis over the final render, reads integrated LUFS, loudness range, and true-peak, and re-adjusts if any value falls outside the target spec.", "category": "Loudness", "related_terms": ["Loudness consistency", "Integrated loudness (LUFS)", "True-peak", "Loudness range (LRA)", "Delivery specification", "Metering"], "common_mistakes": ["Checking only the peak meter and ignoring integrated loudness and true-peak.", "Validating a single section instead of the whole program.", "Assuming inter-sample (true) peaks are safe just because sample peaks read below 0 dBFS."], "scenario_contexts": ["Confirming a TV mix meets -24 LKFS per ATSC A/85 before broadcast.", "Checking a master against a streaming loudness spec before upload.", "Quality-checking a batch of podcast episodes for a consistent target loudness."]}, "bc62385b-74aa-42b1-9a93-ea4bc65b39f8": {"definition": "A distinct element or group of elements in a mix that carries the low-frequency energy-such as a kick, bass guitar, synth sub, or an added sub-octave part-arranged so the bottom end is full and controlled without masking or phase conflict.", "plain_english": "This is the part of a mix that makes the deep, low sound you feel as much as hear. It usually comes from the kick drum and the bass. Building it well is like laying a solid foundation under a house.", "purpose_function": "It provides the weight and power at the bottom of a mix, and because low frequencies use a lot of energy and headroom, it is managed carefully so it stays tight and does not swamp the rest.", "practical_application": "A mixer balances kick and bass together, may add a sub layer to reinforce the lowest octave, and uses EQ, high-pass filtering, and mono placement to keep the low end clean and easy to translate.", "category": "Mix balance", "related_terms": ["Kick drum", "Bass management", "Sub-bass", "High-pass filter", "Frequency masking", "Mono compatibility"], "common_mistakes": ["Letting kick and bass fight in the same frequency range so the low end turns muddy.", "Judging bass balance on small speakers or earbuds that cannot reproduce it.", "Leaving low frequencies wide in stereo, which can weaken mono playback and vinyl cutting."], "scenario_contexts": ["Balancing kick and bass in a dance track.", "Adding a sub layer under a thin bass recording.", "High-passing non-bass tracks to clear room for the low end."]}, "77986925-d523-4ec1-b2d7-fe1fc0d91dda": {"definition": "In MIDI Polyphonic Expression (MPE), one of two configurable channel zones; the Lower Zone uses MIDI channel 1 as its Master Channel and assigns ascending Member Channels (from channel 2 upward) to individual notes, so each note has its own channel for per-note pitch bend and control. It contrasts with the Upper Zone, which uses channel 16 as its master.", "plain_english": "In a MIDI system called MPE, notes are spread across many channels so each note can bend and change on its own. The Lower Zone is one group of these channels, led by channel 1. Think of it as one team of channels with channel 1 as the captain.", "purpose_function": "It exists so an MPE controller can send separate expression for every note, using channel 1 as a shared master for zone-wide messages and individual member channels for each note's own control.", "practical_application": "A technician setting up an MPE controller and synth selects the Lower Zone, sets how many member channels it spans, and makes sure both devices agree so per-note slides and pressure work.", "category": "MIDI", "related_terms": ["Upper Zone", "MIDI Polyphonic Expression (MPE)", "MIDI channel", "Pitch bend", "Master channel", "Member channel"], "common_mistakes": ["Setting the controller and synth to different zones or channel counts, so notes do not respond.", "Expecting per-note pitch bend on a normal single-channel MIDI setup instead of an MPE zone.", "Confusing the zone's Master Channel with a member (per-note) channel."], "scenario_contexts": ["Configuring an MPE keyboard controller to play an MPE-capable synth.", "Setting up per-note pitch slides for a DAW software instrument.", "Troubleshooting why note expression is not passing between a controller and a plug-in."]}, "3d70390a-e8d8-4719-a399-37f2b454684f": {"definition": "Large-scale change across a piece-shifts in energy, arrangement density, dynamics, or texture between whole sections such as verse and chorus-as opposed to micro variation in small, moment-to-moment detail; it shapes the overall dynamic journey of a mix.", "plain_english": "This is the big-picture change in a song from one part to the next. A quiet verse that grows into a loud chorus is macro variation. It is like the rise and fall of a story, not the tiny details inside each line.", "purpose_function": "It exists to give a track contrast and momentum over its whole length, keeping the listener engaged as sections build, drop, and lift.", "practical_application": "In mixing and arrangement, an engineer uses level rides, mutes, added parts, and dynamic contrast so sections differ in energy, protecting the impact of a chorus or drop.", "category": "Arrangement", "related_terms": ["Micro variation", "Dynamic range", "Arrangement", "Automation", "Macrodynamics", "Section contrast"], "common_mistakes": ["Making every section the same loudness so the song feels flat and tiring.", "Confusing macro variation (whole sections) with micro detail (single notes or hits).", "Using a heavy limiter that flattens the loud-quiet contrast between sections."], "scenario_contexts": ["Planning for a verse to sit lower in energy than the chorus.", "Automating levels so a bridge pulls back before the final chorus.", "Reviewing a mix to check that sections have enough contrast."]}, "dd908d12-99e3-45b1-b613-12b52549447c": {"definition": "The primary mixing console or software mixer through which the main signals of a session are summed, processed, and routed to the master output, as distinct from sub-mixers, monitor mixers, or auxiliary buses.", "plain_english": "The main mixer is the central desk where all the sound channels are blended together. It sets each part's volume and tone and sends out the final mix. Think of it as the control center for the whole sound.", "purpose_function": "It exists to combine every input into one balanced final mix and route that mix to the main outputs, giving a single place to control levels, tone, and effects.", "practical_application": "An engineer sets channel levels, EQ, and sends on the main mixer to build the front-of-house or recording mix, then routes its master bus to the amplifiers or recorder.", "category": "Mixing", "related_terms": ["Mix bus", "Master fader", "Submix", "Auxiliary send", "Channel strip", "Front of house"], "common_mistakes": ["Pushing every channel fader up instead of balancing them, which clips the main bus.", "UNSAFE: Sending a hot, clipping main mix into powered speakers or amplifiers without proper gain staging, which can damage drivers.", "Confusing the main mix bus with a monitor or aux mix and adjusting the wrong one."], "scenario_contexts": ["Building a front-of-house mix at a live show.", "Summing all tracks to a stereo master bus in a studio session.", "Routing the main mix to a recorder for a live capture."]}, "fd606cd4-fcae-42d6-ab69-2efb6f3ed026": {"definition": "In a DAW or audio application, the primary application window that hosts the core workspace-typically the arrangement/edit area, transport, and track layout-from which other windows such as the mixer, editors, or plug-in windows are opened.", "plain_english": "The main window is the first big screen you see in your music software. It shows your tracks and the timeline, and it is where you do most of your work. Other panels, like the mixer, open from it.", "purpose_function": "It exists as the central hub of the program's interface, giving quick access to tracks, the timeline, transport controls, and the menus that open every other tool.", "practical_application": "A technician records, arranges, and edits in the main window, opens the mixer or plug-in windows from it, and arranges the layout to suit the task at hand.", "category": "DAW interface", "related_terms": ["Arrange view", "Mixer window", "Transport", "Track", "Timeline", "Marker List"], "common_mistakes": ["Losing a floating window off-screen and thinking the program has frozen.", "Confusing the main arrange window with the separate mixer window.", "Not saving a window layout, so the workspace resets every session."], "scenario_contexts": ["Opening a DAW project and seeing the tracks in the main window.", "Switching between the main window and the mixer while balancing a mix.", "Setting up one screen layout for editing and another for mixing."]}, "8ba43b12-06ac-44b1-848d-977662bf19a4": {"definition": "A DAW feature that shows all markers (cue points or memory locations) placed on the timeline as a navigable list, letting the user name, edit, and jump to specific positions such as song sections, edit points, or sync references.", "plain_english": "A marker list is like a set of bookmarks for your song. Each marker points to a spot on the timeline, such as the chorus or a scene change. You click one to jump straight there.", "purpose_function": "It exists to speed up navigation and organization, letting an engineer label sections and move instantly to any point instead of scrolling through the whole project.", "practical_application": "An engineer drops markers at section starts, edit points, or sync cues, names them, and uses the marker list to jump between them while editing, mixing, or working with a client.", "category": "DAW navigation", "related_terms": ["Marker", "Memory location", "Timeline", "Locate", "Cue point", "Main window"], "common_mistakes": ["Leaving markers unnamed, so the list is hard to read later.", "Confusing timeline markers with clip or arrangement locators.", "Forgetting that markers are saved with the project and re-creating them each time."], "scenario_contexts": ["Labeling verse, chorus, and bridge for fast navigation in a mix.", "Marking edit or sync points when working to picture.", "Jumping between sections during a client revision session."]}, "10b68ba3-41c6-455c-a191-de3bd533c175": {"definition": "In Pro Tools, a Memory Location configured as a Marker: a saved reference point tied to a timeline position that names and flags a spot in the session, appearing in the Markers ruler and the Memory Locations window for instant recall.", "plain_english": "It is a saved bookmark on the timeline. You give it a name and a spot, then jump straight to it later instead of scrolling around to find it.", "purpose_function": "It lets an engineer label and instantly recall key spots such as verse, chorus, or an edit point, so navigation and communication during editing and mixing stay fast and consistent.", "practical_application": "A technician drops markers at each song section, then presses the marker's number on the numeric keypad to jump the playhead there while editing or mixing.", "category": "Session Navigation", "related_terms": ["Marker track (Logic)", "Marquee selection", "Playhead", "Timeline", "Loop points"], "common_mistakes": ["Confusing a Marker Memory Location with a Selection Memory Location, which recalls a highlighted range rather than a single point.", "Assuming markers always move with edits; when tied to absolute time, inserting or deleting audio can misalign them unless they are tied to bars and beats.", "Leaving markers unnamed, which makes the Memory Locations list hard to read and defeats the purpose."], "scenario_contexts": ["Marking song sections before a mix so the team can jump between verse and chorus quickly.", "Flagging a spot that needs a fix during a tracking session for later attention.", "Setting recall points to speed up punch-in recording."]}, "c28a5bb6-9ae7-4f50-a595-7f061fffb249": {"definition": "In Logic Pro, the Marker track is a global track that displays markers along the timeline; markers are named positional reference points used to label sections of a project and to navigate or select between them.", "plain_english": "It is a strip above your song that holds named bookmarks. You can see each part, like intro or chorus, and click to jump to it.", "purpose_function": "It provides a visual map of a project's structure with quick navigation, so an arrangement's sections are easy to find, name, and move between.", "practical_application": "An engineer opens the global tracks, adds markers on the Marker track at each section, then uses them to navigate or to set a cycle range while editing.", "category": "Session Navigation", "related_terms": ["Marker Memory Location", "Global tracks", "Arrangement markers", "Cycle range", "Playhead"], "common_mistakes": ["Confusing the Marker track (section labels) with Arrangement markers, which actually reorder sections of the project.", "Hiding the global tracks and assuming the markers were deleted.", "Leaving markers unnamed, which loses the navigation benefit."], "scenario_contexts": ["Labeling intro, verse, and chorus before editing a song in Logic.", "Jumping the playhead to a marked section during a mix revision.", "Setting a cycle range around a marked section for looped playback."]}, "ae190748-c18d-4168-8e9e-268b9e027cac": {"definition": "A time-and-track selection made by dragging a rectangle (marquee) across a portion of one or more tracks, as with Logic Pro's Marquee tool, highlighting a range independent of region boundaries for editing, cutting, or processing.", "plain_english": "You drag a box over part of your audio to highlight just that piece. It is like using a highlighter to pick out one section, even across several tracks.", "purpose_function": "It lets you select and act on any span of material regardless of where regions start or end, so precise edits, splits, and deletions do not require cutting regions first.", "practical_application": "An editor drags a marquee over a bad breath or a section across multiple tracks, then deletes, fades, or replaces just that range in one action.", "category": "Editing", "related_terms": ["Marquee tool", "Region", "Playhead", "Marker track (Logic)", "Crossfade"], "common_mistakes": ["Thinking a marquee selection permanently splits regions; it only defines a range until you act on it.", "Forgetting that a marquee spanning several tracks edits all of them at once.", "Confusing the marquee (a time range) with selecting a whole region."], "scenario_contexts": ["Deleting a cough across all tracks of a live recording.", "Selecting a two-bar range to apply a fade or gain change.", "Setting the playback start point by clicking within a marquee selection."]}, "d5dc96ac-67f2-456f-9314-b93b94122339": {"definition": "A structured list of verification items completed before a final master is approved for delivery, typically covering integrated loudness, true-peak level, format and sample-rate compliance, metadata, fades and spacing, and quality checks, confirming the master meets delivery specifications.", "plain_english": "It is a to-do list you check off before calling a master finished. It makes sure the loudness, levels, and file details are all correct before you send it out.", "purpose_function": "It exists to catch errors before release, making sure a master meets loudness, peak, format, and metadata requirements consistently rather than relying on memory.", "practical_application": "Before sending a master to a client or distributor, an engineer runs down the checklist, confirming integrated loudness, true-peak ceiling, sample rate, fades, and metadata, and only then signs off.", "category": "Quality Control", "related_terms": ["Master readiness", "Integrated loudness", "True-peak", "Metadata", "Dither"], "common_mistakes": ["Checking only sample-peak level and ignoring integrated loudness or true-peak, which can trigger platform normalization or inter-sample clipping.", "Skipping format and sample-rate checks and delivering the wrong file specification.", "Approving without a reference check on more than one playback system."], "scenario_contexts": ["Final sign-off before uploading a master to a streaming distributor.", "Preparing deliverables for a client with specific loudness and format specs.", "A quality-control pass before a mastering session is archived."]}, "e412bec3-ceda-4639-9184-6fc9c9fbe96f": {"definition": "In iZotope Ozone, Master Assistant is an assistive feature that analyzes an input track and generates a custom starting mastering chain, setting module parameters toward a chosen target or reference loudness and tonal profile as a first-draft master the engineer then refines.", "plain_english": "It is a smart helper in mastering software that listens to your song and builds a rough first master for you. You then tweak it, instead of starting from nothing.", "purpose_function": "It speeds up mastering setup by suggesting EQ, dynamics, and loudness settings matched to the material or a reference, giving a useful starting point rather than a blank slate.", "practical_application": "An engineer plays the loudest section through Ozone's Master Assistant, picks a target or reference, and gets an initial chain that they audition and adjust before finalizing.", "category": "Mastering Workflow", "related_terms": ["Master-bus compression", "Reference track", "Integrated loudness", "Master readiness", "Master approval checklist"], "common_mistakes": ["Treating the Assistant's output as a finished master rather than a starting point to refine.", "Feeding it a quiet or unrepresentative section so it mis-targets loudness and tone.", "Ignoring the target or reference choice, which drives all of its decisions."], "scenario_contexts": ["Getting a quick first-pass master to audition against a reference track.", "Setting a loudness target for a streaming release.", "Giving a beginner a plausible starting mastering chain to learn from."]}, "5883227f-0b57-49c4-9069-3d7cf8c09c22": {"definition": "Effects processing inserted on the master (main) output bus so it acts on the entire summed mix, for example EQ, compression, limiting, or saturation applied to the stereo output rather than to an individual channel.", "plain_english": "These are effects placed on the final output where all tracks meet. Whatever you add here changes the whole song at once, not just one instrument.", "purpose_function": "It exists to glue, shape, and control the overall mix, balancing tone, controlling dynamics, and setting final level, because these processes act on the combined signal.", "practical_application": "A mixer adds gentle bus compression, a corrective EQ, and a limiter to the master FX chain to tighten and level the full mix before bouncing.", "category": "Mix Bus Processing", "related_terms": ["Master-bus compression", "Master track (Live)", "Limiter", "Mix bus", "Master readiness"], "common_mistakes": ["Over-processing the master bus so individual balance problems get masked instead of fixed within the mix.", "Leaving heavy master FX active while still mixing, which skews level and tone decisions.", "Bouncing with a monitoring-only limiter that was never meant to be part of the final file."], "scenario_contexts": ["Adding mix-bus glue compression across a full song.", "Placing a limiter on the main output to hit a rough loudness for a demo.", "Applying corrective EQ to the whole mix before it goes to mastering."]}, "8d712277-6a79-438e-9d8a-1716d126a612": {"definition": "The condition of a mix or master meeting the technical and creative criteria needed to advance to the next stage, such as a mix with adequate headroom, no clipping, and balanced tonality ready for mastering, or a master meeting loudness, peak, and format specs ready for delivery.", "plain_english": "It means a mix or master is truly finished and safe to hand off. The levels, headroom, and file details are all in good shape for the next step.", "purpose_function": "The idea exists to define a clear go/no-go point, preventing unfinished or technically flawed audio from moving on to mastering or release.", "practical_application": "Before exporting a mix for mastering, a technician confirms readiness by leaving headroom, removing any master limiter, and checking for clipping, so the mastering engineer receives a clean file.", "category": "Quality Control", "related_terms": ["Master approval checklist", "Headroom", "Master-bus compression", "Integrated loudness", "Bounce"], "common_mistakes": ["Exporting a mix for mastering with a limiter or heavy bus processing crushing the peaks, leaving no room to work.", "Assuming loud equals ready and ignoring headroom and clipping.", "Delivering without checking sample rate, bit depth, and true-peak level."], "scenario_contexts": ["Deciding a mix is ready to send to a mastering engineer.", "Confirming a master meets a distributor's loudness and format specs before release.", "Signing off a stem delivery for a client."]}, "bc4ee777-58f5-4164-9326-e71a3e6fe45c": {"definition": "In Ableton Live, the Master track (renamed the Main track in Live 11) is the fixed output track through which all other tracks are summed; it hosts the final level control, panning, and any master-bus devices before the signal reaches the audio output.", "plain_english": "In Ableton Live, it is the single track where every other track flows together. It sets the final volume and holds effects that shape the whole song.", "purpose_function": "It exists as the common summing point and final output stage, giving one place to control overall level and apply mix-bus processing to the entire mix.", "practical_application": "A producer sets the Master track fader for final level, adds a limiter or EQ there, and watches its meter to avoid clipping the output.", "category": "Signal Routing", "related_terms": ["Master FX", "Master-bus compression", "Mix bus", "Return track", "Limiter"], "common_mistakes": ["Confusing the Master track with a Return track; the Master is the final sum, not an aux send destination.", "Pushing the Master fader to fix balance instead of adjusting the individual tracks.", "Clipping the Master output because too many tracks sum too hot."], "scenario_contexts": ["Setting final output level and metering in an Ableton Live set.", "Placing a master limiter before exporting.", "Routing the sum of all tracks for mix-bus processing."]}, "1ced54d9-73eb-4f73-9b1b-b8ff126a53ff": {"definition": "Dynamic-range compression applied to the master (mix) bus, the summed stereo output, typically at low ratios and small amounts of gain reduction to control overall dynamics and glue the mix's elements into a cohesive whole.", "plain_english": "It is gentle compression on the final mix, where all tracks meet. It smooths the loud and soft parts a little and helps everything sound like one blended track.", "purpose_function": "It reduces overall dynamic swings and improves cohesion between elements, and can add subtle loudness and punch, because it acts on the combined mix rather than a single channel.", "practical_application": "A mixer inserts a compressor on the mix bus, sets a low ratio around 1.5:1 to 2:1 with roughly 1 to 3 dB of gain reduction, and times the attack and release to breathe with the tempo.", "category": "Mix Bus Processing", "related_terms": ["Master FX", "Master track (Live)", "Mix bus", "Makeup gain", "Limiter"], "common_mistakes": ["Applying too much gain reduction, which squashes transients and flattens the mix.", "Setting the attack too fast so it kills punch, or the release wrong so it pumps unintentionally.", "Adding it late and re-balancing everything, instead of mixing into it from early in the session."], "scenario_contexts": ["Gluing a full band mix with 1 to 2 dB of gain reduction.", "Adding cohesion and subtle level to a mix before it goes to mastering.", "Mixing into a bus compressor from the start of a session."]}, "9e536c6a-8f79-451e-a32b-7e1872c61bce": {"definition": "In REAPER (Cockos), the Media Explorer is a docked browser window used to navigate the file system, audition audio and MIDI files, and insert them into a project. It can auto-match a previewed loop to the project tempo and pitch before import.", "plain_english": "It is a file browser built into the REAPER program. You use it to find sound files on your computer, listen to them, and drop the ones you like into your song.", "purpose_function": "It gives a technician one place to search, audition, and import media without leaving the DAW, which speeds up choosing loops and samples.", "practical_application": "A technician opens the Media Explorer to browse a sample library, plays a loop to hear it in time with the project, then drags it onto a track.", "category": "DAW Feature", "related_terms": ["Media item", "MediaBay", "Audio import", "Loop", "Project tempo", "Sample library"], "common_mistakes": ["Confusing previewing a file with inserting it; auditioning does not add the file to the project.", "Forgetting that tempo-matching is applied on import, so loops get time-stretched and can sound different from the raw file.", "Assuming the browser edits or moves the source files on disk rather than just pointing to them."], "scenario_contexts": ["Auditioning drum loops against a project's tempo before committing them to a track.", "Importing a folder of recorded takes into a mix session.", "Searching a sample library for a specific one-shot during sound design."]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"0ff0319f-ca7a-40a4-a172-96076131af31": {"definition": "In REAPER, a media item is the basic container object placed on a track's timeline that references source media (audio or MIDI) and holds one or more takes. Editing operations such as trimming, fades, moving, and splitting act on the media item rather than on the underlying source file.", "plain_english": "A media item is one block of sound or MIDI sitting on a track's timeline. You move, cut, and fade these blocks to build your song, and doing so does not change the original file on your drive.", "purpose_function": "It lets the DAW arrange and edit recorded or imported media on the timeline without altering the source files, keeping editing non-destructive.", "practical_application": "A technician trims, splits, and crossfades media items to comp takes and tighten an arrangement on the timeline.", "category": "DAW Feature", "related_terms": ["Media Explorer", "Take", "Non-destructive editing", "Clip", "Crossfade", "Timeline"], "common_mistakes": ["Thinking that deleting a media item deletes the source audio file; it only removes the reference from the project.", "Confusing a media item with a take, when one item can hold several takes.", "Assuming edits to the item change the source file, rather than just the item's view of it."], "scenario_contexts": ["Splitting a vocal recording into media items to comp the best phrases.", "Crossfading two adjacent media items to hide an edit point.", "Moving a media item to line a sound effect up with a video cue."]}, "4beff751-2070-4f18-a253-9fb487f0c5e8": {"definition": "MediaBay is Steinberg's media-management system in Cubase and Nuendo: a database-backed browser for finding, previewing, tagging, and organizing audio files, MIDI loops, presets, and track presets across the system using attribute filters and text search.", "plain_english": "MediaBay is a search tool inside Cubase and Nuendo. It scans your drives so you can find, tag, and preview sounds, loops, and presets, a bit like a search engine for your own audio files.", "purpose_function": "It indexes a user's media and presets so they can be found by attributes such as tempo, key, or category instead of by remembering folder paths.", "practical_application": "A technician tags a sample library once, then uses MediaBay filters to pull up, for example, all 120 BPM minor-key drum loops during a session.", "category": "DAW Feature", "related_terms": ["Media Explorer", "Preset", "Track preset", "Loop", "Metadata", "Attribute"], "common_mistakes": ["Expecting MediaBay to find files it has never scanned; folders must be indexed first.", "Confusing MediaBay's attribute tags with the file's own embedded metadata.", "Assuming a rating or tag edits the file itself rather than MediaBay's database."], "scenario_contexts": ["Building a tagged loop library for fast recall across projects.", "Filtering presets by category when searching for a synth patch.", "Auditioning construction-kit loops in key and tempo before dragging them in."]}, "1e1f49c6-1927-47f8-9a06-6763fa524d42": {"definition": "A melody layer is one of the sound sources or tracks in an arrangement that carries the primary melodic line, often stacked or doubled with other timbres to thicken and reinforce the tune. As a layer, it is one element among several combined to build the full melodic part.", "plain_english": "The melody layer is the part of a song that plays the main tune. Producers often stack two or more sounds on the same notes, like several singers on one line, to make the melody fuller and stronger.", "purpose_function": "It gives the melody more weight, character, or width by combining several sounds on the same line, and lets a mixer balance each contribution on its own.", "practical_application": "A producer layers a lead synth with a doubled octave or a plucked sound to reinforce the melody, then balances the layers in the mix.", "category": "Arrangement", "related_terms": ["Layering", "Doubling", "Lead", "Arrangement", "Countermelody", "Timbre"], "common_mistakes": ["Stacking too many melody layers so the parts mask each other and the tune loses clarity.", "Layering sounds that are out of tune or out of phase, which weakens rather than reinforces the melody.", "Forgetting to balance the level of each layer, letting one sound dominate the line."], "scenario_contexts": ["Doubling a vocal melody with a synth to add width in a pop production.", "Stacking octaves on a lead line so a hook cuts through a busy mix.", "Blending a soft and a bright sound so the melody layer sits well in the arrangement."]}, "63bdb03b-b5f7-40d3-94e2-2f8b124095c6": {"definition": "Menu music is the looping musical cue that plays behind the menu, title, or pause screens of a video game, DVD/Blu-ray, or other interactive media. It is written to loop seamlessly and to set tone while the user navigates, distinct from in-scene or gameplay score.", "plain_english": "Menu music is the tune that plays while you sit on a game's start or pause screen. It is written to loop over and over without an obvious join, so it can keep going for as long as the player stays on the menu.", "purpose_function": "It sets mood and keeps the interface feeling alive while the user makes choices, filling time of unknown length, which is why it must loop cleanly.", "practical_application": "A composer or editor prepares a seamless loop and sets loop points so the menu track repeats without a click or gap during navigation.", "category": "Interactive Audio", "related_terms": ["Loop", "Seamless loop", "Game audio", "Underscore", "Stinger", "Ambience"], "common_mistakes": ["Creating a loop with an audible seam or gap at the loop point, so the repeat is obvious.", "Making menu music too loud or too busy, so it competes with menu sound effects and voice.", "Writing the cue to end rather than loop, forgetting it may play for an unknown length of time."], "scenario_contexts": ["Scoring the title screen of a video game with a looping theme.", "Providing background music for a DVD or Blu-ray menu.", "Composing a calm loop for a game's pause or settings screen."]}, "93ef30dc-c66f-4fd9-99a9-a079d090d038": {"definition": "A metadata validation report is the output of a check that confirms a media file's metadata conforms to a required delivery specification or schema. It lists which fields are present, correctly formatted, and within allowed values, and flags any that are missing or non-compliant.", "plain_english": "It is a checklist result that shows whether a file's information tags meet the rules a broadcaster or platform requires. It tells you which tags are correct and which are missing or wrong, so you can fix them before you send the file.", "purpose_function": "It catches metadata errors before a file is delivered, so a program is not rejected for wrong titles, IDs, timecodes, or audio-track labels.", "practical_application": "Before delivering a program, a technician runs an automated check against the delivery spec and uses the validation report to correct any failed metadata fields.", "category": "Delivery/QC", "related_terms": ["Metadata", "Delivery specification", "Quality control", "Timecode", "Loudness compliance", "Broadcast delivery"], "common_mistakes": ["Treating a passed validation report as proof the picture and sound are correct; it only checks metadata, not content.", "Acting only on hard failures and ignoring warnings, then having the file rejected on delivery.", "Assuming embedded metadata matches the sidecar or delivery document without validating it."], "scenario_contexts": ["Checking an AS-11 broadcast master against a broadcaster's delivery spec.", "Validating loudness and program metadata before uploading to a streaming platform.", "Confirming timecode and track-layout metadata on a finished deliverable."]}, "f96904b8-9222-4ab3-8aea-cf3eb869f378": {"definition": "Microtiming refers to small, expressive deviations in the timing of musical events relative to the underlying metric grid or beat, usually on the order of a few to tens of milliseconds. These deviations shape the groove or feel of a performance and can be preserved, added, or reduced through quantize settings and groove templates.", "plain_english": "Microtiming is the tiny push and pull in when notes are played, just ahead of or behind the strict beat. These small shifts are what make a groove feel human or laid-back instead of stiff and robotic.", "purpose_function": "It carries the human feel and groove of a performance, which is why producers control it with quantize strength and groove templates instead of snapping everything hard to the grid.", "practical_application": "A technician applies a groove template or lowers quantize strength to keep some microtiming, so a programmed drum part grooves instead of sounding mechanical.", "category": "Timing", "related_terms": ["Quantize", "Groove template", "Swing", "Humanize", "Grid", "Nudge"], "common_mistakes": ["Quantizing everything to full strength and removing the microtiming that gave the part its feel.", "Confusing microtiming with tempo changes; microtiming shifts individual hits, not the overall speed.", "Assuming any timing offset is an error to fix rather than intentional feel."], "scenario_contexts": ["Extracting a groove template from a live drummer to apply its microtiming to programmed parts.", "Loosening quantize on a hi-hat pattern so it grooves.", "Nudging a bass note slightly behind the kick to create a laid-back feel."]}, "dcc754a1-9fd0-4dbb-baac-38f365851fb2": {"definition": "A MIDI Editor is a DAW window for viewing and editing the MIDI data on a part or track, including note pitch, start, length, and velocity plus controllers such as pitch bend and modulation, most commonly shown as a piano-roll grid. It edits performance data, not audio.", "plain_english": "The MIDI Editor is the screen where you draw and change the notes a virtual instrument will play. Notes usually show as bars on a grid next to a piano keyboard, so you can move, lengthen, or delete them by hand.", "purpose_function": "It lets a technician correct and shape MIDI performances, fixing wrong notes, timing, and loudness, before those notes are turned into sound by an instrument.", "practical_application": "A technician opens the MIDI Editor to fix a wrong note, adjust velocities for dynamics, and quantize the timing on a recorded keyboard part.", "category": "MIDI", "related_terms": ["Piano roll", "Velocity", "Quantize", "MIDI note", "Controller data", "Key Editor"], "common_mistakes": ["Editing MIDI notes and expecting the audio waveform to change, forgetting the sound comes from the instrument playing the notes.", "Confusing note velocity with track volume; velocity sets how hard each note is played.", "Overwriting recorded controller data by drawing over it without checking what is already there."], "scenario_contexts": ["Correcting a fluffed note in a recorded piano performance.", "Drawing in a hi-hat pattern step by step for a drum machine.", "Editing velocities to add dynamics to a stiff programmed part."]}, "288d11ae-7d7c-4dd0-b4a2-24575c0b4401": {"definition": "In Ableton Live, 'MIDI From' is the upper input-routing chooser in a MIDI track's In/Out section that selects the source of incoming MIDI for that track, such as an external hardware input, another track, or a plug-in, together with the specific MIDI channel. A separate Monitor setting then determines when that input is passed through.", "plain_english": "'MIDI From' is the menu in Ableton Live that picks where a track's MIDI notes come in from, such as a keyboard or another track. You choose the source and the MIDI channel so the track listens to the right controller.", "purpose_function": "It routes control data into a track so the right MIDI source drives that track's instrument, and it lets one track's MIDI feed another for layering or processing.", "practical_application": "A technician sets 'MIDI From' to a keyboard's input and channel to record a part, or points one MIDI track's input at another track to stack instruments.", "category": "MIDI", "related_terms": ["MIDI Editor", "Input routing", "Monitor", "MIDI channel", "Track routing", "Audio From"], "common_mistakes": ["Leaving 'MIDI From' on the wrong source or channel, so the track receives no notes.", "Confusing 'MIDI From' input routing with 'MIDI To' output routing.", "Forgetting that the Monitor setting, not just 'MIDI From', controls whether the input is heard."], "scenario_contexts": ["Selecting a hardware keyboard as a track's MIDI input before recording.", "Routing one MIDI track to another to layer two instruments from one part.", "Choosing a specific MIDI channel to separate parts from a multi-timbral controller."]}, "c3b7b122-71f6-4240-8cda-77bb7c297054": {"definition": "In Steinberg Cubase, a MIDI Part is a container object on a MIDI or Instrument track that holds MIDI events such as notes and controller data. It appears as a block in the Project window and is opened in an editor (Key, Drum, or List Editor) to edit the events it contains.", "plain_english": "In Cubase, a MIDI part is a block on a MIDI track that holds the notes you played. You can move or copy the whole block, then open it to change the notes inside. It is like a folder that keeps one section of your performance together.", "purpose_function": "It groups MIDI events into a single moveable, copyable object so a performance can be arranged, repeated, and edited as one unit instead of one note at a time.", "practical_application": "A technician records or draws a MIDI passage, then drags, copies, or loops the resulting Part along the timeline and double-clicks it to edit notes and velocities in the Key Editor.", "category": "MIDI Sequencing", "related_terms": ["MIDI event", "Instrument track", "Key Editor", "Quantize", "Piano roll"], "common_mistakes": ["Confusing a MIDI Part (a container of MIDI data) with an audio event (recorded audio).", "Assuming the Part contains the sound itself, when the actual sound comes from the instrument the track feeds.", "Trimming a Part so that notes falling outside its boundaries stop playing."], "scenario_contexts": ["Recording a synth bassline on an Instrument track and looping the resulting MIDI Part across the chorus.", "Double-clicking a MIDI Part to fix a wrong note in the Key Editor.", "Copying a drum MIDI Part to repeat a groove through a verse."]}, "f1777319-c7e5-4ec5-9006-9f2877965cc0": {"definition": "In Ableton Live, 'MIDI To' is the output chooser in a track's In/Out section that sets where the track's MIDI signal is sent, typically to another track (to play that track's instrument) or to an external MIDI port or device.", "plain_english": "In Ableton Live, 'MIDI To' picks where a track sends its MIDI notes. You can send those notes to another track so it plays the sound, or send them out to a hardware synth. Think of it as choosing which instrument should listen to this track.", "purpose_function": "It lets one track's notes drive an instrument on a different track or on outboard gear, so where notes are played can be separated from where they make sound.", "practical_application": "A technician sets 'MIDI To' on a track to a software-instrument track (and picks its input) to layer sounds, or routes it to an external MIDI output to trigger a hardware synth.", "category": "MIDI Routing", "related_terms": ["MIDI From", "Instrument track", "MIDI channel", "External Instrument", "Track monitoring"], "common_mistakes": ["Setting 'MIDI To' but forgetting to arm or monitor the destination track, so no sound is heard.", "Confusing 'MIDI To' (the output destination) with 'MIDI From' (the input source).", "Leaving the destination's MIDI input set to 'No Input' so the routed notes never reach its instrument."], "scenario_contexts": ["Routing a MIDI clip to a hardware synth's MIDI input for tracking.", "Layering two instrument tracks by sending one track's MIDI to the other.", "Sending MIDI to an External Instrument device to play outboard gear in time."]}, "8aeeff96-eae0-4bec-9538-97fc947c7b46": {"definition": "Mixing around the vocal is a vocal-centric mixing approach in which the lead vocal is established as the focal point first, and every other element's level, EQ, panning, and effects are then shaped to support the vocal and stay out of its way.", "plain_english": "Mixing around the vocal means you make the singing the star first, then fit everything else around it. You turn down or carve out sounds that fight the voice so the words stay clear. It is like framing a photo so the main person is never blocked.", "purpose_function": "In most vocal music the voice carries the song, so building the mix around it keeps the lyrics and melody clear and emotionally front-and-center.", "practical_application": "A technician sets the vocal level and tone first, then uses EQ carving, panning, and sometimes ducking on competing parts so nothing masks the voice.", "category": "Mixing Technique", "related_terms": ["Frequency masking", "EQ carving", "Static mix", "Sidechain ducking", "Level balance"], "common_mistakes": ["Mixing the backing tracks loud first, then finding there is no space left for the vocal.", "Fixing vocal masking only by raising the vocal instead of carving the competing parts.", "Forgetting to check the vocal balance on several playback systems."], "scenario_contexts": ["Balancing a dense pop production so the lead vocal stays clear and intelligible.", "Carving guitars and synths that mask a vocal in the same frequency range.", "Setting the vocal first as the anchor for the rest of the mix."]}, "33604de0-8e35-451a-8d97-f2916bb5e5b3": {"definition": "Mix Assistant is an assistive feature in modern mixing software (such as iZotope Neutron) that analyzes the tracks in a session and automatically sets a starting balance of relative levels, usually built around a user-chosen focus element, to provide a quick rough starting point for a mix.", "plain_english": "Mix Assistant is a smart tool that listens to all your tracks and sets a rough volume balance for you. You tell it which part matters most, like the vocal, and it turns the others up or down to fit. It gives you a fast starting point that you then finish by ear.", "purpose_function": "It speeds up the slow first step of getting faders roughly balanced, giving a beginner or a busy engineer a coherent starting mix to refine by ear.", "practical_application": "A technician loads the assistant, selects the lead vocal as the focus, lets it set initial levels across the session, then adjusts each fader by ear from there.", "category": "Mixing Tools", "related_terms": ["Gain staging", "Static mix", "Reference track", "Level balance", "Focus track"], "common_mistakes": ["Treating the assistant's result as a finished mix rather than a rough starting point.", "Skipping proper gain staging first, which skews the levels the tool suggests.", "Assuming it replaces critical listening and arrangement decisions."], "scenario_contexts": ["Building a fast rough balance on a large session before detailed mixing.", "Setting starting levels around a lead-vocal focus.", "Teaching a beginner how relative levels shape a mix."]}, "0c5f8fd7-ea27-42e2-9e6a-92d4aec7126e": {"definition": "Mixing by meters is the practice of making level and balance decisions mainly from visual meter readings (peak, RMS, VU, or LUFS) rather than from critical listening; meters serve as an objective reference but are not a substitute for judging the mix by ear.", "plain_english": "Mixing by meters means setting your levels by watching the screen instead of trusting your ears. Meters are useful guides, but they cannot tell you if a mix sounds good. Skilled engineers glance at meters but make the real call by listening.", "purpose_function": "Meters give an objective reference for level, headroom, and loudness targets, which helps keep gain staging safe and delivery loudness on spec.", "practical_application": "A technician checks meters to confirm headroom and hit a LUFS target, but sets the actual balance of instruments by ear on trusted monitors.", "category": "Mixing Technique", "related_terms": ["LUFS", "Gain staging", "Headroom", "VU meter", "Reference track"], "common_mistakes": ["Setting instrument balance purely by matching meter numbers instead of listening.", "Trusting one meter type for a job it is not designed for, such as using peak meters to judge loudness.", "Treating meters as the only truth and ignoring the room and monitors."], "scenario_contexts": ["Confirming headroom before printing a mix.", "Meeting a streaming loudness target in LUFS.", "Matching rough levels between song sections while still checking by ear."]}, "52061b1f-fa4e-4527-93ae-df7375ba7a74": {"definition": "A mix channel is a single signal path in a mixing console or DAW mixer that carries one source and provides controls such as input gain, EQ, dynamics, sends, pan, and a fader before the signal is routed to a bus or the main output.", "plain_english": "A mix channel is one strip in the mixer that handles a single sound, like the kick drum or a vocal. It has its own volume fader, tone controls, and knobs. Using one channel per source lets you shape each sound on its own.", "purpose_function": "It isolates one source so its level, tone, and effects can be controlled independently before all the channels are blended together.", "practical_application": "A technician assigns each mic or track to its own mix channel, sets its fader and EQ, then routes it to a group or the main mix bus.", "category": "Mixing Basics", "related_terms": ["Channel strip", "Bus", "Fader", "Insert", "Aux send"], "common_mistakes": ["Confusing a channel with a bus, which sums several channels together.", "Assigning two sources to one channel and losing separate control of each.", "Running a channel into clipping instead of setting input gain properly first."], "scenario_contexts": ["Setting up one channel per microphone at a live gig.", "Adjusting the vocal channel's fader and EQ during a mix.", "Routing several instrument channels into a single drum group."]}, "83c54bd3-ae8b-4d12-bbfd-30642959ba84": {"definition": "Mix consistency is the degree to which a mix holds a stable tonal balance, level relationship, and character throughout a song and across an engineer's projects, so that mixes translate reliably across different playback systems.", "plain_english": "Mix consistency means your mixes sound steady and dependable. Levels and tone stay balanced from the start of a song to the end, and your work sounds similar in quality from one project to the next. It also means the mix holds up on phones, cars, and big speakers.", "purpose_function": "Consistent mixes reduce surprises when a track is played on unfamiliar systems and make an engineer's results predictable and professional.", "practical_application": "A technician uses reference tracks, careful gain staging, and checks on several monitors and earbuds to keep balance and loudness consistent within and between projects.", "category": "Mixing Technique", "related_terms": ["Reference track", "Translation", "Gain staging", "Level balance", "Monitoring"], "common_mistakes": ["Judging a mix on only one set of speakers, so it fails to translate elsewhere.", "Mixing too loud, which tires the ears and lets balance decisions drift over time.", "Changing tonal balance a lot between sections with no musical reason."], "scenario_contexts": ["Checking a mix on monitors, earbuds, and a phone speaker to confirm it translates.", "Using a reference track to keep tonal balance in line with a genre standard.", "Keeping level and tone steady across all the songs on an album."]}, "90ab32ae-766c-407f-901f-ebe8e53dbb0c": {"definition": "In PreSonus Studio One, Mix Engine FX are processors that plug into the mixer's channel and bus engine and use State Space modeling to add analog-console behavior, such as drive, crosstalk, and subtle noise, across the summed signal; the example included with Studio One is Console Shaper.", "plain_english": "In Studio One, Mix Engine FX add the warm, glued sound of an analog mixing desk to your whole mix. They work deep inside the mixer, not just on one track, adding gentle drive and character. Console Shaper is the one that ships with the program.", "purpose_function": "They recreate the interaction and coloration of a hardware console inside the DAW, giving a digital mix cohesion and analog-style character without outboard gear.", "practical_application": "A technician inserts Console Shaper on the main bus in Studio One and enables per-channel drive to add subtle console glue and saturation across the mix.", "category": "Mixing Tools", "related_terms": ["Console emulation", "Bus processing", "Saturation", "Summing", "Insert effect"], "common_mistakes": ["Overdriving Console Shaper so the mix becomes distorted instead of subtly warmed.", "Expecting Mix Engine FX to behave like a normal insert on a single track, when it processes the wider mix engine.", "Assuming it is available in every DAW, when it is a Studio One feature."], "scenario_contexts": ["Adding analog-style glue to a fully in-the-box mix.", "Enabling channel drive across a session for subtle saturation.", "Emulating console crosstalk and character on a mix bus."]}, "15d4ed8f-be96-4b05-ae9d-827e75a97ee0": {"definition": "A subgroup bus that routes several related channels (for example all drum tracks) through one fader, so they can be balanced and processed together as a single unit.", "plain_english": "A way to link several tracks so one fader moves them all at once. Think of putting the whole drum kit on one slider you can raise or lower together.", "purpose_function": "It lets an engineer control the level of many channels at once and apply shared processing, keeping the mix organized and faster to adjust.", "practical_application": "A technician routes all the drum mics to a drum group, then rides that one fader to bring the whole kit up or down without touching each channel.", "category": "Signal Routing", "related_terms": ["Subgroup", "Bus", "VCA group", "Auxiliary send", "Master bus"], "common_mistakes": ["Confusing an audio group (which carries the summed signal) with a VCA (which only links fader levels)", "Adding processing to a group but forgetting that some channels are not routed to it", "Double-counting a channel by sending it to both the group and the master directly"], "scenario_contexts": ["Routing all drum mics to one group to control kit balance with a single fader", "Bus-compressing a background-vocal group for a tighter blend", "Muting a whole instrument section quickly during a live show"]}, "93b2d876-e678-4ae4-9144-85e1f1ee4a9a": {"definition": "The level margin between the mix's normal signal peaks and the clipping point (0 dBFS in a digital system), reserved so transients and summed peaks do not distort.", "plain_english": "The safety gap between how loud your mix is and the point where it starts to distort. It is like not filling a cup to the brim so it does not spill when bumped.", "purpose_function": "Headroom prevents clipping on loud peaks and leaves room for later stages such as mastering, protecting sound quality.", "practical_application": "An engineer keeps mix peaks a few dB below 0 dBFS so the master bus and the mastering stage have room to work without distortion.", "category": "Gain Structure", "related_terms": ["Gain staging", "Clipping", "0 dBFS", "Peak level", "Dynamic range", "Mix-bus limiting"], "common_mistakes": ["Pushing the mix bus near 0 dBFS and leaving no room for mastering", "Confusing loudness with level and clipping the mix to make it sound louder", "Ignoring inter-sample (true) peaks that overshoot after conversion even when meters look safe"], "scenario_contexts": ["Leaving several dB below 0 dBFS before sending a mix to mastering", "Setting gain structure so summed peaks never clip the master bus", "Checking a true-peak meter before exporting a final file"]}, "c3568a48-fa86-4106-9590-c5ba9286718b": {"definition": "The live-sound practice of shaping a mix for how it actually sounds out in the venue's audience area, compensating for the room's acoustics rather than judging only at the console.", "plain_english": "Shaping a live mix so it sounds right out in the actual room, not just at the desk. The space changes the sound, so you tune the mix to fit it.", "purpose_function": "It ensures the audience hears a balanced mix by accounting for reflections, absorption and distance, which alter the sound between the console and the seats.", "practical_application": "A front-of-house engineer walks out into the room to hear the PA where the audience stands, then returns to adjust EQ and balance for that space.", "category": "Monitoring", "related_terms": ["Room acoustics", "PA system", "Front of house", "System tuning", "Mix to the room"], "common_mistakes": ["Judging the mix only at the console and not out in the audience area", "Forgetting that a crowd absorbs high frequencies and changes the sound during the show", "UNSAFE: raising SPL to fill a large room past safe exposure limits without hearing protection (per OSHA 1910.95)"], "scenario_contexts": ["Walking the room to hear how the PA sounds where the audience stands", "Tuning the mix so it still carries clearly to the back rows", "Compensating for strong reflections off hard walls in a reverberant venue"]}, "4dd856df-5065-45b7-83c7-291a811e48a3": {"definition": "How well the tonal and level balance heard at the mix position holds up at other listening locations in the room, so a mix judged at the console still sounds balanced elsewhere.", "plain_english": "How well your mix holds up when you move to a different seat or spot in the room. A good mix still sounds balanced from more than one place.", "purpose_function": "It matters because the mix position is only one point in a space; a mix that fails to translate leaves much of the audience hearing a different, poorer balance.", "practical_application": "An engineer checks a mix balanced at front of house from several seats around the venue to confirm it still works away from the console.", "category": "Monitoring", "related_terms": ["Mix position", "Front of house", "Coverage", "Room acoustics", "System tuning"], "common_mistakes": ["Assuming what sounds good at the desk sounds good everywhere in the room", "Placing the mix position in an acoustic null and mixing to a false picture", "Not checking the mix from several seats before the doors open"], "scenario_contexts": ["Confirming a mix balanced at front of house still works at the back of the venue", "Moving around the room to test coverage and tonal balance", "Choosing a mix position that represents the average audience experience"]}, "002685e9-e29b-4345-89b8-c5377f587950": {"definition": "A fixed, calibrated monitoring loudness (often a set SPL such as around 83-85 dB SPL per channel) used consistently while mixing so balance and tonal decisions are made against a stable reference.", "plain_english": "A set, steady loudness you always monitor at while mixing. Keeping the volume the same each time helps you judge the sound fairly.", "purpose_function": "It gives consistent monitoring so decisions are not skewed by the ear's changing frequency response at different volumes, making mixes more repeatable and translatable.", "practical_application": "An engineer calibrates the monitors to a known SPL and mixes at that level, occasionally checking quieter and louder to confirm the balance holds.", "category": "Monitoring", "related_terms": ["Monitoring level", "K-system", "SPL", "Calibration", "Loudness", "Equal-loudness contours"], "common_mistakes": ["Mixing at constantly changing volumes so balance decisions drift", "Mixing too loud and fatiguing the ears, skewing EQ and level choices", "Assuming louder monitoring reveals more detail when it mainly adds low-end and high-end bias"], "scenario_contexts": ["Calibrating monitors to a fixed SPL for consistent mixing sessions", "Checking a mix at a quiet reference level to judge vocal balance", "Matching room monitoring level to a mastering-studio standard"]}, "1ccc06a5-84ef-4329-973d-917cab6ef0be": {"definition": "The practice of adjusting a mix to suit the acoustics of the specific space it is heard in, compensating for the room's resonances, reflections and absorption.", "plain_english": "Adjusting your mix to match the room you are playing in. A boomy hall or a dead room each need different tuning.", "purpose_function": "It accounts for the fact that no room is acoustically neutral, so the same mix can sound very different from space to space; tuning to the room keeps the intended balance.", "practical_application": "A technician cuts low mids in a boomy gym or adds brightness in a heavily damped room so the mix sounds right where it is actually played.", "category": "Monitoring", "related_terms": ["Room acoustics", "Reverberation time", "Monitoring", "System tuning", "Mix position translation"], "common_mistakes": ["Mixing only by the meters and ignoring how the room actually sounds", "Over-correcting for a bad room so the mix falls apart in a better space", "UNSAFE: pushing levels to overcome a dead room and exceeding safe hearing-exposure limits (OSHA 1910.95)"], "scenario_contexts": ["Cutting low mids in a boomy gymnasium to keep vocals clear", "Adding high-frequency lift in a heavily carpeted, damped room", "Re-checking a live mix as an empty hall fills with an absorbing crowd"]}, "adef5f46-edc1-411f-a17f-d80da894e974": {"definition": "The principle that final mixing decisions should be made by listening rather than by relying on visual metering, waveform displays or analyzer readouts.", "plain_english": "Trusting what you hear instead of what the screen shows you. The meters and waveforms help, but your ears make the final call.", "purpose_function": "It keeps the focus on how the mix actually sounds, since meters and graphs measure signal but cannot judge musical balance, tone or emotion the way listening can.", "practical_application": "An engineer sets EQ and compression by listening and comparing, using visual tools only as a reference rather than letting a display dictate the choice.", "category": "Mixing Technique", "related_terms": ["Critical listening", "Metering", "Monitoring", "A/B comparison", "Reference track"], "common_mistakes": ["Cutting a frequency because the analyzer shows a peak even though it sounds fine", "Matching waveform sizes by eye instead of judging loudness by sound", "Trusting a plugin preset or number over what is actually heard"], "scenario_contexts": ["Setting EQ by listening rather than chasing a flat spectrum display", "Judging compression by feel and sound instead of only the gain-reduction meter", "Leaving a scary-looking waveform alone because it sounds clean"]}, "df008a6f-ff97-4d45-8d31-41640a59691c": {"definition": "Applying a limiter across the mix (master) bus to catch peaks and control the overall level ceiling of the full mix, often to raise perceived loudness or protect against overs.", "plain_english": "Putting a limiter on the main output to catch the loudest peaks and lift the overall volume. It acts like a ceiling that stops the mix from going too high.", "purpose_function": "It manages the summed peaks of the whole mix so the output stays below a set ceiling, allowing a louder, more controlled level without clipping.", "practical_application": "An engineer places a gentle limiter on the master bus to tame stray peaks and add loudness to a rough mix sent to a client, or before a loudness target.", "category": "Bus Processing", "related_terms": ["Master bus", "Limiter", "Mix headroom", "Loudness", "True peak", "Bus compression"], "common_mistakes": ["Over-limiting the mix bus and squashing all the punch and dynamics", "Mixing into a heavy limiter and then being unable to remove it without the mix falling apart", "Confusing a limiter with a compressor and setting a slow attack that misses the peaks"], "scenario_contexts": ["Catching stray peaks on the master bus before export", "Adding gentle limiting for a louder rough mix to send to a client", "Controlling transient overshoot before hitting a broadcast loudness target"]}, "90b32d58-537b-44bd-a7a5-6df1fb0e9940": {"definition": "The integrated mixer window in Steinberg's Cubase and Nuendo DAWs, providing channel strips with faders, pan, EQ, inserts, sends and routing for every track in the project.", "plain_english": "The built-in mixing board inside Cubase and Nuendo, the music software from Steinberg. It is the on-screen version of a studio mixing desk, with faders and knobs for each track.", "purpose_function": "It gathers level, pan, EQ, effects and routing controls for all channels in one window so the whole mix can be balanced and processed from a single view.", "practical_application": "A technician opens the MixConsole to set levels and pan, add insert effects and EQ per channel, and manage bus routing during a mixdown in Cubase or Nuendo.", "category": "DAW Mixer", "related_terms": ["Channel strip", "Fader", "Bus", "DAW", "Insert", "Send"], "common_mistakes": ["Confusing the MixConsole window with the project window's smaller mixer view", "Losing track of routing because channel visibility is filtered or hidden", "Assuming its settings are separate from the channel/track inspector when they are actually linked"], "scenario_contexts": ["Setting levels and pan for every track from one window in Cubase", "Adding insert effects and channel EQ during a mixdown", "Recalling a saved mix configuration in Nuendo"]}, "b9ff101c-c14c-4ca2-b568-28afde913bf1": {"definition": "The array of physical or on-screen controls—faders, rotary pots, switches, and meters—on a mixing device through which an operator adjusts levels, tone, routing, and processing of audio signals. It is the operator-facing surface of a hardware console or the control interface of a software mixer.", "plain_english": "A mixer's control panel is the group of knobs, sliders, and buttons on it. You use them to change each sound's volume, tone, and place in the mix. It works like a car dashboard, where each control does one job.", "purpose_function": "It gives the operator a single organized surface to set level, tone, routing, and effects for every signal, making real-time control of a mix possible.", "practical_application": "A technician learns each control's position so they can adjust a channel's gain, EQ, or send quickly during a session or live show without looking away from the work.", "category": "Mixing Console", "related_terms": ["Mixing Board", "Mixer window", "Channel strip", "Fader", "Aux send"], "common_mistakes": ["Assuming every control panel is laid out the same; control functions and layout differ between makes and models.", "Adjusting a control without first checking which channel or layer is currently selected.", "Confusing an interface's DSP-mixer control panel with the DAW's own mixer window."], "scenario_contexts": ["Setting channel levels on a live console before a show.", "Teaching a new operator where the gain, EQ, and fader controls live.", "Recalling a scene and confirming physical controls match the stored settings."]}, "5d50ffdf-be6a-4279-b515-e52bf5ce417e": {"definition": "In a digital audio workstation, the window that presents each track as a vertical channel strip—level fader, pan, input/output routing, insert and send slots, and metering—arranged in a mixing-console layout, as distinct from the arrange/edit window.", "plain_english": "The mixer window is a screen in music software that shows each track as a channel strip. Every strip has a volume slider, a pan knob, and slots for effects. It looks like a picture of a real mixing desk on your computer.", "purpose_function": "It lets an engineer see and adjust every track's level, pan, routing, and processing in one console-style view, separate from arranging or editing clips.", "practical_application": "During mixdown an engineer works mostly in the mixer window to set balances, add inserts, build aux and reverb sends, and group tracks.", "category": "DAW Interface", "related_terms": ["Channel strip", "Insert", "Aux send", "Mixing Board", "Bus"], "common_mistakes": ["Confusing the mixer window with the edit/arrange window; clip edits happen in one, level and routing in the other.", "Adding a plugin as an insert when a send/return was intended, or the reverse.", "Not revealing hidden tracks or busses and assuming a signal path is broken."], "scenario_contexts": ["Balancing a multitrack song during mixdown.", "Setting up headphone cue sends before a tracking session.", "Creating group or bus channels to process several tracks together."]}, "1dc05874-9468-4915-b8f0-c2519b357f7a": {"definition": "A common name for a mixing console (mixing desk): an electronic device that accepts multiple audio inputs and combines, routes, levels, and processes them into one or more output signals. Channels typically provide input gain, EQ, dynamics, auxiliary sends, panning, and level control.", "plain_english": "A mixing board is the big desk with many sliders that blends sounds together. Each channel handles one sound, like a voice or a drum. You set how loud each one is and send them all out as one mix.", "purpose_function": "It exists to combine many separate sources into a controlled blend, giving each a set level, tone, and position while routing them to speakers, recorders, or broadcast feeds.", "practical_application": "An engineer uses it to set input gain, shape each channel with EQ and dynamics, balance faders, and send the result to the main output and monitor mixes.", "category": "Mixing Console", "related_terms": ["Mixer window", "Channel strip", "Fader", "Aux send", "Bus", "Gain staging"], "common_mistakes": ["Confusing a mixing board with an audio interface; the board mixes and routes, while an interface converts audio for a computer.", "Setting level with the channel fader instead of the input gain/trim, hurting signal-to-noise or causing clipping.", "UNSAFE: Switching phantom power on while patching ribbon mics or unbalanced sources, which can damage gear."], "scenario_contexts": ["Mixing a band's inputs into a main PA feed at a live gig.", "Combining recorded tracks into a stereo mix in the studio.", "Routing separate monitor mixes to stage performers."]}, "9ad8075f-d248-40be-80b2-f7ef69cf787b": {"definition": "Room and monitor correction that uses machine-learning algorithms to analyze acoustic measurements at a listening position and derive equalization and time-domain filters that compensate for room and loudspeaker response errors. It aims to deliver a flatter, more accurate monitoring response than the untreated room.", "plain_english": "ML room correction uses smart software to fix how speakers sound in a room. Rooms add echoes and can boost or cut some notes. The software listens to a test tone and builds a filter to even things out. ML means 'machine learning,' a program that learns from data.", "purpose_function": "It aims to remove the room's and speakers' coloration from what you hear, so mixing decisions translate better to other playback systems.", "practical_application": "An engineer runs a guided measurement with a calibrated mic, and the software generates correction filters applied to the monitor path or a plugin on the monitor bus.", "category": "Monitoring", "related_terms": ["Room correction", "Monitor calibration", "Reference monitor", "Frequency response", "Acoustic treatment"], "common_mistakes": ["Treating correction as a substitute for acoustic treatment; EQ alone cannot fix long reflections or strong bass modes.", "Applying the correction filters to the recorded signal instead of only the monitor path.", "Trusting a single measurement position rather than an averaged set of points."], "scenario_contexts": ["Calibrating monitors in an untreated home studio.", "Improving low-frequency accuracy at the mix position.", "Matching the sound of two rooms for consistent mixing."]}, "de36c2ae-7f56-482d-ae90-eeabac3df626": {"definition": "An input-monitoring mode in which a record-enabled track automatically switches its monitored source with the transport: it passes the live input while armed for or during recording and monitors previously recorded material during playback. This lets performers hear the incoming source only when it is relevant.", "plain_english": "Auto mode decides for you what a track plays. While you record, you hear the live sound coming in. While you play back, you hear what was already saved. It switches on its own so you don't have to.", "purpose_function": "It automates input monitoring so performers hear the live source only when recording is relevant and hear the existing take during playback, with no manual switching.", "practical_application": "An engineer leaves record-armed tracks in Auto during overdubs so the player hears their live input while recording and the existing take during playback.", "category": "Monitoring", "related_terms": ["Monitor In mode", "Monitor Off mode", "Input monitoring", "Record enable", "Punch in/out"], "common_mistakes": ["Blaming latency or a routing fault when the mode is simply switching sources as designed.", "Expecting to hear the live input during playback, which Auto does not do.", "Leaving tracks in Auto when constant input monitoring is actually needed."], "scenario_contexts": ["Overdubbing a vocal against a previous take.", "Punch-in recording to fix a small mistake.", "Standard tracking where hands-free monitoring is wanted."]}, "b35bc1d2-3a74-47b1-8771-e588fb568d7d": {"definition": "An input-monitoring mode in which a track always monitors its live input signal regardless of arm state or transport, so the incoming source is heard at all times.", "plain_english": "In mode means the track always plays the live sound coming in. You hear the input all the time, even during playback. It is handy when a player wants to keep hearing their instrument.", "purpose_function": "It forces constant monitoring of the live input so the incoming source is always audible, regardless of transport or record state.", "practical_application": "A technician selects In when a player needs to keep hearing their instrument through the session, or when setting levels and tone before recording.", "category": "Monitoring", "related_terms": ["Monitor Auto mode", "Monitor Off mode", "Input monitoring", "Record enable", "Direct monitoring"], "common_mistakes": ["Leaving In active during playback of a finished take, so the live input bleeds over what you meant to review.", "Creating a doubled or feedback sound when the interface is also monitoring the same input.", "Confusing In-monitoring latency with a recording problem."], "scenario_contexts": ["Dialing in a guitar tone before hitting record.", "Letting a singer warm up while hearing themselves.", "Checking a mic signal path during setup."]}, "df041167-ea5f-4348-8066-f8698d772071": {"definition": "An input-monitoring mode in which a track never monitors its live input; only previously recorded material on the track is heard. It is used when monitoring is handled elsewhere—such as by an external mixer or the recording interface—to avoid double monitoring or latency.", "plain_english": "Off mode stops the track from playing the live sound coming in. You only hear what was already recorded. This helps when another mixer or device already lets you hear the input.", "purpose_function": "It prevents the track from passing the live input to the monitors so only recorded material is heard, leaving source monitoring to other gear.", "practical_application": "An engineer uses Off when the performer already hears the input through a hardware mixer or the interface's low-latency path, avoiding a delayed doubled signal.", "category": "Monitoring", "related_terms": ["Monitor In mode", "Monitor Auto mode", "Direct monitoring", "Latency", "Input monitoring"], "common_mistakes": ["Setting Off and then wondering why the live input cannot be heard at all.", "Using Off while expecting the input to still be recorded—monitoring and recording are separate.", "Forgetting to switch back to In or Auto for the next overdub."], "scenario_contexts": ["Tracking through an interface that provides its own zero-latency monitoring.", "Avoiding a slap-back caused by hearing both direct and software-monitored input.", "Reviewing recorded takes without the live source in the mix."]}, "28318c5a-8cd4-4780-ad4b-ef37cc28b056": {"definition": "A chain of effects inserted only in the monitoring or cue path so that performers or engineers hear the processing without it being committed to the recorded signal. Common examples include reverb or compression added to a headphone cue while the recorded track stays dry.", "plain_english": "A monitoring FX chain is a set of effects you hear but do not record. For example, a singer can hear reverb in the headphones while the saved take stays dry. It helps a performer feel at ease without changing the file.", "purpose_function": "It lets performers and engineers hear helpful processing without printing it, keeping the recorded signal clean and flexible for later mixing.", "practical_application": "During tracking an engineer adds reverb to the singer's headphone cue so they perform comfortably, while the recorded vocal stays dry.", "category": "Monitoring", "related_terms": ["Cue mix", "Headphone mix", "Aux send", "Reverb", "Wet/dry"], "common_mistakes": ["Accidentally recording the monitor effects onto the track instead of keeping them on the cue only.", "Adding heavy monitor processing that adds latency and throws off the performer's timing.", "Assuming the mix engineer will hear the same monitor effects later; they are not saved with the take."], "scenario_contexts": ["Giving a vocalist reverb in the headphones while recording dry.", "Adding light compression to a monitor cue so a quiet part is easier to hear.", "Setting up a comfortable headphone blend for a nervous performer."]}, "be52336a-208f-475e-ae82-168ef05ee939": {"definition": "The process of verifying that a stereo or multichannel mix remains coherent when summed to mono, checking for level loss, tonal change, or disappearing elements caused by phase cancellation between correlated channels. It is typically done by auditioning a mono sum and watching a phase-correlation meter or goniometer.", "plain_english": "This is a check to make sure a mix still sounds right when both speakers are joined into one. Sometimes sounds cancel out and get quiet or thin when joined this way. You press a 'mono' button and listen, so phones and clubs that play in mono still sound good.", "purpose_function": "It catches phase and level problems before release, ensuring the mix holds up on mono systems like phone speakers, some clubs, and many broadcast feeds.", "practical_application": "An engineer presses a mono-sum button and listens for elements that vanish or go thin, then fixes phase, panning, or stereo-widening effects that cause the loss.", "category": "Mix Quality Control", "related_terms": ["Mono sum", "Phase cancellation", "Phase correlation meter", "Stereo width", "Goniometer", "Panning"], "common_mistakes": ["Skipping the mono check because the stereo mix sounds fine on studio monitors.", "Over-using stereo wideners, which can make sounds cancel and disappear in mono.", "Mistaking a level change in mono for a broken monitor path rather than phase cancellation."], "scenario_contexts": ["Checking a mix before it goes to streaming and phone listeners.", "Preparing audio for broadcast or club systems that sum to mono.", "Diagnosing a bass or vocal that weakens when summed to mono."]}, "6fd6c2a0-3b24-425d-859d-fa1b9fe05a90": {"definition": "A modifier key—typically Shift, Ctrl/Command, or Alt/Option—held down while clicking or dragging with the mouse to temporarily change what the mouse action does in a DAW or editor, such as constraining movement, enabling fine adjustment, overriding snap, or adding to a selection.", "plain_english": "It is a keyboard key you hold while you use the mouse. Holding it changes what your click or drag does. For example, holding Shift can let you pick more than one clip at once.", "purpose_function": "It lets a single mouse tool perform several actions without switching tools, speeding up editing and mixing by giving quick access to variations like fine control or a snap override.", "practical_application": "An engineer holds a modifier while dragging a fader or clip to nudge it in small steps, keep it on one axis, or bypass the grid, keeping a hand on the mouse instead of hunting through menus.", "category": "DAW workflow", "related_terms": ["Keyboard shortcut", "Snap to grid", "Nudge", "Automation lane", "Fader", "Selection tool"], "common_mistakes": ["Assuming the same modifier does the same thing in every DAW—assignments differ between Pro Tools, Cubase, Logic, and Live.", "Forgetting that the modifier must be held before or during the action, not pressed afterward.", "Confusing a mouse modifier with a permanent tool change, then wondering why the behavior reverts once the key is released."], "scenario_contexts": ["Holding a fine-adjust modifier while dragging a fader to set a precise level.", "Shift-clicking several regions to select and move them together.", "Holding a modifier to temporarily disable grid snapping while trimming a clip."]}, "fe8c61d6-9967-4af0-b4da-c293a3213d01": {"definition": "A single track that carries more than one channel of audio as one linked entity—such as stereo, LCR, 5.1, 7.1, or an immersive bed—rather than a mono track that holds one channel. Its width is set by a channel format, and all of its channels are recorded, edited, routed, and processed together.", "plain_english": "It is one track that holds several audio channels at once, like left and right, or all the speakers in surround. Instead of many separate mono tracks, you handle them as one. It keeps grouped sounds lined up and moving together.", "purpose_function": "It keeps the channels of a stereo or surround signal together so they stay in sync and share editing, routing, and plug-in settings, which simplifies working with multichannel material.", "practical_application": "A technician records a stereo overhead pair or imports a 5.1 stem onto one multichannel track, then edits and routes all of its channels in one move instead of managing each channel separately.", "category": "Track types", "related_terms": ["Mono track", "Stereo track", "Channel format", "Surround sound", "Bus", "Stem"], "common_mistakes": ["Assuming a multichannel track is just several mono tracks stacked—its channels are linked and share one set of controls.", "Placing a mono-only plug-in on a multichannel track and collapsing or misrouting the channels.", "Ignoring channel order, so a 5.1 track's channels end up assigned to the wrong outputs."], "scenario_contexts": ["Importing a 5.1 music stem onto one track for a film re-recording session.", "Recording a stereo room-mic pair to a single stereo track.", "Routing an immersive bed through a multichannel track to the correct output format."]}, "6072bd2b-10b5-4449-bf5e-2bd241cf5963": {"definition": "The quality-control process of verifying that a multichannel audio file or stem conforms to its intended format specification—correct channel count and order, correct assignment of content to each channel, no empty, swapped, or polarity-inverted channels, and compliance with the loudness and level targets for the deliverable.", "plain_english": "It means checking that a surround or multi-track file is built correctly. You confirm each channel holds the right sound and sits in the right slot. It catches problems like a missing channel or two channels swapped by mistake.", "purpose_function": "It exists to catch channel-mapping and level errors before delivery, so a surround or immersive mix plays back correctly on the client's system and meets its format and loudness requirements.", "practical_application": "Before delivering a 5.1 or immersive master, an engineer checks each channel for correct content, order, and loudness, often soloing channels and reading meters to confirm nothing is empty, swapped, or out of spec.", "category": "Quality control", "related_terms": ["Multichannel track", "Channel order", "Loudness", "Surround sound", "Deliverable", "Metering"], "common_mistakes": ["Checking only the front channels and missing an empty or wrong surround or LFE channel.", "Assuming a correct channel count means correct channel order—content can still be mapped to the wrong speakers.", "Skipping a loudness check, so the deliverable fails the broadcaster's or streaming platform's spec."], "scenario_contexts": ["Verifying a 5.1 stem's channel assignments before handing off to the dub stage.", "Confirming an immersive deliverable meets channel-order and loudness spec before upload.", "Auditioning each channel of a surround master to catch a swapped left-surround/right-surround pair."]}, "19abb346-1e13-4a37-9555-09d527af2130": {"definition": "In interactive audio middleware, a music callback is a notification the music engine sends back to game or application code at defined musical points—such as each beat or bar, a segment's entry or exit cue, a user-placed marker, or a playlist jump—so that gameplay events can be synchronized precisely to the music.", "plain_english": "It is a message the music system sends to the game at a set musical moment, like on every beat or bar. The game can then act right in time with the music. For example, an enemy could attack exactly on the downbeat.", "purpose_function": "It exists to let game logic react in musical time, so on-screen action, effects, and transitions can be locked to beats, bars, and cues instead of drifting out of sync with the score.", "practical_application": "A sound designer or programmer registers a callback on beats or a custom cue so that, for example, a light flashes on each bar or a stinger fires when a music segment reaches its exit point.", "category": "Interactive music", "related_terms": ["Music segment", "Music state", "Cue", "Beat", "Marker", "RTPC"], "common_mistakes": ["Expecting sample-accurate visuals from a callback that is delivered on the game thread and may arrive a frame late.", "Registering for beat or bar callbacks and never unregistering them, leaving stale callbacks firing.", "Confusing a music callback (music-timed) with a general event callback that just reports when a sound finished."], "scenario_contexts": ["Flashing an environment light on every musical bar during a boss fight.", "Firing a gameplay stinger when a music segment hits its exit cue.", "Syncing a rhythm-game input window to beat callbacks from the music engine."]}, "3197b8df-94d9-4067-9de6-03de22d52a7c": {"definition": "In adaptive music, an intensity layer is one of several stacked, time-aligned music stems that are faded in or out—vertical layering, or vertical re-orchestration—to raise or lower the energy of the score without changing the underlying arrangement, in response to a game or program state.", "plain_english": "It is one layer of a piece of music that can be added or removed to make the music feel bigger or calmer. All the layers play in time together. Adding a drum or brass layer makes a scene feel more intense.", "purpose_function": "It exists to let one piece of music shift energy smoothly—calm to tense and back—by muting or adding layers, avoiding an abrupt jump to a completely different track.", "practical_application": "A game composer builds a cue as several aligned stems and maps a parameter to fade in higher-intensity layers as danger rises, so the music grows without ever restarting.", "category": "Interactive music", "related_terms": ["Vertical layering", "Music state", "Stem", "Music segment", "RTPC", "Crossfade"], "common_mistakes": ["Rendering layers that are not the same length or tempo, so they drift out of sync when combined.", "Fading a layer in too abruptly, making the change obvious instead of smooth.", "Confusing vertical layering (adding or removing layers) with horizontal re-sequencing (switching to different sections)."], "scenario_contexts": ["Fading in a percussion layer as enemies approach the player.", "Removing high-intensity layers when combat ends to return to a calm exploration feel.", "Mapping a health or threat parameter to the volume of each intensity layer."]}, "f3aeb78e-2c9a-4a5d-a26b-87130a4131f5": {"definition": "A music mixer is the engineer, console, or software function responsible for combining and balancing the musical sources of a production into a coherent music mix; in film and broadcast post-production it is specifically the re-recording mixer who handles the music stem, alongside the dialogue and effects mixers.", "plain_english": "A music mixer is the person or gear that blends all the musical parts into one balanced mix. In film and TV, it is the engineer who handles just the music. They set how loud each musical element sits.", "purpose_function": "It exists to turn many separate musical elements into one balanced, polished result, and in post-production to keep music as its own stem so it can be weighed against dialogue and effects.", "practical_application": "On a scoring or re-recording stage, the music mixer balances the orchestra or song elements and rides the music level so it supports the scene without covering dialogue.", "category": "Mix roles", "related_terms": ["Re-recording mixer", "Stem", "Music premix", "Dialogue mixer", "Submix", "Mixing console"], "common_mistakes": ["Assuming the music mixer also mixes dialogue and effects—on larger productions these are separate roles.", "Thinking 'music mixer' always means a device, when it often means the engineer or their role.", "Pushing the music level so high it buries dialogue in the final mix."], "scenario_contexts": ["A re-recording mixer balancing the music stem on a film dub stage.", "An engineer mixing a song's multitrack down to a stereo master.", "Setting music levels against dialogue and effects during a TV final mix."]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"2f694d4f-e373-4f17-9b49-61f878551f2b": {"definition": "A music premix (or music pre-dub) is a preliminary submix in which all of a program's music elements are balanced and processed together into the music stem, prepared before the final re-recording mix so that music can be handled as one manageable unit against dialogue and effects.", "plain_english": "It is a rough-but-balanced mix of just the music, made before the final mix. It bundles all the music into one group. That makes the last mixing stage simpler, because the music is already sorted.", "purpose_function": "It exists to reduce the number of elements at the final mix by consolidating many music tracks into one balanced stem, while keeping music separate for later level changes, revisions, or foreign-language versions.", "practical_application": "Before the final dub, the mixer balances all cues and song elements into a music premix stem, which is then brought into the final mix and set against dialogue and effects.", "category": "Mix workflow", "related_terms": ["Premix", "Stem", "Music mixer", "Final mix", "Submix", "Dialogue premix"], "common_mistakes": ["Printing the premix with too much processing baked in, leaving no room to adjust music at the final mix.", "Not documenting levels or routing, so the premix cannot be recreated if a cue changes.", "Treating the premix as final—premixes exist to be re-balanced against dialogue and effects."], "scenario_contexts": ["Consolidating dozens of music cues into one 5.1 music stem before a film's final dub.", "Preparing separate music premixes so a show can be re-versioned in another language.", "Delivering a music premix stem to the re-recording mixer for the final balance."]}, "267e35d9-4ba3-40dd-9bdb-3969957ac9b1": {"definition": "In interactive music, a music segment is the basic unit of the music hierarchy: a container holding one or more time-aligned music tracks along with entry and exit cues and a defined duration, representing a self-contained musical piece such as an intro, a loop, or a transition that the engine can queue, loop, and join to other segments.", "plain_english": "It is one chunk of music the game can play, like an intro or a looping section. It has a start point and an end point. The music system strings these chunks together to build the score as you play.", "purpose_function": "It exists to break a score into reusable musical building blocks with defined entry and exit points, so the engine can rearrange, loop, and transition between them smoothly at runtime.", "practical_application": "A composer authors an intro segment, a looping gameplay segment, and an ending segment, then the middleware chains them—waiting for each segment's exit cue before moving on—so the music adapts as the game changes.", "category": "Interactive music", "related_terms": ["Music state", "Music callback", "Music intensity layer", "Cue", "Transition", "Playlist container"], "common_mistakes": ["Ignoring entry and exit cues, so segments join at musically wrong points and the transition sounds jarring.", "Building segments of mismatched tempo or length that will not loop or transition cleanly.", "Confusing a music segment (a unit of music) with a music track (a single layer inside a segment)."], "scenario_contexts": ["Looping a gameplay music segment until the player enters combat.", "Transitioning from an exploration segment to a combat segment on a musical bar.", "Queuing an ending segment when a level is completed."]}, "d7cf32a3-a686-424f-a4c2-18e88ebcca29": {"definition": "In adaptive music, a music state is a named, usually global condition of the game or program—such as Exploration, Combat, Stealth, or Victory—that the music system reads to decide which music plays and how it transitions, driving horizontal re-sequencing between different musical sections to match the current situation.", "plain_english": "It is a label for what is happening in the game, like 'exploring' or 'fighting'. The music system watches this label and plays music that fits. When the state changes to combat, the music switches to combat music.", "purpose_function": "It exists to connect gameplay context to musical choice, so the score follows the action by switching or transitioning between sections whenever the situation changes.", "practical_application": "A designer defines states like Explore and Combat and assigns music to each, so when the game sets the state to Combat the music system transitions to the combat music at a musically appropriate point.", "category": "Interactive music", "related_terms": ["Music segment", "Music callback", "Music intensity layer", "Transition", "RTPC", "Switch container"], "common_mistakes": ["Setting transitions to happen immediately instead of on a beat or bar, causing abrupt musical jumps.", "Confusing states (discrete conditions like Combat) with continuous parameters used to fade layers.", "Defining too many states, making transitions hard to author and test."], "scenario_contexts": ["Switching from exploration to combat music when enemies engage.", "Returning to calm music when the player reaches a safe area.", "Triggering victory music by setting a Victory state at the end of a fight."]}, "b87b7e4e-904a-49c1-b3f0-7608cd2fcbca": {"definition": "In interactive and game audio, a change from one piece or section of music to another triggered by a game state or parameter rather than by a fixed timeline; in Wwise this is handled by a Music Switch Container that selects the appropriate music for the current Switch or State.", "plain_english": "It is when a game swaps one piece of music for another as things change on screen. Move from a quiet area into a fight, and the music switches to match.", "purpose_function": "It lets music follow unpredictable gameplay by choosing the right cue for the current situation, keeping the score in step with what the player is doing.", "practical_application": "A game-audio implementer maps calm, tension, and combat cues to game states in middleware, so the engine switches music automatically as the player crosses those thresholds.", "category": "Interactive Music", "related_terms": ["Dynamic score", "Music transition rule", "Music synchronization point", "Music-only stem", "Musical stinger"], "common_mistakes": ["Switching music instantly at any moment, causing an abrupt jump instead of a musical change", "Not pairing switches with transition rules, so cues cut off mid-phrase", "Building too many music states, making behavior hard to predict and test"], "scenario_contexts": ["Music changing when a player enters a boss arena", "Switching from exploration to stealth music as the player is detected", "Menu-to-gameplay music changes when a match starts"]}, "f88649e9-2db5-4e85-9e0c-35fd8ce51c0f": {"definition": "In film and media scoring, a specific moment in the picture where the music is composed and edited to align exactly with an on-screen event, such as a cut, an action, or an emotional beat. Composers plan a cue around these points and hit them precisely using streamers, punches, or a click track.", "plain_english": "When music is written for a film, some moments must match the picture exactly. A music sync point is one of those moments, like a drum hit landing right as a door slams. The composer marks these spots so the music lines up with the action. It keeps the sound and picture feeling connected.", "purpose_function": "It gives the composer and mixer fixed targets so the music emphasizes key visual moments, tightening the rhythmic and emotional link between sound and picture.", "practical_application": "During spotting, a composer notes each sync point against the timecode on a cue sheet, then uses streamers, punches, or a click so the recorded or programmed cue lands on those exact frames.", "category": "Film Scoring", "related_terms": ["Spotting session", "Click track", "Cue", "Timecode", "Underscore", "Hit point"], "common_mistakes": ["Placing the musical accent a frame or beat late so it misses the on-screen moment it should mark", "Ignoring the sync point and letting the cue drift out of step with the picture", "Confusing a sync point with the overall tempo, when it is one fixed target the cue must reach"], "scenario_contexts": ["Scoring an action scene so a musical hit lands on an impact", "Spotting a film with the director to mark where the music should punctuate the picture", "Using streamers and punches to hit sync points while recording an orchestra to picture"]}, "7fe17fd0-2622-4877-a611-7e67b0693502": {"definition": "In interactive music systems, a rule that defines how playback moves from a source musical segment to a destination one, specifying where the source may exit (immediately or on the next beat, bar, grid, or cue point), any fade or transition segment used, and where the destination begins, so state-driven music changes stay musical.", "plain_english": "It is the set of instructions that tells the music how to change smoothly from one piece to the next. It waits for a good spot, like the end of a bar, so the switch sounds natural.", "purpose_function": "It prevents jarring cuts when music changes with gameplay by controlling the timing and blending of each transition, keeping the score on beat and in phrase.", "practical_application": "In Wwise, an implementer sets a transition rule to exit the source at the next bar with a short crossfade, so combat music enters cleanly when the player is attacked.", "category": "Interactive Music", "related_terms": ["Music switch", "Dynamic score", "Music synchronization point", "Music-only stem", "Musical stinger"], "common_mistakes": ["Using immediate exit for everything, producing abrupt, unmusical jumps", "Ignoring tempo and time-signature differences between segments, so transitions fall out of time", "Forgetting to set a destination entry point, so the new cue starts in the wrong place"], "scenario_contexts": ["Setting music to change only on the next bar during a combat trigger", "Adding a short transition segment between exploration and boss music", "Matching exit and entry cue points so a stinger lands on the beat"]}, "1e7021a2-f5c0-4c70-9e2d-b2b00ba88a79": {"definition": "A mix of a program that contains all of its music and sound effects, including Foley and ambience, but no dialogue, produced so that dialogue in another language can be recorded and added later. It is a standard post-production deliverable, commonly abbreviated M&E, used for foreign-language dubbing and versioning.", "plain_english": "This is a version of a show's sound that keeps the music and all the sound effects but leaves out the talking. With the voices gone, a studio in another country can add speech in its own language. The background sound still fits the picture. It saves them from rebuilding the whole soundtrack.", "purpose_function": "It lets a film or TV show be re-voiced in other languages without remaking the music and effects, protecting the original sound design while supporting worldwide distribution.", "practical_application": "A re-recording mixer prints the full soundtrack with the dialogue stem muted, checks that no dialogue bleeds through the effects, and delivers the M&E so dubbing studios can drop in translated dialogue.", "category": "Mix Deliverables", "related_terms": ["Music-and-Effects Track", "Dialogue stem", "Stems", "Re-recording mixer", "Foley", "International version"], "common_mistakes": ["Leaving dialogue or narration buried in the effects so it cannot be replaced in the dub", "Forgetting to cover on-camera or crowd voices with filled or optional effects, leaving gaps when dialogue is removed", "Confusing the M&E mix with a full final mix that still contains dialogue"], "scenario_contexts": ["Delivering a TV series to a distributor who will dub it into several languages", "Preparing a film for international release with localized dialogue", "Supplying an M&E alongside the final mix as part of a standard deliverables package"]}, "68a184fe-939b-4bd6-a22c-8e3cbb8de618": {"definition": "The delivered audio track, or set of tracks, that carries a program's music-and-effects mix, holding all music and sound effects with no dialogue. Supplied with the finished program, it is the tangible deliverable used for foreign-language dubbing and archival.", "plain_english": "This is the actual audio track that holds a show's music and sound effects with no talking on it. It is handed over with the finished program. Dubbing studios use it to add voices in other languages. Archives also keep it in case the sound is needed again.", "purpose_function": "It packages the dialogue-free soundtrack as a ready-to-use asset, so localization teams and archives always have the music and effects on hand without the original dialogue.", "practical_application": "When wrapping a project, the mixer exports the M&E as a separate track or file, labels the channels clearly, and includes it in the delivery package alongside the final mix and stems.", "category": "Mix Deliverables", "related_terms": ["Music-and-effects mix", "Dialogue stem", "Stems", "Deliverables", "Re-recording mixer", "Print master"], "common_mistakes": ["Treating the M&E track as optional and leaving it out of the delivery package", "Mislabeling channels so the dubbing house cannot tell an M&E from a full mix", "Baking in dialogue reverb or effects that reveal the missing dialogue"], "scenario_contexts": ["Assembling a broadcast deliverables package that must include an M&E track", "A streaming platform requires a dialogue-free M&E for its localization pipeline", "Archiving a film so its music and effects can be reused for future versions"]}, "254edb45-d4ad-4a9a-a667-ef790ad2d605": {"definition": "A stem containing only the music elements of a mix, bounced as a separate submix in time with the full program so it can be recombined with the other stems. It isolates music from dialogue and effects for mixing, delivery, and re-versioning.", "plain_english": "A stem is a submix of just one part of the whole mix. A music-only stem holds just the music, with no voices or sound effects. Because it lines up in time with the other parts, engineers can add it back or change it on its own. That makes later changes to the music easy.", "purpose_function": "It separates the music so its level or content can be changed without touching dialogue or effects, supporting mastering, trailer edits, and localized versions.", "practical_application": "An engineer routes all music channels to one bus and exports it as a time-aligned stem, delivering it with the dialogue and effects stems so others can rebalance or rebuild the mix.", "category": "Mix Deliverables", "related_terms": ["Stems", "Dialogue stem", "Music-and-effects mix", "Submix", "Bus", "Mixdown"], "common_mistakes": ["Rendering the music stem out of time so it will not line up when combined with the other stems", "Including reverb or bus processing that double-counts when the stems are summed", "Confusing a stem with a single track or with the full final mix"], "scenario_contexts": ["Delivering separate music, dialogue, and effects stems for a film mix", "Providing a music-only stem so a trailer editor can feature the score", "Preparing stems that let a mastering engineer nudge the music level"]}, "14815bef-4340-4be4-9246-1f7947f8bcb4": {"definition": "An audio engineer who specializes in capturing musical performances, handling microphone selection and placement, signal chains, the recording system, and level and take management during tracking sessions. The role centers on recording music and is distinct from mixing, mastering, or live-sound engineering, though duties often overlap.", "plain_english": "This is the person who records music in a studio. They choose and place the microphones, set the levels, and run the recording gear during a session. Their job is to capture a clean, good-sounding performance. Other engineers may later mix or master what they recorded.", "purpose_function": "The role exists to capture high-quality source recordings of musicians, giving the mixing and mastering stages the best possible raw material to work with.", "practical_application": "In a tracking session, the music-recording engineer sets up mics on the drum kit and instruments, sets gain and headphone monitor mixes, and records each take while watching for clipping and noise.", "category": "Roles & Workflow", "related_terms": ["Tracking", "Mixing engineer", "Mastering engineer", "Signal chain", "Gain staging", "Microphone technique"], "common_mistakes": ["Confusing the recording engineer with the mixing or mastering engineer, who work at later stages", "Setting input gain too hot and clipping the recording, or too low and raising the noise floor", "Neglecting microphone placement and expecting to fix it in the mix later"], "scenario_contexts": ["Recording a band's tracking session in a studio", "Capturing an orchestra with a mic setup for a film score", "Setting up headphone mixes so musicians can hear themselves while recording"]}, "c7d8489d-994b-447b-8783-000fbee98ea0": {"definition": "A short, sharp musical phrase or chord used to punctuate a moment, mark a transition, or cue an emotional beat in a broadcast, film, podcast, or stage production. Stingers are brief accents rather than full cues, often serving as branding or to underline an on-screen action.", "plain_english": "A stinger is a very short burst of music, sometimes just one dramatic chord. It marks a moment, like the sharp sound when a big reveal happens on a TV show. It can also act like a jingle between segments. Its job is to grab attention fast.", "purpose_function": "It exists to punctuate or brand a moment quickly, pulling the listener's attention to a transition, reveal, or emotional beat without the length of a full music cue.", "practical_application": "A broadcast or podcast editor drops a stinger on the timeline to bridge two segments or hit a dramatic line, then trims and levels it so it lands cleanly with the picture or speech.", "category": "Music Editing", "related_terms": ["Cue", "Bumper", "Underscore", "Sync point", "Crossfade", "Sound effect"], "common_mistakes": ["Setting the stinger too loud so it startles the listener or masks nearby dialogue", "Placing the stinger a beat late so it misses the moment it should punctuate", "Overusing stingers until they lose impact and clutter the edit"], "scenario_contexts": ["Adding a dramatic chord as a reveal happens on a reality show", "Using a short musical sting between segments of a podcast", "Punctuating a scene change or punchline in a stage or radio production"]}, "a7bcc453-22c6-42d4-92e0-9c4999a53aa5": {"definition": "An automation pass in which the engineer writes mute on and off moves for one or more channels along the timeline, so sections silence or open automatically during playback. It is one dedicated stage of writing automation, focused on mutes rather than fader, pan, or plug-in moves.", "plain_english": "Automation lets the DAW remember and replay your moves. A mute automation pass is when you go through the song and record where each track turns off and on. After that, the tracks mute and unmute by themselves on playback. It helps clean up parts you do not want heard.", "purpose_function": "It automates the silencing of unused or noisy sections and controlled entrances, cleaning up the mix and removing bleed or noise without muting by hand on every playback.", "practical_application": "An engineer arms mute automation on a track, plays the song, and clicks the mute where the part should drop out or come back in, then edits the written mute points for tightness.", "category": "Automation", "related_terms": ["Automation", "Fader automation", "Mute", "Automation mode", "DAW", "Crossfade"], "common_mistakes": ["Writing mutes so tight they clip off note tails, reverb, or breaths", "Leaving the track in a write mode and overwriting good mute data on the next pass", "Using a hard mute where a short fade would avoid clicks at the mute point"], "scenario_contexts": ["Muting a vocal track between phrases to remove headphone bleed and noise", "Automating instrument entrances and exits across an arrangement", "Cleaning up a multitrack by silencing unused sections before the final mix"]}, "31b3a586-bdcd-4c9a-b74b-0add3dcfc2a9": {"definition": "The consistent practice of muting channels, buses, or outputs that are not actively contributing to a mix, and managing those mute states deliberately throughout a session or show. It keeps unused signal paths silent so they do not add noise, bleed, or the risk of feedback and unwanted audio at the main output.", "plain_english": "It means turning off (muting) any channel you are not using right now, and being careful about what is on or off. This keeps stray noise and mistakes out of the mix, like closing doors to rooms you are not in so their noise stays out.", "purpose_function": "It reduces built-up noise, crosstalk, and feedback by making sure only wanted sources reach the mix, and it stops accidental audio such as open mics or talkback from being heard.", "practical_application": "An engineer mutes unused input channels, mutes a vocal between sections, and checks mute states before unmuting so no unwanted sound is sent to the PA or the recording.", "category": "Mixing Practice", "related_terms": ["Channel mute", "Solo", "Gain before feedback", "Bleed", "Bus", "Talkback"], "common_mistakes": ["Leaving unused channels open so their noise and bleed add to the mix", "Forgetting to unmute a needed channel before a cue and missing the entrance", "Pulling faders down instead of muting, so bleed and noise still pass through"], "scenario_contexts": ["A live engineer mutes a guitar channel during a spoken intro so amp hiss stays out of the PA", "A studio engineer mutes tracks during silent passages to keep the mix clean", "A broadcast operator mutes a mic between segments to avoid off-air chatter going live"]}, "8cedf0de-8251-42ed-9a4c-da3f4c2ee87a": {"definition": "Nanosampler is the sample-playback instrument plug-in bundled with MOTU Digital Performer; samples are dragged into its waveform display and played from a MIDI keyboard, with modes for pitched playback across the keys, one-shot triggering, and automatic slicing, plus time-stretch/pitch-shift, filter, envelopes, and an LFO.", "plain_english": "It is a built-in instrument in the Digital Performer program that lets you play sounds from your keyboard. You drop in an audio clip, and it turns that clip into a playable instrument or drum kit.", "purpose_function": "It gives Digital Performer users a quick way to turn any audio sample into a playable, tunable instrument without leaving the DAW.", "practical_application": "A DP user drags a vocal or loop into Nanosampler, chooses Classic, 1-Shot, or Slice mode, and plays or sequences it via MIDI, shaping it with the built-in filter and envelopes.", "category": "Virtual Instruments", "related_terms": ["Digital Performer project", "Drum multisample", "Sampler", "One-shot", "Time-stretching"], "common_mistakes": ["Expecting it to work as a full REX loop player (the sliced-loop format from ReCycle), when it does not trigger individual REX slices or time-stretch independently of pitch", "Loading long samples in Classic mode and getting unwanted pitch changes across the keyboard", "Forgetting to set the right playback mode (Classic, 1-Shot, or Slice) for the material"], "scenario_contexts": ["Turning a one-shot vocal phrase into a playable keyboard instrument in Digital Performer", "Slicing a drum loop across MIDI notes to re-sequence a beat", "Building a quick drum kit from individual hit samples inside DP"]}, "d9c943d3-21a5-4945-89c9-3866f5cca0ea": {"definition": "A stem, meaning a printed submix of related tracks, that contains only the narration or voiceover elements of a program, kept separate from the music, dialogue, and effects stems. It lets the narration be re-balanced, replaced, or re-versioned without remixing the whole soundtrack.", "plain_english": "It is a separate mixed track that holds just the narration or voice-over from a video. Keeping it on its own lets you change the voice level, or swap it for another language, without redoing the whole mix.", "purpose_function": "It isolates the spoken narration so it can be level-adjusted, translated into other languages, or removed for music-and-effects versions, which supports flexible delivery and re-versioning.", "practical_application": "In post-production a mixer delivers the narration stem alongside the music and effects stems so a client can raise or lower the voice or make foreign-language versions.", "category": "Mix Deliverables", "related_terms": ["Stem", "Dialogue stem", "Music and effects (M&E)", "Voiceover", "Submix", "Bus"], "common_mistakes": ["Printing the narration stem with music or effects baked in, which defeats its purpose", "Not matching the stem's level and processing to the final mix, so the summed stems do not recreate the master", "Leaving other sources unmuted so the stem is not truly isolated"], "scenario_contexts": ["A documentary mix delivers a narration stem so the network can create a Spanish-language version", "An editor lowers the narration stem under music without touching other elements", "A re-recording mixer supplies narration, dialogue, music, and effects stems as deliverables"]}, "2e51b602-17df-470c-8fdb-effbe360a13a": {"definition": "A printmaster, the final combined master mix of a program from which delivery copies are made, that is created or evaluated on near-field monitors for close-distance, non-theatrical playback such as television, streaming, or home viewing. It represents the finished soundtrack referenced at a short listening distance rather than in a large dubbing theatre.", "plain_english": "It is the final full mix of a show, checked on small speakers placed close to you instead of in a big cinema room. It is done this way so it sounds right for home TV or streaming, where people sit near their speakers.", "purpose_function": "It makes sure the final master translates to close-range, consumer playback, because a mix balanced for a large theatre can sound different on the near-field speakers used for TV and streaming.", "practical_application": "A post mixer prints the final master while listening on near-field monitors to confirm dialogue clarity and balance for broadcast or streaming delivery.", "category": "Mix Deliverables", "related_terms": ["Printmaster", "Nearfield monitor", "Stem", "Re-recording mix", "Master"], "common_mistakes": ["Assuming a theatrical printmaster will translate unchanged to near-field home playback", "Judging final balance only on large main monitors and skipping near-field checks", "Confusing the printmaster (the final combined master) with the individual stems"], "scenario_contexts": ["A TV mix is finalized on near-field monitors to match how viewers hear it at home", "A streaming deliverable master is checked on nearfields for dialogue intelligibility", "An engineer compares the theatrical and near-field masters before delivery"]}, "a67931af-850b-4758-8059-7051257cd973": {"definition": "iZotope Neutron is a modular mixing plug-in that combines processing modules such as EQ, dynamics (compressor and gate), transient shaper, exciter, and sculptor in a single channel-strip interface, together with assistive features that analyze a track and suggest starting settings. It is used to shape individual tracks and to manage tonal balance and masking across a mix.", "plain_english": "Neutron is a computer plug-in from iZotope that puts several mixing tools, like EQ and compression, in one window. It can also listen to your track and suggest settings to get you going, like a helper that hands you a first draft.", "purpose_function": "It bundles common track-processing tools and analysis into one plug-in so engineers can shape tone and dynamics and spot balance or masking problems without loading many separate plug-ins.", "practical_application": "A mixer inserts Neutron on a vocal or instrument track, uses its Assistant to get starting EQ and compression, then fine-tunes each module by hand.", "category": "Mixing Tools", "related_terms": ["Channel strip", "Equalizer (EQ)", "Compressor", "Transient shaper", "Exciter", "Plug-in"], "common_mistakes": ["Accepting the Assistant's suggested settings without listening and adjusting", "Turning on every module when only one or two are needed, wasting CPU and over-processing", "Confusing Neutron (mixing) with Ozone (mastering)"], "scenario_contexts": ["A beginner uses Neutron's Track Assistant to get a starting mix on a vocal", "An engineer uses its masking meter to reduce clash between bass and kick", "A mixer loads Neutron as a channel strip across several tracks in a session"]}, "cac748d0-edd4-4dcc-b2d7-52b3bdd3baff": {"definition": "A supplementary track or element made of noise, such as white, pink, vinyl, or tape noise or recorded ambience, layered quietly within a mix or a sound to add texture, warmth, cohesion, or to mask edits and gaps. It is added on purpose as a creative or gluing element, unlike unwanted residual noise that should be removed.", "plain_english": "It is an extra track of noise, like hiss, static, or room sound, mixed quietly under the main sounds on purpose. It adds texture or hides small edits, a bit like a soft rain sound placed under a scene to fill the silence.", "purpose_function": "It adds texture, perceived warmth, or continuity to a sound or mix, and can hide edit points, loop seams, or quiet gaps so they feel smooth and intentional.", "practical_application": "A producer layers a low vinyl-crackle or tape-hiss track under a beat for character, or a sound designer adds a noise layer to mask the seam where a loop repeats.", "category": "Sound Design", "related_terms": ["Layering", "White noise", "Pink noise", "Texture", "Sound design", "Bus"], "common_mistakes": ["Setting the noise layer too loud so it raises the mix noise floor and muddies the sound", "Confusing an intentional noise layer with unwanted hum or hiss that should be removed", "Not band-limiting the noise, so it clutters the low end"], "scenario_contexts": ["A beatmaker adds a vinyl-crackle noise layer to give a track a lo-fi feel", "A sound designer layers filtered noise under a whoosh to add body", "An engineer uses a quiet noise layer to smooth over edits in an ambient background"]}, "ee5b2c62-fb1e-4e16-9385-2659b81bcc4c": {"definition": "The process of measuring and confirming that the residual noise level, or noise floor, of a signal chain, recording, or system meets an expected specification or delivery requirement. It verifies that background noise is low enough relative to program level before a recording or system is accepted or delivered.", "plain_english": "It means checking that the quiet background hiss of a system or recording is low enough to be acceptable. You measure the noise when nothing is playing, like making sure a room is quiet before you record.", "purpose_function": "It confirms that self-noise from mics, preamps, converters, or a room is within spec, protecting audio quality and catching faults such as ground hum or bad gain staging before they spoil a job.", "practical_application": "Before a session or at delivery, a technician meters or records silence and compares the noise-floor level to a target so problems can be fixed before program material is captured.", "category": "Signal Quality", "related_terms": ["Noise floor", "Signal-to-noise ratio", "Gain staging", "Dynamic range", "Hum", "Metering"], "common_mistakes": ["Measuring with the wrong meter or weighting, giving a misleading noise figure", "Ignoring ground hum or interference that sits above the true self-noise", "Setting input gain too high or too low, so gain staging rather than the gear dominates the reading"], "scenario_contexts": ["An engineer checks the noise floor of a mic preamp chain before a quiet acoustic session", "A post facility validates that a delivered file's noise floor meets broadcast spec", "A technician traces a raised noise floor to a ground loop after a rig change"]}, "00db1fde-b7aa-49b5-b354-68d8f19fed7c": {"definition": "A Nuendo project is the working document of Steinberg Nuendo, a digital audio workstation aimed at post-production for film, television, and game audio. The project file, with its linked media, stores the session's tracks, events, edits, mixer settings, automation, and references to audio and video media.", "plain_english": "A Nuendo project is the save file for Steinberg's Nuendo program, which is used to mix sound for film and TV. It holds all your tracks, edits, and settings in one place, like a document that remembers your whole session.", "purpose_function": "It keeps all parts of a post-production session, meaning audio, video reference, edits, routing, and automation, together so work can be saved, reopened, and shared while media files stay linked rather than duplicated.", "practical_application": "A post engineer opens a Nuendo project to continue an edit, imports the video and audio, and saves the project so the session state and automation are kept between sessions.", "category": "DAW / Software", "related_terms": ["Digital audio workstation (DAW)", "Session", "Automation", "Stem", "Post-production", "Cubase"], "common_mistakes": ["Moving or deleting linked media files, so the project opens with missing audio", "Confusing Nuendo with Cubase; the projects are similar but not identical in features", "Not backing up or saving new versions, risking loss of session work"], "scenario_contexts": ["A dubbing mixer opens a Nuendo project to mix dialogue, music, and effects for a film", "A game-audio designer manages a Nuendo project for interactive sound assets", "An editor archives a Nuendo project with its media pool for later re-opening"]}, "917e9db2-7fca-4a03-8634-59084f6f9875": {"definition": "A recorded audio sample of a hi-hat struck while the two cymbals are held apart (foot pedal up), producing a sustained, ringing 'open' sound; it is used in samplers and drum machines as the open-hi-hat voice, contrasting with the short closed-hi-hat sample.", "plain_english": "It is a recording of a hi-hat cymbal played with the two plates held open, so it rings out instead of making a short 'tick.' Producers drop it into beats when they want a longer, sizzly cymbal sound.", "purpose_function": "It supplies the open, sustained hi-hat articulation in programmed drum parts, working against the short closed-hi-hat sample to build groove and accents.", "practical_application": "A technician loads it onto a pad or MIDI note in a sampler and usually sets it to choke (cut off) when the closed hi-hat plays, mimicking a real drummer's foot on the pedal.", "category": "Drum Samples", "related_terms": ["Closed hi-hat sample", "Drum sampler", "Choke group", "Velocity layer", "One-shot sample", "Drum programming"], "common_mistakes": ["Letting the open hi-hat ring across the next closed hi-hat instead of using a choke/mute group, which sounds cluttered and unnatural", "Treating it like a closed hi-hat and not accounting for its longer decay in the mix", "Not tuning or time-aligning the sample so its length clashes with the track tempo and feel"], "scenario_contexts": ["Building a hip-hop or electronic beat and placing an open hi-hat on the offbeats", "Setting up a choke group so the open hi-hat cuts off the instant the closed hi-hat triggers", "Layering an open-hi-hat sample over live drums to add sizzle"]}, "7ffd3ac7-ffb4-4374-b8c7-4aac6c759bd6": {"definition": "In a stem delivery, a grouped submix (stem) supplied as a non-mandatory extra, such as an alternate vocal, an effects-only, or a spare instrument-group stem, provided in addition to the required stems to give more flexibility in later re-mixing, mastering, or media use.", "plain_english": "A stem is one part of a song bounced out on its own, like all the drums together. An 'optional' stem is an extra one you include just in case someone needs it later, even though the job does not require it.", "purpose_function": "It gives downstream users such as mastering engineers, film mixers, or remixers extra separated material to work with, without cluttering the required set of deliverables.", "practical_application": "When exporting stems, an engineer may add optional stems (for example a clean lead vocal or a reverb-only bus) and label them clearly so the client can use them only if needed.", "category": "Stems & Delivery", "related_terms": ["Stem", "Submix", "Bus", "Stem mastering", "Deliverables", "Bounce/Export"], "common_mistakes": ["Labeling optional stems poorly so the client cannot tell them apart from the required set", "Bouncing optional stems at a different level, length, or sample rate than the main stems, breaking alignment", "Assuming a stem is optional when the delivery spec actually requires it"], "scenario_contexts": ["Delivering song stems to a mastering engineer and adding an optional instrumental stem", "Providing optional effects-only stems for a film re-recording mixer", "Supplying an optional a cappella stem for possible remix use"]}, "03979326-c4bd-458c-848f-63ecd2815fd7": {"definition": "The process of balancing, panning, and processing a recorded orchestra so the sections (strings, brass, woodwinds, percussion) sit in a natural, coherent stereo or surround image, typically preserving the acoustic depth and hall ambience of the recording rather than the close-mic separation of pop production.", "plain_english": "It is mixing a recording of a full orchestra so every section can be heard in the right place and at the right volume. The goal is to keep it sounding natural, like sitting in a concert hall.", "purpose_function": "It delivers a believable orchestral balance and sense of space for film, game, or album work, letting the composer's arrangement come through clearly.", "practical_application": "An engineer blends spot (close) mics with the main and room mics, sets section levels, and adds subtle reverb to seat the orchestra in one consistent hall, often matching picture in scoring work.", "category": "Orchestral Mixing", "related_terms": ["Spot microphone", "Decca tree", "Section balance", "Reverb", "Surround mix", "Stem"], "common_mistakes": ["Over-panning sections so the orchestra sounds far wider than any real hall", "Relying only on spot mics and losing the natural blend the main and room mics provide", "Adding so much reverb that detail and clarity disappear"], "scenario_contexts": ["Mixing a recorded film score to picture", "Balancing a live-recorded symphony for album release", "Combining Decca-tree main mics with spot mics for a video-game orchestral cue"]}, "5d4adf55-38eb-45c8-a9c7-173b847a2709": {"definition": "The quality-control step of checking that a mix's final rendered file meets the required delivery specification, including integrated loudness (LUFS), true-peak ceiling, sample rate, bit depth, file format, channel or track layout, and metadata, before it is exported or handed off.", "plain_english": "It is the last check to make sure the finished audio file is correct before you send it. You confirm things like loudness, format, and that nothing is clipping or missing.", "purpose_function": "It catches format and level errors before delivery, so the file is accepted and plays back correctly on the target platform.", "practical_application": "Before delivering, a technician runs a loudness meter and file checker to confirm the render hits the spec's LUFS and true-peak targets and is in the correct format, then logs the result.", "category": "Delivery & QC", "related_terms": ["Loudness normalization", "True peak", "LUFS", "Deliverables", "Bounce/Export", "Metadata"], "common_mistakes": ["Validating only peak level and ignoring the integrated loudness (LUFS) target", "Checking the session but not the actual exported file, so a bad render slips through", "Skipping format checks such as sample rate, bit depth, and channel order that cause rejection"], "scenario_contexts": ["Checking a mastered track hits its streaming loudness and true-peak targets before upload", "Verifying a broadcast mix meets EBU R128 before delivery", "Confirming exported stems are all the same length, sample rate, and format"]}, "99e6bd28-df3f-4311-a2ad-181677ca49d4": {"definition": "To push a signal chain or sound-reinforcement system past its linear operating range, by raising gain or level beyond the equipment's headroom, so it clips or distorts; it is sometimes done deliberately for saturation, but on a PA it risks driving amplifiers into clipping and damaging loudspeakers.", "plain_english": "It means turning a system up so hard that it can no longer handle the signal cleanly and starts to distort. A little can sound gritty on purpose, but too much sounds bad and can wreck speakers.", "purpose_function": "The term describes exceeding a device's or system's clean headroom, either as an intentional distortion effect or as an unwanted fault that degrades sound and endangers gear.", "practical_application": "A technician watches meters and clip lights to avoid overdriving amps and drivers during a loud show, and only overdrives a channel or plugin on purpose, at controlled levels, for tonal color.", "category": "Gain Structure", "related_terms": ["Clipping", "Headroom", "Gain staging", "Saturation", "Distortion", "Limiter"], "common_mistakes": ["UNSAFE: Overdriving a power amplifier into clipping, whose flat-topped waveform sends excess energy to the drivers and can overheat and destroy loudspeakers", "UNSAFE: Pushing system level past its clean limit to chase more volume instead of adding proper amplification and speakers, risking hearing damage and gear failure", "Confusing pleasant analog-style saturation with hard clipping and overdoing the level"], "scenario_contexts": ["A PA sounds harsh and distorted because the amps are being overdriven at front-of-house", "Deliberately overdriving a channel plugin for a gritty bass tone", "The master bus clips on export because the mix overdrives the output"]}, "d238425c-0814-46f8-bf9d-257a05751da4": {"definition": "iZotope Ozone is a modular mastering software suite, available as a plug-in and standalone application, that combines processing modules such as an equalizer, dynamics, multiband exciter, stereo imager, and a peak-limiting Maximizer together with metering, used to finalize a mix into a distribution-ready master.", "plain_english": "Ozone is a mastering program. It puts many polishing tools in one place, like EQ, compression, and a loudness limiter. Engineers use it as the last step to make a song sound balanced and ready to release.", "purpose_function": "It exists to provide an integrated mastering chain and consistent metering in one interface, so an engineer can shape tonal balance, control dynamics, adjust stereo width, and raise loudness on a finished mix without patching together separate plug-ins.", "practical_application": "A technician loads Ozone on the stereo/master bus or in its standalone editor and uses its modules, reference tools, and meters to match a target tonal balance and hit a required integrated loudness and true-peak ceiling before export.", "category": "Mastering Software", "related_terms": ["Maximizer", "Limiter", "True peak", "Integrated loudness", "Mastering", "Stereo imaging"], "common_mistakes": ["Treating the Master Assistant or a preset as a finished master rather than a starting point that still needs critical listening", "Pushing the Maximizer for maximum loudness and introducing audible distortion or true-peak overshoots", "Expecting mastering in Ozone to repair a poor balance that should have been fixed in the mix"], "scenario_contexts": ["Preparing a final stereo master to meet streaming loudness and true-peak targets before upload", "Matching the tonal balance of a mix to a commercial reference track", "Applying gentle, consistent bus processing and metering across an album"]}, "b920ec62-20e4-4ad8-8f9b-b0c15843ace9": {"definition": "A dedicated run through a song in which the engineer writes or refines panning automation, recording changes in a track's or bus's stereo (or surround) position over time, so panning moves dynamically with the arrangement instead of staying static.", "plain_english": "It is a focused run through the song where you record how sounds move left and right over time. Instead of setting one fixed pan, you draw or perform pan changes so things can shift as the music changes.", "purpose_function": "It lets stereo placement change with the music, such as following a solo, widening a chorus, or moving an effect, adding motion and clarity that a single static pan cannot provide.", "practical_application": "The engineer arms pan automation (write, touch, or latch), performs or draws the moves for the chosen tracks, then plays back and edits the automation curve until the movement feels musical.", "category": "Automation", "related_terms": ["Automation", "Panning", "Write/Touch/Latch modes", "Automation lane", "Fader automation pass", "Stereo image"], "common_mistakes": ["Leaving the automation mode in Write, which erases existing moves on the next pass", "Making pan moves so fast or wide that they distract the listener", "Automating pan on a center-critical element like a lead vocal or kick and weakening the mix"], "scenario_contexts": ["Doing a pan automation pass to sweep a synth from left to right in a breakdown", "Automating pan to follow a guitar solo slightly off-center during its feature", "Adding subtle pan moves to widen background vocals in the chorus"]}, "0565b4ee-a1f5-468b-b140-84219c82ba49": {"definition": "A display mode in a DAW or on a mixing console that shows the pan (stereo or surround position) settings of channels or tracks, letting the engineer see and adjust left-to-right placement across the whole mix in one place.", "plain_english": "It is a screen or view that shows where each track sits from left to right. It lets you see and change all your panning in one spot instead of hunting channel by channel.", "purpose_function": "It gives a single overview of stereo placement so the engineer can compare and balance the panning of many tracks quickly.", "practical_application": "The engineer switches to the pan view to spot tracks stacked in the same position, then spreads them out for a wider, clearer stereo image.", "category": "DAW Interface", "related_terms": ["Panning", "Pan pot", "Stereo image", "Mixer view", "Pan automation pass", "Balance control"], "common_mistakes": ["Confusing a true pan control with a balance control on stereo tracks", "Judging pan positions from the view alone instead of listening", "Overlooking that some views display pan law or level compensation differently"], "scenario_contexts": ["Opening the pan view to check nothing is crowded in the center", "Using a console's pan view to set up a wide drum-overhead image", "Reviewing pan positions before printing a mix"]}, "a329b6b8-c45c-45ed-b364-0153d2ebeb41": {"definition": "A signal-processing configuration in which a set of devices (effects or processors) is fed a copy of the source and processed independently, then blended back with the unprocessed or differently processed signal, rather than being inserted in series; it is commonly used for parallel compression, saturation, or effect blends.", "plain_english": "Instead of sending a sound through effects one after another, you split off a copy and treat it on its own. Then you mix that copy back in. This adds a heavily processed layer while keeping the original clean sound.", "purpose_function": "It lets an engineer add strong processing, like heavy compression or distortion, while keeping the natural dynamics and tone of the untreated signal by blending the two together.", "practical_application": "A technician sends a copy of a drum bus to a parallel chain of compression and EQ, through a return, aux, or a parallel rack, then blends it under the dry drums for extra punch.", "category": "Signal Routing", "related_terms": ["Parallel compression", "Aux/return bus", "Dry/wet mix", "Series processing", "Send", "Device rack"], "common_mistakes": ["Phase or timing problems when the parallel path has latency that is not compensated, which thins the combined sound", "Blending in so much of the processed path that it defeats the point of keeping the dry signal", "Confusing parallel (blended) routing with series (in-line) insert processing"], "scenario_contexts": ["Setting up parallel compression on drums through a return chain", "Blending a distorted parallel bass chain under the clean bass", "Using a parallel effect rack in a DAW for a heavily processed reverb layer"]}, "100b1516-7af8-4cad-926d-147a6283a366": {"definition": "The routing that carries a track's post-fader output to its parent - the folder or group channel that contains it, or the master bus when the track sits at the top level. In DAWs such as REAPER it appears as the 'Master/parent send' control, which enables or disables this upward signal flow so the track feeds the group mix.", "plain_english": "A parent send is how a track passes its sound up to the group it belongs to, or to the main mix. Think of it like a small stream flowing into a bigger river. If you switch it off, that track no longer reaches the mix.", "purpose_function": "It defines where a track's audio goes in a nested mixing structure, letting several tracks collapse into one group so they can be processed and level-controlled together. Turning it off lets you reroute a track elsewhere without it also leaking into the parent group.", "practical_application": "A technician toggles or checks the parent send when a track is unexpectedly missing from, or doubling into, a group; disabling it is common when a track should feed only a submix or aux and must not also hit the master.", "category": "Signal Routing", "related_terms": ["Bus", "Subgroup", "Aux send", "Master bus", "Group channel"], "common_mistakes": ["Assuming a track is muted from the mix when its parent send is simply disabled, so the fader and solo seem to behave oddly.", "Leaving the parent send on while also adding a manual send to the same bus, which double-routes the signal and causes level buildup or comb filtering.", "Confusing an aux/effects send (a parallel tap) with the parent send (the track's main output path)."], "scenario_contexts": ["Building a drum submix by folding kick, snare and overheads into one parent group for shared compression.", "Muting a stem from the master while still feeding it to a headphone or aux mix by disabling its parent send.", "Troubleshooting a track that plays in solo but vanishes in the full mix because its parent send was turned off."]}, "61d95060-b42b-47be-b94e-105bbea85820": {"definition": "Console and mixing jargon for setting a channel or master fader to a chosen level and leaving it fixed for the duration, rather than continuously riding or automating it. A 'parked' fader holds a static gain so that source stays at one balance in the mix.", "plain_english": "To park a fader means to set it to one level and then leave your hand off it. It is like setting cruise control on a car instead of pressing the pedal the whole time. The sound stays at the same volume until you choose to move it again.", "purpose_function": "It gives a stable, repeatable balance for a source that does not need moment-to-moment level changes, freeing the operator's attention for parts of the mix that do need active riding.", "practical_application": "An engineer parks steady sources like a click return or a backing pad, then spends live-mix effort riding vocals and solos; parked levels also form the static starting balance before automation is written.", "category": "Console Operation", "related_terms": ["Fader", "Gain riding", "Automation", "Static mix", "Unity gain"], "common_mistakes": ["Parking a fader well below or above unity out of habit and losing gain-structure headroom instead of fixing the level at the source.", "Parking every fader and never riding dynamic sources like a lead vocal, so it gets buried or jumps out.", "Forgetting a fader is parked while an automation write mode is armed, so the console overwrites intended moves with the static value."], "scenario_contexts": ["Live mixing where the engineer parks stable channels and rides only vocals and solos.", "Setting a static starting balance before recording automation passes in a DAW.", "Leaving a talkback or click return parked at a fixed monitor level throughout a session."]}, "3681c26b-860b-4a5a-ad2a-c85f73759ef2": {"definition": "Automation whose parameter moves are stored in and recalled with a sequencer pattern, so level, pan, filter or effect changes repeat every time that pattern plays. On step-based instruments it is often implemented as per-step parameter changes, such as Elektron's parameter locks.", "plain_english": "Pattern automation means volume, tone or effect changes are saved inside a short repeating pattern. Every time the pattern loops, those same moves happen again on their own. It is like a wind-up music box that plays the exact same twists each turn.", "purpose_function": "It lets a repeating musical block carry its own dynamic changes, adding movement and variation to loops without a musician performing the moves live each time.", "practical_application": "A producer draws or step-locks filter sweeps, volume fades or pan moves inside a drum or synth pattern so the loop evolves; those moves travel with the pattern when it is copied or chained into an arrangement.", "category": "Sequencing", "related_terms": ["Automation", "Pattern sequencer", "Parameter lock", "Pattern chain", "Step sequencer"], "common_mistakes": ["Expecting pattern automation to keep running after the pattern ends, when the moves reset with each loop.", "Writing automation into the wrong pattern, then not hearing it because a different pattern is playing.", "Confusing pattern (loop-based) automation with linear timeline automation on an arrangement track."], "scenario_contexts": ["Adding a filter sweep inside a 16-step bass pattern on a groovebox.", "Automating a reverb send per step so only certain hits are wet.", "Copying a pattern to a new section and having its volume swells copy with it."]}, "edf6cc08-169d-4da7-b472-77ff33f4bb22": {"definition": "A sequence of individual patterns linked to play back one after another in a set order, forming a longer passage or full song from short looped building blocks. Chaining is the step between single looping patterns and a full arrangement in pattern-based sequencers and drum machines.", "plain_english": "A pattern chain is a list of short patterns set to play one after the other. Instead of looping one beat forever, you line up several so they play like verses and choruses. It is like a playlist, but made of short drum or music loops.", "purpose_function": "It turns a collection of short loops into an arranged performance, letting an artist build song structure without recording one long take.", "practical_application": "On a drum machine or groovebox the tech enters chain or song mode and lists pattern numbers in order, sometimes with repeat counts, so an intro, verse and chorus play back hands-free during a set.", "category": "Sequencing", "related_terms": ["Pattern sequencer", "Song mode", "Pattern length", "Pattern variation", "Arrangement"], "common_mistakes": ["Editing a pattern used several times in a chain and being surprised the change appears at every point it plays.", "Forgetting to save the chain or song, so the order is lost when a new pattern is selected.", "Mismatched pattern lengths in a chain causing unexpected timing or dropped beats at transitions."], "scenario_contexts": ["Building a full track from intro, verse and chorus patterns on a Roland or Elektron box.", "Performing live by triggering a pre-built chain so the arrangement runs hands-free.", "Sketching song structure quickly before exporting stems to a DAW."]}, "b8d4032a-d02e-4efb-9789-26a9933f4ba1": {"definition": "A short variation pattern - most often a drum fill - used to break up and lead between repetitions of a main pattern, typically triggered momentarily or inserted at the end of a phrase. Many drum machines provide a dedicated fill or variation function that plays this alternate pattern for a bar or beat before returning to the main groove.", "plain_english": "A pattern fill is a short burst that breaks up a looping beat, like a quick drum roll before the next section. You usually trigger it for just a bar, then the main groove comes back. It keeps a repeating pattern from sounding boring.", "purpose_function": "It adds momentum and signals transitions in an otherwise repetitive loop, imitating how a live drummer plays a fill to lead into a new section.", "practical_application": "A performer holds or triggers the fill button near the end of a phrase so the machine plays a roll or variation, then drops back to the main pattern for the next section.", "category": "Sequencing", "related_terms": ["Pattern variation", "Pattern chain", "Pattern sequencer", "Drum fill", "Groove"], "common_mistakes": ["Triggering fills too often so they stop feeling like special transitions.", "Confusing a momentary fill (temporary) with permanently switching to a different pattern.", "Fills of a different length knocking the sequence off the bar so the next section starts late."], "scenario_contexts": ["Triggering a drum fill going into a chorus during a live set.", "Using a machine's fill or variation button to add motion to a looped beat.", "Programming an alternate fill pattern to play automatically every eighth bar."]}, "21cc42fd-7566-4230-84b4-996814604d40": {"definition": "The number of steps or bars a sequencer pattern spans before it loops. Setting pattern length fixes how long the loop is - for example 16 steps of a sixteenth-note grid equals one bar - and some sequencers allow independent track lengths within one pattern to create polyrhythms.", "plain_english": "Pattern length is how long a loop is before it repeats. For example, 16 short steps usually make one bar of music. Make it longer for a bigger loop, or shorter for a quicker repeat.", "purpose_function": "It sets the size of the repeating musical block and, together with the step rate, determines the loop's duration and feel; independent track lengths let parts of different sizes cycle against each other.", "practical_application": "A producer sets pattern length to control how many steps are programmable and how often the loop turns over, extending it for longer phrases or using odd lengths for evolving polyrhythmic patterns.", "category": "Sequencing", "related_terms": ["Pattern sequencer", "Step sequencer", "Pattern chain", "Time signature", "Polyrhythm"], "common_mistakes": ["Confusing pattern length (how many steps) with tempo (how fast the steps play).", "Leaving the default 16 steps and cutting off phrases that need more.", "Setting mismatched track lengths by accident and getting a drifting, unintended polyrhythm."], "scenario_contexts": ["Extending a pattern from 16 to 32 steps to fit a two-bar bassline.", "Setting a hi-hat track to a different length than the kick for an evolving groove.", "Matching pattern lengths across a chain so sections line up on the bar."]}, "517e4395-5b7c-4226-8fdb-d2ab6ceffb07": {"definition": "A sequencer that stores and plays musical events as short, self-contained repeating patterns (loops) which are then selected, edited and chained, rather than recorded along one continuous linear timeline. Drum machines and grooveboxes are typical examples, commonly using a step grid to enter notes and triggers.", "plain_english": "A pattern sequencer is a tool that plays music as short loops you build and then line up. Instead of recording one long take, you make small patterns and arrange them. Drum machines work this way, often using a row of step buttons.", "purpose_function": "It makes it fast to build, edit and rearrange repeating musical parts, which suits beat-driven and electronic music where loops are the core building blocks.", "practical_application": "A producer programs kicks, snares and notes onto a step grid to make a pattern, tweaks and copies it, then chains patterns into a full arrangement or triggers them live.", "category": "Sequencing", "related_terms": ["Step sequencer", "Pattern chain", "Pattern length", "Drum machine", "Groovebox"], "common_mistakes": ["Expecting linear timeline recording and getting confused by the loop-based pattern workflow.", "Editing a shared pattern and unintentionally changing it everywhere it is used in a chain.", "Not saving patterns before switching, losing programmed work."], "scenario_contexts": ["Programming a beat on a hardware groovebox or drum machine.", "Using a DAW's pattern or clip view to build loops before arranging.", "Chaining patterns to perform a track live without a laptop."]}, "20bef4f0-1cfe-46bd-b434-4303c23e7b3d": {"definition": "An alternate version of a pattern that keeps its overall identity while changing some notes, hits or parameters, used to relieve repetition - for example a B-variation of a drum pattern or a fill-style change. Many drum machines provide A/B or numbered variations that can be switched or chained with the main pattern.", "plain_english": "A pattern variation is a slightly changed version of a loop. It keeps the same feel but adds or removes a few hits so the beat does not sound too repetitive. It is like singing a verse the second time with a small twist.", "purpose_function": "It adds interest and marks sections by giving a repeating loop small changes, so a track feels less static without needing a whole new pattern.", "practical_application": "A producer makes an A pattern and a B variation, then switches or chains between them for verse and chorus feel, or drops a variation in every few bars for movement.", "category": "Sequencing", "related_terms": ["Pattern fill", "Pattern chain", "Pattern sequencer", "Pattern length", "Groove"], "common_mistakes": ["Making variations so different they sound like an unrelated pattern and break the groove.", "Forgetting which slot holds the variation and triggering the wrong one live.", "Overusing variations so none of them feels special."], "scenario_contexts": ["Switching from an A groove to a busier B variation in the chorus.", "Adding a variation with an extra snare every fourth bar for motion.", "Chaining main and variation patterns to build a simple arrangement."]}, "acf04dd8-ddb2-42e9-a160-87e44553322a": {"definition": "Peak validation is the quality-control process of measuring and confirming that an audio file's peak levels, including inter-sample (true) peaks, stay at or below a defined ceiling and meet the delivery specification, so the signal does not clip on playback or when re-encoded.", "plain_english": "Peak validation means checking that the loudest points in a track never go over the safe limit. It is like making sure nothing pokes above a line before you send the file, so it will not crackle or distort.", "purpose_function": "It exists to catch clipping and true-peak overshoots before delivery, protecting the audio from distortion added by converters and lossy encoders, which can push inter-sample peaks above 0 dBFS.", "practical_application": "An engineer reads a true-peak meter during export or in a metering tool and confirms peaks sit at or below the required ceiling, often around -1 dBTP for streaming, re-limiting if any overshoot appears.", "category": "Quality Control", "related_terms": ["True peak", "Clipping", "Peak meter", "dBFS", "Limiter", "Loudness normalization"], "common_mistakes": ["Reading only the sample-peak meter and missing inter-sample (true) peaks that exceed 0 dBFS after conversion", "Assuming a file that reads 0 dBFS is safe for lossy encoding, which can raise true peaks further", "Confusing peak level with loudness (LUFS), which measure different things"], "scenario_contexts": ["Verifying a master meets a -1 dBTP true-peak ceiling before uploading to a streaming platform", "Checking a mix or stems for clipping before sending to mastering", "Confirming a broadcast deliverable meets the true-peak limit of its loudness standard"]}, "6dfe2674-473e-40e7-9ae4-4fc6991491a4": {"definition": "A percussion layer is a supplementary rhythmic element (such as a shaker, tambourine, or extra drum part) added to a mix on top of the core drum parts, or one of several percussion sounds stacked together to form a single fuller-sounding hit or groove.", "plain_english": "It is an extra percussion sound stacked on top of the main drums to add texture and groove. Think of it like adding a shaker or tambourine over a beat to fill it out.", "purpose_function": "It adds rhythmic detail, energy, and stereo width that the main kit alone cannot provide, helping a groove feel fuller and more finished.", "practical_application": "When mixing, an engineer balances each percussion layer under the main drums, panning and EQing shakers, congas, or tambourines so they support the groove without cluttering it.", "category": "Arrangement", "related_terms": ["Percussion sample", "Layering", "Panning", "Bus", "Stereo image", "EQ"], "common_mistakes": ["Stacking too many percussion layers so the groove becomes cluttered and loses punch.", "Leaving every layer at full level instead of balancing them beneath the main drums.", "Forgetting to check that stacked layers are in phase, causing weak or hollow hits.", "Not high-pass filtering thin percussion layers, letting low-end mud build up."], "scenario_contexts": ["Adding a tambourine and shaker layer to lift the choruses of a pop song.", "Stacking a sampled clap on top of a live snare to reinforce the backbeat.", "Building a percussion layer of congas and shakers to give an electronic track a live feel."]}, "63a5e3f0-3c0d-4478-a891-c785724253ef": {"definition": "A percussion sample is a short, pre-recorded digital audio file of a single percussion sound (such as a kick, snare, clap, or shaker) stored for playback and triggering in a sampler, drum machine, or DAW.", "plain_english": "It is a short recording of one drum or percussion sound saved on a computer. You can trigger it with a pad or key to play that exact sound whenever you want.", "purpose_function": "It lets producers reuse consistent, high-quality percussion hits without re-recording them, and gives precise control over each sound's timing, pitch, and level.", "practical_application": "A producer loads percussion samples into a drum sampler or places them on a DAW timeline, layering and tuning them to build beats and reinforce recorded drums.", "category": "Sampling", "related_terms": ["Percussion layer", "Sampler", "Drum machine", "One-shot", "Trigger", "Velocity"], "common_mistakes": ["Using a low-quality or heavily compressed sample and expecting clean, punchy results.", "Not checking the sample's tuning against the song's key.", "Triggering samples at one fixed velocity so the part sounds robotic and flat.", "Ignoring the sample's built-in room tone or reverb, which can clash with the mix."], "scenario_contexts": ["Loading a kick and snare sample into a drum machine to program a beat.", "Layering a percussion sample under a weak live drum recording to add punch.", "Replacing a poorly recorded tom with a matched percussion sample during editing."]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"ac0a9ba0-8b0e-4656-85e6-a43b2400c619": {"definition": "Phase validation is the process of checking that the phase (time and polarity) relationships between related audio signals, such as multiple microphones on one source, are correct so the signals reinforce rather than cancel each other when summed.", "plain_english": "It means checking that your tracks line up in time so they do not fight each other. When two mics on one drum are out of step, the sound gets thin or hollow, so you test and fix it first.", "purpose_function": "It exists to catch phase cancellation early, protecting low-end power and tonal balance when multi-mic or layered signals are combined.", "practical_application": "An engineer validates phase by summing tracks to mono, flipping a polarity switch, or nudging tracks, listening for the fullest, most solid sound before committing to the mix.", "category": "Phase Alignment", "related_terms": ["Phase-locked audio editing", "Polarity", "Phase cancellation", "Mono compatibility", "Comb filtering", "Time alignment"], "common_mistakes": ["Confusing polarity (a 180-degree flip) with true time-based phase differences.", "Only checking in stereo and never summing to mono to reveal cancellation.", "Assuming a polarity flip alone fixes phase problems caused by mic distance.", "Skipping phase checks on multi-mic drum and guitar recordings."], "scenario_contexts": ["Checking top and bottom snare mics before mixing a drum kit.", "Verifying a DI and mic'd guitar amp sum together without thinning out.", "Testing a mix for mono compatibility before it plays on a club or phone speaker."]}, "057a8f84-5dd9-4eea-a088-83a6adf1d18b": {"definition": "Phase-locked audio editing is editing multiple related tracks (such as all the microphones on a drum kit) together as a group, so every cut, move, or time adjustment is applied identically across them, preserving their relative timing and phase relationships.", "plain_english": "It means editing a group of tracks all at once so they stay lined up in time. If you move one drum mic, every other drum mic moves the exact same amount, so the sound never goes out of step.", "purpose_function": "It exists to keep multi-mic recordings phase-coherent during editing, preventing the thin or hollow tone that results when tracks drift out of alignment.", "practical_application": "When editing drums, an engineer uses edit groups in the DAW so quantizing, trimming, and crossfades happen on every kit track together rather than one at a time.", "category": "Editing", "related_terms": ["Phase validation", "Edit group", "Quantization", "Crossfade", "Comb filtering", "Beat Detective"], "common_mistakes": ["Editing one drum mic alone and shifting it out of phase with the others.", "Forgetting to enable the edit group before quantizing multi-mic drums.", "Using crossfades that are too short, causing clicks at edit points.", "Not creating matching crossfades on every grouped track."], "scenario_contexts": ["Tightening a live drum take by quantizing all kit mics as one group.", "Comping a multi-mic acoustic guitar so every mic stays aligned.", "Editing a bleed-heavy band recording where isolating one track would cause phase shifts."]}, "f30af591-deb9-4acb-800d-502ef9eadb18": {"definition": "A phrase-aligned transition is an arrangement or edit change (such as an effect sweep, drop, or section change) timed to land exactly on the boundary of a musical phrase, typically a group of bars, so the change feels musically natural.", "plain_english": "It is a change in the music that lands right at the end of a musical phrase, not in the middle of one. Like finishing a sentence before starting a new one, it makes the switch between sections feel smooth.", "purpose_function": "It exists to make section changes, builds, and edits feel intentional and musical by tying them to the song's natural phrasing rather than to arbitrary points.", "practical_application": "An engineer places crossfades, filter sweeps, or scene changes on phrase boundaries, often every 4, 8, or 16 bars, using the DAW grid and markers to keep transitions tight.", "category": "Arrangement", "related_terms": ["Phrase", "Bar", "Automation", "Crossfade", "Arrangement marker", "Grid"], "common_mistakes": ["Dropping a transition mid-phrase so the change feels jarring.", "Ignoring the song's bar count and eyeballing edits instead of using the grid.", "Cutting off a vocal or melodic tail at the transition point.", "Assuming every phrase is 8 bars without counting the actual arrangement."], "scenario_contexts": ["Timing a riser and drop to land on the first beat of a chorus.", "Aligning a DJ-style crossfade between two songs to the phrase.", "Placing a filter sweep so it resolves exactly at a new section."]}, "57969935-b5f2-47e5-8ae2-c8b6dece6083": {"definition": "\"Pin the meters\" is a colloquial term for driving a signal so hot that the level meters read at or beyond their maximum, with the indicator held (\"pinned\") against the top of its range, usually indicating overload and clipping.", "plain_english": "It means pushing a sound so loud that the level meter slams to the very top and stays there. It is a warning that the signal is too hot and is starting to distort.", "purpose_function": "The phrase flags that a signal has run out of headroom; spotting pinned meters tells an engineer to pull levels back before clipping or distortion ruins the recording.", "practical_application": "When setting gain, a technician backs off any channel or master fader whose meters are pinned, leaving headroom so peaks stay below 0 dBFS on a digital system.", "category": "Metering", "related_terms": ["Headroom", "Clipping", "Gain staging", "0 dBFS", "Peak meter", "Overload"], "common_mistakes": ["UNSAFE: Cranking a power amp until its meters pin, risking clipped drivers and hearing damage.", "Treating pinned meters as \"loud and good\" instead of a clipping warning.", "Confusing a peak meter pinning briefly with sustained overload.", "Chasing pinned meters instead of setting proper gain staging with headroom."], "scenario_contexts": ["Seeing input meters pinned during soundcheck and reducing preamp gain.", "Noticing the mix bus meters pinned in the red and lowering the master.", "Catching a bass DI pinning the converter and backing off its level."]}, "a9c7881e-881c-4ccf-819c-0bed5169752d": {"definition": "A pipeline hardware insert is a DAW routing tool (an insert-style plugin) that sends a channel's signal out of a physical audio-interface output to an external hardware processor and back through an input, placing the outboard gear into the mix signal path with automatic latency compensation.", "plain_english": "It is a tool that lets you plug a real piece of studio hardware into your computer mix. The software sends the sound out to the gear, then back in, and lines it up in time so nothing drifts.", "purpose_function": "It exists so engineers can use the sound of physical outboard gear, like a hardware compressor or EQ, inside an otherwise in-the-box mix without manual timing errors.", "practical_application": "An engineer patches an external EQ or compressor through the hardware insert, then runs a calibration ping so the DAW compensates for the round-trip delay and keeps the track in sync.", "category": "Routing", "related_terms": ["Insert", "Outboard gear", "Latency compensation", "Send and return", "I/O plugin", "Signal flow"], "common_mistakes": ["UNSAFE: Hot-patching gear without muting, sending a loud pop that can damage speakers and hearing.", "Forgetting to enable delay compensation, leaving the hardware track out of time.", "Creating a feedback loop by mis-routing the output back into the same input.", "Mismatching operating levels (+4 dBu vs -10 dBV) and overloading the hardware input."], "scenario_contexts": ["Running a mix bus through an external analog compressor during mixdown.", "Inserting a hardware EQ on a vocal track from inside a DAW session.", "Calibrating round-trip latency before printing a track processed by outboard gear."]}, "ccc69574-21d2-47fe-8059-eacf47832c79": {"definition": "A pitch correction handle is a draggable graphical control in a pitch-editing tool (such as a note \"blob\" in Melodyne or a note in Logic's Flex Pitch) that lets an engineer grab and move an individual note's pitch, and often its timing or other parameters, to correct or shape it.", "plain_english": "It is the little grab point on a note in tuning software that you drag to fix its pitch. Grab it and slide the note up or down until it sits in tune, like dragging a slider for that one note.", "purpose_function": "It exists to give precise, per-note control over tuning, letting an engineer nudge or fully correct individual notes without affecting the rest of the performance.", "practical_application": "When tuning vocals, an engineer drags each pitch correction handle to move flat or sharp notes onto the correct pitch, keeping the movement subtle to preserve a natural sound.", "category": "Pitch Editing", "related_terms": ["Pitch correction", "Pitch drift (Flex)", "Melodyne", "Flex Pitch", "Quantization", "Formant"], "common_mistakes": ["Snapping every note perfectly to pitch, producing an unnatural, robotic vocal.", "Dragging the handle and accidentally changing timing instead of pitch.", "Over-correcting notes and losing their natural vibrato and slides.", "Editing a note with heavy background bleed, which confuses the pitch analysis."], "scenario_contexts": ["Nudging a slightly flat chorus note back into tune on a lead vocal.", "Correcting a bass guitar note that drifted sharp during a take.", "Fixing one out-of-tune note in an otherwise strong vocal comp."]}, "7f134c46-cf38-48b7-9edc-10229c938a22": {"definition": "Pitch Drift is a Flex Pitch note parameter in Logic Pro, adjusted with hotspots at the upper corners of a note, that controls the amount of pitch deviation at the beginning and end of the note, reducing or increasing how much the pitch slides into and out of its sustained value.", "plain_english": "In Logic Pro's tuning tool, Pitch Drift controls how much a note bends up or down at its start and end. You can flatten out a wobble or keep a natural slide, shaping how smoothly the note enters and leaves its pitch.", "purpose_function": "It exists to fine-tune the natural slides at a note's edges, letting an engineer tighten sloppy transitions or preserve expressive pitch movement instead of flattening the whole note.", "practical_application": "When tuning a vocal in Flex Pitch, an engineer drags the upper-left and upper-right Pitch Drift hotspots to tame an unwanted scoop or fall-off at the start or end of a note.", "category": "Pitch Editing", "related_terms": ["Flex Pitch", "Pitch correction handle", "Fine Pitch", "Vibrato", "Formant Shift", "Pitch correction"], "common_mistakes": ["Removing all pitch drift and making natural note transitions sound stiff.", "Confusing Pitch Drift with the coarse Pitch parameter that moves the whole note.", "Adjusting drift on notes with heavy vibrato and getting unpredictable results.", "Forgetting that the two drift hotspots control the start and end separately."], "scenario_contexts": ["Reducing an unwanted upward scoop at the start of a sustained vocal note.", "Cleaning up a note that falls flat at its tail end.", "Keeping a tasteful pitch slide while still correcting the note's center pitch."]}, "8ea4df99-e305-4900-b0d7-415a087407ff": {"definition": "Platform optimization is the process of tailoring a master or deliverable to the loudness-normalization target, codec, sample rate, bit depth, and metadata requirements of a specific distribution platform, such as a streaming service, broadcaster, or video site, so it plays back as intended after the platform's own processing.", "plain_english": "Platform optimization means getting a song ready for the exact place it will play, such as Spotify or YouTube. Each service adjusts loudness and file type in its own way, so you prepare the file to fit and still sound good.", "purpose_function": "It exists because each platform normalizes loudness to its own target and re-encodes audio, so matching those targets and formats prevents unwanted turn-down, distortion, or quality loss and keeps playback consistent for listeners.", "practical_application": "A mastering engineer sets an integrated loudness and true-peak ceiling suited to a platform and delivers in its required format, for example allowing extra true-peak headroom for lossy codecs and aiming near the service's normalization level.", "category": "Mastering & Delivery", "related_terms": ["Loudness normalization", "Integrated loudness", "True peak", "LUFS", "Mastering", "Peak validation"], "common_mistakes": ["Mastering as loud as possible when platform loudness normalization simply turns it down, sacrificing dynamics for no benefit", "Ignoring the extra true-peak headroom lossy codecs need and getting encoder distortion", "Delivering one identical file to every platform without checking each one's target and format"], "scenario_contexts": ["Setting integrated loudness and true peak appropriate for Spotify or Apple Music", "Preparing an alternate louder master a client wants for a specific use", "Choosing loudness and file format for a podcast or video platform"]}, "2e4a6796-2ede-4f76-bed1-8d12c3023871": {"definition": "In a DAW, the Playback Cursor is the moving on-screen line that shows the exact point in the timeline currently being played, advancing in real time as audio plays. It is distinct from the stationary Edit Cursor (insertion point) that marks where editing and the next playback will begin.", "plain_english": "It is the line that moves across the screen while your song plays. It shows the exact spot you are hearing right now. It is like a bouncing ball that follows the words in a sing-along.", "purpose_function": "It gives the engineer constant visual feedback of the current playback position, so events, edits, and punch points can be matched to exactly what is being heard.", "practical_application": "An engineer watches the Playback Cursor to confirm where a click, breath, or downbeat falls, and uses its position to judge timing before setting loop or record points.", "category": "DAW Interface", "related_terms": ["Edit Cursor", "Timeline", "Transport controls", "Playhead", "Insertion point"], "common_mistakes": ["Confusing the moving Playback Cursor with the stationary Edit Cursor (insertion point), which is where playback and edits actually start", "Assuming the Playback Cursor sets the location for an edit, when it only reports position and does not place the insertion point", "Thinking playback will resume from where the moving cursor stopped, when the Edit insertion point usually governs that"], "scenario_contexts": ["Following the Playback Cursor to find the exact spot where a vocal breath should be edited out", "Watching the cursor cross a section boundary to confirm a transition lands on the downbeat", "Using the cursor's position during playback to decide where to set a loop for a repeating section"]}, "84b849f8-1c35-4ea8-914f-6cad19e54bd2": {"definition": "Playback translation is how well a finished mix keeps its intended tonal balance, clarity, and level relationships when heard on playback systems other than the one it was mixed on, such as car speakers, earbuds, phone speakers, or club systems.", "plain_english": "This means how good your mix still sounds on other speakers, not just the ones you mixed on. A great mix holds up on a phone, in a car, and on cheap earbuds too. It is like a recipe that still tastes good in any kitchen.", "purpose_function": "It measures whether mix decisions hold up in the real world, since listeners use many different and often low-quality devices rather than studio monitors.", "practical_application": "Engineers check translation by auditioning a mix on several systems, such as nearfield monitors, headphones, a phone, and a car, then adjust balances so it works everywhere.", "category": "Mixing Concept", "related_terms": ["Mix translation", "Reference monitor", "Nearfield monitor", "Reference track", "Mono compatibility", "Frequency balance"], "common_mistakes": ["Judging a mix only on one expensive pair of monitors and assuming it will sound the same everywhere", "Blaming poor translation entirely on the mix when an untreated room can be misleading the engineer", "Boosting extreme lows or highs that sound good on large monitors but disappear or distort on small speakers"], "scenario_contexts": ["Bouncing a rough mix and playing it in the car to check translation before ending a session", "Comparing a mix on earbuds and a phone speaker to make sure the vocal stays audible", "A mix that sounds full on studio monitors but thin on laptop speakers, revealing a translation problem"]}, "61a1acb9-5b3c-484b-bb7c-1cc0d72ab117": {"definition": "In a DAW (notably Pro Tools), Playlist View is a track display mode that shows a track's alternate edit playlists as separate stacked lanes, letting the engineer compare and comp together the best parts of multiple takes.", "plain_english": "It is a view that stacks all the takes of a part in separate lanes. You can then pick the best bits from each take and join them into one. It is like choosing the best photo from a burst of shots.", "purpose_function": "It exists to make comping easy, organizing multiple recorded takes of the same part so an engineer can audition, rate, and combine them into a single composite performance.", "practical_application": "After recording several vocal takes, an engineer switches the track to Playlist View and drags the strongest phrase from each lane up into the main playlist.", "category": "DAW Interface", "related_terms": ["Comping", "Take", "Playlist", "Track lanes", "Loop recording", "Composite take"], "common_mistakes": ["Confusing edit playlists (alternate takes on one track) with a playback queue or a streaming playlist", "Deleting an alternate playlist thinking it only clears the view, permanently losing that take", "Comping from lanes but forgetting to check crossfades at the edit points, causing clicks"], "scenario_contexts": ["Comping a lead vocal from ten loop-recorded takes shown as separate lanes", "Keeping alternate guitar solos on separate playlists to A/B later", "Building a composite drum take by choosing the best fill from several passes"]}, "e6bca3d8-1d22-45c8-8313-0e81eafc19df": {"definition": "A plug-in automation pass is a single run through a section during which an engineer records real-time changes to one or more of a plug-in's parameters (such as a filter cutoff or reverb mix) as automation data, so those moves replay automatically on later passes.", "plain_english": "It is one recorded run where you move a plug-in's controls while the song plays. The software remembers every move and replays it for you next time. It is like recording yourself turning a dial so it turns itself later.", "purpose_function": "It lets parameter changes be captured performance-style and repeated exactly on every playback, freeing the engineer from riding controls by hand each time.", "practical_application": "An engineer enables a plug-in parameter for automation, plays the section, and sweeps a filter or rides a reverb send in one pass; the DAW writes it as an automation curve to refine afterward.", "category": "Automation", "related_terms": ["Automation mode", "Write automation", "Touch automation", "Automation curve", "Parameter", "Automation lane"], "common_mistakes": ["Leaving the track in Write mode after the pass, so a later playback overwrites the automation you just recorded", "Automating the wrong control because the plug-in parameter was not correctly enabled for automation", "Trying to capture too many parameters in one pass instead of building it up over several focused passes"], "scenario_contexts": ["Recording a filter sweep on a synth in one automation pass during a build-up", "Riding a delay throw's feedback on a single vocal word in one pass", "Automating a plug-in's wet/dry mix to swell reverb into a chorus"]}, "85944355-027d-4f00-adde-da771c21d11b": {"definition": "Plug-in View refers to the on-screen window or panel that displays a plug-in's graphical interface and controls, opened from an insert slot so the engineer can see and adjust that processor's parameters and metering.", "plain_english": "It is the window that shows a plug-in's knobs, sliders, and meters. Opening it lets you see and change how that effect is set. It is like lifting the lid of a gadget to reach its dials.", "purpose_function": "It gives visual access to a plug-in's controls and metering so settings can be seen and edited, rather than staying hidden inside an insert slot.", "practical_application": "An engineer clicks an insert to open the Plug-in View, then dials in EQ curves or compressor settings while watching the plug-in's meters.", "category": "DAW Interface", "related_terms": ["Insert", "Plug-in", "Insert slot", "Signal chain", "Mix window", "Parameter"], "common_mistakes": ["Opening many Plug-in View windows at once and losing track of which insert each belongs to", "Assuming closing the Plug-in View bypasses or removes the plug-in, when it only hides the window", "Confusing a single Plug-in View window with the channel's Inserts view that lists all slots"], "scenario_contexts": ["Opening the Plug-in View of an EQ to sculpt a vocal's high end", "Watching a compressor's gain-reduction meter in its Plug-in View while setting the threshold", "Recalling a saved preset from within a plug-in's view window"]}, "c7f6f60d-780a-47b3-bf60-03297b297f80": {"definition": "Polarity validation is the process of confirming that a signal path preserves correct absolute polarity, so that a positive-going input produces a positive-going output and is not inverted, across cables, connectors, microphone channels, and loudspeaker drivers.", "plain_english": "This is checking that a signal is not accidentally flipped upside down by gear or cables. A flip can make sounds cancel and get weaker when they mix together. It is like two people pushing a swing in opposite directions instead of together.", "purpose_function": "It exists to prevent polarity inversions that cause cancellation and weak, hollow sound when signals are combined, such as summed microphone pairs or a mono fold-down.", "practical_application": "A technician uses a polarity tester (a paired send and receive unit) or a scope to check mic cables, DI boxes, and loudspeaker wiring, confirming the fuller result when polarity is correct.", "category": "Signal Integrity", "related_terms": ["Absolute polarity", "Phase", "Polarity inversion", "Comb filtering", "Mono compatibility", "Polarity switch"], "common_mistakes": ["Confusing polarity (a fixed 180-degree flip) with phase (a frequency- and time-dependent shift), and using the terms interchangeably", "Assuming a working cable is wired correctly for polarity without ever testing it", "Flipping polarity on one mic and forgetting to recheck the summed result, trading one cancellation for another"], "scenario_contexts": ["Checking a snare top and bottom mic pair for polarity before deciding whether to invert one", "Validating a batch of XLR cables with a polarity tester before a show", "Confirming loudspeaker wiring polarity so cabinets in an array push together rather than against each other"]}, "3e2f6e7f-b332-4248-9bfd-536a06f4727a": {"definition": "A polymetric sequence is a musical or programmed passage in which two or more parts run in different meters, or repeat over different bar or step lengths, at the same time, so the parts realign only after a longer combined cycle.", "plain_english": "It is when two rhythms of different lengths loop at the same time. Because they are not equal, they drift apart and only line up again later. Think of two runners on laps of different lengths who meet at the start only now and then.", "purpose_function": "It creates evolving, non-repeating rhythmic patterns and tension by layering cycles of unequal length that phase against each other before resetting.", "practical_application": "In a DAW or step sequencer, an engineer sets loops or clips to different lengths, such as a 7-step pattern against a 4-step pattern, so they combine into a long, shifting groove.", "category": "Rhythm & Timing", "related_terms": ["Polyrhythm", "Meter", "Time signature", "Step sequencer", "Loop length", "Odd meter"], "common_mistakes": ["Confusing polymeter (different meters or lengths running together) with polyrhythm (different subdivisions over the same span)", "Setting all patterns to the same length and then expecting a polymetric effect", "Forgetting the long combined cycle length and cutting the loop too short, so the interplay never resolves"], "scenario_contexts": ["Programming a 5-step hi-hat loop against a 4-step kick pattern for a shifting groove", "Layering a 7/8 synth line under a 4/4 drum beat in an electronic track", "Using clips of unequal length in a session to build an evolving background texture"]}, "f6b33709-4c9e-4902-91e8-e89440f90022": {"definition": "A Flex Time algorithm in Apple Logic Pro designed for editing the timing of complex, polyphonic audio that contains several simultaneous pitches, such as chords, piano, or a full mix. It analyzes the overlapping tones so transients and note positions can be moved and stretched without breaking the material into separate single notes.", "plain_english": "A setting in Logic Pro for stretching the timing of parts that play several notes at once, like a guitar chord or a whole band. It lets you nudge the timing without the sound falling apart.", "purpose_function": "It exists so an editor can correct or adjust the timing of chord-based or full-mix audio, where simpler single-note algorithms would fail, while keeping the harmony intact.", "practical_application": "An editor selects Polyphonic as the Flex Time algorithm on a piano, acoustic guitar, or stereo mix track, then drags flex markers to tighten the timing against the grid or the other instruments.", "category": "Time & Pitch Editing", "related_terms": ["Flex Time", "Time stretching", "Quantization", "Transient detection", "Monophonic mode (Flex)", "Elastic Audio"], "common_mistakes": ["Using the Monophonic algorithm on chordal material, which smears the sound, instead of Polyphonic", "Applying heavy stretching and expecting no artifacts, when polyphonic processing adds phasey or watery tone at large amounts", "Assuming Flex analysis is perfect and not checking or correcting the detected transient markers"], "scenario_contexts": ["Tightening the timing of a strummed acoustic guitar to the grid", "Fixing a rushed piano chord in a live recording", "Stretching a stereo mix or loop to match a new project tempo"]}, "74bee041-eb00-4e5e-9b35-2a3c779d6640": {"definition": "A sequenced or programmed musical pattern in which two or more independent rhythmic cycles of differing subdivision or length sound at the same time, such as three notes played against two. The parts share a common pulse only at intervals, producing a layered, interlocking rhythmic texture.", "plain_english": "A programmed pattern where two different rhythms run at once, like three beats laid over two. The parts line up only now and then, which gives the groove a rolling, woven feel.", "purpose_function": "It lets a producer build rhythmic interest and tension by combining meters or subdivisions that do not share the same pulse, adding movement beyond a single straight rhythm.", "practical_application": "A producer programs one MIDI part in triplets and another in eighth notes, or sets two step sequencers to different lengths, so the patterns drift against each other and realign over a longer cycle.", "category": "Rhythm & Sequencing", "related_terms": ["Step sequencer", "MIDI sequencing", "Time signature", "Quantization", "Groove template", "Subdivision"], "common_mistakes": ["Confusing a polyrhythm (different pulses at once) with a polymeter (different bar lengths sharing one pulse)", "Quantizing every part to the same straight grid, which flattens the polyrhythm", "Setting the two patterns to the same cycle length so they never actually shift against each other"], "scenario_contexts": ["Programming a three-against-two hand-drum pattern in a drum machine", "Layering step sequencers of different lengths in a modular or DAW project", "Building an African- or Latin-influenced groove from interlocking rhythmic parts"]}, "fdcc9823-7737-44b6-bc6b-c086e3ee1fd0": {"definition": "In Steinberg Cubase and Nuendo, the Pool is a project window that lists and manages every media file used in or imported to the project, including audio, video, and MIDI. It shows each clip's status, format, disk location, and whether it is currently used, and is the central place for organizing and housekeeping project media.", "plain_english": "A window in Cubase and Nuendo that lists every sound and clip your project uses. It works like a filing cabinet where you can find, rename, convert, or remove media.", "purpose_function": "It centralizes media management so an editor can see which files are used, relink missing files, convert formats, or delete unused audio to keep a project tidy and portable.", "practical_application": "An engineer opens the Pool to find and remove unused recordings before backing up a project, or to relink media that the DAW reports as missing after files were moved.", "category": "Media Management", "related_terms": ["Audio clip", "Project file", "Media file", "Import audio", "Back up project", "Region"], "common_mistakes": ["Confusing 'Remove from Pool' (leaves the file on disk) with 'Delete' or emptying the Pool trash (erases the file permanently)", "Deleting clips that appear unused without checking edit versions, then losing takes still referenced elsewhere", "Ignoring missing-file warnings in the Pool instead of relinking, so audio drops out on playback"], "scenario_contexts": ["Cleaning out unused audio before archiving a Cubase project", "Relinking media after moving a Nuendo project to another drive", "Reviewing which recordings are actually used in a large session"]}, "b54b2eaa-1cd7-404d-8a07-fd337982a942": {"definition": "A send configuration in which the auxiliary send signal is tapped after the channel fader, so the send level follows the fader. Lowering or muting the channel fader also lowers or removes the signal fed to the effect or aux bus.", "plain_english": "A send setting that takes its signal after the channel's volume fader. When you turn the channel down, the amount going to the effect goes down too, so the effect stays in balance.", "purpose_function": "It keeps time-based effects like reverb and delay proportional to the dry channel level, so the wet-to-dry balance stays consistent as the engineer rides the fader.", "practical_application": "An engineer sets reverb and delay sends to post-fader so that pulling down or muting a vocal also pulls down its reverb and delay tails, keeping the effect glued to the source.", "category": "Signal Routing", "related_terms": ["Aux send", "Pre-fader send mode", "Effects return", "Aux bus", "Channel fader", "Reverb"], "common_mistakes": ["Using post-fader sends for stage monitor mixes, so a performer's monitor level changes every time the front-of-house engineer moves the channel fader", "Assuming all sends default to post-fader without checking the console or DAW routing", "Muting a channel and being surprised the effect return still needs muting when the send was actually pre-fader"], "scenario_contexts": ["Feeding a shared reverb bus for vocals and instruments in a mix", "Setting up delay throws that follow a lead vocal's level", "Routing effects sends on a live console so effects track the main mix"]}, "02f3af10-a3c3-4f4c-a0d6-5b4f256fb16d": {"definition": "A send configuration in which the auxiliary send signal is tapped before the channel fader, so the send level is independent of the fader position. Moving or muting the channel fader does not change the amount of signal fed to the aux bus.", "plain_english": "A send setting that takes its signal before the channel's volume fader. The amount going out stays the same no matter where you set the channel volume.", "purpose_function": "It provides a feed that is independent of the main mix, which is essential for monitor and foldback mixes and for headphone cues, where levels must not follow the front-of-house fader.", "practical_application": "A monitor engineer uses pre-fader sends to build each performer's stage mix, so those levels stay put even when the front-of-house engineer adjusts the channel faders.", "category": "Signal Routing", "related_terms": ["Aux send", "Post-fader send mode", "Monitor mix", "Foldback", "Aux bus", "Cue mix"], "common_mistakes": ["Building monitor mixes on post-fader sends by mistake, causing sudden stage-level changes when front-of-house faders move", "Forgetting a pre-fader send still passes signal when the channel fader is fully down, causing unexpected bleed in monitors", "Leaving a pre-fader send up on a muted channel, so the sound continues in the aux mix"], "scenario_contexts": ["Creating independent stage monitor mixes at a live show", "Setting up headphone cue mixes for musicians in a studio", "Feeding a pre-fader signal to a parallel processing or recording bus"]}, "022ad6b5-1e23-49ee-9a70-851cc3e4840f": {"definition": "In audio post-production, a premix (or pre-dub) is a session in which related tracks, such as all dialogue, all music, or all sound effects, are combined, balanced, and processed into a smaller set of stems ahead of the final mix. It reduces a very large number of tracks to a manageable few before the final re-recording stage.", "plain_english": "A stage in film and TV sound where you blend groups of tracks, like all the dialogue or all the effects, into a few tidy submixes. It clears the clutter so the final mix is easier to handle.", "purpose_function": "It condenses hundreds of individual tracks into manageable dialogue, music, and effects stems, so the final mix can focus on overall balance rather than every raw track.", "practical_application": "A re-recording team premixes dialogue, music, and effects separately, then loads those stems for the final mix and for building international music-and-effects deliverables.", "category": "Post-Production Mixing", "related_terms": ["Stem", "Final mix", "Re-recording mixer", "Printmaster", "Music-and-effects mix", "Dialogue stem"], "common_mistakes": ["Baking in heavy or committed processing during the premix that cannot be undone at the final mix", "Confusing a premix with the final mix, and treating stems as finished deliverables", "Letting premixed stem levels drift so the elements no longer balance cleanly at the final stage"], "scenario_contexts": ["Premixing dialogue, music, and effects before a film's final dub", "Consolidating a large TV episode's tracks into stems for the mix stage", "Preparing effects and Foley stems that will feed an M&E deliverable"]}, "adc0eb9e-5a5d-4668-95d6-c7d4d4d46e7b": {"definition": "The highest-quality, unaltered archival copy of a recording, created and stored specifically for long-term preservation. It captures the full resolution of the source with no added processing or corrective editing, and serves as the authoritative original from which access and distribution copies are later derived.", "plain_english": "The top-quality archive copy of a recording, kept safe for the long term. It has no extra processing added, so clean copies can always be made from the original later.", "purpose_function": "It safeguards the definitive version of a recording against loss and format decay, acting as the trusted source that all working and listening copies are made from.", "practical_application": "An archivist captures a tape transfer at high resolution, saves it unprocessed with full metadata as the preservation master, and then makes separate access copies for listening and editing.", "category": "Archiving & Preservation", "related_terms": ["Access copy", "Production master", "Flat transfer", "Sample rate", "Bit depth", "Metadata"], "common_mistakes": ["Applying noise reduction, EQ, or level changes to the preservation master instead of keeping it flat and unprocessed", "Storing only one copy in one place, with no verified backup against drive failure", "Capturing at too low a resolution so the master cannot represent the full source signal"], "scenario_contexts": ["Digitizing analog tape for a sound archive", "Preparing an archival master before a label reissue", "Maintaining institutional collections of at-risk audio recordings"]}, "5b03e8e6-f669-4d6b-8dee-c81c2e813d37": {"definition": "In Avid Pro Tools, Preview is an automation state that lets an engineer audition proposed automation values in real time without writing them to the track. The change is heard against the existing automation but is committed only when the engineer chooses to punch it in or capture it.", "plain_english": "A Pro Tools setting that lets you try out fader or plug-in moves and hear them without saving them yet. You listen first, then decide whether to keep the change.", "purpose_function": "It lets a mixer experiment with a new level or setting in context and commit it only once it sounds right, avoiding accidental overwrites of existing automation.", "practical_application": "A mixer enables Preview, sets a new chorus vocal level, listens in the mix, then punches it in to write that value while leaving the rest of the automation pass untouched.", "category": "Mixing Automation", "related_terms": ["Write mode", "Touch mode", "Latch mode", "Trim automation", "Punch (automation)", "Automation playlist"], "common_mistakes": ["Forgetting to punch or capture a previewed value, so the audition is lost when playback stops", "Confusing Preview with Write mode and overwriting existing automation instead of auditioning it", "Leaving parameters in Preview and wondering why moves are not being recorded"], "scenario_contexts": ["Auditioning a new vocal ride before committing it", "Trying a different reverb send level against a finished mix", "Refining one parameter without disturbing the surrounding automation"]}, "00e3fcb2-15ec-407a-8c34-92b83a997351": {"definition": "In film and television post-production, the printmaster is the final, approved master of the completed soundtrack, combining all premixed stems at final level and format. It is the definitive source from which release prints, distribution masters, and delivery versions are made.", "plain_english": "The finished master of a film's soundtrack, made from the final mix. It is the copy that release versions and streaming files are then made from.", "purpose_function": "It provides one approved, correctly leveled and formatted version of the soundtrack, so every release copy is generated from the same authoritative master.", "practical_application": "After the final mix is approved, the team creates the printmaster in the required channel layout and format, then derives theatrical, broadcast, and streaming deliverables from it.", "category": "Post-Production Mixing", "related_terms": ["Final mix", "Premix session", "Stem", "Music-and-effects mix", "Re-recording mixer", "Master"], "common_mistakes": ["Confusing the printmaster with the premix or with the working final mix session", "Delivering the printmaster in the wrong channel layout or loudness spec for the target platform", "Making late fixes to a release copy instead of updating the printmaster and re-deriving deliverables from it"], "scenario_contexts": ["Creating the theatrical soundtrack master after a film's final dub", "Producing a broadcast master that meets a network's loudness spec", "Deriving streaming and home-video deliverables from one approved master"]}, "aad2d145-2a1a-4316-baa8-1551994a813e": {"definition": "A digital audio workstation or dubbing-console session used to build the print master — the final, fully balanced and leveled composite mix of a film or program from which all release deliverables are made. It combines the finished dialogue, music, and effects stems into the completed soundtrack, ready for encoding and distribution.", "plain_english": "This is the session where the whole soundtrack gets finished. All the talking, music, and sound effects are mixed into one final blend. That final blend is then used to make the copies people watch.", "purpose_function": "It exists to assemble the separately mixed stems into a single, delivery-ready master with correct levels and format, so one approved mix can be encoded for cinema, broadcast, or streaming.", "practical_application": "A re-recording mixer opens the printmaster session at the end of post-production to lay back the final mix, check it against the delivery specs, and render the deliverables the client will distribute.", "category": "Post-Production", "related_terms": ["Stems", "Final mix", "Re-recording mix", "Deliverables", "Program loudness", "Mastering"], "common_mistakes": ["Confusing the print master with the individual stems — the print master is the combined final mix, not the separate dialogue, music, and effects tracks.", "Skipping a check of the print master against the project's delivery loudness and true-peak specs before rendering.", "Assuming creative changes can still be made freely at the print master stage; edits belong upstream in the stems, not in the printmaster session."], "scenario_contexts": ["Finishing a feature film's soundtrack by combining approved dialogue, music, and effects stems into the final print master.", "Creating multiple delivery versions (theatrical, streaming, broadcast) from one approved print master.", "Verifying that the final mix meets a broadcaster's loudness and true-peak delivery requirements before sign-off."]}, "df3efe72-4d9b-4fc7-95da-87d218afabf3": {"definition": "In Avid Pro Tools, a Project is a cloud-backed document format that stores the edit, mix, and automation data online while keeping a synchronized local working copy, enabling media and version sharing across collaborators. It differs from a locally stored session by hosting project data and media through Avid's cloud service.", "plain_english": "A Pro Tools project is a way to save your work in the cloud, not just on your computer. It keeps a copy on your machine and syncs it online. Then people you work with can open and share the same files.", "purpose_function": "It exists to support online collaboration and backup, letting multiple users work on and sync the same material through Avid's cloud rather than handing files off manually.", "practical_application": "A technician chooses the Project format when several people need cloud access to the same work, then relies on syncing to keep everyone's local copy current.", "category": "Session Files", "related_terms": ["Pro Tools session", "Cloud collaboration", "Automation", "Bounce", "Session template", "Backup"], "common_mistakes": ["Confusing a Project (cloud-backed) with a Session (local .ptx file) and assuming they store media the same way.", "Forgetting to sync before closing, so recent changes are never uploaded for collaborators.", "Treating the cloud copy as the only backup instead of also keeping a local archive."], "scenario_contexts": ["Sharing an in-progress mix with a remote collaborator through Avid's cloud.", "Working on the same material from two different studios and syncing between them.", "Keeping an online backup of ongoing work in addition to local storage."]}, "25a63e55-a289-4e7e-a575-19ad478a454a": {"definition": "In Avid Pro Tools, a Session is the primary document file (with a .ptx extension) that stores all editing, mixing, routing, and automation data along with references — not the audio itself — to the media files it uses. Audio and other media are stored locally in a folder alongside the session file rather than in the cloud.", "plain_english": "A Pro Tools session is the main file that holds your whole project. It does not hold the audio itself. Instead it points to the sound files saved next to it. It also remembers all your edits, levels, and settings.", "purpose_function": "It exists to hold the complete state of your work in one document so the project can be saved, reopened, and shared exactly as you left it, while the large audio files stay stored separately.", "practical_application": "A technician opens a session file to resume work and must keep its linked Audio Files folder together with it so the media relinks correctly.", "category": "Session Files", "related_terms": ["Pro Tools project", "Audio Files folder", "Relink", "Bounce", "Automation", "Session template"], "common_mistakes": ["Thinking the session file contains the audio — it only references media in its Audio Files folder, so moving the session alone breaks the links.", "Emailing or copying only the .ptx file and leaving its linked audio behind.", "Not saving incrementally, risking lost edits if the program crashes.", "Confusing a session (local media) with a project (cloud-backed)."], "scenario_contexts": ["Opening a saved .ptx session to continue mixing a track.", "Transferring a session to another studio by copying the session file together with its Audio Files folder.", "Relinking media when a session opens with missing-file warnings."]}, "353f33a1-8c16-49ae-a9d5-25caa92604df": {"definition": "A sequencing technique in which each step or note in a pattern is assigned a probability — a percentage chance of triggering on any given pass — so the sequence varies from repeat to repeat rather than playing identically every cycle. It introduces controlled randomness and evolving variation into otherwise fixed patterns.", "plain_english": "This is a way to make a repeating pattern less predictable. Each note gets a chance, like 70 percent, of playing each time around. So the pattern shifts a little on every loop.", "purpose_function": "It exists to add life and variation to sequenced parts, letting a programmer humanize or generate evolving rhythms and melodies without editing every repeat by hand.", "practical_application": "A producer sets per-step probability on a drum or synth sequencer so hits like hi-hats or fills drop in and out naturally across a loop.", "category": "Sequencing", "related_terms": ["Step sequencer", "MIDI", "Quantization", "Groove", "Randomization", "Velocity"], "common_mistakes": ["Setting probabilities so low that important structural notes, like the downbeat, sometimes disappear.", "Assuming a recorded pass will keep changing — once printed to audio, the chosen variation is fixed.", "Confusing note probability with randomization of velocity or other parameters."], "scenario_contexts": ["Programming a hi-hat pattern where some steps only occasionally trigger for a natural feel.", "Creating generative, evolving synth lines in a live performance set.", "Adding subtle fills to a looped drum pattern without editing each bar."]}, "e6d2574e-645a-45c1-a3df-2e32510fa597": {"definition": "A production audit is a systematic review of a production project, covering its session files, track organization, edits, levels, plug-in use, and deliverables, to verify technical integrity, consistency, and compliance with the project's specification before it advances to the next stage or is delivered.", "plain_english": "A production audit is a careful check of a whole project before it moves on. You go through the files, edits, and levels to make sure nothing is broken or missing, like a checklist before you hand in your work.", "purpose_function": "It exists to catch errors, missing files, and spec problems early, giving a documented, repeatable checkpoint that keeps quality high and reduces costly fixes later in the workflow.", "practical_application": "An engineer works through a checklist, confirming file naming, sample rate, absence of clipping, correct routing, and complete deliverables, and logs any issues to fix before sign-off.", "category": "Quality Control", "related_terms": ["Production quality assurance", "Peak validation", "Output validation", "Deliverables", "Session management", "Stem"], "common_mistakes": ["Treating the audit as a formality and skimming instead of following a defined checklist", "Auditing only the audio and ignoring file organization, naming, and metadata", "Running the audit too late, after the point where problems are cheap to fix"], "scenario_contexts": ["Reviewing a mix session before delivering stems to mastering", "Checking a post-production project against a broadcast delivery spec", "Verifying an archived project is complete and can be reopened later"]}, "04105933-0f8c-4e60-8aae-c968653af587": {"definition": "A production completion report is a document that summarizes a finished production, listing the delivered files and formats, the technical specifications met (such as sample rate, bit depth, loudness, and true peak), version history, and any notes or approvals, providing a record that the work is complete and to specification.", "plain_english": "A production completion report is a short write-up that says a project is done. It lists what was delivered, the file details, and who signed off, so everyone has a clear record.", "purpose_function": "It exists to close out a project with a clear, shareable record of what was delivered and to what standard, supporting hand-off, billing, archiving, and future reference.", "practical_application": "At delivery, an engineer or coordinator fills out the report with file names, formats, loudness and true-peak figures, and client approval, then stores it with the project archive.", "category": "Documentation", "related_terms": ["Production audit", "Production quality assurance", "Deliverables", "Session management", "Integrated loudness", "Master"], "common_mistakes": ["Leaving out the exact technical specs of the deliverables, making the report hard to verify later", "Writing the report from memory instead of from the actual delivered files", "Failing to store the report with the project archive, so it is lost when needed"], "scenario_contexts": ["Documenting final masters delivered to a label with their formats and loudness values", "Recording sign-off and specs at the end of a post-production job", "Providing a hand-off summary when a project passes between teams"]}, "5bd114ca-c9fc-47fe-90b1-8fefa1a6dc05": {"definition": "Production quality assurance (QA) is the set of processes and checks applied throughout a production to ensure the final audio meets defined technical and creative standards, covering aspects such as levels, noise, edits, phase/polarity, format compliance, and translation across playback systems.", "plain_english": "Production quality assurance means checking the work at every step, so the final sound meets the required standard. It is like quality control in a factory, but for audio. The goal is to catch problems before you release the work.", "purpose_function": "It exists to build quality into the workflow rather than relying on a single final check, reducing errors, rework, and rejected deliverables.", "practical_application": "A technician applies QA steps such as reference listening on several systems, metering for loudness and true peak, and checking for clicks, noise, and phase issues before signing off each stage.", "category": "Quality Control", "related_terms": ["Production audit", "Peak validation", "Output validation", "Playback translation", "Loudness normalization", "Deliverables"], "common_mistakes": ["Confusing quality assurance, which builds in checks throughout, with a single quality-control pass at the very end", "Checking on one set of speakers only and missing problems that appear on other systems", "Relying on meters alone without critical listening, or on listening alone without meters"], "scenario_contexts": ["Setting up a checklist and metering standard for a studio's deliverables", "Cross-checking a mix on multiple playback systems before release", "Verifying broadcast deliverables meet a loudness standard as part of routine QA"]}, "26af1cf7-133c-4b3f-b0d0-a9f19ae5af94": {"definition": "The integrated (average) loudness of an entire program measured over its full duration, expressed in LUFS (Loudness Units referenced to Full Scale) using the gated algorithm of ITU-R BS.1770. Broadcast and streaming standards such as EBU R128 set target program-loudness levels (for example −23 LUFS) so different programs play back at a consistent perceived loudness.", "plain_english": "This is how loud a whole show sounds on average, from start to end. A special meter measures it and gives a number in units called LUFS. Broadcasters aim for a set target so shows and ads all feel about equally loud.", "purpose_function": "It exists to give a single, standardized loudness value for a complete program, so content can be normalized to a common target and listeners are not jarred by loudness jumps between programs or channels.", "practical_application": "An engineer measures integrated program loudness with a compliant meter and adjusts the mix so the final value meets the delivery target, such as −23 LUFS for EBU R128 or −24 LKFS for ATSC A/85.", "category": "Loudness & Metering", "related_terms": ["LUFS", "True peak", "Loudness range", "Loudness normalization", "EBU R128", "Dynamic range"], "common_mistakes": ["Confusing program loudness (integrated over the whole program) with short-term or momentary loudness readings.", "Chasing peak levels instead of the loudness target, then failing the delivery spec.", "Assuming a limiter alone sets loudness — integrated loudness depends on the program's level across its whole length."], "scenario_contexts": ["Delivering a TV program mixed to −23 LUFS to meet EBU R128.", "Checking a podcast or streaming master against a platform's loudness target.", "Reconciling a commercial's loudness with the surrounding program to avoid loudness jumps."]}, "e3f83084-40f8-4447-ad58-72deb3a93347": {"definition": "An alternative saved version of a project kept alongside the main version, used to explore a different mix, arrangement, or edit decision without altering or overwriting the original. Alternatives let a team preserve and compare options and return to any retained version.", "plain_english": "This is a spare copy of a project saved so you can try a new idea. You can change the mix in it without wrecking the first one. Later you can compare both and keep the one you like.", "purpose_function": "It exists to preserve creative and technical options, so an engineer can test changes safely and recall or compare earlier versions instead of losing work to overwrites.", "practical_application": "Before a big change, a technician saves an alternative — for example with Save As or a new version — so the current mix stays intact as a fallback.", "category": "Workflow", "related_terms": ["Pro Tools session", "Save As", "Playlist", "Version control", "Recall", "Backup"], "common_mistakes": ["Overwriting the only version instead of saving a separate alternative before major changes.", "Losing track of which alternative is the latest or approved version because of poor naming.", "Assuming an alternative updates itself — each version is a separate saved copy."], "scenario_contexts": ["Saving an alternative mix to try a louder master while keeping the original.", "Exploring two arrangement ideas as separate versions for a client to compare.", "Keeping a fallback version before applying risky edits or plug-in changes."]}, "cfd20b31-0afb-40db-8147-25478f631128": {"definition": "A project-level media list, exemplified by Logic Pro's Project Audio browser, that shows every audio file belonging to the current project along with the regions derived from those files, so they can be located, renamed, and managed independently of the timeline arrangement.", "plain_english": "It is a list of every sound file used in your project. You can find, rename, or delete files here without touching the song's timeline. Think of it like a folder that shows all the clips your project depends on.", "purpose_function": "It gives one place to see and manage all the audio a project references, so files can be organized, checked for use, or cleaned up without hunting through every track.", "practical_application": "An engineer opens it to spot unused recordings, rename raw takes, or confirm every clip is present before archiving or backing up a session.", "category": "Media Management", "related_terms": ["Region", "Audio file", "Project Setup", "Bounce", "Session backup"], "common_mistakes": ["Deleting a file here thinking it only clears the view, when it can remove the file from the project or disk.", "Confusing the audio file with the region: trimming a region does not change the underlying file.", "Assuming listed files are copies stored inside the project, when they may be references to originals kept elsewhere."], "scenario_contexts": ["Cleaning up a finished session by removing unused recordings before archiving.", "Renaming a batch of raw takes so a co-editor can find them.", "Checking that every clip is accounted for before moving a session to another studio."]}, "89115e24-cf2f-4ae6-a4a4-d2e78133e948": {"definition": "In Steinberg Cubase and Nuendo, the Project Logical Editor is a tool that automates editing in the Project window: the user defines filter conditions to select matching events, parts, tracks, or markers, then applies defined actions such as move, transform, or delete to everything that matches.", "plain_english": "It is a search-and-change tool for your whole project. You tell it what to look for, like every track of one color, and what to do with them. It then makes that change everywhere at once, so you do not have to do each by hand.", "purpose_function": "It exists to carry out repetitive or rule-based edits across a large project quickly and consistently, instead of selecting and changing each item by hand.", "practical_application": "An editor might use it to select every event on muted tracks and delete them, or to shift all markers by a set amount, in a single step.", "category": "DAW Editing", "related_terms": ["Logical Editor", "MIDI Logical Editor", "Macro", "Project marker", "Event"], "common_mistakes": ["Confusing it with the MIDI Logical Editor; the Project version works on project events and structure, not MIDI note data.", "Running an action without testing the filter first, so it changes more items than intended.", "Forgetting that actions apply to everything matching the filter, not just the visible selection."], "scenario_contexts": ["Deleting all events on tracks whose names contain a keyword.", "Selecting and processing every part of one color across a busy arrangement.", "Building a reusable preset to tidy up imported projects."]}, "61f4c85c-6238-4508-ac8b-53abe29efdac": {"definition": "A project marker is a labeled reference point, or range, placed on a project's timeline to mark a specific position or section, allowing quick navigation to and identification of song parts, edit points, or cues.", "plain_english": "It is a labeled flag on your project's timeline. You drop it at spots like the chorus or a scene change so you can jump straight there. It works like a bookmark in a long document.", "purpose_function": "It lets an engineer name and instantly locate important points in a session, making navigation and talk about song structure faster.", "practical_application": "A mixer sets markers at each song section to jump to the second chorus instantly, or to line up cues with picture in post.", "category": "Navigation", "related_terms": ["Cycle marker", "Marker track", "Locator", "Timeline", "Cue"], "common_mistakes": ["Leaving markers unnamed, so a project fills with generic labels that give no useful information.", "Confusing a single position marker with a range or cycle marker that defines a start and end.", "Assuming markers move audio; they only flag positions and do not edit the material."], "scenario_contexts": ["Labeling verse, chorus, and bridge before a mix session.", "Marking edit or punch points for a vocal comp.", "Placing cues to sync music to video in post-production."]}, "fa386961-9eb7-47da-aa6d-36d560a6c7e3": {"definition": "In Steinberg Cubase and Nuendo, Project Setup is a dialog that defines a project's global properties, including sample rate, bit depth and record file format, project length, display format, and frame rate, which govern how audio is recorded and how time is shown throughout the session.", "plain_english": "It is the settings page for a whole project. Here you pick basics like the sample rate and how time is shown before you start work. Getting these right early keeps everything in the project lined up.", "purpose_function": "It sets the technical foundation of a session so that recording quality and the timeline behave consistently from the very start.", "practical_application": "A technician opens Project Setup first to confirm the sample rate and bit depth match the session's delivery format and any imported material.", "category": "Session Setup", "related_terms": ["Sample rate", "Bit depth", "Frame rate", "Record file format", "Project marker"], "common_mistakes": ["Changing the sample rate after recording, which can make existing audio play back at the wrong pitch and speed.", "Setting a bit depth or record format that does not match the delivery spec.", "Overlooking frame rate when the project must sync to video."], "scenario_contexts": ["Starting a new session and matching its sample rate to the rest of an album.", "Setting the frame rate for a project that will sync to picture.", "Confirming record format before a tracking date."]}, "8c6e5581-6f13-4827-bb7b-291d0d8ef0a5": {"definition": "A project tab is a clickable tab in a DAW's interface that represents one open project, letting the user keep several projects open at once and switch between them by selecting the matching tab.", "plain_english": "It is a tab for each open project, like tabs in a web browser. When you have more than one session open, you click a tab to switch between them. It saves you from closing one project to see another.", "purpose_function": "It provides fast switching between several open projects within one window, which streamlines tasks that span more than one session.", "practical_application": "An engineer keeps a reference project and the working mix open in separate tabs to copy settings or compare arrangements quickly.", "category": "DAW Interface", "related_terms": ["Project", "Workspace", "Template", "Session", "Project Setup"], "common_mistakes": ["Editing in the wrong project because the active tab was not the one intended.", "Assuming all open tabs share settings or playback, when each project is independent.", "Leaving many projects open in tabs, which uses extra memory and CPU."], "scenario_contexts": ["Switching between a rough mix and a reference session while balancing a track.", "Copying plug-in chains from one open project into another.", "Keeping a template and a live session open side by side."]}, "3e2278d7-7e08-4051-b4b2-54acb1748097": {"definition": "A promotional mix is an alternate version of a song's mix prepared for promotion rather than commercial sale, such as a radio edit, clean version, or shortened cut supplied to broadcasters, DJs, or press to publicize a release.", "plain_english": "It is a special version of a song made to help promote a release. It might be shorter, cleaned of swearing, or set up for radio play. It is handed out to get attention, not sold in stores.", "purpose_function": "It exists to give radio, DJs, and media a version tailored for airplay and publicity, which can differ from the main commercial mix.", "practical_application": "A mix engineer delivers a promotional mix alongside the main mix, often a clean, radio-length edit ready for broadcast rotation.", "category": "Mix Deliverables", "related_terms": ["Radio edit", "Clean version", "Alternate mix", "Instrumental mix", "Mixdown"], "common_mistakes": ["Treating the promotional mix as the final master rather than a purpose-made alternate.", "Forgetting to clean explicit lyrics on a version meant for broadcast.", "Delivering a full-length cut when a shorter radio edit was expected."], "scenario_contexts": ["Preparing a clean radio edit for airplay before an album drops.", "Supplying a shortened mix to a promoter for a single launch.", "Sending a tailored version to DJs to build early buzz."]}, "8335bcd5-c5ca-4eb7-9682-e4ab739e969f": {"definition": "Public-address contribution refers to the portion of the total sound at a venue supplied by the public-address (sound-reinforcement) system, as distinct from the direct acoustic sound of the source; it can also describe the amount of PA signal captured in a live recording or broadcast feed.", "plain_english": "Public-address contribution is how much of what people hear comes from the speakers, not straight from the performers. In a small room the PA adds a little; in a big venue it supplies most of the sound.", "purpose_function": "Thinking in terms of PA contribution helps a system designer decide how much reinforcement is needed for even coverage and intelligibility while keeping a natural balance with the acoustic source.", "practical_application": "A live engineer judges how much level the PA should add relative to stage volume and room acoustics, raising reinforcement in large or noisy spaces and easing it where the acoustic source already carries.", "category": "Sound Reinforcement", "related_terms": ["Sound reinforcement", "Coverage", "Gain before feedback", "Stage volume", "Intelligibility", "Direct-to-reverberant ratio"], "common_mistakes": ["Assuming more PA level always improves clarity, when excess contribution can worsen feedback and muddiness", "Ignoring the acoustic contribution of loud stage sources when setting PA level", "Over-reinforcing a small, lively acoustic space as if it were a large venue"], "scenario_contexts": ["Deciding how much reinforcement a room needs for even coverage and speech intelligibility", "Balancing PA level against a loud acoustic drum kit on a small stage", "Assessing how much PA spill is captured in a live broadcast or recording"]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"f1709696-f9c9-447a-9e89-d46ecc092745": {"definition": "\"Pull the band back\" is an informal mixing instruction to lower the level of the backing band or instruments in a mix, usually so a featured element such as a lead vocal or spoken announcement sits clearly in front.", "plain_english": "It means turn the band down in the mix. You do this so the singer or speaker is easy to hear over the music. It is like lowering background music when someone starts to talk.", "purpose_function": "It serves to shift the balance so a lead voice or featured part becomes clearer by reducing the competing level of the instruments.", "practical_application": "During a live broadcast, an engineer pulls the band back on the faders when a presenter speaks, then brings it up again for the performance.", "category": "Mix Balance", "related_terms": ["Fader", "Level balance", "Gain staging", "Ducking", "Foreground"], "common_mistakes": ["Pulling the band back so far that the mix loses energy and feels empty.", "Making the level move abruptly instead of riding the faders smoothly.", "Reaching for EQ or mutes when a simple level move would do the job."], "scenario_contexts": ["Lowering the band under a presenter's announcement in a live show.", "Making room for a lead vocal during a quiet verse.", "Bringing instruments down so a solo instrument can be featured."]}, "965cdba7-80dd-4235-bdb8-2e571f4148a9": {"definition": "Punch automation is a method of writing mixer automation only across a defined section of the timeline: the engineer punches in to start overwriting automation and punches out to stop, leaving automation before and after that region unchanged, much as punch-in recording replaces only a selected part of a take.", "plain_english": "It lets you rewrite automation for just one part of a track. You punch in where the change starts and punch out where it ends. Everything outside that spot keeps its old moves, like re-recording only one line of a take.", "purpose_function": "It exists to let an engineer fix or replace automation in one exact spot without disturbing the moves already set elsewhere on the track.", "practical_application": "A mixer punches in over a single loud word to write a quick volume dip, then punches out so the rest of the vocal automation stays as it was.", "category": "Automation", "related_terms": ["Automation", "Write mode", "Touch mode", "Latch mode", "Punch-in"], "common_mistakes": ["Staying punched in too long and overwriting good automation past the intended spot.", "Confusing it with punch-in recording, which replaces audio rather than automation data.", "Not setting clear in and out points, so the change bleeds into neighboring sections."], "scenario_contexts": ["Writing a fast level dip over one harsh note in a vocal.", "Replacing a bad automation move in a single bar without redoing the whole pass.", "Punching in a pan change for one phrase only."]}, "0d83b565-8808-4701-9a0d-5a2b62595c99": {"definition": "Punch Guard is a MOTU Digital Performer feature that records extra audio before the punch-in point and after the punch-out point during a punch recording, capturing guard (pre- and post-roll) material beyond the punch region so that missed note attacks or tails can be recovered by dragging out the resulting soundbite's edges.", "plain_english": "Punch Guard records a few extra seconds before and after a punch take. If you start recording a touch late or stop too soon, you can drag the clip's edge out to get the missing part back.", "purpose_function": "It exists as a safety net for punch recording, letting an engineer fix slightly early or late punch points and build clean crossfades without asking the performer for another take.", "practical_application": "With Punch Guard on, a technician punches in over a section and, if an attack or tail was clipped, drags out the soundbite edge to reveal the guard audio instead of re-recording.", "category": "Recording Workflow", "related_terms": ["Punch in/out", "Pre-roll", "Soundbite", "Crossfade", "Take", "Punch automation mode"], "common_mistakes": ["Assuming the guard audio is unlimited, when it is bounded by the pre- and post-roll times set in Preferences", "Forgetting Punch Guard is enabled and being surprised by extra recorded material around punches", "Relying on it to rescue grossly mistimed punches instead of setting sensible punch points"], "scenario_contexts": ["Recovering a clipped word at the start of a punched vocal line", "Extending a punched guitar note's tail to build a smooth crossfade", "Fixing a slightly early punch-out on an instrumental overdub"]}, "8250877c-23d7-4096-9cdd-a8a7f4f2e29d": {"definition": "The process of enhancing the perceived punch of a track or mix - its sense of impact and transient energy - by shaping transients with compressor attack and release settings, transient designers, and EQ in the low and low-mid frequencies.", "plain_english": "Punch is the feeling of a sound hitting hard, like the thump of a kick drum. This is the work of tuning a sound so those hits feel stronger and more solid.", "purpose_function": "It gives drums, bass, and full mixes a stronger sense of impact and energy so they feel powerful and drive the song forward.", "practical_application": "An engineer optimizes punch by setting a slower compressor attack so transients pass through, using a transient shaper on the kick or snare, or lifting the low-mids that carry weight.", "category": "Mixing Technique", "related_terms": ["Transient", "Attack time", "Transient shaper", "Compression", "Bus compression"], "common_mistakes": ["Using a very fast compressor attack that clamps down on transients and actually removes punch", "Over-compressing the whole mix so nothing retains its impact", "Boosting low-end level instead of shaping the transient, which adds mud rather than punch"], "scenario_contexts": ["Setting compressor attack and release on a kick drum so it hits harder", "Using a transient designer to add snap and impact to a snare", "Tuning bus compression so a full mix feels punchy without being squashed flat"]}, "551aea62-5166-45a8-b485-739803dca8e4": {"definition": "PureDSP pitch correction is pitch editing performed with MOTU's PureDSP engine in Digital Performer, which analyzes a monophonic soundbite and can alter its pitch, formant, and tempo independently, allowing tuning correction of individual notes while preserving natural timbre.", "plain_english": "PureDSP pitch correction is a tool in Digital Performer that fixes the tuning of one melody line. It can move notes in tune and still keep the sound natural.", "purpose_function": "It exists to correct or reshape the pitch of monophonic material without the artifacts of simple pitch shifting, by handling pitch, formant, and time separately so the result still sounds realistic.", "practical_application": "An engineer selects a monophonic vocal or instrument soundbite and uses Digital Performer's pitch-editing tools, driven by PureDSP, to nudge off-key notes to the correct pitch while keeping formants natural.", "category": "Pitch & Time Editing", "related_terms": ["Pitch correction", "Formant", "Monophonic", "Time stretching", "Soundbite", "Quantize audio"], "common_mistakes": ["Trying to use it on polyphonic (chordal) material, when PureDSP pitch editing targets monophonic soundbites", "Over-correcting every note to perfect pitch and losing natural expression", "Thinking of it as a real-time tuning plug-in rather than an edit applied to the soundbite"], "scenario_contexts": ["Tuning a lead vocal take note by note in Digital Performer", "Correcting a few sour notes in a monophonic sax or synth line", "Adjusting the pitch and formant of a sampled phrase to fit a new key"]}, "72358ec0-323d-45e4-8a9b-098d4b3b8ab1": {"definition": "A mixing instruction to increase the prominence of the lead vocal in a mix - making it louder or more forward relative to the backing tracks - typically by raising its fader level, riding gain, writing level automation, or increasing compression.", "plain_english": "This means make the singer's voice stand out more in the song. You turn the voice up or bring it forward so it sits on top of the music.", "purpose_function": "It keeps the lead vocal as the clear focal point of a song, so the lyrics and melody stay easy to follow above the instruments.", "practical_application": "During a mix, an engineer pushes the vocal by riding the fader up in a chorus or automating a few extra decibels on quiet lines so the voice cuts through a dense arrangement.", "category": "Mixing Technique", "related_terms": ["Fader ride", "Gain automation", "Vocal compression", "Lead vocal", "Mix balance"], "common_mistakes": ["Pushing the vocal so loud it no longer blends with the track", "Raising the whole vocal fader instead of automating only the quiet phrases that need it", "Treating 'push' as adding brightness or effects rather than raising level"], "scenario_contexts": ["Bringing the lead vocal up a couple of dB in the chorus of a pop song", "Automating extra level on quiet verse lines so every word is intelligible", "A producer asking the mix engineer to push the vocal after noting that the lead vocal sounds buried"]}, "1f60400d-8854-4284-a897-47156b93165e": {"definition": "Q-Range is an advanced quantization parameter in Logic Pro, set in ticks, that restricts quantization according to how far each note lies from the nearest grid position. A value of 0 quantizes every note; positive values quantize only notes already within the range of the grid, while negative values quantize only notes falling outside the range, moving badly-timed notes to the grid while leaving those close to it untouched to preserve the original feel.", "plain_english": "Q-Range decides which notes get fixed. It goes by how far off the beat each note is. Set to a negative value, it pulls only the badly timed notes onto the grid. Notes that are already close are left alone. So the groove still feels natural.", "purpose_function": "It exists to quantize selectively, correcting only notes that are noticeably off while protecting intentional timing, so a part with a good groove can be tightened without being flattened.", "practical_application": "On a part that grooves but has a few rushed or dragged notes, an engineer sets a negative Q-Range so only the worst-timed notes snap to the grid and the rest keep their feel.", "category": "Quantization", "related_terms": ["Quantize", "Q-Strength", "Grid", "Groove", "Swing", "Tick"], "common_mistakes": ["Confusing Q-Range (which notes are affected, by distance) with Q-Strength (how far notes move)", "Expecting a positive value to protect off-grid notes, when it targets notes already near the grid", "Leaving Q-Range at 0 and quantizing everything when only a few notes needed fixing"], "scenario_contexts": ["Fixing a few rushed notes in an otherwise well-timed drum take", "Tightening only the loose notes in a live bass performance", "Preserving a swung MIDI groove while correcting obvious mistakes"]}, "c99ecb6b-e64e-47c2-8d15-38d1a6c23f6b": {"definition": "Q-Strength is an advanced quantization parameter in Logic Pro, expressed as a percentage, that sets how far each note or transient marker is moved toward its nearest grid position: 100% snaps notes fully to the grid, 0% leaves them at their recorded timing, and intermediate values move them proportionally, tightening timing while retaining some of the original feel.", "plain_english": "Q-Strength sets how hard notes are pulled toward the beat grid. At 100% they land exactly on the grid; at lower settings they move only part of the way, so the take still feels human.", "purpose_function": "It exists to let an engineer tighten timing without making a part sound rigid, by controlling the amount of correction instead of forcing every note fully onto the grid.", "practical_application": "After choosing a quantize value, a producer lowers Q-Strength, for example to around 80 to 90 percent, so notes move closer to the grid but keep a natural feel rather than sounding mechanical.", "category": "Quantization", "related_terms": ["Quantize", "Q-Range", "Quantize strength", "Grid", "Swing", "Groove"], "common_mistakes": ["Leaving Q-Strength at 100% by habit, which can make parts sound stiff", "Setting a very low strength and then expecting tight timing", "Confusing Q-Strength (the amount of pull) with the quantize value (the grid resolution)"], "scenario_contexts": ["Tightening a live drum performance while keeping its groove", "Partially correcting a bass line that is slightly loose", "Applying gentle timing correction to keep a natural feel on recorded MIDI"]}, "9d77403e-c29b-4883-9fd8-ce9a786b6203": {"definition": "The process of aligning recorded audio to a rhythmic grid (bars, beats, or subdivisions) by detecting transients, slicing the audio into events, and moving those events onto the nearest grid positions, commonly using elastic or flex time processing to preserve continuity between slices.", "plain_english": "This snaps recorded sounds so they land exactly on the beat. The software finds each hit, cuts the audio there, and nudges each piece onto the grid so the timing is tight.", "purpose_function": "It tightens loose or uneven timing in a performance so a part locks to the tempo, without having to re-record it.", "practical_application": "An engineer quantizes a drum recording by detecting each hit and snapping it to the grid, or uses flex/elastic audio to pull a sloppy bass take back into time.", "category": "Timing & Editing", "related_terms": ["Quantize strength", "Quantize swing", "Grid", "Transient detection", "Elastic Audio"], "common_mistakes": ["Quantizing at full strength so the performance sounds robotic and loses its feel", "Poor transient detection creating audible glitches or double-triggered slices", "Quantizing to the wrong grid value so notes snap to the wrong subdivision"], "scenario_contexts": ["Tightening a live drum take to the grid before mixing", "Snapping a slightly rushed guitar strum back into time", "Aligning a multi-track drum kit while keeping the mics phase-coherent"]}, "d603f6a2-2b72-4345-84fa-384d03ec828e": {"definition": "A quantize parameter, usually expressed as a percentage, that controls how far each note or audio event is moved toward its nearest grid position; 100% snaps events exactly to the grid, while lower values move them only part of the way, preserving some of the original timing.", "plain_english": "This sets how strongly the timing gets corrected. At full strength notes land right on the beat; at a lower setting they move only partway, so the take keeps some of its natural feel.", "purpose_function": "It lets an engineer tighten timing without fully erasing the human feel of a performance, by choosing how much of the original groove to keep.", "practical_application": "Instead of 100%, an engineer might set quantize strength to about 60-80% on drums so the timing tightens but still breathes.", "category": "Timing & Editing", "related_terms": ["Quantize audio", "Quantize swing", "Grid", "Groove", "Humanize"], "common_mistakes": ["Always using 100% strength, making parts feel stiff and lifeless", "Assuming strength changes pitch or dynamics rather than only timing", "Setting it so low that clearly off notes still sound out of time"], "scenario_contexts": ["Setting around 70% strength to tighten a drum take while keeping its groove", "Applying gentle strength to a bass line so it locks with the kick but stays natural", "Dialing strength back when full quantize makes a part feel mechanical"]}, "d7c27ca7-897d-49e3-9ffa-2f8bfb7b24c4": {"definition": "A quantize parameter that shifts every other grid subdivision (typically the off-beat eighth or sixteenth notes) later in time by a set percentage, giving a swung or shuffled rhythmic feel instead of strictly even timing.", "plain_english": "Swing pushes every other note slightly late to create a bouncy, groovy feel. It is the difference between a stiff straight beat and one that shuffles.", "purpose_function": "It adds groove and human-like bounce to programmed or quantized parts that would otherwise sound rigidly even.", "practical_application": "An engineer applies, say, 55-62% swing to a hi-hat or drum pattern so it grooves like a shuffle instead of sitting dead straight.", "category": "Timing & Editing", "related_terms": ["Quantize audio", "Quantize strength", "Groove", "Shuffle", "Grid"], "common_mistakes": ["Applying heavy swing to parts meant to be straight, making them sound out of time", "Using different swing amounts on layered parts so they fight each other", "Confusing swing with quantize strength or with the grid value"], "scenario_contexts": ["Adding swing to a straight programmed hi-hat to give it a shuffle feel", "Matching a sampled loop's swing so a new part grooves with it", "Applying subtle swing to quantized drums so they feel less robotic"]}, "c773d0a5-b81f-4cba-9d4b-d3d51ba09720": {"definition": "The set of power and signal cables that interconnect the units mounted in an equipment rack, dressed and secured so each device's inputs, outputs, and power feeds are correctly routed and easy to service. It spans audio, data/network, and mains wiring managed within a rack and between racks.", "plain_english": "Rack cabling is all the wires that link the gear stacked inside an equipment rack. The cables are tied down neatly. That way each box gets power and passes its sound to the next one.", "purpose_function": "It carries power and audio or data between rack units in an orderly, labeled way so signal flows correctly and any fault can be traced and fixed quickly.", "practical_application": "A technician wiring a rack routes and labels each cable, leaves a small service loop, and keeps mains power separated from audio lines to avoid hum before powering the system up.", "category": "Rack Systems", "related_terms": ["Patchbay", "Signal flow", "Balanced connection", "Ground loop", "Rack instrument"], "common_mistakes": ["Running mains power cables tightly bundled with audio lines, which can induce hum and buzz", "Leaving no service loop, so cables are strained and hard to trace later", "Failing to label both ends of each cable, which makes fault-finding slow", "UNSAFE: Overloading a single rack power circuit or daisy-chaining power strips beyond their rated load"], "scenario_contexts": ["Building a studio outboard rack and wiring processors to a patchbay", "Prepping a touring effects or drive rack for fast setup and teardown", "Tracing a hum fault back to power and audio cables bundled together"]}, "9896dc06-1ae2-416b-a8d6-102189d4f1b4": {"definition": "Within a device Rack (such as an Instrument or Effect Rack in a DAW), a chain is one of the parallel signal paths inside the rack; each chain receives the same input, processes it serially through its own devices, and the chains' outputs are summed to form the rack's output.", "plain_english": "A rack chain is one lane of sounds or effects inside a bigger rack. Each lane gets the same signal and changes it in its own way. Then all the lanes are blended back together.", "purpose_function": "Chains let you build parallel processing or layered sounds inside a single rack, so several effect or instrument paths run at once and are mixed together under one shared set of controls.", "practical_application": "A producer uses chains to blend a distorted and a clean version of a sound, or to split a drum rack so each pad triggers its own chain of devices.", "category": "DAW Devices", "related_terms": ["Rack instrument", "Parallel processing", "Signal routing", "Macro control", "Drum rack"], "common_mistakes": ["Thinking chains process one after another, when each parallel chain actually receives the same input at the same time", "Leaving chain volume levels unbalanced, so the summed rack output clips or sounds lopsided", "Deleting a chain and losing its devices instead of first extracting it to its own track", "Forgetting to set chain key or velocity zones, so all chains sound together unintentionally"], "scenario_contexts": ["Layering two synth chains to create a fuller pad inside one instrument rack", "Building a drum rack where each chain holds one drum sound", "Setting up parallel clean and distorted guitar chains in an effect rack"]}, "a26ea735-294f-469d-bc79-9944da30e4c1": {"definition": "Rack Extension is Reason Studios' native plug-in format for instruments and effects that install directly into Reason's virtual rack. Unlike VST or AU plug-ins, Rack Extensions run only inside the Reason rack environment and are distributed and authorized through Reason Studios' online shop.", "plain_english": "A Rack Extension is an add-on instrument or effect built to slot into the Reason software's rack. It works only inside Reason, a bit like a game add-on that runs only in that one game.", "purpose_function": "The format lets developers add new instruments and effects that behave like Reason's built-in rack gear, including back-panel cabling, while staying protected and stable inside the host.", "practical_application": "A Reason user browses the Rack Extension shop, installs a device, and it appears in the rack ready to patch, play, and automate like any native module.", "category": "Plugin Formats", "related_terms": ["Rack instrument", "VST", "Plugin", "Combinator", "Reason rack"], "common_mistakes": ["Assuming a Rack Extension is a standalone VST that loads into any DAW, when it runs only inside Reason or the Reason Rack plug-in", "Confusing Rack Extensions with Reason's older ReFill sound libraries", "Forgetting that a Rack Extension must be authorized to your account before it will load"], "scenario_contexts": ["Adding a third-party synth to Reason from the Rack Extension shop", "Trying to open a Reason-only device in another host and finding it unavailable", "Managing installed Rack Extensions and authorizations across two studio computers"]}, "84fdfbd3-5999-4ce3-8ec2-540aca20fea0": {"definition": "A sound-generating instrument device housed in a rack rather than built into a keyboard: either a hardware rackmount sound module or tone generator, or a virtual instrument loaded into a software or DAW device rack (such as Reason's rack or a host's instrument rack).", "plain_english": "A rack instrument is a sound-making unit that lives in a rack instead of having its own keys. It can be a real box in a metal rack or a software one in a program's rack. You play it by sending it notes.", "purpose_function": "It provides playable sounds triggered by MIDI or a controller, keeping the tone generator separate from the keys so many instruments can share one keyboard or sequencer.", "practical_application": "A technician patches a MIDI keyboard or sequencer to a rackmount sound module, or a producer loads a virtual instrument into the software rack and drives it from a MIDI track.", "category": "Virtual Instruments", "related_terms": ["Sound module", "MIDI", "Virtual instrument", "Rack Extension", "Rack chain"], "common_mistakes": ["Expecting sound from a rack instrument without sending it MIDI note data or a controller signal", "Confusing a rack instrument, which is a sound source, with an effects unit that only alters incoming audio", "Forgetting to match the MIDI channel, so the instrument ignores the incoming notes"], "scenario_contexts": ["Driving a rackmount synth module from a master keyboard in a studio", "Loading a software instrument into a device rack and sequencing it from a MIDI clip", "Sharing one MIDI controller across several rack instruments on different channels"]}, "1b796314-46b9-45e1-8f32-de5c9223bc5c": {"definition": "In an Ableton Live Rack, a zone is a data filter at the input of each chain that determines whether incoming MIDI notes, velocities, or macro data reach that chain's devices; the three zone types, edited in the Rack's zone editors, are the Key Zone (note range), the Velocity Zone (velocity range), and the Chain Select Zone (position relative to the Chain Selector).", "plain_english": "A Rack zone is a range setting that decides which sounds inside a Rack will play. For example, a Key Zone can make low notes play a bass and high notes play a lead, like splitting a keyboard.", "purpose_function": "Zones exist so one Rack can hold many chains and route notes, velocities, or macro positions to the right ones, enabling keyboard splits, velocity layers, and switchable preset banks.", "practical_application": "A producer drags the Key, Velocity, or Chain Select zone edges in the Rack's Chain List to split a keyboard, layer sounds by playing strength, or crossfade between chains with the Chain Selector.", "category": "Instrument Racks", "related_terms": ["Instrument Rack", "Chain", "Chain Selector", "Key zone", "Velocity", "Macro control"], "common_mistakes": ["Confusing the three zone types (Key, Velocity, and Chain Select) and editing the wrong one", "Setting a chain's zone so it does not overlap the current value, leaving that chain silent", "Overlooking zone fade ranges, which attenuate at the edges rather than hard-cutting"], "scenario_contexts": ["Splitting a keyboard so different note ranges trigger different instruments", "Building velocity layers so soft and hard hits play different samples", "Setting up a Chain Select bank to switch or crossfade presets live"]}, "c5590a14-ccd7-470c-bbaa-b36ee9ded345": {"definition": "In step sequencing and synthesis, ratcheting is the rapid retriggering of a single sequencer step into two or more evenly spaced subdivisions, producing a fast roll, stutter, or burst of repeated notes within the time span of that one step.", "plain_english": "Ratcheting is when one beat in a sequencer fires several fast hits instead of just one. It turns a single note into a quick burst, like a short drum roll.", "purpose_function": "It adds rhythmic detail and energy to a pattern without extra programming, letting one step become a burst of subdivisions for rolls, fills, and accents.", "practical_application": "A producer enables ratchet on a sequencer step to turn a single hi-hat or bass note into a two-, three-, or four-hit burst that drives the groove.", "category": "Sequencing", "related_terms": ["Step sequencer", "Note repeat", "Gate", "Trigger", "Arpeggiator"], "common_mistakes": ["Confusing ratcheting with simply raising the tempo, when it only subdivides that one step", "Overusing ratchets so the pattern sounds busy and cluttered", "Expecting every device to call it 'ratchet', when some label the feature retrigger, note repeat, or roll"], "scenario_contexts": ["Programming rapid hi-hat rolls on a hardware step sequencer", "Adding a burst of repeated bass notes on one step of a modular sequence", "Recreating a drum fill without drawing in each individual note"]}, "82e55d71-b041-4c42-b49a-2153dcd3a73c": {"definition": "In REAPER, a razor edit area is a user-drawn selection spanning one or more tracks, and optionally individual automation envelope lanes, that marks a region of content for non-destructive editing such as moving, copying, trimming, or deleting.", "plain_english": "A razor edit area is a box you draw over part of your tracks in REAPER. It marks the exact chunk you want to change. Then you can move, copy, or delete that chunk without harming the rest.", "purpose_function": "It gives precise, non-destructive control over any region of a project, so you can grab and edit sections across several tracks at once or just one envelope lane.", "practical_application": "An editor drags a razor edit area across the chorus of several tracks to copy it, or over one section of a volume envelope to raise just that part.", "category": "Editing", "related_terms": ["Non-destructive editing", "Automation envelope", "Time selection", "Crossfade", "Split"], "common_mistakes": ["Confusing a razor edit area with an ordinary time selection, which behaves differently", "Editing across tracks by accident because the area spans more lanes than intended", "Forgetting that a razor area can include envelope lanes, so automation moves along with the audio"], "scenario_contexts": ["Copying a multi-track section of a song to a new position in REAPER", "Deleting a bad take across several tracks at once", "Adjusting just one region of a volume envelope with a razor area"]}, "fc340549-ec65-4ec0-9b2b-adc72df7182c": {"definition": "In film and television post-production, the re-recording mix is the final stage in which the edited dialogue, music, and sound-effects stems are combined, balanced, processed, and panned into the finished soundtrack, typically on a dubbing stage by a re-recording mixer.", "plain_english": "A re-recording mix is the final sound mix for a film or TV show. All the speech, music, and sound effects are blended into one polished soundtrack. It is usually done in a special mixing theater.", "purpose_function": "It brings every separately prepared sound element together into a single balanced, format-ready soundtrack that matches the picture and meets delivery standards.", "practical_application": "A re-recording mixer works at a large console on a dubbing stage, balances the dialogue, music, and effects stems to picture, and outputs the final mix in stereo and surround formats.", "category": "Post Production", "related_terms": ["Dialogue editing", "Stem", "Dubbing stage", "Foley", "Surround mix"], "common_mistakes": ["Confusing the re-recording mix with a music recording session; it combines finished stems rather than capturing new performances", "Assuming 're-recording' means recording the audio again, when it means combining existing edited elements", "Delivering without the required stems or loudness spec for broadcast or cinema"], "scenario_contexts": ["Finalizing a feature film's soundtrack on a dubbing stage", "Mixing dialogue, music, and effects stems to picture for a TV episode", "Producing both a cinema surround and a broadcast stereo version from the same stems"]}, "5ea359e7-1266-4e25-ab75-645841837bef": {"definition": "Read is the automation mode in which a DAW or console channel plays back its previously written automation data, moving faders, pans, and plug-in parameters accordingly, but records no new automation moves.", "plain_english": "Read mode makes the mixer play back the automation you already recorded. The faders and knobs move on their own. In this mode your hands cannot change that saved data.", "purpose_function": "It lets recorded automation control the mix on playback so moves repeat consistently every time, while protecting the existing data from accidental changes.", "practical_application": "An engineer leaves channels in Read so the mix plays back exactly as automated, then switches a single channel to Write, Touch, or Latch only when new moves are needed.", "category": "Automation", "related_terms": ["Write automation mode", "Touch automation mode", "Latch automation mode", "Automation envelope", "Fader"], "common_mistakes": ["Trying to adjust a fader in Read and wondering why it snaps back to the automated value", "Confusing Read with Off; Off ignores automation entirely, while Read plays it back", "Leaving a channel in Write instead of Read and erasing good automation on the next pass"], "scenario_contexts": ["Playing back a finished automated mix for a final review", "Switching one channel out of Read to Touch to fix a single fader move", "Auditioning automated plug-in changes without risk of overwriting them"]}, "144e438b-ee6f-41e6-8f5c-74c732e6f55c": {"definition": "A REAPER project is the working document of the REAPER DAW, saved as a plain-text .RPP file. It stores the full session state - track layout, media item references, take and envelope data, routing, FX chains, tempo map, and markers and regions - while pointing to the audio files on disk rather than embedding them.", "plain_english": "A REAPER project is the file that saves your whole session in REAPER. It remembers your tracks, edits, effects, and settings, and it links to your audio files instead of holding them inside. Opening it puts your work back just as you left it.", "purpose_function": "It exists to capture every setting and edit of a mix session in one reloadable file, so work can be saved, reopened, and continued exactly where it stopped.", "practical_application": "A technician opens, saves, and version-names .RPP files through a session, and keeps the project next to its audio in one folder so the links stay intact when moving between machines.", "category": "Project Files", "related_terms": ["REAPER project template", "Region manager", "Region marker", "Reason song", "Track", "Automation"], "common_mistakes": ["Assuming the .RPP file contains the audio itself, then losing sound when the project is moved without its media folder", "Saving over one project file for every version instead of using incremental save or Save As", "Not copying media into the project folder, which breaks file links later"], "scenario_contexts": ["Reopening yesterday's mix to continue where you left off", "Handing a session to another engineer by zipping the .RPP with its audio folder", "Recovering a crashed session from REAPER's auto-saved project backup"]}, "5e233753-b5a3-41fc-9c79-0aec6bb3a1ba": {"definition": "A REAPER project template is a saved .RPP stored in REAPER's project-template folder that serves as a preconfigured starting point for new projects. Loading it opens a fresh, untitled project already containing chosen tracks, routing, FX, and settings, and one can be set as the default so every new project begins from it.", "plain_english": "A REAPER project template is a ready-made starting layout you save once and reuse. When you load it, REAPER opens a new empty project that already has your usual tracks, effects, and settings in place. It saves you from building the same setup from scratch every time.", "purpose_function": "It exists to remove repetitive setup by letting a technician begin each new session from a known, consistent configuration instead of an empty project.", "practical_application": "An engineer builds a template with standard buses, monitoring, and FX chains, saves it with Save As Project Template, and either picks it for new work or sets it as the default startup project.", "category": "Project Files", "related_terms": ["REAPER project", "Track", "Bus", "FX chain", "Routing", "Region manager"], "common_mistakes": ["Confusing a template with a normal project and saving mix work back over the template", "Building a template so overloaded with tracks and plugins that new sessions become heavy and cluttered", "Forgetting to set the template as the default, so new projects still open empty"], "scenario_contexts": ["Starting every podcast edit from a template with host and guest tracks preset", "Opening a live-recording template with all stage inputs already labelled and routed", "Standardising a studio's sessions so any engineer starts from the same layout"]}, "f0089946-7edd-43b2-b9fd-047a5e33f4d2": {"definition": "The Reason mixer is the Main Mixer in Reason Studios' Reason, a full-featured mixing console that acts as the remote control for the program's Audio Track and Mix Channel devices. Each channel strip offers input gain and phase, dynamics, a four-band parametric EQ with filters, insert and send effects, and pan, width, and fader controls, with a master section that includes a bus compressor and master inserts.", "plain_english": "The Reason mixer is the big mixing desk inside the Reason program. It gives every track its own strip with volume, tone, and effect controls, just like a real studio console. You use it to balance all the sounds into one finished mix.", "purpose_function": "It exists to give producers a single console-style surface for setting levels, tone, dynamics, and effects across all tracks, shaping many separate sounds into one balanced mix.", "practical_application": "A user balances faders, dials in EQ and compression per channel, sends tracks to shared reverb or delay returns, and rides the master bus compressor to finish a mix inside Reason.", "category": "DAW Mixer", "related_terms": ["Reason Rack", "Reason song", "Channel strip", "Bus compressor", "Send effect", "EQ"], "common_mistakes": ["Thinking the Main Mixer is separate from the rack, when each channel strip mirrors a Mix Channel or Audio Track device", "Over-processing every channel strip instead of setting a clean static balance first", "Loading effects as inserts when a shared send and return would be tidier and lighter"], "scenario_contexts": ["Mixing a multitrack song down to a stereo master in Reason", "Setting up reverb and delay sends shared across several channels", "Using the master bus compressor to glue a full mix together"]}, "26e7e09d-6d2d-46fb-a0a8-f03b617cedcf": {"definition": "A Player device in Reason is a MIDI/note effect placed above an instrument in the rack that generates or transforms note data before it reaches that instrument. Examples include Scales & Chords, Dual Arpeggio, and Note Echo, which respectively map notes to a key, create arpeggios, and add rhythmic note repeats.", "plain_english": "A Player device in Reason is a helper that sits on top of an instrument and changes the notes it plays. It can turn one note into a full chord, make an arpeggio, or echo notes in time. You use it to create parts you might not play by hand.", "purpose_function": "It exists to generate or reshape performance data automatically, letting a musician build chords, arpeggios, and rhythmic note patterns without programming every note by hand.", "practical_application": "A producer stacks a Player like Scales & Chords or Dual Arpeggio above a synth so incoming notes are turned into in-key chords or moving arpeggios as they play or record.", "category": "MIDI Effects", "related_terms": ["Reason Rack", "Reason mixer", "Arpeggiator", "MIDI effect", "Sequencer", "Instrument device"], "common_mistakes": ["Placing the Player device below the instrument instead of above it, so it never processes the notes", "Expecting a Player to change already-recorded audio rather than note data", "Stacking several note generators and losing track of which one is creating the parts"], "scenario_contexts": ["Playing in-key chords from single notes with Scales & Chords", "Generating a moving arpeggio under a pad with Dual Arpeggio", "Adding rhythmic echoes to a lead line with Note Echo"]}, "f21436fd-977b-4e4b-b789-f8d81eed876a": {"definition": "The Reason Rack is the virtual equipment rack at the heart of Reason, where instrument, effect, and Player devices are added and wired together with virtual patch cables. It mirrors a hardware studio rack, letting audio and control signals flow between devices for sound design and routing.", "plain_english": "The Reason Rack is a virtual stack of music gear inside the program. You add synths, effects, and note tools to it and connect them with on-screen cables, just like real studio equipment. It is where you build the sounds for your song.", "purpose_function": "It exists to hold and interconnect all the sound-making and processing devices in a project, giving producers hardware-style patching and flexible signal routing in software.", "practical_application": "A user adds instruments and effects to the rack, flips it around to see the back panel, and reconnects virtual cables to route audio and control voltage in custom ways.", "category": "DAW Environment", "related_terms": ["Reason mixer", "Reason song", "Reason Player device", "Instrument device", "Effect device", "CV routing"], "common_mistakes": ["Forgetting to flip the rack to its back panel to see or change the actual cabling", "Deleting a device and breaking the cable chain that fed later devices", "Confusing the rack's device order with the Main Mixer's channel order"], "scenario_contexts": ["Building a synth-and-effects chain from scratch in the rack", "Rewiring devices on the rack's back panel for creative routing", "Grouping several rack devices as one instrument with a Combinator"]}, "90ac61c3-3d4e-46ee-82e7-4bc8047794b2": {"definition": "A Reason song is the project document of Reason, saved as a .reason file that contains the complete device setup and connections in the rack, all Main Mixer settings, and everything recorded in the sequencer, including tempo, markers, and automation. It can be made self-contained so its samples and REX files are stored inside the file for easy transfer.", "plain_english": "A Reason song is the file that saves your whole project in Reason. It holds all your devices, cables, mixer settings, and recorded parts in one place. You can even pack the samples inside it so the song opens correctly on another computer.", "purpose_function": "It exists to store an entire Reason project in one reopenable file, so a producer can save, share, and continue work with every device, setting, and recording intact.", "practical_application": "A user saves work as a .reason file, turns on self-contain settings before moving it to another machine, and reopens it to find the rack, mixer, and sequence exactly as left.", "category": "Project Files", "related_terms": ["Reason Rack", "Reason mixer", "REAPER project", "Sequencer", "Self-contained song", "Sample"], "common_mistakes": ["Moving a .reason file to another computer without self-containing it, so linked samples go missing", "Assuming recordings are embedded when unsaved audio sits in the Scratch Disk folder until the song is saved", "Saving over the only copy instead of keeping dated versions"], "scenario_contexts": ["Saving and reopening a track to keep producing across several days", "Self-containing a song to send to a collaborator", "Archiving a finished project with all its samples in one file"]}, "d2220be8-cfb6-4d71-a59d-226c24ed4069": {"definition": "Reference translation describes how well a mix keeps its intended tonal balance, clarity, and impact when judged against professional reference tracks and played back on different systems. It joins referencing - comparing a mix to trusted commercial recordings - with translation, the degree to which a mix holds up from studio monitors to earbuds, phones, and car speakers.", "plain_english": "Reference translation is about making sure your mix sounds good everywhere, not just in the studio. You compare it to well-known songs you trust, then check it on phones, earbuds, and car speakers. If it still sounds right on all of them, your mix translates well.", "purpose_function": "It exists to keep mix decisions honest and portable, guarding against choices that only sound right on one set of speakers by testing them against known references and varied playback.", "practical_application": "An engineer level-matches a commercial reference track, A/Bs it against the mix, then auditions the mix on several playback systems to confirm the balance survives outside the control room.", "category": "Mix Referencing", "related_terms": ["Reference track", "Monitoring", "Mix bus", "Frequency balance", "Loudness matching", "Mastering"], "common_mistakes": ["Comparing to a reference track without matching levels, so the louder one always seems better", "Judging translation only on one pair of monitors and skipping phone, earbud, and car checks", "Chasing the exact tone of a mastered reference during the mix stage"], "scenario_contexts": ["A/Bing a mix against a commercial track in the same genre", "Checking a near-final mix on phone, earbuds, and car speakers", "Using references to set low-end weight and overall brightness"]}, "2debbf0a-6a1f-4921-8ed5-1f720938dd1c": {"definition": "A region manager is a dedicated window - in REAPER the Region/Marker Manager - that lists every marker and region in a project with their names, positions, and lengths. From it a technician can navigate to, rename, add, remove, and reorder markers and regions, and control which regions are included when rendering.", "plain_english": "A region manager is a list window that shows all the markers and section labels in your project. From it you can jump to a spot, rename a section, or add and delete markers in one place. It makes moving around a long session much faster.", "purpose_function": "It exists to give one organised list for viewing and managing all of a project's markers and regions, speeding navigation and controlling which regions get rendered.", "practical_application": "An editor opens the region manager to jump between song sections, rename regions like verse and chorus, and tick which regions to export in a batch render.", "category": "Markers & Regions", "related_terms": ["Region marker", "REAPER project", "Marker", "Render matrix", "Timeline", "Arrangement"], "common_mistakes": ["Confusing markers, which are single points, with regions, which are time spans, in the list", "Manually scrolling a long timeline instead of jumping from the manager", "Rendering the wrong regions by not checking the render selection in the manager"], "scenario_contexts": ["Jumping between labelled song sections during a long mix", "Renaming regions before a batch stem or region render", "Cleaning up leftover markers from an edited session"]}, "50735a56-55fb-4cac-9369-ba7ac8296654": {"definition": "A region marker is a timeline marker that defines a region - a named span with a start and end point - rather than a single cue point. It labels and bounds a section of a project, such as a verse or chorus, and can be used to select that range for looping, editing, or rendering.", "plain_english": "A region marker labels a whole section of your timeline, not just one spot. It has a start and an end, so it wraps around a part like the chorus. You can click it to select that section for looping, editing, or exporting.", "purpose_function": "It exists to divide a project timeline into clearly labelled sections and to give a quick way to select or export a whole span at once.", "practical_application": "A technician draws region markers around each song section, names them, and uses them to loop a part, jump to it, or render that span as a separate file.", "category": "Markers & Regions", "related_terms": ["Region manager", "Marker", "REAPER project", "Loop", "Timeline", "Render matrix"], "common_mistakes": ["Mixing up a region marker, which labels a span, with a point marker, which is a single position", "Leaving regions unnamed, which makes the region manager and renders hard to read", "Overlapping regions and then rendering unexpected, doubled sections"], "scenario_contexts": ["Marking out verse, chorus, and bridge in an arrangement", "Selecting a region to render it as an individual stem", "Looping a marked section for practice or editing"]}, "c7d701af-b04e-431e-843b-80b9bdf6be32": {"definition": "The tempo information tied to an audio or MIDI region (also called a clip or part) in a DAW, describing the beats-per-minute at which its musical content was recorded or is meant to play. DAWs use this value to align, time-stretch, or warp the region so it conforms to the project's tempo.", "plain_english": "A region is one block of audio or notes on a track. Its region tempo is the speed, in beats per minute, that the block was played at. The software uses this speed to line the block up with the song, like matching two dancers to the same beat.", "purpose_function": "It tells a DAW the native speed of a piece of audio so the software can stretch or warp it to match the session tempo, keeping every part in sync.", "practical_application": "When importing a loop or an out-of-time take, a technician sets or corrects its region tempo so the DAW warps it cleanly to the project tempo instead of drifting.", "category": "Tempo & Sync", "related_terms": ["Tempo map", "Time-stretching", "Warping", "Beat mapping", "Rhythm pattern", "Metronome"], "common_mistakes": ["Confusing a region's tempo with the project tempo, then wondering why an imported loop plays back too fast or too slow.", "Leaving the region tempo wrong so the DAW over-stretches the audio and adds artifacts.", "Assuming every audio file carries embedded tempo data — many do not, and the tempo must be set by hand."], "scenario_contexts": ["Importing a drum loop recorded at 90 BPM into a 120 BPM session and needing it to follow the project.", "Correcting the detected tempo of a live-recorded take before enabling flex or warp.", "Building a tempo-matched remix from stems tracked at different speeds."]}, "06ecbd22-7d3c-499c-b596-8fc5a9906320": {"definition": "An automation writing mode in which new fader, pan, or parameter moves are applied as an offset added to the existing automation data rather than replacing it with absolute values. Also called trim automation, it shifts a whole existing curve up or down while preserving its shape.", "plain_english": "Automation records the moves of a control, like the volume fader, so they play back on their own. Relative automation lets you nudge all those saved moves up or down at once without erasing their shape. It works like one master dial that shifts the whole recorded ride together.", "purpose_function": "It lets an engineer change the overall level of an already-automated part without redrawing every move, so balanced detail stays intact while the average value shifts.", "practical_application": "After automating a vocal to sit in the mix, a technician uses relative (trim) mode to raise the entire pass by a decibel in the chorus without losing the word-by-word rides.", "category": "Automation", "related_terms": ["Absolute automation", "Trim mode", "Automation pass", "Fader ride", "Write mode", "Read mode"], "common_mistakes": ["Confusing relative (trim) mode with absolute mode and overwriting existing moves instead of offsetting them.", "Forgetting to leave trim mode, so later passes keep adding offsets and levels drift.", "Expecting relative changes to reshape the automation curve when they only slide it up or down."], "scenario_contexts": ["Raising an entire automated backing-vocal ride by 1.5 dB without touching its internal moves.", "Trimming a busy synth automation down a little across a whole section during a revision.", "Making a global level tweak to a client-approved automation pass late in a project."]}, "8444c40a-a08b-43ee-8c04-20c078ecf016": {"definition": "A final quality-control review carried out before a mix or master is delivered for release, confirming that the audio meets technical requirements — level, file formats, metadata, track spacing, and freedom from defects — and satisfies the creative brief. It is the sign-off step that catches problems while they are still cheap to fix.", "plain_english": "This is the last check before a song is sent out to the world. Someone listens right through and confirms the sound, loudness, file types, and track details are all correct, with no clicks or missing parts. It is like proofreading a paper one more time before you hand it in.", "purpose_function": "It exists to catch technical faults and creative mismatches at the final stage, so a finished release does not ship with errors that are costly or impossible to fix later.", "practical_application": "Before delivering masters to a label or distributor, a technician runs a release readiness review — checking loudness targets, file formats, fades, track order, and metadata — and signs off only when every item passes.", "category": "Delivery & QC", "related_terms": ["Mastering", "Loudness normalization", "Metadata", "Reference track", "Bounce", "Dither"], "common_mistakes": ["Skipping a full listen and only checking loudness while missing clicks, dropouts, or wrong fades.", "Reviewing on one set of speakers or headphones instead of several playback systems.", "Approving files without confirming the delivery format, sample rate, and metadata the distributor requires."], "scenario_contexts": ["Final sign-off on an album master before it goes to a streaming distributor.", "Checking a podcast episode for level, spacing, and edits before publishing.", "Reviewing a game or film audio deliverable against the client's technical spec sheet."]}, "8ec7203f-1200-42c8-ab88-789a222a685f": {"definition": "An internal input source that captures a DAW's own master or bus output so it can be recorded back onto an audio track — for example Ableton Live's 'Resampling' input choice. It lets a technician commit synths, effects, and full submixes to new audio entirely inside the software.", "plain_english": "Resampling means recording your software's own sound back into itself as a new clip. The resampling input is the setting that grabs the program's output for that recording. It is like pointing a track's microphone at the mixer's own output instead of the outside world.", "purpose_function": "It provides a purely internal signal path to record the DAW's output, so instruments and effect chains can be turned into plain audio for further editing, layering, or CPU savings.", "practical_application": "A producer sets an audio track's input to resampling, arms it, and records a synth-and-effects passage into a fresh clip that can be chopped, warped, or re-processed without the original devices.", "category": "Routing", "related_terms": ["Return Track", "Bounce", "Freeze", "Internal routing", "Warping", "Sample rate"], "common_mistakes": ["Confusing resampling (recording internal output) with sample-rate conversion, which is a different meaning of the word.", "Recording through the resampling input while monitoring effects that then get captured a second time.", "Forgetting that resampling bakes in the current settings, so later changes to the source no longer affect the new clip."], "scenario_contexts": ["Capturing a CPU-heavy synth patch as audio to lighten the session.", "Resampling a full drum bus to chop and rearrange it as one clip.", "Printing an effect-drenched vocal chain to committed audio before mixdown."]}, "bb7d3646-c8d6-4d9e-9a27-4b00cbf777d6": {"definition": "A mixer channel that receives signal from the sends of other tracks, most often to host a shared effect such as reverb or delay, with its output feeding the master or another bus. In Ableton Live it is called a return track; on other consoles the equivalent is an aux, effects, or return bus.", "plain_english": "A return track is a track built to hold one effect, like reverb, that many other tracks can share. Each track sends a little of its sound to it, and the wet effect comes back into the mix. It works like one shared bucket of reverb the whole band can dip into.", "purpose_function": "It centralizes an effect so several sources share a single instance, which saves CPU, keeps a consistent sound, and lets the wet effect level be balanced apart from the dry tracks.", "practical_application": "An engineer puts a reverb on a return track, then sets each vocal and instrument's send amount to place them at different depths in the same shared space.", "category": "Routing", "related_terms": ["Send", "Aux bus", "Return-track send", "Return-track routing", "Master track", "Wet/dry mix"], "common_mistakes": ["Putting a send effect at 100% wet on the source track instead of on a shared return.", "Setting the return track's effect below fully wet, which lets dry signal leak through twice.", "Routing a return back into a track that feeds it, creating a feedback loop."], "scenario_contexts": ["Sharing one reverb across a vocal group to glue them into one space.", "Setting up a delay throw on a return that several instruments can send to.", "Building parallel compression by sending drums to a return holding a compressor."]}, "73b27f85-4919-430d-8880-66ea29af99e2": {"definition": "The signal-routing configuration of a return track — what feeds it (the sends assigned to it) and where its output goes, such as to the master bus, a group, or another return. Correct return-track routing determines how a shared effect sits within the overall signal flow.", "plain_english": "This is how a shared effect track is wired into the rest of the mix. It covers which tracks feed it and where its sound goes afterward, usually to the main output. Think of it as the plumbing that decides where the effect's water flows in and out.", "purpose_function": "It defines the path of a shared effect within the mixer so its output lands in the right place and can be grouped, processed, or metered as intended.", "practical_application": "When building a mix, a technician sets return-track routing so a reverb feeds a reverb group or the master, and can chain one return into another for effects like reverb into delay.", "category": "Routing", "related_terms": ["Return Track", "Return-track send", "Send", "Bus", "Master track", "Aux bus"], "common_mistakes": ["Routing a return's output to a track that sends to it, which creates a feedback loop.", "Sending a return to the wrong bus so its effect bypasses a group's processing.", "Leaving a return routed to master when it was meant to feed a submix, breaking the intended balance."], "scenario_contexts": ["Chaining a reverb return into a delay return for a layered space.", "Routing all effect returns through one effects group for shared bus processing.", "Redirecting a return from master to a stems bus for separate delivery."]}, "e141b359-b1c3-4c87-b648-e46236cbe575": {"definition": "A send control on a track that routes an adjustable amount of that track's signal to a return track, feeding the shared effect hosted there. The send level sets how much of the source is heard through that effect.", "plain_english": "A return-track send is the knob that decides how much of a track's sound goes to a shared effect. Turn it up and more of that track gets, say, reverb. It is like choosing how much sauce to pour from a shared bottle.", "purpose_function": "It lets each source contribute a chosen amount to a shared effect on its own, so different tracks can sit at different effect depths using one effect instance.", "practical_application": "A technician raises the return-track send on a lead vocal to push it deeper into a shared reverb while keeping a backing part drier with a smaller send.", "category": "Routing", "related_terms": ["Return Track", "Send", "Return-track routing", "Pre-fader", "Post-fader", "Aux send"], "common_mistakes": ["Leaving a send pre-fader by mistake, so the effect stays loud even when the track fader is pulled down.", "Turning the send too high and drowning the source in effect.", "Sending to the wrong return and applying the wrong effect to a track."], "scenario_contexts": ["Setting individual vocal reverb depths from one shared reverb return.", "Using post-fader sends so effect level follows fader automation.", "Adding a subtle delay to a guitar by nudging its send to a delay return."]}, "53697382-6b0a-4f26-b10b-4e454531d75e": {"definition": "A software protocol, developed by Propellerhead Software (now Reason Studios) with Steinberg, that links two running audio applications so a client program streams its audio and MIDI into a host DAW while they share a synchronized transport and tempo. It let apps such as Reason run inside hosts like Cubase or Live; the technology was discontinued in 2020.", "plain_english": "ReWire was a way to connect two music programs so they worked as one. One program was the host, and another fed its sound and notes into it, all playing in perfect time. It was like plugging one app into another with a virtual cable. It is no longer supported in newer software.", "purpose_function": "It existed to combine separate audio applications — for example a dedicated synth program inside a full DAW — with locked transport, tempo, and multi-channel audio, without any physical cabling.", "practical_application": "A producer would launch a DAW as the ReWire host, start Reason as the client, and route Reason's instruments into the DAW's mixer as synced channels for recording and mixing.", "category": "Integration", "related_terms": ["Host DAW", "MIDI", "Virtual instrument", "Transport sync", "Plug-in", "Return Track"], "common_mistakes": ["Launching the client application before the host, which stops the ReWire link from forming.", "Expecting ReWire to work in current DAW versions, though support was removed after 2020.", "Confusing ReWire's app-to-app streaming with plug-in hosting, which loads instruments directly inside the DAW."], "scenario_contexts": ["Running Reason as a synth rack inside Cubase on older systems.", "Streaming Ableton Live's audio into Pro Tools with synced transport.", "Maintaining a legacy project that still relies on a ReWire client."]}, "13232d40-8ff4-4540-8a60-99782eec3b57": {"definition": "A repeating arrangement of note onsets, durations, accents, and rests that defines the rhythmic feel of a part over a set span such as a bar or phrase. In production it is often a programmed sequence — for instance a drum pattern — looped to drive a groove.", "plain_english": "A rhythm pattern is a repeating set of hits and gaps that gives a part its beat. Think of a steady drum groove that loops around every bar. It is the timing skeleton that the rest of the music hangs on.", "purpose_function": "It provides the recurring rhythmic framework that sets a section's groove and tempo feel, giving other parts a timing reference to lock to.", "practical_application": "A producer programs a rhythm pattern in a drum sequencer, loops it across a section, and layers bass and other parts against its accents to build a groove.", "category": "Rhythm & Timing", "related_terms": ["Groove", "Quantization", "Step sequencer", "Region tempo", "Tempo map", "Swing"], "common_mistakes": ["Quantizing a rhythm pattern so hard that it loses all human feel and groove.", "Confusing the rhythm pattern with the tempo — the pattern is the arrangement of hits, tempo is the speed.", "Building patterns only one bar long so the part feels static over a whole section."], "scenario_contexts": ["Programming a four-on-the-floor kick pattern for a dance track.", "Copying a verse rhythm pattern and varying it for the chorus.", "Locking a bassline to the accents of a drum pattern for a tight groove."]}, "81a89a02-83bb-47c8-a3c3-56fb7aa97a33": {"definition": "In medieval music theory, one of the six standard rhythmic patterns used in Notre Dame school polyphony (c. 1150-1250). Each mode fixed a repeating pattern of long and short note values in triple (ternary) groupings, signalled by patterns of ligatures in the notation, and it organized rhythm before the rise of mensural notation.", "plain_english": "A rhythmic mode is one of six set patterns of long and short notes used by composers in the Middle Ages. Think of it like a fixed drum groove: you pick a pattern, then repeat it to drive the music along.", "purpose_function": "Rhythmic modes gave early polyphony a shared, repeatable way to organize time, so several voices could line up rhythmically before there was a precise notation for individual note lengths.", "practical_application": "A performer or scholar working with Notre Dame organum reads the ligature patterns to identify which rhythmic mode applies, then works out the intended long-short rhythm from it.", "category": "Music theory", "related_terms": ["Ligature", "Mensural notation", "Organum", "Ternary meter", "Clausula", "Perfect time"], "common_mistakes": ["Confusing rhythmic mode with the pitch-based church modes such as Dorian or Phrygian, which describe scales rather than rhythm", "Assuming the classic six modes allow duple groupings, when they are built on triple, ternary divisions", "Reading the ligatures as fixed pitches rather than as cues to a rhythmic pattern"], "scenario_contexts": ["Transcribing 13th-century Notre Dame organum from ligature notation into modern rhythm", "Teaching a music-history class on how rhythm was organized before mensural notation", "Directing an early-music ensemble in performing Perotin with the correct modal rhythm"]}, "df3d3f05-2785-40ef-a04e-3aa6bd3021a5": {"definition": "A recorded audio sample of a ride cymbal being struck, stored for playback in a sampler, drum machine, or virtual drum instrument. It reproduces the sustained, shimmering tone of a real ride cymbal so it can be triggered from a MIDI note or drum pad instead of a live cymbal.", "plain_english": "A ride sample is a recording of one hit on a ride cymbal, saved so software can play it back. It lets you add a real cymbal sound to a beat without recording a drummer.", "purpose_function": "It provides a ready-made, controllable cymbal sound for programmed drum parts, so a producer can get a convincing ride without miking and recording an acoustic kit.", "practical_application": "A producer loads a ride sample into a drum sampler and triggers it from a MIDI pattern, adjusting its level and decay so it sits with the rest of the programmed kit.", "category": "Drum programming", "related_terms": ["Sample", "Sampler", "Drum machine", "MIDI", "Velocity", "One-shot"], "common_mistakes": ["Triggering the same identical ride hit over and over so it sounds robotic, with no velocity or round-robin variation", "Forgetting that a long ride sample can build up unwanted cymbal wash and mask other tracks", "Grabbing any cymbal sample instead of choosing one that fits the song's tempo and style"], "scenario_contexts": ["Programming a drum beat in a DAW with a sampled kit", "Replacing a poorly recorded live ride with a clean sample", "Adding cymbal accents to an electronic track that has no live drums"]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"605f4a98-9877-4f92-8169-4ff8a1699ab9": {"definition": "The practice of manually moving a fader in real time (or drawing volume automation) to control the level of a solo instrument throughout its section, raising it so it stays prominent and easing it back at louder moments to keep it balanced against the rest of the mix.", "plain_english": "Riding the solo means moving a fader by hand to keep a solo at the right volume the whole way through. You nudge it up so the solo stands out, then ease it back when it gets too loud.", "purpose_function": "It keeps a featured solo consistently audible and expressive, correcting level swings that a single fixed fader setting or a compressor cannot fully smooth out.", "practical_application": "During a mix the engineer draws automation or moves the fader live so a guitar solo rides a few dB above the band, then returns it to normal when the solo ends.", "category": "Level automation", "related_terms": ["Fader riding", "Gain riding", "Volume automation", "Ride the vocal", "Mix balance", "Automation"], "common_mistakes": ["Pushing the solo so far above the band that it feels detached and unnatural", "Making abrupt fader jumps instead of smooth moves, which draws attention to the level change", "Relying only on a compressor and never riding the fader, so quiet solo phrases still disappear"], "scenario_contexts": ["Bringing up a guitar solo in the bridge of a rock song", "Keeping a saxophone solo even against a busy horn section", "Automating a keyboard solo so every phrase is heard clearly"]}, "c68e4cc4-5530-456a-bf86-af058503b434": {"definition": "The practice of continuously adjusting the lead vocal fader, by hand or via automation, so the vocal stays at a consistent, intelligible level above the backing track, compensating for the natural loud and soft variations in the performance.", "plain_english": "Riding the vocal means moving the vocal fader up and down as the song plays so the singing is always easy to hear. When a line is soft you push it up; when it is belted you pull it back.", "purpose_function": "It keeps the lead vocal even and clearly on top of the mix, fixing moment-to-moment level changes that compression alone often cannot fully tame.", "practical_application": "The engineer writes volume automation on the vocal track, nudging quiet words up and loud peaks down so every lyric sits at about the same level.", "category": "Level automation", "related_terms": ["Fader riding", "Gain riding", "Volume automation", "Vocal compression", "Lead vocal", "Ride the solo"], "common_mistakes": ["Using heavy compression as a substitute for riding, which can flatten the vocal's natural dynamics", "Flattening the vocal to one uniform volume so it sounds lifeless and pasted on top", "Forgetting to ride quiet consonants and phrase ends, so some words get lost"], "scenario_contexts": ["Keeping a pop lead vocal consistent over a dense mix", "Lifting whispered or quiet lines in a ballad so the words stay clear", "Live mixing, where the engineer rides the vocal fader to match a singer who moves off-mic"]}, "54644df4-a221-4fc2-aa80-8e114e5dae0c": {"definition": "The Right Zone is a dockable panel on the right side of the Cubase/Nuendo Project window that gives tabbed access to production tools without leaving the arrangement view, typically containing the VSTi Rack, the Media Rack (MediaBay), the Control Room (CR), and the Meter tab.", "plain_english": "The Right Zone is a panel on the right side of the Cubase project window. It holds handy tools, like your instruments, media, and meters, so you can reach them without opening extra windows.", "purpose_function": "It exists to keep frequently used tools docked next to the arrangement, streamlining workflow by reducing the number of floating windows an engineer has to manage.", "practical_application": "An engineer shows or hides the Right Zone and its tabs from the toolbar to add a VST instrument, drag in media, or watch the Control Room and metering while arranging, all within one window.", "category": "DAW Interface", "related_terms": ["Left Zone", "Lower Zone", "VSTi Rack", "MediaBay", "Control Room", "Project window"], "common_mistakes": ["Confusing the Right Zone with the Left Zone (Inspector/Visibility) or the Lower Zone (MixConsole and editors)", "Not realizing individual tabs can be hidden, then thinking a feature is missing", "Searching for the standalone VST Instruments window when the Right Zone's rack offers the same access"], "scenario_contexts": ["Adding and tweaking a VST instrument from the VSTi Rack while arranging", "Dragging loops or presets from the Media Rack into the project", "Monitoring the Control Room and metering during mixing without a separate window"]}, "811caf63-7011-4d76-acc5-94c889a7248a": {"definition": "The programming of drum rolls, meaning rapid evenly spaced repeated hits, into a step sequencer, drum machine, or DAW. It is done either by entering fast subdivided notes or by using a dedicated 'roll' or retrigger function that repeats a sound at a set rate.", "plain_english": "Roll programming means telling a drum machine or software to play a fast string of repeated hits, like a snare roll. You either place many quick notes in a row or turn on a built-in roll button.", "purpose_function": "It lets a producer build fills, buildups, and rolls in programmed drum parts without playing them live, giving precise control over the speed and timing of the repeated hits.", "practical_application": "A producer programs a snare roll before a chorus by drawing sixteenth or thirty-second notes on the step grid, or by holding a drum machine's roll button set to the chosen rate.", "category": "Drum programming", "related_terms": ["Step sequencer", "Drum machine", "Fill", "Flam", "Quantization", "Velocity"], "common_mistakes": ["Leaving every hit in the roll at the same velocity, so it sounds mechanical instead of building naturally", "Setting the roll rate out of time with the song's tempo, making the fill feel rushed or dragging", "Overusing rolls so they lose impact instead of marking key transitions"], "scenario_contexts": ["Programming a snare buildup into a chorus in electronic music", "Adding a hi-hat roll for energy in a trap beat", "Recreating a live drum fill with a step sequencer"]}, "a3fd8617-253d-4854-bfe7-a7f53bcce064": {"definition": "In mixing, the use of recorded room ambience, usually from distant room microphones, blended underneath the close-miked tracks to add natural space, depth, and cohesion, in effect filling out the mix with the sound of the recording space.", "plain_english": "Room fill is the sound of the room itself, picked up by far-away mics and added under the main tracks. Blended in gently, it makes a recording feel like it happened in a real space instead of a dead studio.", "purpose_function": "It supplies natural reverberation and glue that close mics miss, helping separately close-miked instruments sound like a single ensemble in one room.", "practical_application": "An engineer brings up the room mics under a close-miked drum kit, often compressing them, until the kit gains size and depth without washing out the direct sound.", "category": "Ambience", "related_terms": ["Room mic", "Room layer", "Ambient miking", "Reverb", "Depth", "Parallel compression"], "common_mistakes": ["Pushing the room level so high that the mix turns muddy and loses punch", "Ignoring phase between the room mics and close mics, which can thin out the sound", "Assuming artificial reverb and room fill are the same, when captured room sound has a different, natural character"], "scenario_contexts": ["Adding recorded room mics to fatten a close-miked drum kit", "Blending room ambience into a live band recording for a sense of space", "Using captured room sound to glue a multi-mic acoustic session together"]}, "7ac7a22a-c51b-4d56-8d63-971b8fc7ee40": {"definition": "A track or group of tracks of room-microphone ambience blended in as a distinct layer of a mix, most often on drums, to add depth, natural reverberation, and a sense of the recording space alongside the close-miked sound.", "plain_english": "A room layer is a separate track of room-mic sound that you mix in under the main tracks. Blending it in gives drums or a band a bigger, more open feel, like you can hear the room around them.", "purpose_function": "It gives the engineer independent control over the recorded ambience, so the amount of room and depth can be balanced separately from the close mics.", "practical_application": "The engineer routes the room mics to their own layer, then raises, compresses, or mutes it during a mix to dial in exactly how much of the recording space is heard.", "category": "Ambience", "related_terms": ["Room mic", "Room fill", "Ambient miking", "Parallel compression", "Reverb", "Depth"], "common_mistakes": ["Adding the room layer without checking phase against the close mics, which can hollow out the sound", "Leaving the room layer too loud so it smears transients and buries detail", "Letting a noisy room layer play through quiet sections instead of automating it out"], "scenario_contexts": ["Blending a drum room layer to add size in a rock mix", "Automating the room layer up only in the choruses for extra energy", "Using a compressed room layer as parallel ambience on a live recording"]}, "8822824b-7847-4c4b-8a37-d0121d5ca09d": {"definition": "In audio post-production and editing, the practice of filling silent gaps, edit points, or cleaned-out sections with room tone, the recorded ambient background sound of the location with no dialogue or action, so edits sound seamless and the background never drops to unnatural digital silence.", "plain_english": "Room-tone fill means covering silent gaps in an edit with the quiet background hum of the room. Real spaces are never truly silent, so filling gaps this way hides the joins between clips.", "purpose_function": "It keeps the background sound continuous across cuts and repaired spots, so listeners do not hear jarring drops to dead silence where audio was removed or spliced.", "practical_application": "A dialogue editor records or lifts a chunk of room tone from a scene and lays it into pauses and edit points to smooth over cuts and patched-out noises.", "category": "Post-production", "related_terms": ["Room tone", "Ambience", "Dialogue editing", "Presence", "Crossfade", "Noise floor"], "common_mistakes": ["Filling gaps with true digital silence, which makes edits sound abrupt and obvious", "Using room tone from a different space or session, so the background texture does not match", "Forgetting to capture dedicated room tone on location, leaving nothing clean to fill with later"], "scenario_contexts": ["Smoothing dialogue edits in a film or podcast", "Filling the gap left after removing a cough or noise from a recording", "Matching background ambience between takes captured at different times"]}, "691b9e73-7d9b-4b20-84eb-b14b0cf20907": {"definition": "One of a set of alternating recordings of the same drum hit, where a sampler cycles through the variations on successive triggers so repeated notes are not identical. This avoids the mechanical 'machine-gun' effect of retriggering a single static sample.", "plain_english": "It is one of several recordings of the same drum hit. The sampler swaps between them each time you play the note, so fast repeats sound real instead of like a stuck button.", "purpose_function": "It makes programmed or sampled drums sound natural by adding slight variation between repeated hits, mimicking how a real drummer never plays two strokes exactly alike.", "practical_application": "A technician loading a sampled kit relies on round-robin layers so a fast snare roll or hi-hat pattern sounds human rather than obviously looped.", "category": "Sampling", "related_terms": ["Sample-based Track", "Sample choke group", "Velocity layering", "Sample tuning", "One-shot sample"], "common_mistakes": ["Assuming one sample per drum is enough, leaving fast repeats sounding like a 'machine gun'", "Confusing round-robin (cycling equal-velocity takes) with velocity layers (different samples per hit strength)", "Programming too few round-robins so the cycle audibly repeats"], "scenario_contexts": ["Building a realistic sampled drum kit in a software sampler", "Programming a rapid snare roll that must not sound mechanical", "Choosing a drum library based on how many round-robin variations it offers"]}, "c23360f0-4018-4f65-a0a5-9ff36f4e0bf5": {"definition": "A folder track in a DAW that groups several tracks and passes their combined output through a single point, letting the group be routed, processed, and controlled together. It acts as an organizational container that also serves as a submix or bus for the tracks nested inside it.", "plain_english": "It is a folder that holds a group of tracks and sends them all to one place. You can move, mute, or add effects to the whole group at once, like putting many files in one labeled box.", "purpose_function": "It keeps a busy session tidy while giving one set of controls over a whole group of tracks, so drums or backing vocals can be handled as a single unit.", "practical_application": "A mixer drops all the drum tracks into a routing folder to fold them down to one fader, apply bus compression, and clean up the mixer view.", "category": "Signal Routing", "related_terms": ["Routing window", "Routing validation", "Bus", "Submix", "Group channel"], "common_mistakes": ["Confusing a plain organizing folder with one that actually sums and routes audio", "Adding the same processing on both the folder and its child tracks, doubling the effect", "Forgetting that soloing or muting the folder affects every track inside it"], "scenario_contexts": ["Grouping all drum tracks to a single bus for shared compression", "Cleaning up a large session by nesting related tracks", "Automating one fader to raise or lower a whole vocal group"]}, "0d8bad5b-7287-47fa-9db1-b1749ffa2d59": {"definition": "The practice of checking that every signal path in a session or system - inputs, outputs, buses, sends, and returns - is assigned to its intended destination before recording or performance. It confirms audio flows where expected and that no path is misassigned, missing, or duplicated.", "plain_english": "It means checking that every signal goes where it should before you hit record or start a show. You trace each path so nothing is sent to the wrong place or left silent.", "purpose_function": "It catches routing errors early, preventing lost takes, silent channels, or feedback caused by signal reaching the wrong output.", "practical_application": "Before tracking a band, an engineer walks each input to its channel and each bus to its output, confirming meters move where expected.", "category": "Signal Routing", "related_terms": ["Routing window", "Routing Folder", "Signal flow", "Bus", "Patchbay"], "common_mistakes": ["Assuming default routing is correct without checking it", "Testing only the main output and missing wrong bus or send assignments", "Skipping validation after loading a template built for a different session"], "scenario_contexts": ["Line-checking inputs before a recording session", "Verifying monitor and record paths in a new session template", "Confirming console routing before a live show"]}, "fa564c9a-9cb0-4e91-ba24-bbbf54ffe37d": {"definition": "A screen or view in a DAW or digital console that displays and edits signal routing assignments, such as which physical inputs feed channels and which channels feed buses, outputs, sends, and returns. It presents the routing as a list or matrix the user can reassign.", "plain_english": "It is the screen where you see and change where signals go. It lays out the inputs, outputs, and buses so you can connect them, like a map of all the cables inside the software.", "purpose_function": "It gives one place to set up and review the whole signal path, so a technician can wire a session without hunting through every channel.", "practical_application": "An engineer opens the routing window to assign hardware inputs to record tracks and to send a group to a headphone mix.", "category": "Signal Routing", "related_terms": ["Routing validation", "Routing Folder", "Bus", "Signal flow", "Patchbay"], "common_mistakes": ["Confusing the routing window with the mixer view and editing the wrong assignment", "Reassigning an input without noticing it breaks another track's path", "Overlooking that some routings only appear in this window, not on the channel strip"], "scenario_contexts": ["Assigning audio-interface inputs to tracks at the start of a session", "Setting up bus and send routing for a headphone mix", "Reconfiguring outputs when moving a session to a different studio"]}, "3d244a91-9375-4584-98b4-dfb466262ce1": {"definition": "A group setting in a sampler or drum machine where triggering one assigned sound immediately silences another in the same group, so only one can sound at a time. It is most commonly used so a closed hi-hat cuts off a ringing open hi-hat.", "plain_english": "It is a group where playing one sound stops another in the same group. The classic use is a closed hi-hat cutting off an open hi-hat, just like a drummer's foot closing the cymbals.", "purpose_function": "It recreates sounds that cannot physically ring at once, keeping sampled drums realistic and stopping overlapping notes from piling up.", "practical_application": "A beatmaker puts open and closed hi-hat pads in the same choke group so each new hat hit stops the previous one cleanly.", "category": "Sampling", "related_terms": ["Round-robin drum sample", "Sample decay control", "Sample-based Track", "Mute group", "Sample end offset"], "common_mistakes": ["Confusing a choke group (one sound cuts another) with a mute group used only for mixing", "Placing unrelated drums in the same group so wanted hits get cut off", "Forgetting to choke the open hi-hat, leaving it ringing under closed hits"], "scenario_contexts": ["Programming realistic hi-hat patterns on a drum machine or sampler", "Setting up cymbal chokes for an electronic drum kit", "Preventing overlapping one-shots from cluttering a beat"]}, "a3f45653-528b-477a-857f-d51a0381cf92": {"definition": "A parameter that sets how quickly a sample's level falls after its initial attack, shaping the length of the sound's tail. On drum machines and samplers it is often a single decay knob that shortens or lengthens sounds such as a kick or open hi-hat.", "plain_english": "It is a control that sets how fast a sound fades after it starts. Turn it down for a short, tight hit; turn it up for a long ringing tail, like choosing how long a bell rings.", "purpose_function": "It lets a sound be tightened or stretched to fit a track's tempo and feel without replacing the sample itself.", "practical_application": "A producer shortens the decay on an 808-style kick so it stops before the next note, keeping a fast bassline clean.", "category": "Sampling", "related_terms": ["Sample end offset", "Sample tuning", "Sample choke group", "Amplitude envelope", "Sample-based Track"], "common_mistakes": ["Confusing decay (fall after attack) with release (fade after the note is let go)", "Setting a very long decay so drum hits blur into each other", "Using decay to fix timing that really needs the sample's end point trimmed"], "scenario_contexts": ["Tightening a long 808 kick to fit a fast tempo", "Shaping the tail of an open hi-hat sample", "Matching sample length to the groove of a beat"]}, "014d792c-292c-4e5a-8697-e439e59f9e42": {"definition": "A setting that moves the point at which sample playback stops, ending it before the audio file's natural end. It trims unwanted tail, silence, or noise from the back of a sample.", "plain_english": "It sets where a sample stops playing, cutting it off before the recording actually ends. You use it to trim a dead tail or noise at the end, like trimming the end of a video clip.", "purpose_function": "It cleans up or shortens a sample's tail without editing the source file, tightening loops and one-shots.", "practical_application": "A technician nudges the end offset in to drop a click or room noise at the tail of a snare one-shot.", "category": "Sampling", "related_terms": ["Sample decay control", "Sample tuning", "Sample-based Track", "Start point", "Loop point"], "common_mistakes": ["Confusing the end offset (where playback stops) with the loop end point", "Trimming too far in and cutting off part of the wanted sound", "Assuming the offset edits the audio file itself rather than just playback"], "scenario_contexts": ["Trimming noise from the tail of a one-shot drum sample", "Tightening a sampled loop so it ends on the beat", "Removing dead air at the end of a recorded phrase"]}, "48da6259-9805-4ba5-a81b-94439e884492": {"definition": "Adjusting the perceived pitch of a sample, typically by coarse (semitone) and fine (cent) controls, either by changing playback speed or by pitch-shifting. It brings a sample into a target key or aligns it with other pitched material.", "plain_english": "It means changing the pitch of a sample up or down. You do it to put a sound in the right key, like tuning a guitar string so it matches the song.", "purpose_function": "It fits a sample to a track's key and tunes drums for punch or musical effect, so sampled sounds sit in tune with everything else.", "practical_application": "A producer tunes a kick drum sample to the song's root note so the low end reinforces the bass instead of clashing.", "category": "Sampling", "related_terms": ["Sample-based Track", "Sample decay control", "Round-robin drum sample", "Pitch shifting", "Transpose"], "common_mistakes": ["Confusing coarse tuning in semitones with fine tuning in cents", "Tuning a sample so far by playback speed that it sounds obviously sped up or slowed down", "Leaving drum samples untuned so the kick clashes with the bassline"], "scenario_contexts": ["Tuning a kick or 808 to the key of a track", "Matching a vocal chop to the song's melody", "Correcting a slightly off-pitch sampled instrument"]}, "6bf82ba6-262b-43e6-8401-f94db4751cd6": {"definition": "A track whose sound is built from prerecorded audio samples - loops, one-shots, or sampled instruments triggered from a sampler - rather than from live-recorded audio or synthesized tones. The samples are arranged, triggered, and processed to form the part.", "plain_english": "It is a track made from ready-made sound recordings instead of live playing or a synth. You build the part by placing and triggering samples, like making music from a box of prerecorded clips.", "purpose_function": "It lets a producer build parts from existing sounds quickly, giving access to realistic or hard-to-record sounds without live performers.", "practical_application": "A beatmaker builds a drum part on a sample-based track by triggering kick, snare, and hat one-shots from a sampler.", "category": "Sampling", "related_terms": ["Round-robin drum sample", "Sample tuning", "Sample choke group", "One-shot sample", "Sample decay control"], "common_mistakes": ["Assuming samples need no tuning or timing edits to sit in a mix", "Overusing one identical sample so repeats sound mechanical", "Ignoring the sample rate or quality of source clips, hurting the final sound"], "scenario_contexts": ["Building a hip-hop or electronic beat from one-shots and loops", "Layering sampled instruments to form a backing track", "Replacing a recorded drum with a sampled one during production"]}, "89f38824-a96d-49dd-ad15-979b0d551a25": {"definition": "A DAW track type that hosts a built-in sampler instrument, letting a single audio sample be mapped across the keyboard and played back chromatically via MIDI, with controls for root pitch, filter, envelope, and loop points.", "plain_english": "A track in music software that turns one recorded sound into a playable instrument. You drop in a clip, and different keys play it higher or lower, like a piano made from any sound you pick.", "purpose_function": "It lets you build a playable, pitched instrument from any audio clip without a separate hardware sampler, so a recorded note, loop, or one-shot can be performed melodically from a MIDI keyboard.", "practical_application": "A producer drags a vocal chop or a single bass note onto a sampler track, plays a melody from a MIDI keyboard, and shapes each hit with the filter and envelope.", "category": "DAW Instrument", "related_terms": ["Sampler", "MIDI", "Virtual instrument", "Audio sample", "Score Editor"], "common_mistakes": ["Confusing a sampler track with a plain audio track; a sampler track plays a mapped sample chromatically via MIDI, while an audio track just plays a recording on the timeline.", "Forgetting to set the correct root/base pitch, so the sample plays back at the wrong pitch across the keyboard.", "Leaving loop points or the envelope release badly set, causing clicks or abrupt cutoffs on held notes."], "scenario_contexts": ["Turning a one-shot vocal sample into a playable chord instrument for a pop production.", "Mapping a single recorded bass note and performing a bassline from a MIDI keyboard.", "Chopping a drum loop onto a sampler track to re-trigger individual hits in a new pattern."]}, "d820babd-eab7-488d-a4a1-bec4f5153cec": {"definition": "On a digital mixing console, a scene is a stored snapshot of the desk's settings (fader levels, mutes, EQ, routing, effects), and scene automation is the storing and ordered recall of these snapshots so the console reconfigures itself at defined cue points during a show.", "plain_english": "A way to save all your mixer's settings as a snapshot and load them back instantly. During a show you jump from one saved setup to the next at each cue, so the mix changes exactly on time.", "purpose_function": "It lets one operator make large, repeatable changes to a complex mix at the press of a button, so cues happen accurately and the same way every performance.", "practical_application": "A live engineer builds a scene for each song or each section of a musical, then hits next (or lets timecode fire it) to recall levels, mutes, and effects at each cue.", "category": "Console Automation", "related_terms": ["Snapshot", "Recall", "Mute group", "DCA group", "Cue"], "common_mistakes": ["Assuming scene recall changes everything; many desks let you scope or filter parameters, so items left out of scope will not update as expected.", "Not safeing or isolating channels (like a wireless input or a global reverb) that should stay put, so a recall unexpectedly overwrites them.", "Overwriting the wrong scene by storing instead of recalling, losing carefully built settings."], "scenario_contexts": ["Running a musical theatre show where each cue recalls a new scene of mic mutes and levels.", "Switching band configurations between acts at a festival using stored scenes.", "Recalling a preset scene for a specific service format in a house of worship."]}, "515403b7-78ba-4f8e-98af-f4266b9217f4": {"definition": "The relative level and blend among the instruments and sections of a musical score, set so melody, harmony, and supporting parts each sit at their intended prominence within the mix.", "plain_english": "Getting the instruments in a piece of music to the right loudness against each other. It is like making sure the melody stays clear while the backing parts support it instead of covering it up.", "purpose_function": "It makes the listener hear the intended musical hierarchy, with lead lines clear and accompaniment supportive, so the emotional and structural intent of the score comes through.", "practical_application": "A scoring mixer rides section faders so strings, brass, and woodwinds each sit correctly under a solo line, matching the composer's intent for a cue.", "category": "Score Mixing", "related_terms": ["Level balance", "Score stem", "Score premix", "Panning", "Dynamic range"], "common_mistakes": ["Balancing each section in solo instead of in context, so parts that sounded right alone fight once combined.", "Chasing loudness on every part until nothing leads and the mix sounds flat.", "Ignoring how dialogue and picture will sit over the score, so a balance that works alone masks the dialogue later."], "scenario_contexts": ["Mixing an orchestral film cue so the theme carries over the accompaniment.", "Balancing a string section against percussion in a game-music stem.", "Setting relative levels of soloist and ensemble in a concert recording."]}, "a0643b3e-2fb2-4955-a224-05c57daf98df": {"definition": "The sense of front-to-back distance created among the elements of a musical score, produced with reverb, early reflections, relative level, and high-frequency roll-off so some instruments feel close and others farther back in a perceived space.", "plain_english": "How near or far each instrument feels in a piece of music. Using echo and volume, a mixer can make one instrument sound right in front of you and another sound far away, like players spread across a real stage.", "purpose_function": "It recreates a believable acoustic space and separates instruments front to back, giving the score dimension so parts do not all sound stuck in the same flat plane.", "practical_application": "A mixer adds a touch more reverb and gently lowers level and top end on the back of a section to push it back, keeping the solo dry and forward.", "category": "Score Mixing", "related_terms": ["Reverb", "Score width", "Score balance", "Ambience", "Early reflections"], "common_mistakes": ["Adding so much reverb to create depth that the score turns washy and loses clarity.", "Using only level changes for depth while ignoring reverb and high-frequency roll-off, so distance never feels convincing.", "Placing everything up front, leaving the mix flat with no front-to-back dimension."], "scenario_contexts": ["Placing a solo instrument in front of a lush string bed on a film cue.", "Recreating a concert-hall front-to-back perspective in an orchestral mix.", "Pushing pads and textures behind the lead in a hybrid score."]}, "459397ba-017a-49bb-9bb8-15759eb36279": {"definition": "A DAW editing window that displays and edits MIDI data as standard musical notation on staves, letting the user enter, correct, and format notes and then print or export a readable score or parts.", "plain_english": "A part of music software that shows your notes as sheet music instead of blocks or piano-roll bars. You can write and fix notes on the staff and print proper sheet music for players to read.", "purpose_function": "It bridges MIDI sequencing and written notation, so the same performance data can be edited musically and turned into printed scores or parts for live musicians.", "practical_application": "A composer records a MIDI part, opens the Score Editor to clean up rhythms and note spelling, adds dynamics and clefs, then prints parts for a session.", "category": "DAW Editor", "related_terms": ["MIDI", "Piano roll", "Notation", "Quantize", "Key Editor"], "common_mistakes": ["Expecting raw MIDI to look tidy; without quantize and display settings, exact human timing shows as messy, unreadable notation.", "Confusing display quantize (how notation looks) with real quantize (which moves the notes), and altering the performance by accident.", "Assuming what you see is what plays; notation display settings change appearance, not playback."], "scenario_contexts": ["Printing individual parts for a string session from a MIDI mockup.", "Cleaning up note spelling and rhythms before handing a score to a copyist.", "Entering a melody by hand on the staff for a student arrangement."]}, "352af695-8921-4334-a0f3-b2acc39b4bee": {"definition": "In film and TV post-production, a premix (predub) of the music score: a balanced submix of the many recorded music tracks and stems, prepared ahead of the final re-recording mix so the music can be handled as a manageable set of elements during the final dub.", "plain_english": "A rough, tidied-up mix of just the music, made before the final movie mix. It combines many music tracks into a few, so the team is not juggling hundreds of tracks when they blend music with dialogue and effects.", "purpose_function": "It reduces a large music session to a workable, pre-balanced group of elements, saving time and keeping the final mix manageable when music meets dialogue and effects.", "practical_application": "A music mixer balances the orchestral and synth tracks into a score premix, delivering stems the re-recording mixer drops straight into the final dub.", "category": "Post Production", "related_terms": ["Score stem", "Re-recording mix", "Stem", "Dialogue premix", "Score balance"], "common_mistakes": ["Baking in too much processing or level so the re-recording mixer cannot rebalance the music against dialogue later.", "Delivering premix stems that are not level- or phase-consistent, so they do not sum back to the intended full mix.", "Skipping clear labeling and formatting of stems, causing confusion at the final dub."], "scenario_contexts": ["Preparing a music predub before the final re-recording mix of a feature film.", "Delivering balanced score stems to a dub stage.", "Consolidating a huge orchestral session into a few premixed groups for the mix."]}, "7b4ddd8a-b164-437f-a3eb-67d6400b3b08": {"definition": "A large recording studio (scoring stage) purpose-built for recording film, TV, and game music, with an acoustically treated live room big enough for a full orchestra, a control room, and facilities to record to picture in sync.", "plain_english": "A very large recording studio built for recording film music with a whole orchestra at once. It is big enough to fit dozens of players and lets them watch the movie so the music lines up with the picture.", "purpose_function": "It provides the room size, acoustics, and picture-sync facilities needed to capture a full ensemble performing to a film, which a normal studio cannot accommodate.", "practical_application": "A scoring session books a stage where the orchestra plays to picture while the mixer captures multitrack stems for later premixing.", "category": "Recording Facility", "related_terms": ["Live room", "Control room", "Score premix", "Click track", "Multitrack"], "common_mistakes": ["Assuming any large room works; scoring needs controlled acoustics and low noise, not just size.", "Underestimating the headphone/foldback and click-track routing an orchestra needs when playing to picture.", "Forgetting that mic bleed across a big room limits how much each section can be fixed separately later."], "scenario_contexts": ["Recording a feature-film orchestral score to picture.", "Tracking a game-music ensemble across sectional passes on a large stage.", "Capturing choir and orchestra together for a trailer cue."]}, "7a548df3-fb76-4173-b0c1-0d6812c9f4a3": {"definition": "A stem containing only the music score: a submix bounce of the score's grouped elements (or the whole music) delivered as a separate track or set of tracks, kept apart from dialogue and effects for use in the final mix and later versioning.", "plain_english": "A separate mixed-down track of only the music. Keeping the music on its own lets the team turn it up or down without touching dialogue or sound effects, and makes it easy to swap or remove later.", "purpose_function": "It isolates the music as an independent element so it can be balanced, muted, or replaced in the final mix and reused for trailers, foreign versions, or remixes.", "practical_application": "A mixer delivers music stems (for example, orchestra, synths, and percussion) that the dub stage rides against dialogue and effects.", "category": "Post Production", "related_terms": ["Stem", "Score premix", "Dialogue stem", "Effects stem", "Re-recording mix"], "common_mistakes": ["Assuming a stem must be a single track; a score stem is often several grouped stems that sum to the full music.", "Printing stems with different processing than the master, so they do not recombine to match the approved mix.", "Failing to keep stems separate from dialogue and effects, defeating the point of stem delivery."], "scenario_contexts": ["Delivering a music-only stem for a film's final dub.", "Supplying score stems for a trailer edit.", "Providing an isolated music stem for foreign-language (M&E) versions."]}, "9ca1972b-7f3a-4dc6-8564-9d02721691aa": {"definition": "The perceived left-to-right spread of the music score in the stereo (or surround) field, set with panning, stereo miking, and stereo-image processing so sections occupy their intended horizontal positions and overall stage width.", "plain_english": "How wide the music sounds from left to right. By panning instruments and using stereo tricks, a mixer can make the orchestra feel spread across a big stage instead of squashed into the middle.", "purpose_function": "It positions instruments horizontally and controls the overall spread, giving the score a natural stereo image and separating parts so they do not pile up in the center.", "practical_application": "A mixer pans strings, brass, and percussion to their orchestral seating and widens the ambience mics to place the ensemble across the stereo stage.", "category": "Score Mixing", "related_terms": ["Panning", "Stereo image", "Score depth", "Score balance", "Mono compatibility"], "common_mistakes": ["Widening so aggressively with stereo processing that the mix collapses or hollows out when summed to mono.", "Panning everything hard left and right, leaving a hole in the center where the lead should sit.", "Ignoring the standard orchestral seating layout, so instrument positions feel unnatural."], "scenario_contexts": ["Panning an orchestra to its concert seating in a film mix.", "Widening pads and strings to open up space around a centered melody.", "Checking mono compatibility of a widened score for broadcast."]}, "4fa95748-d6e0-4ad8-b238-67904cbb2aa5": {"definition": "The relative level relationship between the musical score and the spoken dialogue in a film, television, or game mix, set so dialogue stays intelligible while the music keeps its emotional impact.", "plain_english": "It is how loud the background music is next to the talking in a film. You set it so you can still hear the words clearly, while the music still moves you.", "purpose_function": "It ensures the audience can always follow the spoken story while the score supports the mood, keeping music from masking important lines.", "practical_application": "A re-recording mixer rides the music level under dialogue, dipping the score a few decibels during key lines and lifting it in transitions or action scenes.", "category": "Mix Balance", "related_terms": ["Dialogue intelligibility", "Re-recording mixer", "Ducking", "Stem", "Level balance", "Scoring mixer"], "common_mistakes": ["Setting the score so loud that dialogue becomes hard to follow", "Judging the balance only in a quiet room instead of at realistic listening levels", "Forgetting that streaming loudness normalization can shift the perceived balance", "Checking the mix only on studio monitors and never on consumer-grade playback"], "scenario_contexts": ["Final re-recording mix of a feature film on a dubbing stage", "Balancing an emotional cue under a character's monologue in a TV drama", "Keeping narration clear over music in a documentary", "Setting adaptive music levels under dialogue in a video game"]}, "b3b6d1da-0c1d-45af-a4e2-4cfaa14bdef0": {"definition": "The recording engineer responsible for capturing a film, television, or game score during scoring-stage sessions, setting up microphones and signal paths and recording the orchestra or ensemble in sync with picture.", "plain_english": "This is the engineer who records the music written for a film. They set up the microphones and capture the orchestra as it plays along to the movie.", "purpose_function": "The role exists to turn a large live ensemble into clean, well-organized recorded tracks that the music team can later edit and mix.", "practical_application": "On a scoring stage the engineer places microphones across the orchestra, manages click and headphone feeds, and records each cue locked to the on-screen picture.", "category": "Studio Roles", "related_terms": ["Scoring mixer", "Scoring stage", "Click track", "Cue", "Orchestral recording", "Re-recording mixer"], "common_mistakes": ["Confusing the scoring engineer with the re-recording mixer who handles the final film mix", "Assuming one person always both records and mixes the score", "Underestimating how much session planning and microphone setup the role requires"], "scenario_contexts": ["Recording an orchestral score to picture on a large scoring stage", "Setting up a click and headphone system for the conductor and players", "Capturing individual cues for a television episode", "Recording a smaller ensemble score in a project studio"]}, "d1e79c44-af6b-4edd-bb23-6ce5fb8d7a78": {"definition": "The engineer who balances and mixes the recorded music for a film, television, or game score, blending the orchestral and instrumental tracks — often in real time during the session — into the stems delivered to the final mix.", "plain_english": "This is the engineer who blends all the recorded music into a finished sound. They often mix the orchestra live as it plays, so each cue is ready to hand off.", "purpose_function": "The role exists to deliver a polished, balanced music mix, usually as stems, that the re-recording mixer can drop into the final soundtrack.", "practical_application": "During a session the scoring mixer balances string, brass, and percussion sections at the console, prints stems, and delivers them for the final dub.", "category": "Studio Roles", "related_terms": ["Scoring engineer", "Stem", "Re-recording mixer", "Scoring stage", "Score-to-dialogue balance", "Cue"], "common_mistakes": ["Treating the scoring mixer and re-recording mixer as the same job", "Assuming the score is always mixed after the session rather than live", "Overlooking the need for clearly labeled stems for the final dub"], "scenario_contexts": ["Mixing an orchestra live to stems during a scoring session", "Delivering separate music stems to the re-recording stage", "Balancing sections of an ensemble for a film cue", "Preparing a stereo and surround music mix for a game score"]}, "8f4c2109-ee2d-4c69-af67-955106ecfa0f": {"definition": "A separate, non-linear workspace in some digital audio workstations where a producer can try out alternate arrangement or edit ideas apart from the main timeline, without altering the primary song.", "plain_english": "It is a side area in some music software for testing new ideas. You can rearrange or experiment there without changing your real song.", "purpose_function": "It lets you compare arrangement options and audition changes safely, keeping experiments out of the committed project until you pick one.", "practical_application": "A producer copies a chorus into the scratch pad, reorders sections to test a new structure, then moves the winning version back into the main arrangement.", "category": "DAW Workflow", "related_terms": ["Arrangement", "Playlist", "Comping", "Take", "Timeline", "Screenset"], "common_mistakes": ["Assuming scratch-pad ideas automatically update the main song", "Forgetting to move a finished idea back into the main timeline", "Confusing it with a scratch track or scratch vocal used as a rough reference"], "scenario_contexts": ["Testing an alternate song structure before committing", "Auditioning two different bridge ideas side by side", "Sketching a rough arrangement while the main mix stays untouched", "Comparing edit versions during production"]}, "3d28bc00-768c-47c8-bcec-6e5cc6ede101": {"definition": "A saved, recallable arrangement of open windows with their sizes, positions, and zoom settings in a digital audio workstation, letting an engineer switch between task-specific layouts with a single key.", "plain_english": "It is a saved layout of your software windows. You press one key to jump to the setup you want, like one view for recording and another for mixing.", "purpose_function": "It speeds up workflow by letting you flip between dedicated layouts — such as editing, mixing, or arranging — instead of moving windows around by hand.", "practical_application": "An engineer assigns a mixing layout to one number key and an editing layout to another, then switches between them instantly during a session.", "category": "DAW Workflow", "related_terms": ["Workspace", "Mixer window", "Arrange window", "Scratch Pad", "Key command", "Template"], "common_mistakes": ["Forgetting that moving a window updates the current screenset automatically", "Locking a screenset and then wondering why layout changes will not save", "Confusing screensets with separate project files"], "scenario_contexts": ["Switching from a tracking layout to a mixing layout instantly", "Recalling an editing window set during a comping session", "Setting up dedicated layouts for a multi-monitor rig", "Building a template with preset screensets"]}, "598df719-16fa-4a3c-b179-fb2d0bea5bfe": {"definition": "A digital audio workstation tool that plays audio at variable speed as you drag the cursor across a waveform, letting you hear exactly what is under the pointer to locate a precise edit point.", "plain_english": "It lets you drag across a sound to hear it slowly, like moving a record under a needle by hand. You use it to find the exact spot to make a cut.", "purpose_function": "It exists to help you find precise edit points by ear, hearing starts and boundaries that are hard to judge from the waveform picture alone.", "practical_application": "An editor scrubs across a drum track to find the exact start of a hit, then places an edit point right at the transient.", "category": "Editing Tools", "related_terms": ["Selector Tool", "Playhead", "Transient", "Waveform", "Edit point", "Zero crossing"], "common_mistakes": ["Confusing scrubbing with normal playback", "Scrubbing too fast to hear fine detail", "Forgetting that scrub is for finding edits, not for final listening judgments"], "scenario_contexts": ["Finding the exact start of a vocal phrase to trim", "Locating a click or noise to edit out", "Setting a precise loop point on a drum hit", "Spotting a sync point against picture"]}, "33b9eaad-d3a5-43d6-a040-ca944996b3ae": {"definition": "A section of music edited so its end flows into its start with no audible gap, click, or discontinuity, allowing it to repeat indefinitely as one continuous piece.", "plain_english": "It is a piece of music that can repeat over and over with no gap or click. When it reaches the end it flows straight back to the start so you cannot tell where it joins.", "purpose_function": "It exists to provide continuous background music, such as in games or on-hold systems, without a jarring break each time the loop restarts.", "practical_application": "A game composer trims the loop at matching zero crossings and matches the tail's reverb to the intro so the join stays inaudible during endless playback.", "category": "Looping", "related_terms": ["Loop point", "Zero crossing", "Crossfade", "Reverb tail", "Bar", "Tempo"], "common_mistakes": ["Cutting the loop where the waveform is not at a zero crossing, causing a click", "Ignoring the reverb or note tail that should carry over the loop join", "Not matching the loop length to whole bars, causing a rhythmic stumble"], "scenario_contexts": ["Creating background music that loops in a video game", "Building a loop for on-hold phone music", "Looping an ambient bed for an installation", "Making a repeating groove for a backing track"]}, "6bc35a7e-a026-4c29-ba78-0dbfda13fa70": {"definition": "The on-screen insertion point in a digital audio workstation that marks where editing will occur and from which a timeline selection is extended, usually shown as a blinking vertical line.", "plain_english": "It is the blinking line that shows where your edit will happen. You click to place it, then drag to select the part of the audio you want to work on.", "purpose_function": "It gives editing commands a precise anchor point, telling the software exactly where to place, cut, or start a selection on the timeline.", "practical_application": "An editor clicks to set the selection cursor on a beat, then drags to highlight a region before cutting or copying it.", "category": "Editing Tools", "related_terms": ["Selector Tool", "Playhead", "Edit point", "Selection", "Timeline", "Marker"], "common_mistakes": ["Confusing the selection cursor with the moving playhead", "Losing track of where the cursor sits before running an edit command", "Assuming a click also starts playback"], "scenario_contexts": ["Placing an insertion point before pasting audio", "Setting the start of a timeline selection", "Marking where a new region should begin", "Positioning for a precise split"]}, "86badfbd-60d9-42d3-ab03-3e99e0f007b4": {"definition": "An editing tool in a digital audio workstation — notably Pro Tools — used to place the edit cursor and drag out selections of audio or MIDI on the timeline for editing, copying, or playback.", "plain_english": "It is the tool you pick to highlight parts of your audio. You click and drag with it to choose the section you want to cut, copy, or play.", "purpose_function": "It exists to define what and where you edit, letting you set an insertion point or select a range before applying a command.", "practical_application": "In Pro Tools an editor chooses the Selector, drags across a chorus to select it, then loops or copies that selection.", "category": "Editing Tools", "related_terms": ["Selection Cursor", "Grabber Tool", "Trim Tool", "Scrub Tool", "Edit point", "Region"], "common_mistakes": ["Confusing the Selector with the Grabber, which moves regions instead of selecting them", "Leaving the wrong tool active and dragging a region by accident", "Forgetting to switch tools for different edit tasks"], "scenario_contexts": ["Selecting a range of audio to delete in Pro Tools", "Placing the edit cursor before recording a punch", "Highlighting a loop selection for playback", "Choosing a MIDI range to quantize"]}, "53b07864-b178-4180-a9fe-b05a08169320": {"definition": "A single recorded run of automation data written to a channel's send control, capturing changes in send level (and sometimes send pan or mute) over time as the mix plays. It is made in a write, touch, or latch automation mode and can be replayed or overwritten on later passes.", "plain_english": "It is one recorded take of moving a send knob while the song plays. The DAW remembers the move and plays it back the same way each time. It is like filming yourself turning a dial so it repeats exactly.", "purpose_function": "It lets the amount of signal feeding an effect or aux bus change automatically at set points in a song, so the engineer does not have to ride the send by hand every playback. This keeps effect levels consistent and repeatable.", "practical_application": "An engineer arms the send for automation, plays the section, and moves the send control, for example pushing more vocal into the reverb only on the last chorus, then refines the recorded moves on later passes.", "category": "Automation", "related_terms": ["Aux send", "Automation mode", "Send level", "Write automation", "Touch automation", "Volume automation"], "common_mistakes": ["Leaving the send in a write mode after the pass, which erases the good moves on the next playback.", "Forgetting that a send is set pre-fader (post-fader is the usual default), so automating the channel fader does not change the effect level as it would with a post-fader send.", "Writing jumpy, exaggerated moves that sound unnatural instead of small, smooth changes."], "scenario_contexts": ["Adding an extra delay throw on the last word of a vocal phrase before the chorus.", "Pulling a guitar out of a heavy reverb during a busy section so the mix stays clear.", "Automating a drum bus send to a parallel compressor to lift only the choruses."]}, "775f8d36-d575-444e-be61-157515f50c20": {"definition": "The area of a DAW mixer or channel strip that displays a track's send controls, its send assignments, levels, and pre/post settings, so signal can be routed to aux buses, return tracks, or effects. In Pro Tools it is the Sends view of the Mix and Edit windows, shown as compact assignments or as expanded individual controls.", "plain_english": "It is the part of the mixer that shows where each track sends a copy of its sound and how much. It is like a set of extra outputs on a channel that feed effects or headphone mixes.", "purpose_function": "It gives one place to see and set how tracks feed shared effects and auxiliary mixes, which keeps routing organized and easy to check. Without it, send assignments would be hidden and hard to manage.", "practical_application": "A technician opens the send view to assign several vocal tracks to a reverb bus, then sets each send level to control how wet each voice sounds.", "category": "DAW Interface", "related_terms": ["Aux send", "Return track", "Bus", "Send level", "Pre-fader send", "Post-fader send"], "common_mistakes": ["Confusing a send with an output, so the track's signal goes to the wrong destination.", "Setting a send pre-fader by accident, so the effect stays loud even when the fader is pulled down.", "Turning up a send with no return or aux set to receive it, so nothing is heard."], "scenario_contexts": ["Building a shared reverb by sending several tracks to one aux bus.", "Creating a separate headphone monitor mix using pre-fader sends.", "Checking why a track sounds dry by opening the send view to confirm its assignment."]}, "334f0a53-9697-432b-9357-fe0c035e34ee": {"definition": "In MOTU Digital Performer, a chunk that holds one sequence, a self-contained arrangement of MIDI and audio tracks with its own timeline. It is one of the chunk types, alongside songs and V-Racks, that can be stored and managed together in a single project's Chunks window.", "plain_english": "In the program Digital Performer, it is one saved song section that has its own tracks and timeline. Think of it as one document you can keep next to others in the same project file.", "purpose_function": "It lets a composer keep many separate arrangements, such as film cues, song versions, or set-list items, inside one project and switch between them quickly. This organizes related material without opening many files.", "practical_application": "A film composer creates a sequence chunk for each cue in a project, then jumps between them from the Chunks window while scoring to picture.", "category": "DAW Workflow", "related_terms": ["Chunk", "Sequence window", "V-Rack", "Song chunk", "Track", "Project file"], "common_mistakes": ["Thinking each sequence chunk must be a separate file, when they all live in one project.", "Editing the wrong chunk because the active sequence was not selected first.", "Losing shared instruments by not placing them in a V-Rack that all chunks can use."], "scenario_contexts": ["Scoring a film with one sequence chunk per cue.", "Keeping alternate arrangements of the same song as separate chunks for comparison.", "Building a live set list where each song is its own sequence chunk."]}, "e5c38a02-f7d6-4803-ab32-31b8d6fffbb2": {"definition": "In a MIDI and audio sequencer such as Digital Performer, the main editing window that displays the tracks and recorded MIDI and audio data of the active sequence along a horizontal time ruler. It is where tracks are arranged, recorded, and edited across the sequence's timeline.", "plain_english": "It is the main window that shows all the tracks of a song laid out over time, left to right. It works like a timeline where you record and rearrange the parts.", "purpose_function": "It provides the overview of a whole arrangement so an engineer can record, move, copy, and trim parts in time. It is the central workspace for building a sequence.", "practical_application": "An engineer records a MIDI part, then opens the sequence window to drag its region into place and line it up with the other tracks.", "category": "DAW Interface", "related_terms": ["Sequence chunk", "Track", "Timeline", "Arrangement", "Edit window", "Transport"], "common_mistakes": ["Confusing the sequence timeline window with a single-track editor and looking for detailed note edits in the wrong place.", "Editing while the wrong sequence is active, so changes land in another arrangement.", "Missing that regions snap to a grid, so parts will not line up freely."], "scenario_contexts": ["Arranging verses and choruses by dragging track regions along the timeline.", "Recording several tracks and reviewing them together in one view.", "Trimming and looping a section before bouncing the mix."]}, "99779d07-016b-45a0-bd24-6a2595302d2a": {"definition": "In Avid Pro Tools, the window that displays and controls a session's core timing and format settings, including sample rate, bit depth, clock source, sync and timecode settings, and session start time. It is the central place to confirm the digital clock and format before recording or playback.", "plain_english": "In Pro Tools, it is the window where you check and set the session's basic settings, like sample rate and where the clock comes from. It is like the settings page you look at before you start recording.", "purpose_function": "It gathers the format and sync settings that must be correct for clean recording and for locking to other gear, so faults like clicks or drift can be avoided. It gives one clear place to verify the clock source.", "practical_application": "Before tracking, a technician opens the Session Setup window to confirm the sample rate matches the project and to set the clock source to the interface when syncing to other devices.", "category": "DAW Interface", "related_terms": ["Sample rate", "Bit depth", "Clock source", "Word clock", "Timecode", "Session template"], "common_mistakes": ["Leaving the clock source on Internal when locked to an external device, causing clicks or drift.", "Setting a sample rate that does not match the recorded files, so audio plays back at the wrong pitch or speed.", "Ignoring the session start time, which throws off timecode alignment with video."], "scenario_contexts": ["Confirming 48 kHz and an external clock before a session with an outboard converter.", "Setting the session start time to match a picture edit for post work.", "Troubleshooting digital clicks by checking the clock source setting."]}, "369d3afd-9928-4f8c-b24d-14113f4c42a5": {"definition": "A saved starting-point session that already contains a chosen set of tracks, routing, buses, plugins, and settings, used to create new projects without building them from scratch. Opening it produces a fresh session preloaded with that setup.", "plain_english": "It is a ready-made session you save and reuse so every new project starts with your usual tracks and setup already in place. It is like a document template that saves you repeating the same steps.", "purpose_function": "It saves setup time and keeps sessions consistent, so recurring work like a band tracking date or a podcast starts the same way every time. This reduces errors and speeds up the start of a project.", "practical_application": "A studio tech builds a template with mic inputs, a drum bus, headphone sends, and a reverb aux already set, then starts each new tracking session from it.", "category": "DAW Workflow", "related_terms": ["Session Setup window", "Bus", "Aux send", "Signal routing", "Track", "Default template"], "common_mistakes": ["Saving audio or takes into the template, so old material carries into new projects.", "Not updating the template when workflow changes, so it recreates outdated routing.", "Forgetting to save as a new session, so work overwrites the template itself."], "scenario_contexts": ["Starting every podcast episode from a two-mic template with processing ready.", "Loading a mixing template with buses and reference meters set up.", "Setting up a live-band tracking template with inputs and headphone mixes."]}}$j$::jsonb)) d
WHERE g.id = d.id;
COMMIT;
